# ════════════════════════════════════════════════════════════════════
# Analytics: page visits + search events (May 18, 2026)
# ════════════════════════════════════════════════════════════════════
#
# Lightweight tracking for the Command Center marketing dashboard.
# Privacy-conscious: we hash visitor IPs with a daily salt so we can
# count uniques without storing actual IPs. Hashes don't persist
# across days, so we cannot track an individual across days.

def _today_visitor_salt() -> str:
    """Per-day salt. Resets at UTC midnight so visitor_hash is unique
    per day but not linkable across days."""
    today_utc = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    # Combine with a stable server-side seed so the salt isn't guessable
    seed = os.environ.get("ANALYTICS_SALT", "wv-default-salt-change-in-prod")
    return f"{today_utc}:{seed}"


def _hash_visitor(ip: str) -> str:
    """Hash an IP with today's salt. Returns a stable 16-char identifier
    that's unique per day per IP, but unlinkable across days and not
    reversible to the IP."""
    if not ip:
        ip = "anon"
    h = hashlib.sha256()
    h.update(_today_visitor_salt().encode("utf-8"))
    h.update(ip.encode("utf-8"))
    return h.hexdigest()[:16]


def _client_ip() -> str:
    """Get the client IP, respecting Cloudflare and proxy headers.
    Cloudflare sets CF-Connecting-IP. Render/proxies set X-Forwarded-For
    (which may have multiple IPs comma-separated; first is client)."""
    cf_ip = request.headers.get("CF-Connecting-IP", "").strip()
    if cf_ip:
        return cf_ip
    xff = request.headers.get("X-Forwarded-For", "").strip()
    if xff:
        return xff.split(",")[0].strip()
    return request.remote_addr or ""


def _client_region() -> tuple[str, str]:
    """Get country code and US state from Cloudflare headers.
    Returns (country, region). Empty strings if unknown."""
    country = request.headers.get("CF-IPCountry", "").strip() or ""
    region = request.headers.get("CF-Region-Code", "").strip() or ""
    return country, region


@app.route("/api/v1/analytics/visit", methods=["OPTIONS"])
def _analytics_visit_preflight():
    return ("", 204)


@app.post("/api/v1/analytics/visit")
def analytics_visit():
    """Log a page visit. Called by the frontend on each screen render.

    Body: {"path": "/", "referrer": "https://google.com/..."}
    Returns: {"ok": true}

    Best effort: errors are logged but never block the visitor.
    The endpoint never returns user data; it's write-only from the
    client's perspective.
    """
    try:
        data = request.get_json(silent=True) or {}
        path = (data.get("path") or "/")[:200]
        referrer = (data.get("referrer") or "")[:500] or None
        ip = _client_ip()
        country, region = _client_region()
        visitor_hash = _hash_visitor(ip)

        # If logged in, link to user_id (best effort)
        user_id = None
        try:
            user = _get_current_user()
            if user:
                user_id = user["id"]
        except Exception:
            pass

        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO page_visits
                       (visited_at_ms, path, visitor_hash, referrer,
                        user_id, country, region)
                       VALUES (%s, %s, %s, %s, %s, %s, %s)""",
                    (int(time.time() * 1000), path, visitor_hash,
                     referrer, user_id, country or None, region or None),
                )
    except Exception as e:
        # Best-effort: never break the visitor's experience
        print(f"[analytics-visit] failed: {e}", flush=True)
    return jsonify({"ok": True})


@app.route("/api/v1/analytics/search", methods=["OPTIONS"])
def _analytics_search_preflight():
    return ("", 204)


@app.post("/api/v1/analytics/search")
def analytics_search():
    """Log a homepage AI search. Called by the frontend when a search
    completes. Tracks what people are searching for and from where.

    Body: {"query": "...", "location": "...", "verdict": "clear|caution|risk"}
    Returns: {"ok": true}
    """
    try:
        data = request.get_json(silent=True) or {}
        query_text = (data.get("query") or "")[:500] or None
        location_text = (data.get("location") or "")[:200] or None
        verdict = (data.get("verdict") or "")[:20] or None
        ip = _client_ip()
        country, region = _client_region()
        visitor_hash = _hash_visitor(ip)

        user_id = None
        try:
            user = _get_current_user()
            if user:
                user_id = user["id"]
        except Exception:
            pass

        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO search_events
                       (searched_at_ms, query_text, location_text, verdict,
                        user_id, visitor_hash, region)
                       VALUES (%s, %s, %s, %s, %s, %s, %s)""",
                    (int(time.time() * 1000), query_text, location_text,
                     verdict, user_id, visitor_hash, region or None),
                )
    except Exception as e:
        print(f"[analytics-search] failed: {e}", flush=True)
    return jsonify({"ok": True})


# ════════════════════════════════════════════════════════════════════
# Image upload + hosting (own-domain media, for inline email + MMS)
# ════════════════════════════════════════════════════════════════════
#
# Mets build graphics in Slides/PowerPoint, export a PNG, and upload it in
# the composer. We optimize it (downscale + recompress so it stays small
# enough to deliver as a picture text), store the bytes in Postgres, and
# serve it from our own domain. That one URL powers the inline email image
# AND the picture text (MMS), with no Google Drive link and no carrier
# filtering risk. (June 2026)

def _ensure_media_table():
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """CREATE TABLE IF NOT EXISTS uploaded_media (
                       token       TEXT PRIMARY KEY,
                       mime_type   TEXT NOT NULL,
                       bytes       BYTEA NOT NULL,
                       byte_size   INTEGER NOT NULL,
                       filename    TEXT,
                       uploaded_by INTEGER,
                       created_at  BIGINT NOT NULL
                   )"""
            )


def _sniff_image_bytes(b: bytes):
    """PNG/JPG/GIF by file signature. Returns (mime, ext) or (None, None)."""
    if b[:8] == b"\x89PNG\r\n\x1a\n":
        return ("image/png", "png")
    if b[:3] == b"\xff\xd8\xff":
        return ("image/jpeg", "jpg")
    if b[:6] in (b"GIF87a", b"GIF89a"):
        return ("image/gif", "gif")
    return (None, None)


def _store_media_bytes(raw: bytes, filename: str, uploaded_by):
    """The storage core behind /api/v1/media/upload, callable from anywhere.
    Optimizes with Pillow when available, stores in uploaded_media, and
    returns (True, public_url) or (False, reason)."""
    mime, ext = _sniff_image_bytes(raw)
    if not mime:
        return False, "not-an-image"
    data = raw
    try:
        import io
        from PIL import Image
        # Memory guard (July 2026): refuse decompression bombs. A small
        # file can decode into gigabytes; 40M pixels is far beyond any
        # legitimate forecast graphic and keeps us under the 512MB plan.
        Image.MAX_IMAGE_PIXELS = 40_000_000
        img = Image.open(io.BytesIO(raw))
        img.load()
        if img.width > 1400:
            ratio = 1400 / float(img.width)
            img = img.resize((1400, max(1, int(img.height * ratio))))
        out = io.BytesIO()
        if mime == "image/png" or img.mode in ("RGBA", "LA", "P"):
            img.save(out, format="PNG", optimize=True)
            mime, ext = "image/png", "png"
        else:
            img.convert("RGB").save(out, format="JPEG", quality=82, optimize=True)
            mime, ext = "image/jpeg", "jpg"
        data = out.getvalue()
    except Exception:
        data = raw
    if len(data) > 5 * 1024 * 1024:
        return False, "too-large"
    token = secrets.token_urlsafe(18)
    _ensure_media_table()
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO uploaded_media
                       (token, mime_type, bytes, byte_size, filename, uploaded_by, created_at)
                   VALUES (%s,%s,%s,%s,%s,%s,%s)""",
                (token, mime, psycopg2.Binary(data), len(data),
                 (filename or "")[:200], uploaded_by, int(time.time() * 1000)),
            )
    try:
        base = request.host_url.rstrip("/")
    except Exception:
        base = "https://api.weathervalet.ai"
    return True, base + "/media/" + token + "." + ext


# Hosts whose links get silently re-hosted onto our own domain before any
# send (July 2026). Google Drive links in picture texts are a known
# carrier-filtering trigger (Twilio error 30007), and shared-drive images
# can expire or require sign-in. A fixed allowlist (rather than "mirror
# everything") avoids turning this into an open server-side fetch.
_MIRROR_HOSTS = (
    "drive.google.com", "docs.google.com", "drive.usercontent.google.com",
    "lh3.googleusercontent.com", "lh4.googleusercontent.com",
    "lh5.googleusercontent.com", "lh6.googleusercontent.com",
    "photos.google.com", "dropbox.com", "www.dropbox.com",
    "dl.dropboxusercontent.com",
)


def _normalize_share_link(url: str) -> str:
    """Turn common share-page links into direct-download links."""
    import re as _re
    m = _re.search(r"drive\.google\.com/file/d/([\w-]+)", url)
    if m:
        return "https://drive.google.com/uc?export=download&id=" + m.group(1)
    m = _re.search(r"drive\.google\.com/open\?id=([\w-]+)", url)
    if m:
        return "https://drive.google.com/uc?export=download&id=" + m.group(1)
    if "dropbox.com" in url and "dl=0" in url:
        return url.replace("dl=0", "dl=1")
    return url


def _mirror_external_image(url: str, uploaded_by) -> str | None:
    """If the URL points at a risky share host (Google Drive etc.),
    download the image and re-host it at weathervalet's own /media/ URL.
    Returns the URL to use: our new URL on success, the original when the
    host isn't on the mirror list or is already ours, or None when the
    mirror was needed but failed (callers keep the original and we log)."""
    u = (url or "").strip()
    if not u.lower().startswith(("http://", "https://")):
        return u or None
    try:
        from urllib.parse import urlparse
        host = (urlparse(u).hostname or "").lower()
    except Exception:
        return u
    if host.endswith("weathervalet.ai"):
        return u
    if host not in _MIRROR_HOSTS:
        return u
    try:
        import urllib.request
        req = urllib.request.Request(
            _normalize_share_link(u),
            headers={"User-Agent": "Mozilla/5.0 (WeatherValet image mirror)"})
        with urllib.request.urlopen(req, timeout=12) as resp:
            raw = resp.read(8 * 1024 * 1024 + 1)
        if len(raw) > 8 * 1024 * 1024:
            print(f"[img-mirror] too large, keeping original: {u[:90]}", flush=True)
            return None
        ok, result = _store_media_bytes(raw, "mirrored-image", uploaded_by)
        if not ok:
            print(f"[img-mirror] store failed ({result}): {u[:90]}", flush=True)
            return None
        print(f"[img-mirror] re-hosted {host} image -> {result}", flush=True)
        return result
    except Exception as e:
        print(f"[img-mirror] fetch failed ({e!r}): {u[:90]}", flush=True)
        return None


@app.route("/api/v1/media/upload", methods=["OPTIONS"])
def _media_upload_preflight():
    return ("", 204)


@app.post("/api/v1/media/upload")
def media_upload():
    user = _get_current_user()
    roles = (user.get("roles") or []) if user else []
    if not user or ("met" not in roles and "admin" not in roles):
        return jsonify({"ok": False, "error": "forbidden"}), 403
    f = request.files.get("file")
    if f is None:
        return jsonify({"ok": False, "error": "no-file",
                        "message": "No image was attached."}), 400
    raw = f.read()
    if not raw:
        return jsonify({"ok": False, "error": "empty",
                        "message": "The image was empty."}), 400
    # Validate by file signature so this works with or without Pillow.
    def _sniff(b):
        if b[:8] == b"\x89PNG\r\n\x1a\n":
            return ("image/png", "png")
        if b[:3] == b"\xff\xd8\xff":
            return ("image/jpeg", "jpg")
        if b[:6] in (b"GIF87a", b"GIF89a"):
            return ("image/gif", "gif")
        return (None, None)
    mime, ext = _sniff(raw)
    if not mime:
        return jsonify({"ok": False, "error": "bad-image",
                        "message": "Please upload a PNG or JPG image."}), 400
    data = raw
    # Optimize with Pillow if it is installed (downscale wide graphics so the
    # picture text stays deliverable). If Pillow is missing, store the original.
    try:
        import io
        from PIL import Image
        # Memory guard (July 2026): refuse decompression bombs. A small
        # file can decode into gigabytes; 40M pixels is far beyond any
        # legitimate forecast graphic and keeps us under the 512MB plan.
        Image.MAX_IMAGE_PIXELS = 40_000_000
        img = Image.open(io.BytesIO(raw))
        img.load()
        if img.width > 1400:
            ratio = 1400 / float(img.width)
            img = img.resize((1400, max(1, int(img.height * ratio))))
        out = io.BytesIO()
        if mime == "image/png" or img.mode in ("RGBA", "LA", "P"):
            img.save(out, format="PNG", optimize=True)
            mime, ext = "image/png", "png"
        else:
            img.convert("RGB").save(out, format="JPEG", quality=82, optimize=True)
            mime, ext = "image/jpeg", "jpg"
        data = out.getvalue()
    except Exception:
        data = raw  # Pillow unavailable or failed; the original bytes are fine
    if len(data) > 5 * 1024 * 1024:
        return jsonify({"ok": False, "error": "too-large",
                        "message": "Image is too large even after optimizing. Try a simpler graphic."}), 400
    token = secrets.token_urlsafe(18)
    try:
        _ensure_media_table()
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO uploaded_media
                           (token, mime_type, bytes, byte_size, filename, uploaded_by, created_at)
                       VALUES (%s,%s,%s,%s,%s,%s,%s)""",
                    (token, mime, psycopg2.Binary(data), len(data),
                     (f.filename or "")[:200], user.get("id"), int(time.time() * 1000)),
                )
    except Exception as e:
        return jsonify({"ok": False, "error": "server", "message": str(e)}), 500
    url = request.host_url.rstrip("/") + "/media/" + token + "." + ext
    return jsonify({"ok": True, "url": url, "bytes": len(data)})


@app.get("/media/<path:token>")
def media_serve(token):
    """Public image serve (no auth): used by email <img>, the web brief,
    and Twilio's MMS fetch. The token may carry a .png/.jpg extension."""
    base = token.rsplit(".", 1)[0]
    try:
        _ensure_media_table()
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT mime_type, bytes FROM uploaded_media WHERE token = %s", (base,))
                row = cur.fetchone()
    except Exception:
        row = None
    if not row:
        return ("Not found", 404)
    data = row["bytes"]
    if isinstance(data, memoryview):
        data = data.tobytes()
    resp = make_response(bytes(data))
    resp.headers["Content-Type"] = row["mime_type"]
    resp.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    return resp


@app.route("/api/v1/admin/message-log", methods=["OPTIONS"])
def _admin_message_log_preflight():
    return ("", 204)


@app.get("/api/v1/admin/message-log")
def admin_message_log():
    """Every message sent to subscribers in a given state on a given local
    day, pulled from BOTH the normal brief history and the ad-hoc 'update'
    drafts (the storm/tornado texts that don't land in brief_history).
    Admin only. Built for pulling marketing screenshots. (June 2026)"""
    user = _get_current_user()
    if user is None or "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403
    date_str = (request.args.get("date") or "").strip()          # YYYY-MM-DD
    state = (request.args.get("state") or "").strip().upper()    # e.g. KS
    tz_name = (request.args.get("tz") or "America/Chicago").strip()
    try:
        y, m, d = [int(x) for x in date_str.split("-")]
        tz = ZoneInfo(tz_name)
        start_ms = int(datetime(y, m, d, 0, 0, 0, tzinfo=tz).timestamp() * 1000)
        end_ms = start_ms + 24 * 60 * 60 * 1000
    except Exception:
        return jsonify({"ok": False, "error": "bad-date",
                        "message": "Use date=YYYY-MM-DD."}), 400

    def parse_state(addr):
        if not addr:
            return None
        tail = addr.strip().rstrip(".").split(",")[-1].strip()
        toks = tail.split()
        if toks:
            c = toks[0].strip().upper()
            if len(c) == 2 and c.isalpha():
                return c
        return None

    try:
        rows = []
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT bh.user_id, bh.delivered_at AS t, bh.brief_type AS kind,
                              bh.verdict, bh.full_body AS body, bh.channels_used AS channels,
                              bh.met_name, u.name AS sub_name, u.email,
                              loc.address_text, loc.label AS loc_label
                       FROM brief_history bh
                       JOIN users u ON u.id = bh.user_id
                       LEFT JOIN saved_locations loc ON loc.user_id = bh.user_id AND loc.is_primary = TRUE
                       WHERE bh.delivery_status = 'sent'
                         AND bh.delivered_at >= %s AND bh.delivered_at < %s""",
                    (start_ms, end_ms),
                )
                rows.extend(cur.fetchall())
                # Ad-hoc updates that never wrote a brief_history row
                # (history_id IS NULL), so we don't double-count.
                cur.execute(
                    """SELECT d.user_id, d.sent_at AS t, d.brief_type AS kind,
                              COALESCE(d.final_verdict, d.met_verdict, d.ai_verdict) AS verdict,
                              COALESCE(d.final_body, d.met_body, d.ai_body) AS body,
                              d.channels, d.sent_by_name AS met_name,
                              u.name AS sub_name, u.email,
                              loc.address_text, loc.label AS loc_label
                       FROM pro_brief_drafts d
                       JOIN users u ON u.id = d.user_id
                       LEFT JOIN saved_locations loc ON loc.user_id = d.user_id AND loc.is_primary = TRUE
                       WHERE d.status = 'sent' AND d.brief_type = 'update'
                         AND d.history_id IS NULL
                         AND d.sent_at >= %s AND d.sent_at < %s""",
                    (start_ms, end_ms),
                )
                rows.extend(cur.fetchall())

        out = []
        for r in rows:
            addr = r.get("address_text")
            st = parse_state(addr)
            if state and st != state:
                continue
            t = r.get("t") or 0
            try:
                when = datetime.fromtimestamp(t / 1000, tz).strftime("%I:%M %p").lstrip("0")
            except Exception:
                when = ""
            out.append({
                "time_ms": t, "time": when,
                "recipient": r.get("sub_name") or r.get("email") or "Subscriber",
                "location": addr or r.get("loc_label") or "",
                "state": st or "",
                "kind": r.get("kind") or "",
                "verdict": r.get("verdict") or "",
                "channels": r.get("channels") or "",
                "met_name": r.get("met_name") or "",
                "text": r.get("body") or "",
            })
        out.sort(key=lambda x: x["time_ms"])
        return jsonify({"ok": True, "date": date_str, "state": state,
                        "count": len(out), "messages": out})
    except Exception as e:
        return jsonify({"ok": False, "error": "server", "message": str(e)}), 500


@app.route("/api/v1/admin/command-center/stats", methods=["OPTIONS"])
def _cmd_center_stats_preflight():
    return ("", 204)


@app.get("/api/v1/admin/command-center/stats")
def admin_command_center_stats():
    """Return marketing stats for the Command Center dashboard.

    Computed:
      - Today / yesterday / 7-day unique visitors (distinct visitor_hash)
      - Today / yesterday / 7-day total page views
      - Today / yesterday / 7-day search counts
      - Current subscriber count (and 7-day delta)
      - Current crew member count (and 7-day delta)
      - Top search regions (US states with most searches in last 7 days)

    All times are UTC. The frontend handles timezone display.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    now_ms = int(time.time() * 1000)
    day_ms = 24 * 60 * 60 * 1000

    # UTC day boundaries
    today_start_dt = datetime.now(timezone.utc).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    today_start_ms = int(today_start_dt.timestamp() * 1000)
    yesterday_start_ms = today_start_ms - day_ms
    week_ago_start_ms = today_start_ms - 6 * day_ms  # last 7 calendar days incl today
    two_weeks_ago_ms = today_start_ms - 13 * day_ms

    stats: dict = {}

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # ── Visitors ──
                cur.execute(
                    """SELECT
                          COUNT(DISTINCT CASE WHEN visited_at_ms >= %s THEN visitor_hash END) AS uniq_today,
                          COUNT(DISTINCT CASE WHEN visited_at_ms >= %s AND visited_at_ms < %s THEN visitor_hash END) AS uniq_yesterday,
                          COUNT(DISTINCT CASE WHEN visited_at_ms >= %s THEN visitor_hash END) AS uniq_7d,
                          COUNT(DISTINCT CASE WHEN visited_at_ms >= %s AND visited_at_ms < %s THEN visitor_hash END) AS uniq_prev_7d,
                          COUNT(CASE WHEN visited_at_ms >= %s THEN 1 END) AS views_today,
                          COUNT(CASE WHEN visited_at_ms >= %s AND visited_at_ms < %s THEN 1 END) AS views_yesterday,
                          COUNT(CASE WHEN visited_at_ms >= %s THEN 1 END) AS views_7d
                       FROM page_visits""",
                    (today_start_ms,
                     yesterday_start_ms, today_start_ms,
                     week_ago_start_ms,
                     two_weeks_ago_ms, week_ago_start_ms,
                     today_start_ms,
                     yesterday_start_ms, today_start_ms,
                     week_ago_start_ms),
                )
                row = cur.fetchone() or {}
                stats["visitors"] = {
                    "today": row.get("uniq_today") or 0,
                    "yesterday": row.get("uniq_yesterday") or 0,
                    "seven_day": row.get("uniq_7d") or 0,
                    "previous_seven_day": row.get("uniq_prev_7d") or 0,
                    "views_today": row.get("views_today") or 0,
                    "views_yesterday": row.get("views_yesterday") or 0,
                    "views_seven_day": row.get("views_7d") or 0,
                }

                # ── Searches ──
                cur.execute(
                    """SELECT
                          COUNT(CASE WHEN searched_at_ms >= %s THEN 1 END) AS today,
                          COUNT(CASE WHEN searched_at_ms >= %s AND searched_at_ms < %s THEN 1 END) AS yesterday,
                          COUNT(CASE WHEN searched_at_ms >= %s THEN 1 END) AS seven_day,
                          COUNT(CASE WHEN searched_at_ms >= %s AND searched_at_ms < %s THEN 1 END) AS prev_seven_day
                       FROM search_events""",
                    (today_start_ms,
                     yesterday_start_ms, today_start_ms,
                     week_ago_start_ms,
                     two_weeks_ago_ms, week_ago_start_ms),
                )
                row = cur.fetchone() or {}
                stats["searches"] = {
                    "today": row.get("today") or 0,
                    "yesterday": row.get("yesterday") or 0,
                    "seven_day": row.get("seven_day") or 0,
                    "previous_seven_day": row.get("prev_seven_day") or 0,
                }

                # ── Subscribers (paying accounts) vs Users (all people) ──
                # One paid account can have up to 4 people: the owner plus
                # added team members. Team members are full subscriber-role
                # users (they get their own briefs), so counting subscriber
                # roles counts PEOPLE, not paying accounts. A user is an added
                # member if they appear as member_user_id in an active/pending
                # pro_multi_memberships row. Accounts = everyone who is NOT an
                # added member (owners + solo subscribers).
                cur.execute(
                    """SELECT
                          COUNT(*) FILTER (WHERE u.is_active = TRUE) AS users_total,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND m.member_user_id IS NULL) AS accounts_total,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND m.member_user_id IS NULL AND u.created_at >= %s) AS acct_new_7d,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND m.member_user_id IS NULL AND u.created_at >= %s AND u.created_at < %s) AS acct_new_prev_7d,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND m.member_user_id IS NOT NULL) AS members_total
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'subscriber'
                       LEFT JOIN (
                           SELECT DISTINCT member_user_id
                           FROM pro_multi_memberships
                           WHERE status IN ('active', 'pending')
                       ) m ON m.member_user_id = u.id""",
                    (week_ago_start_ms, two_weeks_ago_ms, week_ago_start_ms),
                )
                row = cur.fetchone() or {}
                stats["subscribers"] = {
                    # 'total' is now paying ACCOUNTS (owners + solo), the
                    # headline number. Same key so the tile delta keeps working.
                    "total": row.get("accounts_total") or 0,
                    "new_seven_day": row.get("acct_new_7d") or 0,
                    "new_previous_seven_day": row.get("acct_new_prev_7d") or 0,
                    # Total PEOPLE across all accounts, and how many of those
                    # are added team members (seats beyond the owner).
                    "users_total": row.get("users_total") or 0,
                    "members_total": row.get("members_total") or 0,
                }

                # ── Crew members ──
                cur.execute(
                    """SELECT
                          COUNT(*) FILTER (WHERE u.is_active = TRUE) AS total,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND u.created_at >= %s) AS new_7d,
                          COUNT(*) FILTER (WHERE u.is_active = TRUE AND u.created_at >= %s AND u.created_at < %s) AS new_prev_7d
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'crew'""",
                    (week_ago_start_ms, two_weeks_ago_ms, week_ago_start_ms),
                )
                row = cur.fetchone() or {}
                stats["crew"] = {
                    "total": row.get("total") or 0,
                    "new_seven_day": row.get("new_7d") or 0,
                    "new_previous_seven_day": row.get("new_prev_7d") or 0,
                }

                # ── Top search regions (US states with most searches, 7d) ──
                cur.execute(
                    """SELECT region, COUNT(*) AS n
                       FROM search_events
                       WHERE searched_at_ms >= %s AND region IS NOT NULL AND region != ''
                       GROUP BY region
                       ORDER BY n DESC
                       LIMIT 10""",
                    (week_ago_start_ms,),
                )
                stats["top_regions"] = [
                    {"region": r["region"], "count": r["n"]}
                    for r in cur.fetchall()
                ]

                # ── Top search locations (text locations, 7d) ──
                cur.execute(
                    """SELECT location_text, COUNT(*) AS n
                       FROM search_events
                       WHERE searched_at_ms >= %s AND location_text IS NOT NULL AND location_text != ''
                       GROUP BY location_text
                       ORDER BY n DESC
                       LIMIT 10""",
                    (week_ago_start_ms,),
                )
                stats["top_locations"] = [
                    {"location": r["location_text"], "count": r["n"]}
                    for r in cur.fetchall()
                ]

    except Exception as e:
        print(f"[command-center-stats] failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "query-failed"}), 500

    return jsonify({"ok": True, "stats": stats, "computed_at_ms": now_ms})


@app.route("/api/v1/admin/command-center/charts", methods=["OPTIONS"])
def _cmd_center_charts_preflight():
    return ("", 204)


@app.get("/api/v1/admin/command-center/charts")
def admin_command_center_charts():
    """Stage 2 of Command Center analytics. Returns time-series and
    aggregate data for charts in the dashboard.

    Computed:
      - daily_visitors[14]: unique + total views per day for last 14 days
      - daily_searches[14]: search count per day for last 14 days
      - hourly_pattern[24]: average visitors per hour of day (last 7 days)
      - top_queries[10]: most searched plan/query texts (last 7 days)
      - signup_funnel: rough conversion numbers (visitors -> searches -> subscribers)
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    now_ms = int(time.time() * 1000)
    day_ms = 24 * 60 * 60 * 1000

    # UTC day boundaries
    today_start_dt = datetime.now(timezone.utc).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    today_start_ms = int(today_start_dt.timestamp() * 1000)
    fourteen_days_ago_ms = today_start_ms - 13 * day_ms  # 14 days INCLUDING today
    seven_days_ago_ms = today_start_ms - 6 * day_ms

    charts: dict = {}

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # ── Daily visitors (14 days) ──
                # Group visits by day-bucket. We compute the bucket on the
                # backend side to avoid timezone confusion.
                cur.execute(
                    """SELECT
                          FLOOR((visited_at_ms - %s) / %s)::int AS day_offset,
                          COUNT(DISTINCT visitor_hash) AS uniq,
                          COUNT(*) AS views
                       FROM page_visits
                       WHERE visited_at_ms >= %s
                       GROUP BY day_offset
                       ORDER BY day_offset""",
                    (fourteen_days_ago_ms, day_ms, fourteen_days_ago_ms),
                )
                rows = cur.fetchall()
                # Build a full 14-day series with zero-fills
                daily_visitors = []
                rows_by_offset = {r["day_offset"]: r for r in rows}
                for offset in range(14):
                    bucket_start_ms = fourteen_days_ago_ms + offset * day_ms
                    bucket_date = datetime.fromtimestamp(
                        bucket_start_ms / 1000, tz=timezone.utc
                    ).strftime("%Y-%m-%d")
                    r = rows_by_offset.get(offset)
                    daily_visitors.append({
                        "date": bucket_date,
                        "day_offset": offset,
                        "unique_visitors": (r or {}).get("uniq") or 0,
                        "total_views": (r or {}).get("views") or 0,
                    })
                charts["daily_visitors"] = daily_visitors

                # ── Daily searches (14 days) ──
                cur.execute(
                    """SELECT
                          FLOOR((searched_at_ms - %s) / %s)::int AS day_offset,
                          COUNT(*) AS n
                       FROM search_events
                       WHERE searched_at_ms >= %s
                       GROUP BY day_offset
                       ORDER BY day_offset""",
                    (fourteen_days_ago_ms, day_ms, fourteen_days_ago_ms),
                )
                rows = cur.fetchall()
                daily_searches = []
                rows_by_offset = {r["day_offset"]: r for r in rows}
                for offset in range(14):
                    bucket_start_ms = fourteen_days_ago_ms + offset * day_ms
                    bucket_date = datetime.fromtimestamp(
                        bucket_start_ms / 1000, tz=timezone.utc
                    ).strftime("%Y-%m-%d")
                    r = rows_by_offset.get(offset)
                    daily_searches.append({
                        "date": bucket_date,
                        "day_offset": offset,
                        "count": (r or {}).get("n") or 0,
                    })
                charts["daily_searches"] = daily_searches

                # ── Hourly pattern (7 days) ──
                # Computed as average visitors per hour across last 7 days.
                # Uses EXTRACT(HOUR FROM TO_TIMESTAMP) which is portable Postgres.
                cur.execute(
                    """SELECT
                          EXTRACT(HOUR FROM TO_TIMESTAMP(visited_at_ms / 1000))::int AS hour_utc,
                          COUNT(*) AS visits
                       FROM page_visits
                       WHERE visited_at_ms >= %s
                       GROUP BY hour_utc
                       ORDER BY hour_utc""",
                    (seven_days_ago_ms,),
                )
                rows = cur.fetchall()
                hourly_by_hour = {r["hour_utc"]: r["visits"] for r in rows}
                # Fill all 24 hours with zero defaults
                hourly_pattern = []
                for h in range(24):
                    hourly_pattern.append({
                        "hour_utc": h,
                        "visits": hourly_by_hour.get(h, 0),
                    })
                charts["hourly_pattern"] = hourly_pattern

                # ── Top search queries (7 days) ──
                # The "marketing intel goldmine": what are people actually typing?
                cur.execute(
                    """SELECT query_text, COUNT(*) AS n
                       FROM search_events
                       WHERE searched_at_ms >= %s
                         AND query_text IS NOT NULL
                         AND query_text != ''
                       GROUP BY query_text
                       ORDER BY n DESC, query_text
                       LIMIT 10""",
                    (seven_days_ago_ms,),
                )
                charts["top_queries"] = [
                    {"query": r["query_text"], "count": r["n"]}
                    for r in cur.fetchall()
                ]

                # ── Signup funnel (rough lifetime estimate) ──
                # Visitors that ever loaded -> searches done -> subscribers signed up.
                # We use lifetime data for the denominators (because the
                # earliest visits/searches show real funnel pressure).
                # All counts are over the last 7 days for a comparable window.
                cur.execute(
                    """SELECT COUNT(DISTINCT visitor_hash) AS uniq_visitors
                       FROM page_visits
                       WHERE visited_at_ms >= %s""",
                    (seven_days_ago_ms,),
                )
                funnel_visitors = (cur.fetchone() or {}).get("uniq_visitors") or 0

                cur.execute(
                    """SELECT COUNT(DISTINCT visitor_hash) AS searched
                       FROM search_events
                       WHERE searched_at_ms >= %s""",
                    (seven_days_ago_ms,),
                )
                funnel_searched = (cur.fetchone() or {}).get("searched") or 0

                cur.execute(
                    """SELECT COUNT(*) AS new_subs
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'subscriber'
                       WHERE u.created_at >= %s AND u.is_active = TRUE""",
                    (seven_days_ago_ms,),
                )
                funnel_subscribers = (cur.fetchone() or {}).get("new_subs") or 0

                charts["signup_funnel"] = {
                    "visitors_7d": funnel_visitors,
                    "searched_7d": funnel_searched,
                    "new_subscribers_7d": funnel_subscribers,
                    "search_rate_pct": (
                        round(funnel_searched / funnel_visitors * 100, 1)
                        if funnel_visitors > 0 else 0
                    ),
                    "subscribe_rate_pct": (
                        round(funnel_subscribers / funnel_searched * 100, 1)
                        if funnel_searched > 0 else 0
                    ),
                }

    except Exception as e:
        print(f"[command-center-charts] failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "query-failed"}), 500

    return jsonify({"ok": True, "charts": charts, "computed_at_ms": now_ms})


