# ════════════════════════════════════════════════════════════════════
# Admin · Team management endpoints (Phase 4 Chunk 2)
# ════════════════════════════════════════════════════════════════════
# These power the Team tab in the admin Command Center. Session-auth
# gated via @require_role('admin') — caller must be signed in AND have
# the 'admin' role. The older /admin/* HTTP-Basic routes stay around
# as a bootstrap mechanism (you can still curl /admin/set-password etc.
# if your admin user gets locked out).
#
# Uses the existing `db()` context manager. Connections autocommit,
# so no explicit commit/rollback is needed. Row factory is
# RealDictCursor, so cur.fetchone() returns dicts keyed by column name.


def _generate_temp_password():
    """Generate a memorable but secure temp password for new users.
    Pattern: three short English words + two digits, e.g. "river-storm-cedar-42".
    Easier to share verbally than a random string; still high-entropy enough
    that brute force is impractical within the time before the user is
    required to change it on first login (forced via password_must_change).
    """
    import secrets
    words = [
        "storm", "river", "cedar", "quiet", "amber", "north", "calm",
        "flint", "dune", "marsh", "pine", "vivid", "swift", "bright",
        "creek", "ridge", "valley", "meadow", "harbor", "ember",
    ]
    w1 = secrets.choice(words)
    w2 = secrets.choice([w for w in words if w != w1])
    w3 = secrets.choice([w for w in words if w not in (w1, w2)])
    digits = secrets.randbelow(90) + 10  # 10-99
    return f"{w1}-{w2}-{w3}-{digits}"


def _serialize_user_for_admin(row):
    """Shape a users row (dict, since RealDictCursor) + roles list into
    the JSON shape the frontend Team panel expects. `row` is expected
    to have: id, email, name, created_at, last_login_at, is_active, roles.
    """
    import time as _time
    import datetime as _datetime

    last_login_at = row.get("last_login_at")
    if last_login_at:
        delta = int(_time.time()) - int(last_login_at)
        if delta < 60:
            last_login_str = "just now"
        elif delta < 3600:
            last_login_str = f"{delta // 60} min ago"
        elif delta < 86400:
            last_login_str = f"{delta // 3600}h ago"
        elif delta < 86400 * 7:
            last_login_str = f"{delta // 86400}d ago"
        else:
            last_login_str = _datetime.datetime.utcfromtimestamp(last_login_at).strftime("%b %d")
    else:
        last_login_str = "Never"

    roles = row.get("roles") or []
    # Pick highest-priority role for the frontend's single-role-per-row display.
    # Matches workspace-router precedence (admin > met > crew > subscriber).
    role_priority = ["admin", "met", "crew", "subscriber"]
    primary_role = next((r for r in role_priority if r in roles), None)
    # Frontend uses 'meteorologist' for display; backend stores 'met'.
    if primary_role == "met":
        primary_role = "meteorologist"

    return {
        "id": f"u_{row['id']}",
        "user_id": row["id"],
        "is_discounted": bool(row.get("is_discounted")),
        "name": row.get("name") or "",
        "email": row["email"],
        "phone": row.get("phone") or "",
        "role": primary_role or "subscriber",
        "all_roles": roles,
        "subscription_tier": row.get("subscription_tier") or "",
        "primary_met_id": row.get("primary_met_id"),
        "primary_met_name": row.get("primary_met_name") or "",
        "last_login": last_login_str,
        "is_active": bool(row.get("is_active", True)),
        # Onboarding (May 22, 2026) — let admin UI show ✓/✗ per subscriber
        "welcome_sent_at": row.get("welcome_sent_at"),
        "user_configured_at": row.get("user_configured_at"),
        # Primary location (May 23, 2026) — for admin to see at-a-glance
        # which subscribers have real locations vs migrated placeholders
        # like "Lebanon, IN" with default coords. None across all four
        # fields = no saved_locations row exists at all.
        "primary_loc_label":   row.get("primary_loc_label") or "",
        "primary_loc_address": row.get("primary_loc_address") or "",
        "primary_loc_lat":     row.get("primary_loc_lat"),
        "primary_loc_lng":     row.get("primary_loc_lng"),
        "primary_loc_county":  row.get("primary_loc_county") or "",
        # Business grouping (June 2026) — one card per account in the Control
        # Center. account_owner_id groups team members under their primary
        # owner; falls back to the user's own id for owners and solo accounts.
        "business_name":    row.get("business_name") or "",
        "account_owner_id": row.get("account_owner_id") or row["id"],
    }


@app.get("/api/v1/admin/users")
@require_role("admin")
def admin_list_users():
    """List all users with their roles. Returns active and inactive both;
    the frontend handles visual grey-out for inactive ones.

    Phase 3 (May 22, 2026): includes onboarding status for subscribers:
      - welcome_sent_at: when their welcome email was last sent (NULL = never)
      - user_configured_at: when they last saved notification settings
        (NULL = still on defaults from backfill / signup)
    """
    with db() as conn:
        cur = conn.cursor()
        cur.execute("""
            SELECT u.id, u.email, u.name, u.phone, u.created_at, u.last_login_at, u.is_active,
                   u.subscription_tier, u.is_discounted,
                   u.trial_business_name AS business_name,
                   pmm.primary_user_id AS account_owner_id,
                   u.welcome_sent_at,
                   bp.user_configured_at,
                   sc.primary_met_id,
                   met_user.name AS primary_met_name,
                   loc.label        AS primary_loc_label,
                   loc.address_text AS primary_loc_address,
                   loc.lat          AS primary_loc_lat,
                   loc.lng          AS primary_loc_lng,
                   loc.county       AS primary_loc_county,
                   ARRAY_REMOVE(ARRAY_AGG(DISTINCT ur.role ORDER BY ur.role), NULL) AS roles
            FROM users u
            LEFT JOIN user_roles ur ON ur.user_id = u.id
            LEFT JOIN subscriber_coverage sc ON sc.user_id = u.id
            LEFT JOIN users met_user ON met_user.id = sc.primary_met_id
            LEFT JOIN brief_preferences bp ON bp.user_id = u.id
            LEFT JOIN saved_locations loc
              ON loc.user_id = u.id AND loc.is_primary = TRUE
            LEFT JOIN pro_multi_memberships pmm
              ON pmm.member_user_id = u.id AND pmm.status = 'active'
            GROUP BY u.id, sc.primary_met_id, met_user.name, bp.user_configured_at,
                     loc.label, loc.address_text, loc.lat, loc.lng, loc.county,
                     u.trial_business_name, pmm.primary_user_id
            ORDER BY u.is_active DESC, u.created_at DESC
        """)
        rows = cur.fetchall()

    members = [_serialize_user_for_admin(row) for row in rows]
    return jsonify({"ok": True, "members": members})


@app.route("/api/v1/admin/users/<int:user_id>/nudge", methods=["OPTIONS"])
def _admin_nudge_preflight(user_id):
    return ("", 204)


@app.post("/api/v1/admin/users/<int:user_id>/nudge")
@require_role("admin")
def admin_nudge_user(user_id):
    """Send a reminder email to a subscriber who hasn't configured their
    notification settings yet.

    Added May 22, 2026 (Phase 3 onboarding tracking). The admin clicks
    "Nudge" on a row showing ✗ for Settings configured; this fires a
    short email asking the subscriber to log into the portal and set
    their preferred delivery time + channels.

    Idempotency: each call sends a fresh email (no dedupe). If the
    subscriber gets nudged twice it's not great but not harmful.
    Logged to admin_audit_log so we can see who nudged whom.
    """
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.email, u.name, u.phone, u.is_active,
                          bp.user_configured_at
                   FROM users u
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   WHERE u.id = %s""",
                (user_id,),
            )
            sub = cur.fetchone()

    if not sub:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if not sub["is_active"]:
        return jsonify({"ok": False, "error": "user-inactive"}), 400
    if not sub.get("email"):
        return jsonify({"ok": False, "error": "no-email"}), 400

    # Generate a magic link so the subscriber can sign in with one click.
    # (Added May 23, 2026 — many nudged subscribers have "never joined"
    # status: they came in via Stripe checkout but never set a password,
    # so a plain "log into your portal" link would dead-end at the login
    # screen with no clear path forward.)
    #
    # TTL: 72 hours instead of the default 15 minutes. Nudges aren't
    # time-sensitive auth challenges — they can sit in an inbox for a
    # day or two before the subscriber reads them. 72 hours is the
    # balance between "long enough to be useful" and "short enough that
    # an old email isn't a permanent backdoor".
    #
    # Intent: 'new-account' since most nudged users haven't completed
    # account setup. The email framing is "set your password" rather
    # than "sign in", which matches their actual mental state.
    NUDGE_TOKEN_TTL_SECONDS = 72 * 60 * 60  # 72 hours
    raw_token = new_secure_token()
    token_hash = hash_token(raw_token)
    now_secs = now_ts()
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO magic_link_tokens
                       (token_hash, user_id, created_at, expires_at, ip_requested)
                       VALUES (%s, %s, %s, %s, %s)""",
                    (token_hash, sub["id"], now_secs,
                     now_secs + NUDGE_TOKEN_TTL_SECONDS,
                     get_client_ip()),
                )
    except Exception as e:
        print(f"[admin-nudge] token insert failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "token-failed"}), 500

    base_url = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
    magic_link_url = f"{base_url}/?auth=verify&token={raw_token}&intent=new-account"

    subject = "Quick step: set your morning brief delivery time"
    first_name = (sub.get("name") or "").split(" ")[0] or "there"
    body = (
        f"Hi {first_name},\n\n"
        f"We noticed you haven't set your morning brief delivery time and "
        f"notification preferences yet. It only takes a minute and ensures "
        f"your brief arrives exactly when you want it.\n\n"
        f"Click here to sign in and finish setting up your account:\n"
        f"{magic_link_url}\n\n"
        f"(This link signs you in automatically. If you'd like to set or "
        f"change your password, you can do that from Settings once you're in.)\n\n"
        f"Once you're signed in, head to Settings to choose:\n"
        f"  - Preferred delivery time (between 5:00 AM and 10:00 AM local)\n"
        f"  - Email, SMS, or both (you can add or update your phone number\n"
        f"    while you're there if you'd like to get briefs by text)\n\n"
        f"This link is good for 72 hours. If it's expired by the time you "
        f"get to it, just reply and we'll send a fresh one.\n\n"
        f"If you have any questions, just reply to this email.\n\n"
        f"- The WeatherValet team"
    )

    actor = _get_current_user()
    actor_reply_to = actor.get("email") if actor else None
    ok = _send_brief_email(sub["email"], subject, body, reply_to=actor_reply_to)

    # Audit log
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO admin_audit_log
                       (created_at, actor_user_id, actor_name, action, target_kind,
                        target_id, details)
                       VALUES (%s, %s, %s, 'nudge_subscriber', 'user', %s, %s)""",
                    (int(time.time() * 1000),
                     actor["id"] if actor else None,
                     actor.get("name") if actor else "system",
                     user_id,
                     json.dumps({
                         "email": sub["email"],
                         "sent": bool(ok),
                         "magic_link_issued": True,
                         "magic_link_ttl_hours": 72,
                     })),
                )
    except Exception as e:
        print(f"[admin-nudge] audit log failed: {e}", flush=True)

    if not ok:
        return jsonify({"ok": False, "error": "send-failed"}), 502
    return jsonify({"ok": True, "sent_to": sub["email"]})


