# ════════════════════════════════════════════════════════════════════
# Subscriber-provided context for their Met (May 18, 2026)
# ════════════════════════════════════════════════════════════════════
#
# These endpoints let the subscriber write a short personal context
# document that their assigned Met reads when drafting Pro Briefs.
# Fields:
#   business_role        — e.g. "Athletic Director, Lebanon High School"
#   weather_decisions    — e.g. "Outdoor practice scheduling, game-day field conditions"
#   peak_need_times      — e.g. "Tue/Thu practice afternoons, Fri/Sat game days"
#   additional_context   — anything else useful (drainage, lightning policy, etc.)
#
# All fields are optional. The Met workspace + AI brief generator both
# include these when present.

@app.route("/api/v1/me/met-context", methods=["OPTIONS"])
def _me_met_context_preflight():
    return ("", 204)


@app.get("/api/v1/me/met-context")
def me_met_context_get():
    """Return the current user's Met context (business info + needs)."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT business_role, weather_decisions,
                              peak_need_times, additional_context,
                              context_updated_at
                       FROM subscriber_coverage
                       WHERE user_id = %s""",
                    (user["id"],),
                )
                row = cur.fetchone()
    except Exception as e:
        print(f"[me-met-context-get] failed user_id={user['id']}: {e}", flush=True)
        return jsonify({"ok": False, "error": "query-failed"}), 500

    if not row:
        # No coverage row yet (Hobbyist, or new Pro before webhook landed)
        return jsonify({
            "ok": True,
            "business_role": "",
            "weather_decisions": "",
            "peak_need_times": "",
            "additional_context": "",
            "context_updated_at": None,
        })

    return jsonify({
        "ok": True,
        "business_role": row.get("business_role") or "",
        "weather_decisions": row.get("weather_decisions") or "",
        "peak_need_times": row.get("peak_need_times") or "",
        "additional_context": row.get("additional_context") or "",
        "context_updated_at": row.get("context_updated_at"),
    })


@app.post("/api/v1/me/met-context")
def me_met_context_save():
    """Save the current user's Met context. Creates the coverage row
    if missing (for Pro subscribers; Hobbyists also get a row but Met
    assignment fields stay null)."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}
    # Trim and cap lengths so we don't accept abusive input. 2000 chars
    # per field is generous for human-written context.
    def _clean(s, max_len=2000):
        s = (s or "").strip()
        return s[:max_len] if s else ""

    business_role = _clean(data.get("business_role"), 200)
    weather_decisions = _clean(data.get("weather_decisions"), 2000)
    peak_need_times = _clean(data.get("peak_need_times"), 500)
    additional_context = _clean(data.get("additional_context"), 2000)
    now_ms = int(time.time() * 1000)

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # Ensure the row exists. INSERT-on-conflict handles the
                # case where the coverage row was never created (e.g.
                # legacy Hobbyist who's editing their context).
                cur.execute(
                    """INSERT INTO subscriber_coverage
                       (user_id, daily_brief_time, daily_brief_timezone,
                        business_role, weather_decisions, peak_need_times,
                        additional_context, context_updated_at, updated_at)
                       VALUES (%s, '07:00', 'America/New_York',
                               %s, %s, %s, %s, %s, %s)
                       ON CONFLICT (user_id) DO UPDATE SET
                           business_role = EXCLUDED.business_role,
                           weather_decisions = EXCLUDED.weather_decisions,
                           peak_need_times = EXCLUDED.peak_need_times,
                           additional_context = EXCLUDED.additional_context,
                           context_updated_at = EXCLUDED.context_updated_at,
                           updated_at = EXCLUDED.updated_at""",
                    (user["id"], business_role, weather_decisions,
                     peak_need_times, additional_context, now_ms, now_ms),
                )
    except Exception as e:
        print(f"[me-met-context-save] failed user_id={user['id']}: {e}", flush=True)
        return jsonify({"ok": False, "error": "save-failed"}), 500

    return jsonify({
        "ok": True,
        "business_role": business_role,
        "weather_decisions": weather_decisions,
        "peak_need_times": peak_need_times,
        "additional_context": additional_context,
        "context_updated_at": now_ms,
    })


# ════════════════════════════════════════════════════════════════════
# Pro Multi team memberships (May 20, 2026)
# ════════════════════════════════════════════════════════════════════
#
# For Pro Multi subscribers ($1,200/mo flat fee), the primary subscriber
# can add team members at no extra cost. Each team member:
#   - Has their own login (own email, own password, own phone)
#   - Has their own brief delivery preferences (text/email channels)
#   - Has their own Pro Thread with the Met team
#   - Receives the same briefs the primary receives, delivered via
#     their personal channel preferences
#   - Cannot see other team members' Pro Threads
#   - Cannot invite more team members (only the primary can)
#   - Cannot see billing details (only the primary can)
#
# Endpoints:
#   GET    /api/v1/me/team                     — list team members (primary only)
#   POST   /api/v1/me/team/invite              — invite a new team member
#   DELETE /api/v1/me/team/<member_id>         — remove a team member
#
# Status values:
#   'pending'  — invite sent, member has not signed in yet
#   'active'   — member has accepted (logged in via magic link)
#   'removed'  — primary removed them; row kept for audit


# Tier defaults for team-member caps. Matches the pricing page:
#   Pro Single → 3 team members
#   Pro Multi  → 10 team members
# Pro Enterprise is open-ended; default it generously and rely on the
# admin override for anything past that.
# Updated May 23, 2026 — was hardcoded at 25 across the board. Now
# tier-aware so the system actually matches what we sell.
TEAM_CAP_BY_TIER = {
    "pro_single":     3,
    "pro_multi":      10,
    "pro_enterprise": 25,
}


def _team_cap_for_user(user_id: int, tier: str) -> int:
    """Resolve the effective team-member cap for this user.

    Priority:
      1. users.team_cap_override (admin-granted, supersedes everything)
      2. TEAM_CAP_BY_TIER[tier] (matches pricing page)
      3. 0 (no tier match → not allowed)
    """
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT team_cap_override FROM users WHERE id = %s",
                    (user_id,),
                )
                row = cur.fetchone()
                if row and row.get("team_cap_override") is not None:
                    return int(row["team_cap_override"])
    except Exception as e:
        print(f"[team-cap] override lookup failed user={user_id}: {e!r}", flush=True)
    return TEAM_CAP_BY_TIER.get((tier or "").lower(), 0)


# Set of tiers where team-member management is available at all.
# Marketing page commits Pro Single + Pro Multi (and we honor existing
# Pro Enterprise the same way). Updated May 23, 2026 — was Pro Multi only.
TEAM_ELIGIBLE_TIERS = {"pro_single", "pro_multi", "pro_enterprise"}


@app.route("/api/v1/me/team", methods=["OPTIONS"])
def _me_team_preflight():
    return ("", 204)


@app.get("/api/v1/me/team")
def me_team_list():
    """List team members for the calling Pro Multi subscriber.
    
    Returns 403 for non-Pro-Multi subscribers (this isn't their feature).
    Returns the list of (pending + active) members with their names,
    emails, role labels, and status.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    # Pro Single + Pro Multi (and Pro Enterprise) can manage teams.
    # Updated May 23, 2026 — was Pro Multi only, but the pricing page
    # commits Pro Single to "up to 3 users" as well.
    tier = (user.get("subscription_tier") or "").lower()
    if tier not in TEAM_ELIGIBLE_TIERS:
        return jsonify({
            "ok": False,
            "error": "not-team-eligible",
            "message": "Team members are a Pro feature. Your current tier doesn't include this.",
        }), 403

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT pmm.id AS membership_id,
                              pmm.member_user_id,
                              pmm.role_label,
                              pmm.status,
                              pmm.invited_at,
                              pmm.accepted_at,
                              u.name AS member_name,
                              u.email AS member_email,
                              u.phone AS member_phone
                       FROM pro_multi_memberships pmm
                       JOIN users u ON u.id = pmm.member_user_id
                       WHERE pmm.primary_user_id = %s
                         AND pmm.status IN ('pending', 'active')
                       ORDER BY pmm.invited_at DESC""",
                    (user["id"],),
                )
                rows = cur.fetchall()
    except Exception as e:
        print(f"[team-list] failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500

    return jsonify({
        "ok": True,
        "tier": tier,
        "cap": _team_cap_for_user(user["id"], tier),
        "team": [{
            "membership_id": r["membership_id"],
            "member_user_id": r["member_user_id"],
            "name": r["member_name"] or "",
            "email": r["member_email"] or "",
            "phone": r["member_phone"] or "",
            "role_label": r["role_label"] or "",
            "status": r["status"],
            "invited_at": r["invited_at"],
            "accepted_at": r["accepted_at"],
        } for r in rows]
    })


@app.route("/api/v1/me/team/invite", methods=["OPTIONS"])
def _me_team_invite_preflight():
    return ("", 204)


@app.post("/api/v1/me/team/invite")
def me_team_invite():
    """Invite a new team member.

    Body:
      {
        "email": "member@example.com",
        "name": "Member Name",
        "phone": "+13175551234",      // optional
        "role_label": "Assistant Coach" // optional, shown to Met for context
      }

    Behavior:
      1. Validate primary is Pro Multi
      2. Validate not at 25-member cap
      3. Create or update the member's user row (active=true, no password)
      4. Grant subscriber role to the member
      5. Create the membership row (status='pending')
      6. Send the member a magic-link invitation email (intent='team-invite')
      7. Return success

    Idempotency: if the email is already a team member (active or pending)
    of THIS primary, return the existing membership.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    tier = (user.get("subscription_tier") or "").lower()
    if tier not in TEAM_ELIGIBLE_TIERS:
        return jsonify({
            "ok": False,
            "error": "not-team-eligible",
            "message": "Team invites are a Pro feature.",
        }), 403

    data = request.get_json(silent=True) or {}
    member_email = (data.get("email") or "").strip().lower()
    if not member_email or "@" not in member_email:
        return jsonify({"ok": False, "error": "invalid-email"}), 400
    member_name = (data.get("name") or "").strip()
    if not member_name:
        return jsonify({"ok": False, "error": "missing-name"}), 400
    member_phone = (data.get("phone") or "").strip() or None
    role_label = (data.get("role_label") or "").strip() or None

    # Prevent self-invite
    primary_email = (user.get("email") or "").lower()
    if member_email == primary_email:
        return jsonify({
            "ok": False,
            "error": "self-invite",
            "message": "You can't invite yourself.",
        }), 400

    now_ms = int(time.time() * 1000)

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # ── Check team-size cap (tier-aware May 23, 2026) ─────
                # Pro Single: 3, Pro Multi: 10, Enterprise: 25.
                # users.team_cap_override (admin-set) supersedes the tier
                # default if non-null.
                effective_cap = _team_cap_for_user(user["id"], tier)
                cur.execute(
                    """SELECT COUNT(*) AS n FROM pro_multi_memberships
                       WHERE primary_user_id = %s
                         AND status IN ('pending', 'active')""",
                    (user["id"],),
                )
                current_count = cur.fetchone()["n"]
                if current_count >= effective_cap:
                    return jsonify({
                        "ok": False,
                        "error": "team-cap-reached",
                        "message": (
                            f"You've reached your team cap of {effective_cap} "
                            f"member{'s' if effective_cap != 1 else ''}. "
                            f"Remove an inactive member to add a new one, "
                            f"or contact support to upgrade your plan."
                        ),
                    }), 400

                # ── Create or update member's user row ────────────────
                cur.execute(
                    "SELECT id FROM users WHERE LOWER(email) = LOWER(%s)",
                    (member_email,),
                )
                existing = cur.fetchone()
                if existing:
                    member_user_id = existing["id"]
                    # Update name/phone if provided, mark active, and give
                    # the member the primary's subscription tier so they are
                    # a full subscriber: their own location gets its own
                    # daily brief, alerts, and Met messaging. The primary's
                    # plan is what pays for it.
                    cur.execute(
                        """UPDATE users SET
                             name = COALESCE(NULLIF(%s, ''), name),
                             phone = COALESCE(NULLIF(%s, ''), phone),
                             subscription_tier = COALESCE(subscription_tier, %s),
                             is_active = TRUE
                           WHERE id = %s""",
                        (member_name, member_phone, tier, member_user_id),
                    )
                else:
                    cur.execute(
                        """INSERT INTO users
                             (email, name, phone, subscription_tier, created_at,
                              is_active, password_must_change)
                           VALUES (%s, %s, %s, %s, %s, TRUE, TRUE)
                           RETURNING id""",
                        (member_email, member_name, member_phone, tier, now_ms),
                    )
                    member_user_id = cur.fetchone()["id"]

                # ── Grant subscriber role ─────────────────────────────
                cur.execute(
                    """INSERT INTO user_roles (user_id, role, granted_at)
                       VALUES (%s, 'subscriber', %s)
                       ON CONFLICT DO NOTHING""",
                    (member_user_id, now_ms),
                )

                # ── Check for existing membership (idempotency) ───────
                cur.execute(
                    """SELECT id, status FROM pro_multi_memberships
                       WHERE primary_user_id = %s AND member_user_id = %s""",
                    (user["id"], member_user_id),
                )
                existing_membership = cur.fetchone()
                if existing_membership:
                    if existing_membership["status"] in ("pending", "active"):
                        return jsonify({
                            "ok": True,
                            "membership_id": existing_membership["id"],
                            "already_member": True,
                            "message": f"{member_name} is already on your team.",
                        })
                    else:
                        # Re-activate a previously-removed membership
                        cur.execute(
                            """UPDATE pro_multi_memberships SET
                                 status = 'pending',
                                 role_label = COALESCE(%s, role_label),
                                 invited_at = %s,
                                 accepted_at = NULL,
                                 removed_at = NULL,
                                 invited_by_user_id = %s
                               WHERE id = %s""",
                            (role_label, now_ms, user["id"], existing_membership["id"]),
                        )
                        membership_id = existing_membership["id"]
                else:
                    # New membership
                    cur.execute(
                        """INSERT INTO pro_multi_memberships
                             (primary_user_id, member_user_id, role_label,
                              status, invited_at, invited_by_user_id)
                           VALUES (%s, %s, %s, 'pending', %s, %s)
                           RETURNING id""",
                        (user["id"], member_user_id, role_label, now_ms, user["id"]),
                    )
                    membership_id = cur.fetchone()["id"]
    except Exception as e:
        print(f"[team-invite] failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500

    # ── Send invitation email with 7-day magic link ───────────────
    magic_link_sent = False
    try:
        raw_token = new_secure_token()
        token_hash = hash_token(raw_token)
        seven_days_seconds = 7 * 24 * 60 * 60
        now_seconds = int(time.time())
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO magic_link_tokens
                         (token_hash, user_id, created_at, expires_at, ip_requested)
                       VALUES (%s, %s, %s, %s, %s)""",
                    (token_hash, member_user_id, now_seconds,
                     now_seconds + seven_days_seconds, "team-invite"),
                )
        base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai")
        magic_link_url = f"{base}/?auth=verify&token={raw_token}&intent=team-invite"
        primary_name = user.get("name") or "your team lead"
        if _send_team_invite_email(member_email, magic_link_url,
                                   primary_name=primary_name,
                                   member_name=member_name):
            magic_link_sent = True
            # Record that a working invite went out, so the self-healing
            # job does not re-send and the UI can show invite status.
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            "UPDATE pro_multi_memberships SET invite_sent_at = %s WHERE id = %s",
                            (now_ts(), membership_id),
                        )
            except Exception as e:
                print(f"[team-invite] stamp invite_sent_at failed: {e!r}", flush=True)
    except Exception as e:
        print(f"[team-invite] email failed: {e!r}", flush=True)

    return jsonify({
        "ok": True,
        "membership_id": membership_id,
        "member_user_id": member_user_id,
        "magic_link_sent": magic_link_sent,
    })


@app.route("/api/v1/me/team/<int:membership_id>", methods=["OPTIONS"])
def _me_team_delete_preflight(membership_id):
    return ("", 204)


@app.delete("/api/v1/me/team/<int:membership_id>")
def me_team_remove(membership_id: int):
    """Remove a team member from the calling primary's team.

    Soft-delete: sets status='removed' and removed_at timestamp. The
    member's user account remains (they keep their login, can still
    receive briefs from any OTHER team they may be on, etc.) but no
    longer receives this team's briefs.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    tier = (user.get("subscription_tier") or "").lower()
    if tier not in TEAM_ELIGIBLE_TIERS:
        return jsonify({"ok": False, "error": "not-team-eligible"}), 403

    now_ms = int(time.time() * 1000)

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE pro_multi_memberships SET
                         status = 'removed',
                         removed_at = %s
                       WHERE id = %s
                         AND primary_user_id = %s
                       RETURNING id""",
                    (now_ms, membership_id, user["id"]),
                )
                row = cur.fetchone()
                if not row:
                    return jsonify({"ok": False, "error": "not-found"}), 404
    except Exception as e:
        print(f"[team-remove] failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500

    return jsonify({"ok": True})


def _send_membership_invite(membership_id: int) -> bool:
    """Mint a fresh 7-day magic link for a pending team member and send the
    invite email. Stamps invite_sent_at on success. Shared by the manual
    "Resend invite" action and the self-healing scheduler job.

    Returns True if the invite email was accepted by Resend.
    """
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT m.id, m.member_user_id, m.status,
                              mu.email AS member_email, mu.name AS member_name,
                              pu.name AS primary_name
                       FROM pro_multi_memberships m
                       JOIN users mu ON mu.id = m.member_user_id
                       JOIN users pu ON pu.id = m.primary_user_id
                       WHERE m.id = %s""",
                    (membership_id,),
                )
                row = cur.fetchone()
        if not row or not row.get("member_email"):
            return False

        now_seconds = now_ts()
        seven_days_seconds = 7 * 24 * 60 * 60
        raw_token = new_secure_token()
        token_hash = hash_token(raw_token)
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO magic_link_tokens
                         (token_hash, user_id, created_at, expires_at, ip_requested)
                       VALUES (%s, %s, %s, %s, %s)""",
                    (token_hash, row["member_user_id"], now_seconds,
                     now_seconds + seven_days_seconds, "team-invite-resend"),
                )
        base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai")
        magic_link_url = f"{base}/?auth=verify&token={raw_token}&intent=team-invite"
        primary_name = row.get("primary_name") or "your team lead"
        member_name = row.get("member_name") or "there"
        if _send_team_invite_email(row["member_email"], magic_link_url,
                                   primary_name=primary_name,
                                   member_name=member_name):
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE pro_multi_memberships SET invite_sent_at = %s WHERE id = %s",
                        (now_seconds, membership_id),
                    )
            return True
        return False
    except Exception as e:
        print(f"[membership-invite] send failed for membership={membership_id}: {e!r}", flush=True)
        return False


@app.route("/api/v1/me/team/<int:membership_id>/resend-invite", methods=["OPTIONS"])
def _me_team_resend_preflight(membership_id):
    return ("", 204)


@app.post("/api/v1/me/team/<int:membership_id>/resend-invite")
def me_team_resend_invite(membership_id: int):
    """Resend the invite email to a pending team member. Owner-only."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    tier = (user.get("subscription_tier") or "").lower()
    if tier not in TEAM_ELIGIBLE_TIERS:
        return jsonify({"ok": False, "error": "not-team-eligible"}), 403

    # Verify the membership belongs to THIS primary and is still pending.
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT id, status FROM pro_multi_memberships
                       WHERE id = %s AND primary_user_id = %s""",
                    (membership_id, user["id"]),
                )
                row = cur.fetchone()
    except Exception as e:
        print(f"[team-resend] lookup failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500
    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if row.get("status") == "removed":
        return jsonify({"ok": False, "error": "removed"}), 400

    if _send_membership_invite(membership_id):
        return jsonify({"ok": True, "sent": True})
    return jsonify({"ok": False, "error": "send-failed",
                    "message": "We couldn't send the invite just now. Please try again in a moment."}), 502

def _send_team_invite_email(email: str, magic_link_url: str,
                            primary_name: str, member_name: str) -> bool:
    """Send a team invite email. Returns True if Resend accepted the request.

    The email is shorter than a regular magic-link email — focused on
    "you've been added to the X team on WeatherValet" framing rather
    than "set your password."
    """
    if not RESEND_API_KEY:
        print("[team-invite-email] RESEND_API_KEY not set, skipping", flush=True)
        return False
    try:
        subject = f"You've been added to {primary_name}'s WeatherValet team"
        html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#F8F9FB;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#0E1116;">
  <div style="max-width:560px;margin:32px auto;padding:32px 28px;background:#fff;border-radius:12px;box-shadow:0 1px 3px rgba(15,17,22,0.06);">
    <h1 style="font-size:22px;font-weight:600;margin:0 0 16px;">Hi {member_name},</h1>
    <p style="font-size:15px;line-height:1.55;color:rgba(15,17,22,0.75);margin:0 0 14px;">
      {primary_name} has added you to their WeatherValet team, and it is all set up and paid for. You get your own account with daily Meteorologist briefs and severe weather alerts for your own location, plus you can message your Meteorologist directly. Use it for work and for your own life.
    </p>
    <div style="text-align:center;margin:24px 0;">
      <a href="{magic_link_url}" style="display:inline-block;background:#2E4FB8;color:#fff;text-decoration:none;padding:13px 28px;border-radius:8px;font-weight:600;font-size:15px;">Set your password</a>
    </div>
    <div style="background:#F4F6FB;border:1px solid #DCE3F5;border-radius:10px;padding:18px 20px;margin:0 0 22px;">
      <p style="color:#0E1116;font-size:15px;font-weight:700;margin:0 0 12px;">Your quick start list</p>
      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">
        <tr><td style="vertical-align:top;padding:0 10px 14px 0;color:#2E4FB8;font-size:14px;font-weight:700;">1.</td>
          <td style="padding:0 0 14px;color:#3D4148;font-size:13.5px;line-height:1.6;"><b style="color:#0E1116;">Set your password.</b> Tap the button above to set your password and sign in.</td></tr>
        <tr><td style="vertical-align:top;padding:0 10px 14px 0;color:#2E4FB8;font-size:14px;font-weight:700;">2.</td>
          <td style="padding:0 0 14px;color:#3D4148;font-size:13.5px;line-height:1.6;"><b style="color:#0E1116;">Save your location. This one is required.</b> Without it, we cannot send your forecasts or alerts. On your account page, find Saved location and enter your zip code, then click Save location.</td></tr>
        <tr><td style="vertical-align:top;padding:0 10px 14px 0;color:#2E4FB8;font-size:14px;font-weight:700;">3.</td>
          <td style="padding:0 0 14px;color:#3D4148;font-size:13.5px;line-height:1.6;"><b style="color:#0E1116;">Pick your morning brief time.</b> Choose when your daily forecast arrives, written just for your location.</td></tr>
        <tr><td style="vertical-align:top;padding:0 10px 0 0;color:#2E4FB8;font-size:14px;font-weight:700;">4.</td>
          <td style="padding:0;color:#3D4148;font-size:13.5px;line-height:1.6;"><b style="color:#0E1116;">Say hello to your Meteorologist.</b> Send a quick message about who you are and the weather decisions that matter most to you.</td></tr>
      </table>
      <p style="color:#6B7280;font-size:12.5px;line-height:1.5;margin:14px 0 0;">Your account page walks you through each step. This link is valid for 7 days.</p>
    </div>
    <p style="font-size:13px;line-height:1.55;color:rgba(15,17,22,0.55);margin:0;">
      Questions? Just reply to this email and a human will read it.
    </p>
  </div>
</body></html>"""
        text = (f"Hi {member_name},\n\n"
                f"{primary_name} has added you to their WeatherValet team, and "
                "it is all set up and paid for. You get your own account with "
                "daily Meteorologist briefs and severe weather alerts for your "
                "own location, plus you can message your Meteorologist directly. "
                "Use it for work and for your own life.\n\n"
                f"Set your password: {magic_link_url}\n\n"
                "YOUR QUICK START LIST\n"
                "1. Set your password. Tap the link above to set your password and sign in.\n"
                "2. Save your location. This one is required. Without it, we cannot "
                "send your forecasts or alerts. On your account page, find Saved "
                "location and enter your zip code, then click Save location.\n"
                "3. Pick your morning brief time. Choose when your daily forecast "
                "arrives, written just for your location.\n"
                "4. Say hello to your Meteorologist. Send a quick message about who "
                "you are and the weather decisions that matter most to you.\n\n"
                "Your account page walks you through each step. This link is valid "
                "for 7 days. Questions? Just reply to this email and a human will read it.")
        from_addr = os.environ.get("EMAIL_FROM", "").strip() or "WeatherValet <hello@weathervalet.ai>"
        payload = json.dumps({
            "from": from_addr,
            "to": [email],
            "subject": subject,
            "html": html,
            "text": text,
        }).encode("utf-8")
        req = urllib.request.Request(
            "https://api.resend.com/emails",
            data=payload,
            method="POST",
            headers={
                "Authorization": f"Bearer {RESEND_API_KEY}",
                "Content-Type": "application/json",
                "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)",
            },
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                return True
            print(f"[team-invite-email] Resend returned status {resp.status}", flush=True)
            return False
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            pass
        print(f"[team-invite-email] Resend HTTPError {e.code}: {body}", flush=True)
        return False
    except Exception as e:
        print(f"[team-invite-email] failed: {e!r}", flush=True)
        return False


@app.get("/api/v1/me/brief-preferences")
def me_brief_preferences():
    """Return the current user's brief delivery preferences.

    Auto-creates a row with sensible defaults on first read so the
    portal always has something to display.

    Returns:
        200 {"ok": true, "preferences": {...}}
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    now_ms = int(time.time() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT user_id, morning_enabled, morning_window_start,
                          morning_window_end, evening_enabled,
                          evening_window_start, evening_window_end,
                          quiet_start, quiet_end, channels, updated_at
                   FROM brief_preferences WHERE user_id = %s""",
                (user["id"],),
            )
            row = cur.fetchone()

            if row is None:
                # Insert default row
                cur.execute(
                    """INSERT INTO brief_preferences (user_id, updated_at)
                       VALUES (%s, %s)
                       ON CONFLICT (user_id) DO NOTHING
                       RETURNING user_id, morning_enabled, morning_window_start,
                                 morning_window_end, evening_enabled,
                                 evening_window_start, evening_window_end,
                                 quiet_start, quiet_end, channels, updated_at""",
                    (user["id"], now_ms),
                )
                row = cur.fetchone()
                # Fallback: in case ON CONFLICT happened (race), re-fetch
                if row is None:
                    cur.execute(
                        """SELECT user_id, morning_enabled, morning_window_start,
                                  morning_window_end, evening_enabled,
                                  evening_window_start, evening_window_end,
                                  quiet_start, quiet_end, channels, updated_at
                           FROM brief_preferences WHERE user_id = %s""",
                        (user["id"],),
                    )
                    row = cur.fetchone()

    if row is None:
        return jsonify({"ok": False, "error": "preferences-unavailable"}), 500

    return jsonify({
        "ok": True,
        "preferences": {
            "morning_enabled":      row["morning_enabled"],
            "morning_window_start": row["morning_window_start"],
            "morning_window_end":   row["morning_window_end"],
            "evening_enabled":      row["evening_enabled"],
            "evening_window_start": row["evening_window_start"],
            "evening_window_end":   row["evening_window_end"],
            "quiet_start":          row["quiet_start"],
            "quiet_end":            row["quiet_end"],
            "channels":             [c for c in (row["channels"] or "").split(",") if c],
            "updated_at":           row["updated_at"],
        },
    })


