@app.route("/api/v1/admin/subscribers/<int:user_id>/coverage", methods=["OPTIONS"])
def _admin_assign_coverage_preflight(user_id):
    return ("", 204)


@app.post("/api/v1/admin/subscribers/<int:user_id>/coverage")
def admin_assign_coverage(user_id):
    """Set or update a subscriber's primary/backup Met assignment.

    Body: {
      "primary_met_id": 5,           // optional, can be null to clear
      "backup_met_id": 7,            // optional, can be null
      "daily_brief_time": "06:30",   // optional, HH:MM 24h
      "daily_brief_timezone": "America/Chicago"  // optional
    }

    Creates the subscriber_coverage row if missing. Validates that
    assigned Mets actually have the 'met' or 'admin' role.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}
    primary_met_id = data.get("primary_met_id")  # may be None to clear
    backup_met_id = data.get("backup_met_id")
    daily_brief_time = (data.get("daily_brief_time") or "").strip()
    daily_brief_timezone = (data.get("daily_brief_timezone") or "").strip()

    # Validate the assigned Mets actually exist and have the right role
    def _validate_met(met_id):
        if met_id is None:
            return True
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT 1 FROM user_roles
                           WHERE user_id = %s AND role IN ('met', 'admin') LIMIT 1""",
                        (met_id,),
                    )
                    return cur.fetchone() is not None
        except Exception:
            return False

    if primary_met_id is not None and not _validate_met(primary_met_id):
        return jsonify({"ok": False, "error": "invalid-primary-met"}), 400
    if backup_met_id is not None and not _validate_met(backup_met_id):
        return jsonify({"ok": False, "error": "invalid-backup-met"}), 400

    # Validate the user exists and is a subscriber
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'subscriber'
                   WHERE u.id = %s AND u.is_active = TRUE""",
                (user_id,),
            )
            if not cur.fetchone():
                return jsonify({"ok": False, "error": "subscriber-not-found"}), 404

    # Validate time format if provided
    if daily_brief_time and not re.match(r"^\d{2}:\d{2}$", daily_brief_time):
        return jsonify({"ok": False, "error": "invalid-time-format"}), 400

    # Build the upsert. Use COALESCE to preserve existing values when
    # the request omits a field.
    try:
        now_ms = int(time.time() * 1000)
        with db() as conn:
            with conn.cursor() as cur:
                # Ensure a row exists
                cur.execute(
                    """INSERT INTO subscriber_coverage
                       (user_id, daily_brief_time, daily_brief_timezone, updated_at)
                       VALUES (%s, '07:00', 'America/New_York', %s)
                       ON CONFLICT (user_id) DO NOTHING""",
                    (user_id, now_ms),
                )
                # Build SET clauses for the fields we have
                set_parts = ["updated_at = %s"]
                params: list = [now_ms]
                # primary_met_id: always update (None clears it)
                if "primary_met_id" in data:
                    set_parts.append("primary_met_id = %s")
                    params.append(primary_met_id)
                if "backup_met_id" in data:
                    set_parts.append("backup_met_id = %s")
                    params.append(backup_met_id)
                if daily_brief_time:
                    set_parts.append("daily_brief_time = %s")
                    params.append(daily_brief_time)
                if daily_brief_timezone:
                    set_parts.append("daily_brief_timezone = %s")
                    params.append(daily_brief_timezone)
                params.append(user_id)
                cur.execute(
                    f"""UPDATE subscriber_coverage
                        SET {', '.join(set_parts)}
                        WHERE user_id = %s""",
                    params,
                )

                # Return the updated row
                cur.execute(
                    """SELECT sc.*, pm.name AS primary_met_name, pm.email AS primary_met_email,
                              bm.name AS backup_met_name, bm.email AS backup_met_email
                       FROM subscriber_coverage sc
                       LEFT JOIN users pm ON pm.id = sc.primary_met_id
                       LEFT JOIN users bm ON bm.id = sc.backup_met_id
                       WHERE sc.user_id = %s""",
                    (user_id,),
                )
                row = cur.fetchone()
    except Exception as e:
        print(f"[admin-assign-coverage] failed user_id={user_id}: {e}", flush=True)
        return jsonify({"ok": False, "error": "update-failed"}), 500

    # Audit log
    try:
        _audit_log(
            actor_user_id=user["id"],
            actor_name=user.get("name") or user.get("email") or "admin",
            action="subscriber-coverage-update",
            target_type="user",
            target_id=user_id,
            details={
                "primary_met_id": primary_met_id,
                "backup_met_id": backup_met_id,
                "daily_brief_time": daily_brief_time or None,
                "daily_brief_timezone": daily_brief_timezone or None,
            },
        )
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "coverage": {
            "user_id": row["user_id"],
            "primary_met_id": row.get("primary_met_id"),
            "primary_met_name": row.get("primary_met_name") or "",
            "backup_met_id": row.get("backup_met_id"),
            "backup_met_name": row.get("backup_met_name") or "",
            "daily_brief_time": row.get("daily_brief_time") or "07:00",
            "daily_brief_timezone": row.get("daily_brief_timezone") or "America/New_York",
        }
    })


# ════════════════════════════════════════════════════════════════════
# Subscriber portal — write endpoints (Phase 10 Chunk B1)
# ════════════════════════════════════════════════════════════════════
#
# PATCH brief preferences, plus CRUD for threshold alerts.
# Saved-location writes come in Chunk B2 (needs geocoding helper).

@app.patch("/api/v1/me/brief-preferences")
def me_brief_preferences_update():
    """Patch the current user's brief delivery preferences.

    Accepts a partial body — only the fields present in the request
    are updated. The rest stay as-is. Returns the full updated row.

    Validates time strings as HH:MM and channels as a list of allowed
    values ('sms', 'email', 'push'). Rejects unknown fields silently.

    Request body (all optional):
        {
          "morning_enabled": true,
          "morning_window_start": "05:30",
          "morning_window_end":   "07:00",
          "evening_enabled": false,
          "evening_window_start": "17:30",
          "evening_window_end":   "18:30",
          "quiet_start": "21:00",
          "quiet_end":   "05:00",
          "channels": ["sms", "email"]
        }

    Returns:
        200 {"ok": true, "preferences": {...}}  (full updated row)
        400 {"ok": false, "error": "invalid-..."}
        401 not authenticated
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}
    now_ms = int(time.time() * 1000)

    # Validate time strings as HH:MM (00-23 : 00-59)
    def _valid_time(s):
        if not isinstance(s, str): return False
        if len(s) != 5 or s[2] != ':': return False
        try:
            h, m = int(s[:2]), int(s[3:])
            return 0 <= h <= 23 and 0 <= m <= 59
        except (ValueError, TypeError):
            return False

    # Build dynamic SET clause from present fields
    set_clauses = []
    params = []

    if "morning_enabled" in data:
        set_clauses.append("morning_enabled = %s")
        params.append(bool(data["morning_enabled"]))

    if "morning_window_start" in data:
        if not _valid_time(data["morning_window_start"]):
            return jsonify({"ok": False, "error": "invalid-morning-start"}), 400
        set_clauses.append("morning_window_start = %s")
        params.append(data["morning_window_start"])

    if "morning_window_end" in data:
        if not _valid_time(data["morning_window_end"]):
            return jsonify({"ok": False, "error": "invalid-morning-end"}), 400
        set_clauses.append("morning_window_end = %s")
        params.append(data["morning_window_end"])

    if "evening_enabled" in data:
        set_clauses.append("evening_enabled = %s")
        params.append(bool(data["evening_enabled"]))

    if "evening_window_start" in data:
        v = data["evening_window_start"]
        if v is None or v == "":
            set_clauses.append("evening_window_start = NULL")
        elif _valid_time(v):
            set_clauses.append("evening_window_start = %s")
            params.append(v)
        else:
            return jsonify({"ok": False, "error": "invalid-evening-start"}), 400

    if "evening_window_end" in data:
        v = data["evening_window_end"]
        if v is None or v == "":
            set_clauses.append("evening_window_end = NULL")
        elif _valid_time(v):
            set_clauses.append("evening_window_end = %s")
            params.append(v)
        else:
            return jsonify({"ok": False, "error": "invalid-evening-end"}), 400

    if "quiet_start" in data:
        if not _valid_time(data["quiet_start"]):
            return jsonify({"ok": False, "error": "invalid-quiet-start"}), 400
        set_clauses.append("quiet_start = %s")
        params.append(data["quiet_start"])

    if "quiet_end" in data:
        if not _valid_time(data["quiet_end"]):
            return jsonify({"ok": False, "error": "invalid-quiet-end"}), 400
        set_clauses.append("quiet_end = %s")
        params.append(data["quiet_end"])

    if "channels" in data:
        ch = data["channels"]
        if not isinstance(ch, list):
            return jsonify({"ok": False, "error": "invalid-channels"}), 400
        ALLOWED = {"sms", "email", "push"}
        clean = [c for c in ch if isinstance(c, str) and c in ALLOWED]
        if not clean:
            return jsonify({"ok": False, "error": "no-valid-channels"}), 400
        set_clauses.append("channels = %s")
        params.append(",".join(clean))

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    # Always bump updated_at
    set_clauses.append("updated_at = %s")
    params.append(now_ms)

    # Ensure row exists first (auto-create with defaults), then update
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO brief_preferences (user_id, updated_at)
                   VALUES (%s, %s)
                   ON CONFLICT (user_id) DO NOTHING""",
                (user["id"], now_ms),
            )
            params.append(user["id"])
            cur.execute(
                f"UPDATE brief_preferences SET {', '.join(set_clauses)} "
                f"WHERE user_id = %s",
                tuple(params),
            )
            cur.execute(
                """SELECT user_id, morning_enabled, morning_window_start,
                          morning_window_end, evening_enabled,
                          evening_window_start, evening_window_end,
                          quiet_start, quiet_end, channels, updated_at
                   FROM brief_preferences WHERE user_id = %s""",
                (user["id"],),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "preferences": {
            "morning_enabled":      row["morning_enabled"],
            "morning_window_start": row["morning_window_start"],
            "morning_window_end":   row["morning_window_end"],
            "evening_enabled":      row["evening_enabled"],
            "evening_window_start": row["evening_window_start"],
            "evening_window_end":   row["evening_window_end"],
            "quiet_start":          row["quiet_start"],
            "quiet_end":            row["quiet_end"],
            "channels":             [c for c in (row["channels"] or "").split(",") if c],
            "updated_at":           row["updated_at"],
        },
    })


@app.post("/api/v1/me/threshold-alerts")
def me_threshold_alerts_create():
    """Create a new threshold alert for the current user.

    Request body:
        {
          "metric": "wind" | "temp_low" | "temp_high" | "precip_chance" | "humidity",
          "comparator": "gt" | "lt" | "gte" | "lte" | "eq",
          "threshold_value": 25,
          "units": "mph" | "F" | "C" | "pct",
          "channels": ["sms", "email"],   (optional, defaults to ["sms","email"])
          "enabled": true                  (optional, defaults to true)
        }

    Returns:
        200 {"ok": true, "alert": {...}}
        400 invalid field
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}

    ALLOWED_METRICS = {"wind", "temp_low", "temp_high", "heat_index", "precip_chance", "rain_amount", "snow_amount", "humidity"}
    ALLOWED_COMPS = {"gt", "lt", "gte", "lte", "eq"}
    ALLOWED_UNITS = {"mph", "F", "C", "pct", "in"}
    ALLOWED_CHANNELS = {"sms", "email", "push"}

    metric = (data.get("metric") or "").strip()
    if metric not in ALLOWED_METRICS:
        return jsonify({"ok": False, "error": "invalid-metric"}), 400

    comparator = (data.get("comparator") or "").strip()
    if comparator not in ALLOWED_COMPS:
        return jsonify({"ok": False, "error": "invalid-comparator"}), 400

    try:
        threshold_value = float(data.get("threshold_value"))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "invalid-threshold-value"}), 400

    units = (data.get("units") or "").strip()
    if units not in ALLOWED_UNITS:
        return jsonify({"ok": False, "error": "invalid-units"}), 400

    channels_raw = data.get("channels") or ["sms", "email"]
    if not isinstance(channels_raw, list):
        return jsonify({"ok": False, "error": "invalid-channels"}), 400
    channels = [c for c in channels_raw if isinstance(c, str) and c in ALLOWED_CHANNELS]
    if not channels:
        return jsonify({"ok": False, "error": "no-valid-channels"}), 400

    enabled = bool(data.get("enabled", True))
    now_ms = int(time.time() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO threshold_alerts
                   (user_id, metric, comparator, threshold_value, units,
                    channels, enabled, created_at, updated_at)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                   RETURNING id, metric, comparator, threshold_value, units,
                             channels, enabled, created_at, updated_at""",
                (user["id"], metric, comparator, threshold_value, units,
                 ",".join(channels), enabled, now_ms, now_ms),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "alert": {
            "id": row["id"],
            "metric": row["metric"],
            "comparator": row["comparator"],
            "threshold_value": row["threshold_value"],
            "units": row["units"],
            "channels": [c for c in (row["channels"] or "").split(",") if c],
            "enabled": row["enabled"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
    })


@app.route("/api/v1/me/threshold-alerts/<int:alert_id>", methods=["OPTIONS"])
def _me_threshold_alert_id_preflight(alert_id):
    return ("", 204)


@app.patch("/api/v1/me/threshold-alerts/<int:alert_id>")
def me_threshold_alerts_update(alert_id):
    """Update an existing threshold alert.

    Same field validation as create. All fields optional (partial update).
    Only the alert's owner can update it.

    Returns:
        200 {"ok": true, "alert": {...}}
        404 alert not found or not owned by current user
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}

    ALLOWED_METRICS = {"wind", "temp_low", "temp_high", "heat_index", "precip_chance", "rain_amount", "snow_amount", "humidity"}
    ALLOWED_COMPS = {"gt", "lt", "gte", "lte", "eq"}
    ALLOWED_UNITS = {"mph", "F", "C", "pct", "in"}
    ALLOWED_CHANNELS = {"sms", "email", "push"}

    set_clauses = []
    params = []

    if "metric" in data:
        if data["metric"] not in ALLOWED_METRICS:
            return jsonify({"ok": False, "error": "invalid-metric"}), 400
        set_clauses.append("metric = %s")
        params.append(data["metric"])

    if "comparator" in data:
        if data["comparator"] not in ALLOWED_COMPS:
            return jsonify({"ok": False, "error": "invalid-comparator"}), 400
        set_clauses.append("comparator = %s")
        params.append(data["comparator"])

    if "threshold_value" in data:
        try:
            v = float(data["threshold_value"])
            set_clauses.append("threshold_value = %s")
            params.append(v)
        except (ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-threshold-value"}), 400

    if "units" in data:
        if data["units"] not in ALLOWED_UNITS:
            return jsonify({"ok": False, "error": "invalid-units"}), 400
        set_clauses.append("units = %s")
        params.append(data["units"])

    if "channels" in data:
        ch = data["channels"]
        if not isinstance(ch, list):
            return jsonify({"ok": False, "error": "invalid-channels"}), 400
        clean = [c for c in ch if isinstance(c, str) and c in ALLOWED_CHANNELS]
        if not clean:
            return jsonify({"ok": False, "error": "no-valid-channels"}), 400
        set_clauses.append("channels = %s")
        params.append(",".join(clean))

    if "enabled" in data:
        set_clauses.append("enabled = %s")
        params.append(bool(data["enabled"]))

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    set_clauses.append("updated_at = %s")
    now_ms = int(time.time() * 1000)
    params.append(now_ms)

    with db() as conn:
        with conn.cursor() as cur:
            # Verify ownership first
            cur.execute(
                "SELECT user_id FROM threshold_alerts WHERE id = %s",
                (alert_id,),
            )
            existing = cur.fetchone()
            if existing is None or existing["user_id"] != user["id"]:
                return jsonify({"ok": False, "error": "not-found"}), 404

            params.extend([alert_id, user["id"]])
            cur.execute(
                f"UPDATE threshold_alerts SET {', '.join(set_clauses)} "
                f"WHERE id = %s AND user_id = %s",
                tuple(params),
            )
            cur.execute(
                """SELECT id, metric, comparator, threshold_value, units,
                          channels, enabled, created_at, updated_at
                   FROM threshold_alerts WHERE id = %s""",
                (alert_id,),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "alert": {
            "id": row["id"],
            "metric": row["metric"],
            "comparator": row["comparator"],
            "threshold_value": row["threshold_value"],
            "units": row["units"],
            "channels": [c for c in (row["channels"] or "").split(",") if c],
            "enabled": row["enabled"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
    })


@app.delete("/api/v1/me/threshold-alerts/<int:alert_id>")
def me_threshold_alerts_delete(alert_id):
    """Delete a threshold alert. Only the owner can delete.

    Returns:
        200 {"ok": true}
        404 not found or not owned
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT user_id FROM threshold_alerts WHERE id = %s",
                (alert_id,),
            )
            row = cur.fetchone()
            if row is None or row["user_id"] != user["id"]:
                return jsonify({"ok": False, "error": "not-found"}), 404

            cur.execute(
                "DELETE FROM threshold_alerts WHERE id = %s AND user_id = %s",
                (alert_id, user["id"]),
            )

    return jsonify({"ok": True})


# ════════════════════════════════════════════════════════════════════
# Operational profile (onboarding questionnaire) — save endpoint
# ════════════════════════════════════════════════════════════════════
#
# The onboarding page (wv_onboarding.html) POSTs the client's operational
# profile here. Two things happen: the structured context is written onto
# subscriber_coverage so the Met composer sees it, and each watched
# threshold we can actually monitor becomes a threshold_alerts row, so the
# same engine that powers the settings builder picks it up. Categories we
# can't read from the forecast yet (lightning, ice, fog) and "severe"
# (already covered by NWS watch/warning alerting) are skipped and reported
# back so the UI can say so.

def _onboarding_label_to_cat(label):
    """Fallback when the form didn't send a category key: map the visible
    label back to a category."""
    l = (label or "").strip().lower()
    return {
        "wind": "wind", "rain rate": "rain_rate", "rain total": "rain_total",
        "lightning": "lightning", "heat": "heat", "cold / freeze": "cold",
        "snow": "snow", "ice": "ice", "fog / visibility": "fog",
        "humidity": "humidity", "severe / warning": "severe",
    }.get(l, "")


# onboarding category -> (engine metric, endpoint units)
_ONBOARDING_CAT_TO_METRIC = {
    "wind": ("wind", "mph"),
    "rain_rate": ("rain_amount", "in"),
    "rain_total": ("rain_amount", "in"),
    "heat": ("heat_index", "F"),
    "cold": ("temp_low", "F"),
    "snow": ("snow_amount", "in"),
    "humidity": ("humidity", "pct"),
}
_ONBOARDING_OP_TO_COMP = {
    "over": "gt", "under": "lt",
    "at or above": "gte", "at or below": "lte",
    "gt": "gt", "lt": "lt", "gte": "gte", "lte": "lte",
}


@app.route("/api/v1/me/operational-profile", methods=["OPTIONS"])
def me_operational_profile_preflight():
    return ("", 204)


@app.post("/api/v1/me/operational-profile")
def me_operational_profile_save():
    user = _get_current_user()
    if not user:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    data = request.get_json(silent=True) or {}
    now_ms = int(time.time() * 1000)

    # ── 1. Structured context onto subscriber_coverage ──
    industry = (data.get("industry") or "").strip()[:200]
    decisions = data.get("client_decisions") or []
    decisions_txt = (", ".join([str(d) for d in decisions if d])
                     if isinstance(decisions, list) else str(decisions or ""))[:2000]
    cp = data.get("contact_protocol") or {}
    peak_txt = (cp.get("operating_hours") or "").strip()[:500]
    od = data.get("operation_detail") or {}
    extra = []
    if data.get("worst_event_history"):
        extra.append("Worst past event: " + str(data["worst_event_history"]).strip())
    if od.get("weather_exposed"):
        extra.append("Weather-exposed: " + str(od["weather_exposed"]).strip())
    if od.get("sensitive_times"):
        extra.append("Sensitive times: " + str(od["sensitive_times"]).strip())
    if od.get("bad_day_cost"):
        extra.append("Cost of a bad day: " + str(od["bad_day_cost"]).strip())
    for t in (data.get("watched_thresholds") or []):
        imp = (t.get("client_impact") or "").strip()
        wx = (t.get("weather") or "").strip()
        if imp:
            extra.append((wx + ": " if wx else "") + imp)
    additional_ctx = "\n".join(extra)[:2000]

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT user_id FROM subscriber_coverage WHERE user_id=%s", (user["id"],))
                if cur.fetchone():
                    cur.execute(
                        """UPDATE subscriber_coverage
                              SET business_role = COALESCE(NULLIF(%s,''), business_role),
                                  weather_decisions = COALESCE(NULLIF(%s,''), weather_decisions),
                                  peak_need_times = COALESCE(NULLIF(%s,''), peak_need_times),
                                  additional_context = COALESCE(NULLIF(%s,''), additional_context),
                                  updated_at = %s
                            WHERE user_id = %s""",
                        (industry, decisions_txt, peak_txt, additional_ctx, now_ms, user["id"]),
                    )
                else:
                    cur.execute(
                        """INSERT INTO subscriber_coverage
                               (user_id, business_role, weather_decisions, peak_need_times,
                                additional_context, updated_at)
                           VALUES (%s,%s,%s,%s,%s,%s)""",
                        (user["id"], industry, decisions_txt, peak_txt, additional_ctx, now_ms),
                    )
    except Exception as e:
        print(f"[operational-profile] context save failed for user {user['id']}: {e}", flush=True)
        # Non-fatal: still try to save thresholds below.

    # ── 2. Watched thresholds -> threshold_alerts (dedup by content) ──
    created = 0
    skipped = []
    severe_watched = 0
    try:
        with db() as conn:
            with conn.cursor() as cur:
                for t in (data.get("watched_thresholds") or []):
                    cat = (t.get("cat") or "").strip().lower() or _onboarding_label_to_cat(t.get("weather"))
                    mm = _ONBOARDING_CAT_TO_METRIC.get(cat)
                    if not mm:
                        # Severe/warning is covered in real time via official NWS
                        # warnings, so it's watched, just not as a numeric alert.
                        # Lightning/ice/fog can't be auto-watched yet; the Met sees
                        # them. 'other' is a freeform note we don't count.
                        if cat == "severe":
                            severe_watched += 1
                        elif cat and cat != "other":
                            skipped.append(cat)
                        continue
                    metric, units = mm
                    comp = _ONBOARDING_OP_TO_COMP.get((t.get("condition") or "").strip().lower())
                    if not comp:
                        comp = "lt" if metric == "temp_low" else "gt"
                    try:
                        tv = float(str(t.get("value")).strip())
                    except (TypeError, ValueError):
                        continue
                    # Dedup by content so re-submitting the form doesn't pile up
                    # duplicates, and builder-created thresholds aren't touched.
                    cur.execute(
                        """SELECT id FROM threshold_alerts
                            WHERE user_id=%s AND metric=%s AND comparator=%s
                              AND threshold_value=%s AND units=%s""",
                        (user["id"], metric, comp, tv, units),
                    )
                    if cur.fetchone():
                        continue
                    cur.execute(
                        """INSERT INTO threshold_alerts
                               (user_id, metric, comparator, threshold_value, units,
                                channels, enabled, created_at, updated_at)
                           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (user["id"], metric, comp, tv, units, "sms,email", True, now_ms, now_ms),
                    )
                    created += 1
    except Exception as e:
        print(f"[operational-profile] threshold save failed for user {user['id']}: {e}", flush=True)
        return jsonify({"ok": False, "error": "threshold-save-failed"}), 500

    return jsonify({"ok": True, "thresholds_created": created, "skipped": skipped,
                    "severe_watched": severe_watched})


# ════════════════════════════════════════════════════════════════════
# Serve the "full weather profile" onboarding page from the backend.
# ════════════════════════════════════════════════════════════════════
# The portal links to this page. Serving it from the API origin (rather
# than relying on a separately-hosted static file) means the link always
# resolves, AND the page's own save call to /api/v1/me/operational-profile
# becomes a first-party request, so the logged-in session cookie is sent
# reliably. The HTML is embedded base64 so a single app.py paste deploys
# it with no extra files.
_WV_ONBOARDING_HTML_B64 = ""


@app.get("/wv_onboarding.html")
@app.get("/onboarding")
def serve_wv_onboarding():
    import base64 as _b64
    try:
        html = _b64.b64decode(_WV_ONBOARDING_HTML_B64).decode("utf-8")
    except Exception as e:
        print(f"[onboarding] decode failed: {e}", flush=True)
        html = "<!doctype html><meta charset=utf-8><p>This page is temporarily unavailable.</p>"
    resp = make_response(html)
    resp.headers["Content-Type"] = "text/html; charset=utf-8"
    return resp




# ════════════════════════════════════════════════════════════════════
# Saved locations — write endpoints (Phase 10 Chunk B2)
# ════════════════════════════════════════════════════════════════════
#
# CRUD for the subscriber's saved location(s) + a geocoding helper that
# turns a free-form address string into lat/lng using Open-Meteo's free
# geocoding API. The helper is also exposed as its own endpoint so the
# frontend's "Look up" button can show the resolved location before the
# user commits to saving it.

# US state names -> 2-letter abbreviation, used by the geocode confidence
# check below.
_US_STATES = {
    "alabama": "AL", "alaska": "AK", "arizona": "AZ", "arkansas": "AR",
    "california": "CA", "colorado": "CO", "connecticut": "CT", "delaware": "DE",
    "florida": "FL", "georgia": "GA", "hawaii": "HI", "idaho": "ID",
    "illinois": "IL", "indiana": "IN", "iowa": "IA", "kansas": "KS",
    "kentucky": "KY", "louisiana": "LA", "maine": "ME", "maryland": "MD",
    "massachusetts": "MA", "michigan": "MI", "minnesota": "MN",
    "mississippi": "MS", "missouri": "MO", "montana": "MT", "nebraska": "NE",
    "nevada": "NV", "new hampshire": "NH", "new jersey": "NJ",
    "new mexico": "NM", "new york": "NY", "north carolina": "NC",
    "north dakota": "ND", "ohio": "OH", "oklahoma": "OK", "oregon": "OR",
    "pennsylvania": "PA", "rhode island": "RI", "south carolina": "SC",
    "south dakota": "SD", "tennessee": "TN", "texas": "TX", "utah": "UT",
    "vermont": "VT", "virginia": "VA", "washington": "WA",
    "west virginia": "WV", "wisconsin": "WI", "wyoming": "WY",
}
_US_ABBREV_TO_STATE = {v: k for k, v in _US_STATES.items()}


def _geocode_looks_confident(query, geo):
    """Heuristic: does a geocode result plausibly match what the user typed?

    Built to catch the failure where a bare, ambiguous word matches a tiny
    same-named town in the wrong state (the classic case: "Nebraska"
    geocoding to Nebraska, Indiana instead of the state).

    Returns (ok, reason). ok=False means do not trust the result enough to
    auto-write coordinates; leave the member un-located so an admin can
    confirm, which is safer than placing them in the wrong state.
    """
    if not geo:
        return False, "no-result"
    q = (query or "").strip().lower()
    if not q:
        return False, "empty-query"
    result_state = (geo.get("admin1") or "").strip().lower()  # admin1 = state

    tokens = [t for t in q.replace(",", " ").split() if t]

    # Case 1: the input is nothing but a bare US state name (e.g.
    # "nebraska"). They mean the state. If the result's state is a
    # different state, we matched a town, not the state.
    if q in _US_STATES:
        if result_state == q:
            return True, "ok-state"
        return False, "bare-state-name-matched-town"

    # Case 2: the input names a state somewhere (whole-word full name, or
    # a trailing 2-letter code like "Thomas County KS"). That state must
    # match the result's state.
    typed_states = set()
    padded_q = " " + q + " "
    for name in _US_STATES:
        if (" " + name + " ") in padded_q:
            typed_states.add(name)
    if tokens:
        last = tokens[-1]
        if len(last) == 2 and last.upper() in _US_ABBREV_TO_STATE:
            typed_states.add(_US_ABBREV_TO_STATE[last.upper()])
    if typed_states:
        if result_state in typed_states:
            return True, "ok-state-match"
        return False, "state-mismatch"

    # Case 3: no state signal and not a bare state name. We cannot verify
    # the state, so accept but flag it for the logs.
    return True, "unverified-no-state-signal"


def _geocode_address(query: str) -> Optional[dict]:
    """Look up a free-form address string. Two-stage:

    1. Open-Meteo geocoding API — fast, great for place names ("Lebanon, IN",
       "Indianapolis"). No API key, no rate-limit signup. Won't find street
       addresses though.
    2. Nominatim (OpenStreetMap) fallback — slower, handles full street
       addresses ("123 Main St, Lebanon, IN"). Free for low volume,
       requires User-Agent. Used when Open-Meteo returns nothing.

    Returns the first result or None if no match across both providers.
    Result shape:
        {
          "lat": float,
          "lng": float,
          "name": "Lebanon",
          "admin1": "Indiana",        # state
          "admin2": "Boone County",   # county
          "country": "United States"
        }

    Network failures return None silently — caller treats it as "no match"
    and asks the user to drop a pin manually.
    """
    if not query or not isinstance(query, str):
        return None
    q = query.strip()
    if not q:
        return None

    # ── Stage 1: Open-Meteo (place names) ──
    result = _geocode_via_open_meteo(q)
    if result is not None:
        return result

    # ── Stage 2: Nominatim fallback (street addresses) ──
    return _geocode_via_nominatim(q)


def _geocode_via_open_meteo(q: str) -> Optional[dict]:
    """Open-Meteo geocoding: fast, place-name database. No street addresses."""
    try:
        from urllib.parse import quote
        url = (
            "https://geocoding-api.open-meteo.com/v1/search"
            f"?name={quote(q)}&count=1&language=en&format=json"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "weathervalet/1.0"})
        with urllib.request.urlopen(req, timeout=4) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except (urllib.error.URLError, ValueError, TimeoutError) as e:
        print(f"[GEOCODE-OM] failed for '{q[:80]}': {e}", flush=True)
        return None
    except Exception as e:
        print(f"[GEOCODE-OM] unexpected error for '{q[:80]}': {e}", flush=True)
        return None

    results = (data or {}).get("results") or []
    if not results:
        return None

    r = results[0]
    return {
        "lat": float(r.get("latitude")),
        "lng": float(r.get("longitude")),
        "name": r.get("name") or q,
        "admin1": r.get("admin1") or "",   # state
        "admin2": r.get("admin2") or "",   # county
        "country": r.get("country") or "",
    }


def _geocode_via_nominatim(q: str) -> Optional[dict]:
    """Nominatim (OpenStreetMap) geocoding: slower, handles street addresses.

    Free for low-volume use. Requires a real User-Agent (Nominatim policy).
    Max ~1 req/sec at low volume; we trust this won't be hit at launch
    scale. If we exceed, swap to Google Maps Geocoding API.
    """
    try:
        from urllib.parse import quote
        url = (
            "https://nominatim.openstreetmap.org/search"
            f"?q={quote(q)}&format=json&addressdetails=1&limit=1"
            "&countrycodes=us"  # bias to US for now; remove if expanding
        )
        req = urllib.request.Request(url, headers={
            # Nominatim policy: identify the app + contact email
            "User-Agent": "WeatherValet/1.0 (hello@weathervalet.ai)",
            "Accept": "application/json",
        })
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except (urllib.error.URLError, ValueError, TimeoutError) as e:
        print(f"[GEOCODE-NOM] failed for '{q[:80]}': {e}", flush=True)
        return None
    except Exception as e:
        print(f"[GEOCODE-NOM] unexpected error for '{q[:80]}': {e}", flush=True)
        return None

    if not data or not isinstance(data, list) or len(data) == 0:
        return None

    r = data[0]
    addr = r.get("address") or {}
    # Nominatim's address fields: state, county, city/town/village
    name = (addr.get("city") or addr.get("town") or addr.get("village")
            or addr.get("hamlet") or r.get("display_name", "").split(",")[0])
    try:
        return {
            "lat": float(r.get("lat")),
            "lng": float(r.get("lon")),
            "name": (name or q)[:120],
            "admin1": addr.get("state") or "",
            "admin2": addr.get("county") or "",
            "country": addr.get("country") or "",
        }
    except (ValueError, TypeError):
        return None


@app.route("/api/v1/geocode", methods=["OPTIONS"])
def _geocode_preflight():
    return ("", 204)


@app.get("/api/v1/geocode")
def geocode_lookup():
    """Geocode a free-form address string.

    Query params:
        q  — the address string ("Lebanon, IN" or "1600 Pennsylvania Ave")

    Returns:
        200 {"ok": true, "result": {...}}   match found
        200 {"ok": true, "result": null}    no match (treat as user error)
        400 missing q
        401 not authenticated (we keep this auth-only to avoid being a
            free geocoder for the internet)
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    q = (request.args.get("q") or "").strip()
    if not q:
        return jsonify({"ok": False, "error": "missing-query"}), 400

    result = _geocode_address(q)
    return jsonify({"ok": True, "result": result})


@app.post("/api/v1/me/saved-locations")
def me_saved_locations_create():
    """Create a new saved location for the current user.

    Two input shapes are accepted:
      A) {"address_text": "Lebanon, IN", "label": "Home"}
         — backend geocodes to get lat/lng
      B) {"address_text": "Lebanon, IN", "label": "Home",
          "lat": 40.0481, "lng": -86.4694, "county": "Boone County"}
         — frontend already has coords (e.g. after pin-drop), backend trusts them

    `is_primary` defaults to TRUE if this is the user's first location.
    If `is_primary` is explicitly TRUE and another location exists, the
    other one is automatically unset (exactly-one-primary invariant).

    Returns:
        200 {"ok": true, "location": {...}}
        400 invalid input or geocoding failure
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}

    label = (data.get("label") or "").strip()
    if not label:
        # Auto-generate a label from address_text if not supplied
        label = (data.get("address_text") or "Saved location").strip()[:80]
    if len(label) > 120:
        label = label[:120]

    address_text = (data.get("address_text") or "").strip() or None

    # If lat/lng provided, trust them. Otherwise geocode.
    lat = data.get("lat")
    lng = data.get("lng")
    county = (data.get("county") or "").strip() or None

    if lat is None or lng is None:
        # Need to geocode from address_text
        if not address_text:
            return jsonify({"ok": False, "error": "no-location-data"}), 400
        geo = _geocode_address(address_text)
        if not geo:
            return jsonify({"ok": False, "error": "geocoding-failed"}), 400
        lat = geo["lat"]
        lng = geo["lng"]
        if not county:
            county = geo.get("admin2") or None
    else:
        try:
            lat = float(lat)
            lng = float(lng)
        except (ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400
        # Sanity check — somewhere on Earth
        if not (-90 <= lat <= 90 and -180 <= lng <= 180):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400

    now_ms = int(time.time() * 1000)
    requested_primary = bool(data.get("is_primary", False))

    with db() as conn:
        with conn.cursor() as cur:
            # If user has no existing locations, force is_primary=TRUE
            cur.execute(
                "SELECT COUNT(*) AS n FROM saved_locations WHERE user_id = %s",
                (user["id"],),
            )
            row = cur.fetchone()
            existing_count = row["n"] if row else 0
            is_primary = requested_primary or (existing_count == 0)

            # If setting primary, unset any existing primary first
            if is_primary and existing_count > 0:
                cur.execute(
                    "UPDATE saved_locations SET is_primary = FALSE, updated_at = %s "
                    "WHERE user_id = %s AND is_primary = TRUE",
                    (now_ms, user["id"]),
                )

            cur.execute(
                """INSERT INTO saved_locations
                   (user_id, label, address_text, lat, lng, county, is_primary,
                    created_at, updated_at)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                   RETURNING id, label, address_text, lat, lng, county,
                             is_primary, created_at, updated_at""",
                (user["id"], label, address_text, lat, lng, county, is_primary,
                 now_ms, now_ms),
            )
            new_row = cur.fetchone()

            # Phase 10 timezone foundation: if this is becoming the
            # user's primary location, update their timezone too.
            # Brief scheduler uses this to deliver at 7 AM subscriber-
            # local instead of 7 AM UTC.
            if is_primary:
                detected_tz = _timezone_for_latlng(lat, lng)
                cur.execute(
                    "UPDATE users SET timezone = %s WHERE id = %s",
                    (detected_tz, user["id"]),
                )

    return jsonify({
        "ok": True,
        "location": {
            "id": new_row["id"],
            "label": new_row["label"],
            "address_text": new_row["address_text"],
            "lat": new_row["lat"],
            "lng": new_row["lng"],
            "county": new_row["county"],
            "is_primary": new_row["is_primary"],
            "created_at": new_row["created_at"],
            "updated_at": new_row["updated_at"],
        },
    })


@app.route("/api/v1/me/saved-locations/<int:loc_id>", methods=["OPTIONS"])
def _me_saved_location_id_preflight(loc_id):
    return ("", 204)


@app.patch("/api/v1/me/saved-locations/<int:loc_id>")
def me_saved_locations_update(loc_id):
    """Update an existing saved location. Owner-only.

    Same field-validation rules as create. Re-geocoding is NOT automatic —
    if the address_text changes but no new lat/lng is supplied, we keep
    the existing lat/lng (user must do a fresh geocode + pin-drop to move).

    Setting is_primary=true unsets any other primary location for this user.

    Returns:
        200 {"ok": true, "location": {...}}
        404 not found or not owned
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}
    now_ms = int(time.time() * 1000)

    set_clauses = []
    params = []

    if "label" in data:
        label = (data["label"] or "").strip()
        if not label or len(label) > 120:
            return jsonify({"ok": False, "error": "invalid-label"}), 400
        set_clauses.append("label = %s")
        params.append(label)

    if "address_text" in data:
        addr = (data["address_text"] or "").strip()
        set_clauses.append("address_text = %s")
        params.append(addr or None)

    if "lat" in data or "lng" in data:
        # If either coord is in the body, both must be present and valid
        try:
            lat = float(data["lat"])
            lng = float(data["lng"])
        except (KeyError, ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400
        if not (-90 <= lat <= 90 and -180 <= lng <= 180):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400
        set_clauses.append("lat = %s")
        params.append(lat)
        set_clauses.append("lng = %s")
        params.append(lng)

    if "county" in data:
        set_clauses.append("county = %s")
        params.append((data["county"] or "").strip() or None)

    requested_primary = data.get("is_primary")
    if requested_primary is not None:
        set_clauses.append("is_primary = %s")
        params.append(bool(requested_primary))

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    set_clauses.append("updated_at = %s")
    params.append(now_ms)

    with db() as conn:
        with conn.cursor() as cur:
            # Verify ownership
            cur.execute(
                "SELECT user_id FROM saved_locations WHERE id = %s",
                (loc_id,),
            )
            existing = cur.fetchone()
            if existing is None or existing["user_id"] != user["id"]:
                return jsonify({"ok": False, "error": "not-found"}), 404

            # If toggling this location to primary, unset others first
            if requested_primary is True:
                cur.execute(
                    "UPDATE saved_locations SET is_primary = FALSE, updated_at = %s "
                    "WHERE user_id = %s AND is_primary = TRUE AND id != %s",
                    (now_ms, user["id"], loc_id),
                )

            params.extend([loc_id, user["id"]])
            cur.execute(
                f"UPDATE saved_locations SET {', '.join(set_clauses)} "
                f"WHERE id = %s AND user_id = %s",
                tuple(params),
            )
            cur.execute(
                """SELECT id, label, address_text, lat, lng, county, is_primary,
                          created_at, updated_at
                   FROM saved_locations WHERE id = %s""",
                (loc_id,),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "location": {
            "id": row["id"],
            "label": row["label"],
            "address_text": row["address_text"],
            "lat": row["lat"],
            "lng": row["lng"],
            "county": row["county"],
            "is_primary": row["is_primary"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
    })


@app.delete("/api/v1/me/saved-locations/<int:loc_id>")
def me_saved_locations_delete(loc_id):
    """Delete a saved location. Owner-only.

    If the deleted location was primary AND another location exists,
    the most recently created location is promoted to primary so the
    invariant (subscriber always has a primary location when they have
    any locations) holds.

    Returns:
        200 {"ok": true}
        404 not found or not owned
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    now_ms = int(time.time() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT user_id, is_primary FROM saved_locations WHERE id = %s",
                (loc_id,),
            )
            row = cur.fetchone()
            if row is None or row["user_id"] != user["id"]:
                return jsonify({"ok": False, "error": "not-found"}), 404

            was_primary = row["is_primary"]

            cur.execute(
                "DELETE FROM saved_locations WHERE id = %s AND user_id = %s",
                (loc_id, user["id"]),
            )

            # If we removed the primary, promote the newest remaining location
            if was_primary:
                cur.execute(
                    """SELECT id FROM saved_locations
                       WHERE user_id = %s
                       ORDER BY created_at DESC LIMIT 1""",
                    (user["id"],),
                )
                successor = cur.fetchone()
                if successor:
                    cur.execute(
                        "UPDATE saved_locations SET is_primary = TRUE, updated_at = %s "
                        "WHERE id = %s",
                        (now_ms, successor["id"]),
                    )

    return jsonify({"ok": True})


# ════════════════════════════════════════════════════════════════════
# Subscription signup via Stripe Checkout (Phase 10 Chunk C2)
# ════════════════════════════════════════════════════════════════════
#
# Creates a Stripe Checkout Session in 'subscription' mode for the chosen
# tier. Returns the checkout URL; the frontend redirects to it.
#
# On successful checkout, Stripe fires checkout.session.completed →
# the existing webhook (see stripe_webhook_v1) handles user creation,
# subscriber role grant, tier capture, and welcome magic link.
#
# Anonymous checkout is supported (option B from the May 14 plan):
# the user need NOT be signed in. Stripe collects their email at
# checkout; the webhook finds-or-creates the user from that email.
# For signed-in users, we pre-fill the email so the existing user gets
# their subscription linked correctly.

@app.route("/api/v1/subscribe", methods=["OPTIONS"])
def _subscribe_preflight():
    return ("", 204)


@app.post("/api/v1/subscribe")
def subscribe_create_checkout():
    """Create a Stripe Checkout Session for a subscription tier.

    Request body:
        {
          "tier": "hobbyist" | "pro_single" | "pro_multi",
          "starter": true,            // optional — apply STARTER99 coupon
          "rep": "brian"              // optional — sales rep attribution
        }

    Returns:
        200 {"ok": true, "url": "https://checkout.stripe.com/c/pay/..."}
        400 invalid tier
        503 Stripe not configured
    """
    if stripe is None or not STRIPE_SECRET_KEY:
        return jsonify({"ok": False, "error": "stripe-not-configured"}), 503

    data = request.get_json(silent=True) or {}
    tier_key = (data.get("tier") or "").strip()
    if tier_key not in TIER_PRICE_MAP:
        return jsonify({"ok": False, "error": "invalid-tier"}), 400

    price_id = TIER_PRICE_MAP[tier_key]

    # Starter Month — only applies to pro_single
    use_starter = bool(data.get("starter")) and tier_key == "pro_single"

    # Sales rep attribution — slug only, must be alphanumeric+underscore
    rep_slug_raw = (data.get("rep") or "").strip().lower()
    rep_slug = "".join(c for c in rep_slug_raw if c.isalnum() or c == "_")[:40]
    if not rep_slug:
        rep_slug = None

    # If the requester is signed in, pre-fill their email and link to
    # their existing Stripe customer if one exists. If they're cold
    # (anonymous on pricing page), Stripe collects the email at checkout.
    customer_email = None
    existing_stripe_customer = None
    user = _get_current_user()
    if user:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT email, stripe_customer_id FROM users WHERE id = %s",
                    (user["id"],),
                )
                row = cur.fetchone()
        if row:
            customer_email = row.get("email")
            existing_stripe_customer = row.get("stripe_customer_id")

    # Build the success/cancel URLs. We send them back to the home page
    # with a query flag so the frontend knows to celebrate or apologize.
    success_url = f"{FRONTEND_BASE_URL}/?subscribed=1&tier={tier_key}&session={{CHECKOUT_SESSION_ID}}"
    if use_starter:
        success_url += "&starter=1"
    cancel_url = f"{FRONTEND_BASE_URL}/?subscribe_cancelled=1&tier={tier_key}"

    # Build the Checkout Session params. If we have an existing Stripe
    # customer (this user previously subscribed and cancelled, for
    # example), pass `customer=` instead of `customer_email=` so the new
    # subscription is linked to the same customer record.
    metadata = {"wv_tier": tier_key}
    if use_starter:
        metadata["wv_starter"] = "1"
    if rep_slug:
        metadata["wv_rep"] = rep_slug

    session_params = {
        "mode": "subscription",
        "payment_method_types": ["card"],
        "line_items": [{"price": price_id, "quantity": 1}],
        "metadata": metadata,
        # Also attach the tier to the subscription itself, so we can
        # read it back later via subscription metadata if needed.
        "subscription_data": {
            "metadata": metadata.copy(),
        },
        "success_url": success_url,
        "cancel_url": cancel_url,
        "allow_promotion_codes": True,
        # Phase 10 Item #3: collect phone number at checkout so daily
        # briefs and threshold alerts can be sent by SMS without an
        # extra portal step. Stripe surfaces this as an optional field.
        "phone_number_collection": {"enabled": True},
    }
    # Apply STARTER99 coupon for Starter Month signups.
    # Stripe duration:'once' handles the auto-rollover to full price.
    if use_starter:
        session_params["discounts"] = [{"coupon": STARTER_COUPON_ID}]
        # allow_promotion_codes can't coexist with discounts on Stripe Checkout
        session_params.pop("allow_promotion_codes", None)

    if existing_stripe_customer:
        session_params["customer"] = existing_stripe_customer
    elif customer_email:
        session_params["customer_email"] = customer_email
    # else: Stripe collects email at checkout (anonymous flow)

    try:
        session = stripe.checkout.Session.create(**session_params)
    except Exception as e:
        # Log the full error server-side for the Render logs
        print(f"[subscribe] checkout session create failed: {e}", flush=True)
        # Also surface a short version to the frontend for diagnosis.
        # This is safe to expose: Stripe error messages don't include
        # API keys or other secrets.
        err_msg = str(e)[:200]
        return jsonify({
            "ok": False,
            "error": "stripe-error",
            "message": f"Couldn't start checkout. Stripe says: {err_msg}",
            "debug_error": err_msg,
        }), 500

    return jsonify({"ok": True, "url": session.url})


# ════════════════════════════════════════════════════════════════════
# Stripe Customer Portal session (Phase 10 Chunk C1)
# ════════════════════════════════════════════════════════════════════
#
# Creates a Stripe billing portal session for the current user and
# returns the URL the frontend should redirect to. Stripe hosts the
# portal UI — they handle plan changes, cancellation, payment method
# updates, and invoice history. On exit, the user is redirected back
# to our subscriber portal.
#
# Pre-requisites for this to work in production:
#   1. STRIPE_SECRET_KEY set in env (already configured)
#   2. The user must have a stripe_customer_id (set when they signed
#      up via checkout — populated by the existing webhook handler)
#   3. The Stripe Customer Portal must be CONFIGURED in the Stripe
#      Dashboard → Settings → Billing → Customer portal. Enable the
#      features you want customers to self-serve (cancel, change plan,
#      update payment method). Both Test Mode and Live Mode have
#      separate configs — set up both.

@app.route("/api/v1/me/stripe-portal-session", methods=["OPTIONS"])
def _me_stripe_portal_preflight():
    return ("", 204)


@app.post("/api/v1/me/stripe-portal-session")
def me_stripe_portal_session():
    """Create a Stripe billing portal session for the current user.

    Returns:
        200 {"ok": true, "url": "https://billing.stripe.com/p/session/..."}
        400 {"ok": false, "error": "no-stripe-customer"}  user has no Stripe
            customer record (likely a free user or pre-Stripe-launch user)
        401 not authenticated
        500 Stripe API error
        503 Stripe not configured on server
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    if stripe is None or not STRIPE_SECRET_KEY:
        return jsonify({"ok": False, "error": "stripe-not-configured"}), 503

    # Pull the user's stripe_customer_id from the DB. Phase 2 populated
    # this field via webhook when the user first paid; if it's NULL,
    # they have no Stripe customer record and can't open a portal.
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT stripe_customer_id FROM users WHERE id = %s",
                (user["id"],),
            )
            row = cur.fetchone()

    stripe_customer_id = row.get("stripe_customer_id") if row else None
    if not stripe_customer_id:
        return jsonify({
            "ok": False,
            "error": "no-stripe-customer",
            "message": "No active subscription found. Subscribe to a plan to access billing settings.",
        }), 400

    # Return-URL: where Stripe sends them after they're done. We send
    # them back to the subscriber portal so they pick up right where
    # they left off.
    return_url = f"{FRONTEND_BASE_URL}/?portal=back"

    try:
        session = stripe.billing_portal.Session.create(
            customer=stripe_customer_id,
            return_url=return_url,
        )
    except Exception as e:
        # Stripe SDK throws stripe.error.* exceptions; we catch broadly
        # to avoid leaking implementation details to the client.
        print(f"[stripe-portal] session create failed for user={user['id']}: {e}", flush=True)
        return jsonify({
            "ok": False,
            "error": "stripe-error",
            "message": "Couldn't open billing portal. Please try again or contact support.",
        }), 500

    return jsonify({"ok": True, "url": session.url})


# ════════════════════════════════════════════════════════════════════
# Met queue — pending verification_requests for Met workspace (Item #2)
# ════════════════════════════════════════════════════════════════════
#
# The Met workspace's Review Queue tab is currently rendered from a
# hardcoded MET_QUEUE_MOCK array. To make it real, the frontend calls
# this endpoint on workspace entry; if there ARE real paid requests,
# they take priority. Mock rows can still be shown alongside (or below)
# for demo continuity, controlled by the frontend.
#
# Auth: requires the 'met' role. Subscribers and crew can't see the
# queue.

@app.route("/api/v1/met/queue", methods=["OPTIONS"])
def _met_queue_preflight():
    return ("", 204)


@app.get("/api/v1/met/queue")
def met_queue_list():
    """List paid-but-unclaimed verification requests for the Met queue.

    Returns rows in 'paid' status (paid for, waiting for a Met to pick
    them up) plus rows in 'claimed' status that the current Met has
    claimed but not yet submitted. Other Mets' claimed rows are hidden.

    Returns:
        200 {"ok": true, "requests": [...]}
        401 not authenticated
        403 not a Met
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    is_admin = "admin" in roles
    met_id = user["id"]
    now = now_ts()
    stale_before = now - (REVIEW_CLAIM_TTL_MINUTES * 60)

    with db() as conn:
        with conn.cursor() as cur:
            # Step 1 — self-healing reclaim. Any 'claimed' review whose
            # claim has gone stale (older than the TTL, or a legacy claim
            # with no claimed_at) is released back to 'paid' so it can't
            # get stuck on a Met who walked away. Idempotent and cheap.
            cur.execute(
                """UPDATE verification_requests
                   SET status='paid', claimed_at=NULL,
                       claimed_by_user_id=NULL, updated_at=%s
                   WHERE status='claimed'
                     AND (claimed_at IS NULL OR claimed_at < %s)""",
                (now, stale_before),
            )

            # Step 2 — visible queue. Everyone sees all 'paid' (unclaimed)
            # rows. For 'claimed' rows: a Met sees only their own (so they
            # can resume after a refresh / device switch); an admin sees
            # all claimed rows for oversight.
            if is_admin:
                claimed_clause = "OR status = 'claimed'"
                params = ()
            else:
                claimed_clause = "OR (status = 'claimed' AND claimed_by_user_id = %s)"
                params = (met_id,)

            cur.execute(
                f"""SELECT id, created_at, updated_at, status, tier, price_cents,
                          customer_email, customer_phone, plan_text, plan_industry,
                          plan_location, plan_window, ai_brief_markdown, ai_status_key,
                          claim_token, claimed_at, claimed_by_user_id,
                          forecast_snapshot, ai_confidence
                   FROM verification_requests
                   WHERE status = 'paid' {claimed_clause}
                   ORDER BY
                     CASE WHEN status = 'paid' THEN 0 ELSE 1 END,
                     created_at ASC
                   LIMIT 50""",
                params,
            )
            rows = cur.fetchall()

    requests_out = [
        {
            "id": r["id"],
            "tier": r["tier"],
            "tier_label": _format_tier_label(r["tier"]),
            "status": r["status"],
            "price_cents": r["price_cents"],
            "customer_email": r["customer_email"],
            "customer_phone": r["customer_phone"],
            "plan_text": r["plan_text"],
            "plan_industry": r["plan_industry"],
            "plan_location": r["plan_location"],
            "plan_window": r["plan_window"],
            "ai_brief_markdown": r["ai_brief_markdown"],
            "ai_status_key": r["ai_status_key"],
            "ai_confidence": r["ai_confidence"],
            "forecast_snapshot": _safe_json_loads(r["forecast_snapshot"]),
            "claim_token": r["claim_token"],
            "claimed_at": r["claimed_at"],
            "claimed_by_user_id": r["claimed_by_user_id"],
            "claimed_by_me": (r["claimed_by_user_id"] == met_id),
            "created_at": r["created_at"],
            "paid_minutes_ago": max(0, (now - r["created_at"]) // 60),
        }
        for r in rows
    ]
    return jsonify({"ok": True, "requests": requests_out})


def _format_tier_label(tier_key: str) -> str:
    """Convert a verification tier key to a user-facing label."""
    return {
        "single": "Single",
        "day_pass": "Day Pass",
        "pro_monthly": "Pro",
    }.get(tier_key, tier_key.title())


# ════════════════════════════════════════════════════════════════════
# Review-queue claim lock (May 30, 2026 — Task #2 / #3)
# ════════════════════════════════════════════════════════════════════
#
# Two Mets used to be able to open and work the same review unknowingly,
# with the second submit silently lost to the idempotent "already
# completed" guard. These endpoints add an explicit, atomic claim step
# (mirroring the proven pro_brief_drafts claim pattern) plus a release so
# a Met can hand a review back. Abandoned claims auto-return to the queue
# after REVIEW_CLAIM_TTL_MINUTES (handled lazily in met_queue_list).
#
# Frontend wiring (claim-on-open, release-on-cancel, hide others' claims)
# is Phase 2B; these endpoints are the backend foundation it will call.

@app.route("/api/v1/met/queue/<int:request_id>/claim", methods=["OPTIONS"])
def _met_queue_claim_preflight(request_id):
    return ("", 204)


@app.post("/api/v1/met/queue/<int:request_id>/claim")
def met_queue_claim(request_id: int):
    """Atomically claim a paid review for the current Met.

    Grants the claim when the row is:
      - 'paid' (unclaimed), OR
      - already claimed by this same Met (idempotent resume), OR
      - 'claimed' but stale (older than REVIEW_CLAIM_TTL_MINUTES) — the
        previous holder abandoned it.

    The claim is a single guarded UPDATE ... RETURNING so two Mets racing
    for the same row can't both win — exactly one UPDATE matches.

    Returns:
      200 {"ok": true, "claim_token": "...", "status": "claimed"}
      409 {"ok": false, "error": "already-claimed"}        held by another Met
      409 {"ok": false, "error": "already-completed"}      already done
      404 {"ok": false, "error": "not-found"}
      401 / 403 auth
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    met_id = user["id"]
    now = now_ts()
    stale_before = now - (REVIEW_CLAIM_TTL_MINUTES * 60)

    with db() as conn:
        with conn.cursor() as cur:
            # Guarded atomic claim. The WHERE clause is the lock: it only
            # matches a row that is claimable BY THIS MET right now.
            cur.execute(
                """UPDATE verification_requests
                   SET status='claimed', claimed_at=%s,
                       claimed_by_user_id=%s, updated_at=%s
                   WHERE id=%s
                     AND status IN ('paid', 'claimed')
                     AND (
                           status = 'paid'
                           OR claimed_by_user_id = %s
                           OR claimed_by_user_id IS NULL
                           OR claimed_at IS NULL
                           OR claimed_at < %s
                         )
                   RETURNING claim_token""",
                (now, met_id, now, request_id, met_id, stale_before),
            )
            updated = cur.fetchone()

            if updated:
                return jsonify({
                    "ok": True,
                    "claim_token": updated["claim_token"],
                    "status": "claimed",
                })

            # No row matched — figure out why so the Met gets a clear reason.
            cur.execute(
                "SELECT status, claimed_by_user_id FROM verification_requests WHERE id = %s",
                (request_id,),
            )
            row = cur.fetchone()

    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if row["status"] == "completed":
        return jsonify({"ok": False, "error": "already-completed"}), 409
    # Held by a different Met with a still-fresh claim.
    return jsonify({"ok": False, "error": "already-claimed"}), 409


@app.route("/api/v1/met/queue/<int:request_id>/release", methods=["OPTIONS"])
def _met_queue_release_preflight(request_id):
    return ("", 204)


@app.post("/api/v1/met/queue/<int:request_id>/release")
def met_queue_release(request_id: int):
    """Release a claimed review back to the queue.

    Only the Met who holds the claim (or an admin) can release it, and
    only while it's still 'claimed' (a completed review can't be released).

    Returns:
      200 {"ok": true, "status": "paid"}
      409 {"ok": false, "error": "not-claimed-by-you"}   not yours / not claimed
      404 {"ok": false, "error": "not-found"}
      401 / 403 auth
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    is_admin = "admin" in roles
    met_id = user["id"]
    now = now_ts()

    with db() as conn:
        with conn.cursor() as cur:
            # Admins can release any claimed row; a Met only their own.
            if is_admin:
                owner_clause = ""
                params = (now, request_id)
            else:
                owner_clause = "AND claimed_by_user_id = %s"
                params = (now, request_id, met_id)

            cur.execute(
                f"""UPDATE verification_requests
                    SET status='paid', claimed_at=NULL,
                        claimed_by_user_id=NULL, updated_at=%s
                    WHERE id=%s AND status='claimed' {owner_clause}
                    RETURNING id""",
                params,
            )
            released = cur.fetchone()

            if released:
                return jsonify({"ok": True, "status": "paid"})

            cur.execute(
                "SELECT status FROM verification_requests WHERE id = %s",
                (request_id,),
            )
            row = cur.fetchone()

    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    return jsonify({"ok": False, "error": "not-claimed-by-you"}), 409


# ════════════════════════════════════════════════════════════════════
# Admin audit log (Phase 10 Admin Tools)
# ════════════════════════════════════════════════════════════════════

def _audit_log(actor_user_id: Optional[int], actor_name: Optional[str],
               action: str, target_type: Optional[str] = None,
               target_id: Optional[int] = None,
               details: Optional[dict] = None) -> None:
    """Write a row to admin_audit_log. Best-effort — failures are logged
    but never raised, since auditing must not block the real action.

    Pass `details` as a dict; we serialize it to JSON. Keep payloads
    small (under a few KB) — this isn't event storage, it's a
    "what changed" trail.
    """
    try:
        details_json = json.dumps(details) if details is not None else None
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO admin_audit_log
                       (actor_user_id, actor_name, action,
                        target_type, target_id, details_json, created_at)
                       VALUES (%s, %s, %s, %s, %s, %s, %s)""",
                    (actor_user_id, actor_name, action,
                     target_type, target_id, details_json,
                     int(time.time() * 1000)),
                )
    except Exception as e:
        print(f"[audit] log write failed action={action}: {e!r}", flush=True)


def _require_admin():
    """Helper: returns (user, error_response). If error_response is not
    None, the caller should return it immediately. Otherwise `user` is
    the authenticated admin user dict.

    Used as a one-liner gate in admin endpoints:
        user, err = _require_admin()
        if err: return err
    """
    user = _get_current_user()
    if user is None:
        return (None, (jsonify({"ok": False, "error": "not-authenticated"}), 401))
    roles = user.get("roles") or []
    if "admin" not in roles:
        return (None, (jsonify({"ok": False, "error": "forbidden"}), 403))
    return (user, None)


# ════════════════════════════════════════════════════════════════════
# User profile updates (Phase 10 Item #3 — supporting infra)
# ════════════════════════════════════════════════════════════════════
#
# Lets a signed-in user update their own name + phone. Used by the
# subscriber portal so users who didn't supply phone at Stripe checkout
# can still enable SMS delivery for their daily brief.

@app.route("/api/v1/me/profile", methods=["OPTIONS"])
def _me_profile_preflight():
    return ("", 204)


@app.get("/api/v1/me/profile")
def me_profile_get():
    """Return the current user's basic profile (name, email, phone).

    Also returns Met-specific onboarding state: `met_onboarded_at` is
    null until the Met dismisses the workspace welcome card.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, email, name, phone, met_onboarded_at,
                          operational_sms_consent_at,
                          operational_sms_consent_source
                   FROM users WHERE id = %s""",
                (user["id"],),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": False, "error": "user-not-found"}), 404
    return jsonify({
        "ok": True,
        "profile": {
            "email": row["email"],
            "name": row.get("name") or "",
            "phone": row.get("phone") or "",
            "met_onboarded_at": row.get("met_onboarded_at"),
            "operational_sms_consent_at": row.get("operational_sms_consent_at"),
            "operational_sms_consent_source": row.get("operational_sms_consent_source"),
        },
    })


@app.patch("/api/v1/me/profile")
def me_profile_update():
    """Update the current user's name and/or phone.

    Accepts:
      {
        "name": "Jane Smith",     (optional)
        "phone": "+15551234567"   (optional, must be E.164 if present)
      }

    Phone is normalized lightly — leading whitespace stripped and
    bare 10-digit US numbers ("3175551234") get a "+1" prefix. Anything
    else is rejected (we'd rather refuse than silently send to the
    wrong number).
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}
    set_clauses = []
    params = []

    if "name" in data:
        name = (data["name"] or "").strip()
        if len(name) > 200:
            return jsonify({"ok": False, "error": "name-too-long"}), 400
        set_clauses.append("name = %s")
        params.append(name or None)

    if "phone" in data:
        phone_raw = (data["phone"] or "").strip()
        if phone_raw == "":
            # Empty string = clear the phone
            set_clauses.append("phone = NULL")
        else:
            # Try to normalize. We accept:
            #   "+15551234567" — already E.164
            #   "5551234567"   — bare US 10-digit, prepend "+1"
            #   "(555) 123-4567" or "555-123-4567" — strip and prepend "+1"
            digits_only = "".join(c for c in phone_raw if c.isdigit())
            if phone_raw.startswith("+") and 8 <= len(digits_only) <= 15:
                phone_norm = "+" + digits_only
            elif len(digits_only) == 10:
                phone_norm = "+1" + digits_only
            elif len(digits_only) == 11 and digits_only.startswith("1"):
                phone_norm = "+" + digits_only
            else:
                return jsonify({"ok": False, "error": "invalid-phone"}), 400
            set_clauses.append("phone = %s")
            params.append(phone_norm)

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    params.append(user["id"])
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE users SET {', '.join(set_clauses)} WHERE id = %s",
                tuple(params),
            )
            cur.execute(
                "SELECT email, name, phone FROM users WHERE id = %s",
                (user["id"],),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "profile": {
            "email": row["email"],
            "name": row.get("name") or "",
            "phone": row.get("phone") or "",
        },
    })


@app.route("/api/v1/me/operational-sms-consent", methods=["OPTIONS"])
def _me_op_sms_consent_preflight():
    return ("", 204)


@app.post("/api/v1/me/operational-sms-consent")
def me_operational_sms_consent_record():
    """Record the current user's consent to receive operational SMS.

    Added May 27, 2026 for Twilio toll-free verification of the
    Met-facing number (+18889191531). The Met checks a box in their
    workspace and POSTs to this endpoint. We record:
      - timestamp (ms since epoch)
      - source ('web' for self-recorded via this endpoint)
      - IP address at time of consent (for audit / Twilio review)

    Idempotent: if already consented, returns the existing timestamp.
    Refusing consent is handled by DELETE on this same URL.

    Met must have a phone number on file first — refusing to record
    consent for a phone that isn't there.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT phone, operational_sms_consent_at
                   FROM users WHERE id = %s""",
                (user["id"],),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": False, "error": "user-not-found"}), 404
    if not (row.get("phone") or "").strip():
        return jsonify({
            "ok": False,
            "error": "phone-required",
            "hint": "Add a phone number to your profile first, then consent.",
        }), 400

    # If already consented, return existing timestamp (idempotent)
    if row.get("operational_sms_consent_at"):
        return jsonify({
            "ok": True,
            "consented_at": row["operational_sms_consent_at"],
            "already_consented": True,
        })

    # Record fresh consent
    now_ms = int(time.time() * 1000)
    # Capture IP — best effort, may be a proxy. Twilio accepts that.
    consent_ip = (request.headers.get("X-Forwarded-For", "").split(",")[0].strip()
                  or request.remote_addr
                  or "")
    consent_ip = consent_ip[:64]  # truncate paranoia
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE users
                   SET operational_sms_consent_at = %s,
                       operational_sms_consent_ip = %s,
                       operational_sms_consent_source = 'web',
                       operational_sms_consent_recorded_by = %s
                   WHERE id = %s""",
                (now_ms, consent_ip, user["id"], user["id"]),
            )
    print(f"[op-sms-consent] user={user['id']} recorded consent ip={consent_ip}",
          flush=True)
    return jsonify({"ok": True, "consented_at": now_ms})


@app.delete("/api/v1/me/operational-sms-consent")
def me_operational_sms_consent_revoke():
    """Revoke the current user's operational SMS consent.

    Sets all consent fields back to NULL. Future operational SMS
    sends should check operational_sms_consent_at IS NOT NULL before
    firing. (May 27, 2026)
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE users
                   SET operational_sms_consent_at = NULL,
                       operational_sms_consent_ip = NULL,
                       operational_sms_consent_source = NULL,
                       operational_sms_consent_recorded_by = NULL
                   WHERE id = %s""",
                (user["id"],),
            )
    print(f"[op-sms-consent] user={user['id']} REVOKED consent", flush=True)
    return jsonify({"ok": True, "revoked": True})


@app.route("/api/v1/admin/operational-sms-consent/<int:target_user_id>",
           methods=["OPTIONS"])
def _admin_op_sms_consent_preflight(target_user_id):
    return ("", 204)


@app.post("/api/v1/admin/operational-sms-consent/<int:target_user_id>")
def admin_record_operational_sms_consent(target_user_id: int):
    """Admin records a Met's operational SMS consent on their behalf.

    Used for Mets who consented verbally (most current Mets at launch)
    before the in-workspace consent flow existed. Records source as
    'verbal-admin' so the audit trail is clear about who recorded it
    and how.

    Body (JSON):
      { "consent_date": "2026-05-27" }  (optional; defaults to now)

    Twilio accepts both web and verbal-admin consent records as long
    as each is documented per recipient.
    """
    actor, err = _require_admin()
    if err:
        return err

    data = request.get_json(silent=True) or {}
    consent_date = (data.get("consent_date") or "").strip()
    if consent_date:
        try:
            dt = datetime.strptime(consent_date, "%Y-%m-%d")
            consent_ms = int(dt.timestamp() * 1000)
        except Exception:
            return jsonify({"ok": False, "error": "bad-date",
                            "hint": "Use YYYY-MM-DD."}), 400
    else:
        consent_ms = int(time.time() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, phone FROM users WHERE id = %s""",
                (target_user_id,),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": False, "error": "user-not-found"}), 404
    if not (row.get("phone") or "").strip():
        return jsonify({
            "ok": False,
            "error": "phone-required",
            "hint": "Set the user's phone first, then record consent.",
        }), 400

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE users
                   SET operational_sms_consent_at = %s,
                       operational_sms_consent_source = 'verbal-admin',
                       operational_sms_consent_recorded_by = %s,
                       operational_sms_consent_ip = NULL
                   WHERE id = %s""",
                (consent_ms, actor["id"], target_user_id),
            )
    print(f"[op-sms-consent] admin={actor['id']} recorded VERBAL consent "
          f"for user={target_user_id} dated={consent_ms}", flush=True)
    return jsonify({"ok": True, "consented_at": consent_ms,
                    "source": "verbal-admin"})


@app.route("/api/v1/me/met-onboarding-dismiss", methods=["OPTIONS"])
def _me_met_onboarding_dismiss_preflight():
    return ("", 204)


@app.post("/api/v1/me/met-onboarding-dismiss")
def me_met_onboarding_dismiss():
    """Met dismissed the workspace welcome card. Stamps met_onboarded_at
    so the card never shows again for this user. Idempotent — calling
    twice has no extra effect.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "met" not in (user.get("roles") or []) and "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    now_ms = int(time.time() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE users
                   SET met_onboarded_at = COALESCE(met_onboarded_at, %s)
                   WHERE id = %s""",
                (now_ms, user["id"]),
            )
    return jsonify({"ok": True})


