@app.patch("/api/v1/me/crew-location")
def me_crew_location_update():
    """Update the current user's Crew home base.

    Accepts:
      {
        "lat": 40.0481,        (optional)
        "lng": -86.4694,       (optional, but if lat present must also be)
        "label": "Lebanon, IN" (optional human label)
        "active": true         (optional toggle)
      }

    Returns:
        200 {"ok": true, "crew_location": {...}}
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "crew" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}
    set_clauses = []
    params = []

    if "lat" in data or "lng" in data:
        try:
            lat = float(data["lat"])
            lng = float(data["lng"])
        except (KeyError, ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400
        if not (-90 <= lat <= 90 and -180 <= lng <= 180):
            return jsonify({"ok": False, "error": "invalid-coords"}), 400
        set_clauses.append("crew_home_lat = %s")
        params.append(lat)
        set_clauses.append("crew_home_lng = %s")
        params.append(lng)

    if "label" in data:
        label = (data["label"] or "").strip()
        if len(label) > 200:
            return jsonify({"ok": False, "error": "label-too-long"}), 400
        set_clauses.append("crew_home_label = %s")
        params.append(label or None)

    if "active" in data:
        set_clauses.append("crew_active = %s")
        params.append(bool(data["active"]))

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    params.append(user["id"])
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE users SET {', '.join(set_clauses)} WHERE id = %s",
                tuple(params),
            )
            cur.execute(
                """SELECT crew_home_lat, crew_home_lng, crew_home_label, crew_active
                   FROM users WHERE id = %s""",
                (user["id"],),
            )
            row = cur.fetchone()

    return jsonify({
        "ok": True,
        "crew_location": {
            "lat": row.get("crew_home_lat"),
            "lng": row.get("crew_home_lng"),
            "label": row.get("crew_home_label") or "",
            "active": row.get("crew_active") if row.get("crew_active") is not None else True,
        }
    })


# ════════════════════════════════════════════════════════════════════
# Severe weather status for current user (Storm Shelter auto-trigger)
# ════════════════════════════════════════════════════════════════════
#
# Returns the most severe NWS alert tier currently active for the user's
# primary saved location. Frontend polls this every 60 seconds when
# signed in; if the response flips to 'warning' or 'watch', the Storm
# Shelter UI auto-activates.
#
# Returns 200 even when there's no alert (status='clear') so the
# frontend can rely on the response shape. Anonymous users (no signed-in
# session, no saved location) get 'no-location' — frontend treats that
# as "don't auto-trigger; manual only".

@app.route("/api/v1/me/severe-weather-status", methods=["OPTIONS"])
def _me_severe_weather_preflight():
    return ("", 204)


# In-memory cache for NWS active alerts: avoid hammering api.weather.gov
# 60-second-per-user (could be N polls × M users). One fetch per 60s
# serves all callers. Cached for 60s.
_NWS_ALERTS_CACHE = {"data": None, "fetched_at": 0}
_NWS_ALERTS_CACHE_LOCK = threading.Lock()


def _get_cached_nws_alerts() -> list:
    """Return the latest active NWS alerts list, fetching at most once
    per 60 seconds across all callers.

    Also filters out alerts whose expires_at has passed, even if they
    were captured in the cache before expiry. Defense-in-depth.
    """
    with _NWS_ALERTS_CACHE_LOCK:
        now = time.time()
        if _NWS_ALERTS_CACHE["data"] is not None and \
           (now - _NWS_ALERTS_CACHE["fetched_at"]) < 60:
            # Filter expired alerts at read time too
            now_ms = int(now * 1000)
            return [a for a in _NWS_ALERTS_CACHE["data"]
                    if (a.get("expires_at") is None or a["expires_at"] >= now_ms)]
    # Fetch outside the lock so concurrent callers don't all serialize
    fresh = _fetch_active_nws_alerts()
    with _NWS_ALERTS_CACHE_LOCK:
        _NWS_ALERTS_CACHE["data"] = fresh
        _NWS_ALERTS_CACHE["fetched_at"] = time.time()
    return fresh


def _alert_tier_rank(event: str) -> int:
    """Higher number = more severe. Used to pick the worst active alert.
    Tornado Warning beats Severe Thunderstorm Warning beats Flash Flood
    Warning beats their respective Watches."""
    event_lower = (event or "").lower()
    if "tornado warning" in event_lower: return 100
    if "tornado watch" in event_lower: return 60
    if "severe thunderstorm warning" in event_lower: return 80
    if "severe thunderstorm watch" in event_lower: return 55
    if "flash flood warning" in event_lower: return 75
    if "flood warning" in event_lower: return 70
    return 10  # any other alert we somehow got


def _event_to_shelter_tier(event: str) -> str:
    """Map NWS event name → Storm Shelter tier key."""
    event_lower = (event or "").lower()
    if "warning" in event_lower:
        return "warning"
    if "watch" in event_lower:
        return "watch"
    return "clear"


@app.get("/api/v1/me/severe-weather-status")
def me_severe_weather_status():
    """Get current severe-weather tier for the signed-in user's primary location.

    Returns:
        {"ok": true, "status": "warning"|"watch"|"clear"|"no-location",
         "event": "Tornado Warning",  (when active)
         "headline": "...",
         "area_desc": "...",
         "expires_at": <ms timestamp>,
         "location_label": "Lebanon, IN"}
    """
    user = _get_current_user()
    if user is None:
        # Don't 401 — frontend handles this cleanly without auth.
        # Anonymous users just don't get auto-trigger.
        return jsonify({"ok": True, "status": "no-location"})

    # Find their primary saved location
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT label, lat, lng FROM saved_locations
                   WHERE user_id = %s AND is_primary = TRUE
                   LIMIT 1""",
                (user["id"],),
            )
            row = cur.fetchone()

    if not row or row.get("lat") is None or row.get("lng") is None:
        return jsonify({"ok": True, "status": "no-location"})

    user_lat = float(row["lat"])
    user_lng = float(row["lng"])
    user_location_label = row.get("label") or ""

    # Fetch alerts (cached for 60s)
    alerts = _get_cached_nws_alerts()

    # Find the worst alert whose polygon contains the user's location.
    # Defense-in-depth: also filter expired alerts here in case the
    # cache holds a previously-active alert that has since expired.
    now_ms = int(time.time() * 1000)
    worst = None
    worst_rank = 0
    for alert in alerts:
        # Skip expired alerts
        exp = alert.get("expires_at")
        if exp is not None and exp < now_ms:
            continue
        geom = alert.get("geometry")
        if not geom:
            continue
        try:
            geom_str = json.dumps(geom)
            if not _point_in_polygon_geojson(user_lat, user_lng, geom_str):
                continue
        except Exception:
            continue
        rank = _alert_tier_rank(alert.get("event", ""))
        if rank > worst_rank:
            worst_rank = rank
            worst = alert

    if not worst:
        return jsonify({
            "ok": True,
            "status": "clear",
            "location_label": user_location_label,
        })

    return jsonify({
        "ok": True,
        "status": _event_to_shelter_tier(worst.get("event", "")),
        "event": worst.get("event"),
        "headline": worst.get("headline"),
        "area_desc": worst.get("area_desc"),
        "expires_at": worst.get("expires_at"),
        "location_label": user_location_label,
    })


# ════════════════════════════════════════════════════════════════════
# Daily brief delivery (Item #3 — Chunk 3A)
# ════════════════════════════════════════════════════════════════════
#
# Subscribers set their brief preferences (morning_window_start/end,
# channels, location) in the portal. This module:
#   1. Runs a background scheduler thread that checks every 60 seconds
#   2. For each subscriber whose preferences match the current time AND
#      who has NOT already received their brief today, fetch forecast,
#      generate AI brief, send via channels, record in brief_history.
#   3. Skips Pro-tier subscribers (Chunk 3B handles Met-touched briefs).
#
# Threading notes:
#   - The scheduler runs in a daemon thread spawned at first request.
#   - One scheduler instance per Python process. Render runs a single
#     gunicorn worker (default for our service) so we get exactly one.
#   - If the process restarts mid-day, the scheduler picks back up.
#   - Idempotency via brief_history: we check "did we send today already?"
#     before each send, so even multiple workers wouldn't double-send.

_BRIEF_SCHEDULER_STARTED = False
_BRIEF_SCHEDULER_LOCK = threading.Lock()


def _shift_forecast_to_day(data: dict, offset: int) -> dict:
    """Shift Open-Meteo daily/hourly arrays so index [0] is `offset` days out.

    The brief generator and value extractor read index [0] for "the day this
    brief is about." When we pre-generate the night before, the brief is about
    TOMORROW, so we fetch two days and shift the arrays up by one. Callers keep
    reading [0] and transparently get the right day. Falls back to leaving the
    data untouched if the API returned fewer days than requested."""
    if offset <= 0 or not isinstance(data, dict):
        return data
    daily = data.get("daily")
    if isinstance(daily, dict):
        for k, v in list(daily.items()):
            if isinstance(v, list) and len(v) > offset:
                daily[k] = v[offset:]
    hourly = data.get("hourly")
    if isinstance(hourly, dict):
        shift = offset * 24
        for k, v in list(hourly.items()):
            if isinstance(v, list) and len(v) > shift:
                hourly[k] = v[shift:]
    return data


def _fetch_forecast(lat: float, lng: float, day_offset: int = 0) -> Optional[dict]:
    """Fetch a forecast from Open-Meteo for the given lat/lng.

    Returns a dict with the day's high/low, hourly precipitation,
    wind, and overall conditions; or None on failure. Used by the
    brief generator — no user is present so we hit the API directly
    from the backend (unlike ticket forecasts which the frontend fetches).

    day_offset: which day the brief is about, relative to "today" in the
        location's local timezone. 0 = today (the default, for same-morning
        sends). 1 = tomorrow (for night-before pre-generation). When >0 we
        request the extra days and shift the arrays so index [0] is the
        target day, so callers reading [0] need no changes. (June 2026 fix:
        pre-gen was fetching forecast_days=1 at 8 PM, which returns TODAY's
        forecast, so every pre-generated brief shipped yesterday's high.)
    """
    try:
        days = 1 + max(0, int(day_offset))
        url = (
            "https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat}&longitude={lng}"
            "&hourly=temperature_2m,precipitation_probability,windspeed_10m,weathercode"
            "&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,"
            "windspeed_10m_max,weathercode,sunrise,sunset"
            "&temperature_unit=fahrenheit&windspeed_unit=mph"
            f"&precipitation_unit=inch&timezone=auto&forecast_days={days}"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "weathervalet/1.0"})
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        if day_offset:
            data = _shift_forecast_to_day(data, int(day_offset))
        return data
    except Exception as e:
        print(f"[brief-forecast] fetch failed for ({lat},{lng}): {e}", flush=True)
        return None


# ── Rain heads-up alerts (June 2026) ────────────────────────────────
# Proactive "rain is arriving" detector. Uses Open-Meteo's 15-minute
# precipitation nowcast plus the hourly probability to decide WHEN rain
# will start at a location, then (test phase) texts the configured user.
# Scoped to one account via the RAIN_ALERT_TEST_EMAIL env var so nobody
# gets surprise texts; empty env = feature dormant. Next phase will route
# the same detection to the on-duty Met instead of the subscriber.
RAIN_ONSET_IN = 0.01          # inches in a 15-min block that counts as real rain
_LAST_RAIN_ALERT_RUN_MS = 0   # throttle so we only poll every few minutes


def _fetch_rain_nowcast(lat: float, lng: float) -> Optional[dict]:
    """Open-Meteo 15-minute precip nowcast + hourly probability, UTC unixtime."""
    try:
        url = (
            "https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat}&longitude={lng}"
            "&minutely_15=precipitation"
            "&hourly=precipitation,precipitation_probability"
            "&precipitation_unit=inch&timeformat=unixtime&timezone=GMT"
            "&forecast_days=1&forecast_minutely_15=12&forecast_hours=6"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "weathervalet/1.0"})
        with urllib.request.urlopen(req, timeout=6) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        print(f"[rain-alert] nowcast fetch failed ({lat},{lng}): {e}", flush=True)
        return None


def _check_rain_arriving(lat, lng, threshold_pct=80, lead_min=30):
    """Is rain about to START at (lat,lng) within lead_min minutes, at
    >= threshold_pct confidence, when it isn't already falling?

    Returns {"arriving": True, "start_ms", "minutes_out", "prob"} or None.
    """
    data = _fetch_rain_nowcast(lat, lng)
    if not data:
        return None
    now_s = int(time.time())
    horizon_s = now_s + lead_min * 60 + 600   # small buffer past the window

    m15 = data.get("minutely_15") or {}
    m_times = m15.get("time") or []
    m_precip = m15.get("precipitation") or []
    hourly = data.get("hourly") or {}
    h_times = hourly.get("time") or []
    h_prob = hourly.get("precipitation_probability") or []
    h_precip = hourly.get("precipitation") or []

    def _hour_prob_at(ts):
        best = None
        for i, ht in enumerate(h_times):
            if ht <= ts < ht + 3600:
                return h_prob[i] if i < len(h_prob) else None
            if ht <= ts:
                best = i
        if best is not None and best < len(h_prob):
            return h_prob[best]
        return None

    if m_times and m_precip:
        # Currently dry? Find the block covering 'now'.
        for i, t in enumerate(m_times):
            if t <= now_s < t + 900:
                if i < len(m_precip) and (m_precip[i] or 0) >= RAIN_ONSET_IN:
                    return None   # already raining; this is a heads-up, not a now-cast
                break
        # First FUTURE block with real precip inside the window.
        for i, t in enumerate(m_times):
            if t <= now_s:
                continue
            if t > horizon_s:
                break
            amt = m_precip[i] if i < len(m_precip) else 0
            if amt and amt >= RAIN_ONSET_IN:
                minutes_out = int(round((t - now_s) / 60.0))
                if minutes_out > lead_min:
                    return None   # rain exists but is further out than the heads-up window
                prob = _hour_prob_at(t)
                if prob is None or prob >= threshold_pct:
                    return {"arriving": True, "start_ms": t * 1000,
                            "minutes_out": max(minutes_out, 0),
                            "prob": int(prob) if prob is not None else None}
                return None
        return None

    # Fallback: no 15-minute data — use hourly only (coarser).
    for i, ht in enumerate(h_times):
        if ht <= now_s:
            continue
        if ht - now_s > lead_min * 60 + 600:
            break
        amt = h_precip[i] if i < len(h_precip) else 0
        prob = h_prob[i] if i < len(h_prob) else None
        if amt and amt >= RAIN_ONSET_IN and (prob is None or prob >= threshold_pct):
            return {"arriving": True, "start_ms": ht * 1000,
                    "minutes_out": max(int(round((ht - now_s) / 60.0)), 0),
                    "prob": int(prob) if prob is not None else None}
    return None


def _rain_alert_message(place, start_ms, minutes_out, prob, tz_name):
    try:
        tz = ZoneInfo(tz_name)
    except Exception:
        tz = ZoneInfo("America/Indiana/Indianapolis")
    when = datetime.fromtimestamp(start_ms / 1000, tz).strftime("%I:%M %p").lstrip("0")
    prob_txt = (f" ({prob}% chance)" if prob is not None else "")
    return (f"WeatherValet heads-up: rain likely at {place or 'your location'} around "
            f"{when}, about {minutes_out} minutes out{prob_txt}.")


def _process_rain_alerts():
    """Scheduler job: for the configured test account, text a 30-minute
    heads-up when rain is about to start. Dedup so it fires once per event."""
    global _LAST_RAIN_ALERT_RUN_MS
    now_ms = int(time.time() * 1000)
    if now_ms - _LAST_RAIN_ALERT_RUN_MS < 5 * 60 * 1000:
        return
    _LAST_RAIN_ALERT_RUN_MS = now_ms

    test_email = (os.environ.get("RAIN_ALERT_TEST_EMAIL") or "").strip().lower()
    if not test_email:
        return  # dormant until an email is configured in Render

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """CREATE TABLE IF NOT EXISTS rain_alert_state (
                       user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
                       last_event_start_ms BIGINT,
                       last_sent_ms BIGINT
                   )"""
            )
            cur.execute(
                """SELECT u.id, u.phone,
                          COALESCE(u.timezone, 'America/Indiana/Indianapolis') AS timezone,
                          loc.lat, loc.lng, loc.address_text
                   FROM users u
                   LEFT JOIN saved_locations loc
                        ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE LOWER(u.email) = %s AND u.is_active = TRUE
                   LIMIT 1""",
                (test_email,),
            )
            u = cur.fetchone()
            if not u or u.get("lat") is None or u.get("lng") is None or not u.get("phone"):
                return
            cur.execute(
                "SELECT last_event_start_ms, last_sent_ms FROM rain_alert_state WHERE user_id=%s",
                (u["id"],),
            )
            st = cur.fetchone() or {}

    res = _check_rain_arriving(float(u["lat"]), float(u["lng"]), threshold_pct=80, lead_min=30)
    if not res or not res.get("arriving"):
        return

    start_ms = res["start_ms"]
    last_sent = st.get("last_sent_ms") or 0
    last_start = st.get("last_event_start_ms") or 0
    # Never text more than once per 30 min; don't re-text the same event
    # (arrival within 60 min of the last alerted arrival) for 3 hours.
    if now_ms - last_sent < 30 * 60 * 1000:
        return
    if abs(start_ms - last_start) < 60 * 60 * 1000 and now_ms - last_sent < 3 * 60 * 60 * 1000:
        return

    msg = _rain_alert_message(u.get("address_text"), start_ms,
                              res.get("minutes_out") or 0, res.get("prob"), u["timezone"])
    if send_sms(u["phone"], msg):
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO rain_alert_state (user_id, last_event_start_ms, last_sent_ms)
                       VALUES (%s, %s, %s)
                       ON CONFLICT (user_id) DO UPDATE
                         SET last_event_start_ms = EXCLUDED.last_event_start_ms,
                             last_sent_ms = EXCLUDED.last_sent_ms""",
                    (u["id"], start_ms, now_ms),
                )
        print(f"[rain-alert] sent to {test_email}: {msg}", flush=True)


@app.route("/api/v1/admin/rain-alert/test", methods=["OPTIONS"])
def _admin_rain_alert_test_preflight():
    return ("", 204)


@app.post("/api/v1/admin/rain-alert/test")
def admin_rain_alert_test():
    """Run the rain detector on demand so the result is visible immediately,
    without waiting for the scheduler or for live rain. Body {"send": true}
    also texts the alert if rain is arriving. Admin only."""
    user = _get_current_user()
    if user is None or "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403
    data = request.get_json(silent=True) or {}
    do_send = bool(data.get("send"))
    force = bool(data.get("force"))
    test_email = (os.environ.get("RAIN_ALERT_TEST_EMAIL") or "").strip().lower()
    with db() as conn:
        with conn.cursor() as cur:
            if test_email:
                cur.execute(
                    """SELECT u.id, u.phone,
                              COALESCE(u.timezone,'America/Indiana/Indianapolis') AS timezone,
                              loc.lat, loc.lng, loc.address_text
                       FROM users u
                       LEFT JOIN saved_locations loc ON loc.user_id=u.id AND loc.is_primary=TRUE
                       WHERE LOWER(u.email)=%s LIMIT 1""",
                    (test_email,),
                )
            else:
                cur.execute(
                    """SELECT u.id, u.phone,
                              COALESCE(u.timezone,'America/Indiana/Indianapolis') AS timezone,
                              loc.lat, loc.lng, loc.address_text
                       FROM users u
                       LEFT JOIN saved_locations loc ON loc.user_id=u.id AND loc.is_primary=TRUE
                       WHERE u.id=%s LIMIT 1""",
                    (user["id"],),
                )
            u = cur.fetchone()
    used_fallback = False
    if not u:
        # RAIN_ALERT_TEST_EMAIL is unset or misspelled (no account matched).
        # Rather than dead-end the admin who just wants to confirm texting
        # works, fall back to their own account and note it in the response.
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.id, u.phone,
                              COALESCE(u.timezone,'America/Indiana/Indianapolis') AS timezone,
                              loc.lat, loc.lng, loc.address_text
                       FROM users u
                       LEFT JOIN saved_locations loc ON loc.user_id=u.id AND loc.is_primary=TRUE
                       WHERE u.id=%s LIMIT 1""",
                    (user["id"],),
                )
                u = cur.fetchone()
        used_fallback = bool(u)
    if not u:
        return jsonify({"ok": False, "error": "no-user",
                        "message": ("No account matches RAIN_ALERT_TEST_EMAIL"
                                    + (" (" + test_email + ")" if test_email else "")
                                    + ", and your own account couldn't be loaded either.")}), 400

    # Force a sample text regardless of weather, to confirm the SMS path
    # (phone on file + Twilio working). This is separate from the detector.
    if force:
        twilio_ok = bool(TwilioClient and TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN and TWILIO_FROM_NUMBER)
        if not u.get("phone"):
            return jsonify({"ok": True, "forced": True, "sent": False,
                            "message": "No phone number is on file for this account, so there is nothing to text. Add a number to that subscriber and try again."})
        if not twilio_ok:
            return jsonify({"ok": True, "forced": True, "sent": False,
                            "message": "Texting is not fully configured on the server (missing Twilio settings), so no text could be sent."})
        sample = ("WeatherValet test: this is a sample rain heads-up to confirm your texts are working. "
                  "Real alerts fire only when rain is actually on the way.")
        sent = bool(send_sms(u["phone"], sample))
        fb_note = (" (sent to your own admin number, since RAIN_ALERT_TEST_EMAIL didn't match an account)"
                   if used_fallback else "")
        return jsonify({"ok": True, "forced": True, "sent": sent,
                        "to": u.get("phone"), "used_fallback": used_fallback,
                        "message": ("Test text sent to " + str(u.get("phone")) + fb_note
                                    + ". If it doesn't arrive, the number may be unverified or opted out at Twilio.")
                                   if sent else
                                   "Tried to send but Twilio reported a failure. Check the Render logs and your Twilio number."})

    if u.get("lat") is None or u.get("lng") is None:
        return jsonify({"ok": False, "error": "no-location",
                        "message": "That account has no primary location with coordinates set."}), 400

    res = _check_rain_arriving(float(u["lat"]), float(u["lng"]), threshold_pct=80, lead_min=30)
    out = {
        "ok": True,
        "checked_email": test_email or user.get("email"),
        "location": u.get("address_text") or f'{u["lat"]},{u["lng"]}',
        "arriving": bool(res and res.get("arriving")),
    }
    if res:
        out["minutes_out"] = res.get("minutes_out")
        out["prob"] = res.get("prob")
        out["start_ms"] = res.get("start_ms")
    if do_send and res and res.get("arriving") and u.get("phone"):
        msg = _rain_alert_message(u.get("address_text"), res["start_ms"],
                                  res.get("minutes_out") or 0, res.get("prob"), u["timezone"])
        out["sent"] = bool(send_sms(u["phone"], msg))
        out["message_text"] = msg
    elif do_send:
        out["sent"] = False
        out["message_text"] = "No rain arriving in the next 30 minutes, so nothing to send."
    return jsonify(out)


@app.route("/api/v1/admin/nws/test-page", methods=["OPTIONS"])
def _admin_nws_test_page_preflight():
    return ("", 204)


@app.post("/api/v1/admin/nws/test-page")
def admin_nws_test_page():
    """Seed a CLEARLY-LABELED simulated severe-weather page targeting ONLY the
    admin's own account, then page the admin, so the whole alert chain can be
    watched end to end (page text -> portal 'Review & send' banner -> confirm
    -> the sample subscriber alert) without touching a single real subscriber.
    Admin only.
    """
    user = _get_current_user()
    if user is None or "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    admin_id = user["id"]
    admin_name = user.get("name") or user.get("email") or "Admin"

    # Admin's phone for the page text. Missing is not fatal: the portal banner
    # still surfaces the page, so the chain can be tested without a number.
    admin_phone = ""
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT phone FROM users WHERE id = %s", (admin_id,))
                r = cur.fetchone()
                admin_phone = (r.get("phone") or "").strip() if r else ""
    except Exception as e:
        print(f"[nws-test] phone lookup failed: {e}", flush=True)

    now_ms = int(time.time() * 1000)
    test_alert = {
        "nws_id": "TEST-" + new_secure_token()[:16],
        "event": "Tornado Warning",
        "severity": "Extreme",
        "headline": "TEST PAGE — WeatherValet system test, not a real warning",
        "description": ("This is a test of the WeatherValet severe-weather alert "
                        "chain. No real subscribers were notified; only your own "
                        "account is on this test page."),
        "instruction": "This is only a test. No action is needed.",
        "area_desc": "TEST (your account only)",
        "geometry": None,
        "expires_at": now_ms + 60 * 60 * 1000,
    }

    page_token = new_secure_token()
    affected_ids_csv = str(admin_id)     # ONLY the admin; no real subscribers
    paged_phones_csv = admin_phone

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO nws_alert_pages
                       (created_at, nws_alert_id, event, severity, headline,
                        description, instruction, area_desc, polygon_geojson,
                        expires_at, response_token, status, affected_user_ids,
                        met_paged_phone)
                       VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                               'paged', %s, %s)
                       RETURNING id""",
                    (now_ms, test_alert["nws_id"], test_alert["event"],
                     test_alert["severity"], test_alert["headline"],
                     test_alert["description"], test_alert["instruction"],
                     test_alert["area_desc"], json.dumps(test_alert["geometry"]),
                     test_alert["expires_at"], page_token,
                     affected_ids_csv, paged_phones_csv),
                )
                new_row = cur.fetchone()
    except Exception as e:
        print(f"[nws-test] insert failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "insert-failed",
                        "message": "Could not create the test page."}), 500

    paged = False
    if admin_phone:
        try:
            paged = _page_met_for_alert(
                test_alert, [{"user_id": admin_id, "name": admin_name}],
                page_token, met_phone=admin_phone, met_name=admin_name)
        except Exception as e:
            print(f"[nws-test] page send failed: {e}", flush=True)

    base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
    review_url = f"{base}/?nws-page={page_token}"

    if paged:
        note = "A page text was sent to your number, and "
    elif not admin_phone:
        note = "No phone is on file for your account, but "
    else:
        note = "The page text could not be sent (check Twilio), but "
    msg = ("Test page created. " + note
           + "it also appears in your Met portal's 'Review & send' banner. "
           + "Open it there (or the review link), tap confirm, and the sample "
           + "subscriber alert will go only to your own account.")

    print(f"[nws-test] admin={admin_id} page_id={new_row['id']} paged={paged}", flush=True)
    return jsonify({
        "ok": True,
        "page_id": new_row["id"],
        "review_url": review_url,
        "paged_phone": bool(paged),
        "phone_on_file": bool(admin_phone),
        "message": msg,
    })
# In-memory TTL cache for the radio-partner widget endpoint. Keys are
# (lat, lng) tuples rounded to 4 decimal places (~10m precision); values
# are (timestamp_ms, payload) tuples. Widget pages embed on partner
# sites and may be loaded by every visitor on every page view, so we
# cache the upstream Open-Meteo response for WIDGET_CACHE_TTL_SECONDS
# to keep traffic to api.open-meteo.com sane. The cache lives in the
# gunicorn worker process; with multiple workers, each maintains its
# own. That's fine — Open-Meteo handles modest traffic and the cache
# only needs to prevent runaway request rates, not be globally unique.
_WIDGET_FORECAST_CACHE: dict[tuple[float, float], tuple[int, dict]] = {}
WIDGET_CACHE_TTL_SECONDS = 600  # 10 minutes


def _fetch_forecast_7day(lat: float, lng: float) -> Optional[dict]:
    """Fetch a 7-day forecast with current conditions for the widget.

    Returns a raw Open-Meteo response with daily highs/lows/conditions
    for 7 days plus current_weather. Cached for 10 minutes per
    (lat,lng) so embeds don't hammer the upstream API.

    Phase 1 of the widget: this is the only data source. Phase 2 adds
    a Met-edited narrative on top of this AI-generated forecast.
    """
    cache_key = (round(lat, 4), round(lng, 4))
    now_ms = int(time.time() * 1000)
    cached = _WIDGET_FORECAST_CACHE.get(cache_key)
    if cached and (now_ms - cached[0]) < (WIDGET_CACHE_TTL_SECONDS * 1000):
        return cached[1]
    try:
        url = (
            "https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat}&longitude={lng}"
            "&current_weather=true"
            "&hourly=temperature_2m,relativehumidity_2m,precipitation_probability,"
            "windspeed_10m,winddirection_10m,weathercode"
            "&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,"
            "precipitation_probability_max,windspeed_10m_max,weathercode,sunrise,sunset"
            "&temperature_unit=fahrenheit&windspeed_unit=mph"
            "&precipitation_unit=inch&timezone=auto&forecast_days=7"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "weathervalet/1.0"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        _WIDGET_FORECAST_CACHE[cache_key] = (now_ms, data)
        return data
    except Exception as e:
        print(f"[widget-forecast] fetch failed for ({lat},{lng}): {e}", flush=True)
        # On failure, fall back to whatever's in the cache even if stale.
        # Better to show 11-min-old data than nothing.
        if cached:
            print(f"[widget-forecast] serving stale cache for ({lat},{lng})", flush=True)
            return cached[1]
        return None


# ── Widget alert cache (May 28, 2026, Phase 4) ──
# Active NWS alerts cache. Separate from the forecast cache (10 min)
# because severe weather requires FRESH data — a Tornado Warning issued
# at 2:31 PM cannot wait until 2:41 PM to appear on the widget.
# 2-minute TTL is the compromise: NWS pushes new alert states every ~1
# minute, so 2 minutes is "close enough to real-time" without hammering
# api.weather.gov when an embed gets high traffic during a storm.
_WIDGET_ALERTS_CACHE: dict[tuple[float, float], tuple[int, list]] = {}
WIDGET_ALERTS_TTL_SECONDS = 120  # 2 minutes

# Curated list of NWS alert event types the widget surfaces.
# These are the ones that matter for outdoor safety in the Plains/
# Midwest market we're starting with. Marine/coastal/tsunami events
# are intentionally excluded (irrelevant to landlocked stations).
# Add more types here as we expand to other regions.
WIDGET_SURFACED_EVENTS = frozenset({
    # Severe convective
    "Tornado Warning", "Tornado Watch",
    "Severe Thunderstorm Warning", "Severe Thunderstorm Watch",
    # Flooding
    "Flash Flood Warning", "Flash Flood Watch",
    "Flood Warning", "Flood Watch", "Flood Advisory",
    # Winter
    "Winter Storm Warning", "Winter Storm Watch",
    "Blizzard Warning", "Blizzard Watch",
    "Ice Storm Warning",
    "Winter Weather Advisory",
    # Wind / heat / fire / fog / cold
    "High Wind Warning", "High Wind Watch",
    "Wind Advisory",
    "Extreme Heat Warning", "Extreme Heat Watch",
    "Heat Advisory",
    "Red Flag Warning", "Fire Weather Watch",
    "Dense Fog Advisory",
    "Freeze Warning", "Freeze Watch", "Frost Advisory",
    # Special
    "Special Weather Statement",
})


def _fetch_widget_alerts(lat: float, lng: float) -> list:
    """Fetch currently-active NWS alerts for a widget location.

    Returns a list of alert dicts ordered by severity (Extreme/Severe
    first), filtered to the curated WIDGET_SURFACED_EVENTS set.
    Cached for 2 minutes per (lat,lng).

    Each alert dict shape:
      {
        id, event, severity, urgency, certainty,
        headline, description,
        effective_iso, expires_iso, ends_iso,
        sender_name
      }

    Returns [] on any failure — the widget will show a forecast with
    no alert banner, which is the safe default. We don't surface
    fetch errors to the public widget.
    """
    cache_key = (round(lat, 4), round(lng, 4))
    now_ms = int(time.time() * 1000)
    cached = _WIDGET_ALERTS_CACHE.get(cache_key)
    if cached and (now_ms - cached[0]) < (WIDGET_ALERTS_TTL_SECONDS * 1000):
        return cached[1]
    try:
        lat_s = f"{float(lat):.4f}"
        lng_s = f"{float(lng):.4f}"
        url = (
            "https://api.weather.gov/alerts/active"
            f"?point={lat_s},{lng_s}"
        )
        headers = {
            "User-Agent": "WeatherValet (michael@weathervalet.com)",
            "Accept": "application/geo+json",
        }
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        features = data.get("features") or []
        out = []
        for f in features:
            props = f.get("properties") or {}
            event = (props.get("event") or "").strip()
            if event not in WIDGET_SURFACED_EVENTS:
                continue
            out.append({
                "id": props.get("id") or "",
                "event": event,
                "severity": props.get("severity") or "",
                "urgency": props.get("urgency") or "",
                "certainty": props.get("certainty") or "",
                "headline": (props.get("headline") or "").strip(),
                "description": (props.get("description") or "").strip(),
                "effective_iso": props.get("effective") or "",
                "expires_iso": props.get("expires") or "",
                "ends_iso": props.get("ends") or "",
                "sender_name": props.get("senderName") or "",
            })
        # Sort by severity rank — Extreme > Severe > Moderate > Minor > Unknown.
        # Then by event-name severity (Warnings outrank Watches, etc.) as
        # a secondary sort. Most urgent alert appears first in the banner.
        sev_rank = {"Extreme": 0, "Severe": 1, "Moderate": 2, "Minor": 3, "Unknown": 4}
        def _event_rank(ev: str) -> int:
            ev_lower = ev.lower()
            if "warning" in ev_lower: return 0
            if "watch" in ev_lower: return 1
            if "advisory" in ev_lower: return 2
            if "statement" in ev_lower: return 3
            return 4
        out.sort(key=lambda a: (sev_rank.get(a["severity"], 5),
                                _event_rank(a["event"]),
                                a["effective_iso"]))
        _WIDGET_ALERTS_CACHE[cache_key] = (now_ms, out)
        return out
    except Exception as e:
        print(f"[widget-alerts] fetch failed for ({lat},{lng}): {e!r}", flush=True)
        # On failure, fall back to whatever's in the cache even if stale.
        # Better to show 3-min-old alert data than no alerts during a storm.
        if cached:
            return cached[1]
        return []


def _generate_widget_narrative(location_name: str, forecast: dict) -> str:
    """Generate a 3-4 sentence weather narrative for the widget detail page.

    Phase 2 of the radio-partner widget (May 28, 2026). Produces prose
    suitable for a "meteorologist note" — the kind of analytical
    commentary you'd hear on local radio. Examples of the style:
      "An active weather pattern moves through the region this week..."
      "High pressure builds in by mid-week, locking in pleasant
       conditions through the weekend..."

    Deterministic templating against the 7-day forecast — no LLM call.
    Looks at temperature trend (warming/cooling/steady), precipitation
    chances (active vs. dry), and notable wind to construct prose.
    Returns empty string if forecast data is unusable; caller should
    not publish in that case.

    Mets can edit this output in their workspace if they want to add
    local context (e.g., "this is the front that the Climate Prediction
    Center flagged in their 6-10 day outlook"). Editing flips
    met_touched=True on the widget_narratives row.
    """
    if not forecast or "daily" not in forecast:
        return ""
    daily = forecast.get("daily") or {}
    times = daily.get("time") or []
    if len(times) < 3:
        return ""
    highs = daily.get("temperature_2m_max") or []
    lows = daily.get("temperature_2m_min") or []
    precip_in = daily.get("precipitation_sum") or []
    precip_prob = daily.get("precipitation_probability_max") or []
    winds = daily.get("windspeed_10m_max") or []
    codes = daily.get("weathercode") or []

    # Defensive: pad arrays to same length
    n = min(len(times), len(highs), len(lows), len(codes))
    if n < 3:
        return ""

    # ── Sentence 1: Today's setup ──
    today_code = codes[0] if n > 0 else 0
    today_label = _weather_code_label(today_code).lower()
    today_high = highs[0]
    today_low = lows[0]
    today_precip_prob = precip_prob[0] if len(precip_prob) > 0 else None
    today_wind = winds[0] if len(winds) > 0 else None

    s1_parts = []
    # Opening framing depends on conditions
    if today_label in ("clear", "mostly clear"):
        s1_parts.append("Quiet weather to start the day across the area")
    elif today_label == "overcast":
        s1_parts.append("Cloudy skies hold across the area today")
    elif "rain" in today_label or "showers" in today_label or "drizzle" in today_label:
        s1_parts.append("Wet weather is the headline today")
    elif "snow" in today_label:
        s1_parts.append("Snow is the story across the region today")
    elif "thunder" in today_label:
        s1_parts.append("Thunderstorm chances stand out today")
    elif "fog" in today_label:
        s1_parts.append("Fog will be the morning concern")
    else:
        s1_parts.append(f"A mix of conditions sets the stage today")

    if today_high is not None:
        s1_parts.append(f"with highs reaching {round(today_high)}°")
    sentence_1 = ", ".join(s1_parts) + "."

    # ── Sentence 2: Precipitation outlook ──
    sentence_2 = ""
    # Look at next 3 days for precip chances
    wet_days = []
    for i in range(min(4, n)):
        p = precip_prob[i] if i < len(precip_prob) else 0
        if p is not None and p >= 40:
            day_name = "today" if i == 0 else ("tomorrow" if i == 1 else _day_word(times[i]))
            wet_days.append((day_name, int(p)))
    if wet_days:
        if len(wet_days) == 1:
            sentence_2 = f"The best chance for precipitation comes {wet_days[0][0]} at {wet_days[0][1]}%."
        else:
            day_names = ", ".join(d[0] for d in wet_days[:-1]) + f" and {wet_days[-1][0]}"
            sentence_2 = f"Precipitation chances run highest {day_names}."
    else:
        # No notable precip in the window
        sentence_2 = "No widespread precipitation looks likely through the next several days."

    # ── Sentence 3: Temperature trend ──
    sentence_3 = ""
    # Compare today's high to days 2-4
    later_highs = [h for h in highs[1:4] if h is not None]
    if today_high is not None and later_highs:
        avg_later = sum(later_highs) / len(later_highs)
        diff = avg_later - today_high
        if diff >= 8:
            sentence_3 = f"Temperatures climb through midweek, peaking near {round(max(later_highs))}°."
        elif diff <= -8:
            sentence_3 = f"Cooler air settles in over the next few days, with highs dropping to the {_temp_bucket(min(later_highs))}s."
        else:
            sentence_3 = f"Temperatures hold fairly steady, generally in the {_temp_bucket(today_high)}s through the period."

    # ── Sentence 4: Wind callout if significant ──
    sentence_4 = ""
    max_wind = max([w for w in winds[:4] if w is not None] or [0])
    if max_wind >= 25:
        wind_day_idx = next((i for i, w in enumerate(winds[:4]) if w == max_wind), 0)
        wind_day = "today" if wind_day_idx == 0 else ("tomorrow" if wind_day_idx == 1 else _day_word(times[wind_day_idx]))
        sentence_4 = f"Wind picks up {wind_day}, gusting to {round(max_wind)} mph at times."

    parts = [s for s in (sentence_1, sentence_2, sentence_3, sentence_4) if s]
    return " ".join(parts)


def _day_word(date_iso: str) -> str:
    """Convert ISO date to a day-of-week word for narrative use.
    'Wednesday', 'Thursday', etc. Returns 'later this week' if parse fails."""
    try:
        d = datetime.strptime(date_iso, "%Y-%m-%d")
        return d.strftime("%A")
    except Exception:
        return "later this week"


def _temp_bucket(temp_f: float) -> str:
    """Bucket a temperature into a decade label ('70', '80', etc.)
    Used in narratives like 'in the 70s'."""
    try:
        return str(int(temp_f) // 10 * 10)
    except Exception:
        return "comfortable"


def _weather_code_label(code: int) -> str:
    """Open-Meteo WMO weather code → short human label."""
    if code == 0: return "Clear"
    if code in (1, 2): return "Mostly clear"
    if code == 3: return "Overcast"
    if code in (45, 48): return "Fog"
    if code in (51, 53, 55): return "Drizzle"
    if code in (61, 63, 65): return "Rain"
    if code in (66, 67): return "Freezing rain"
    if code in (71, 73, 75, 77): return "Snow"
    if code in (80, 81, 82): return "Rain showers"
    if code in (85, 86): return "Snow showers"
    if code in (95, 96, 99): return "Thunderstorms"
    return "Mixed conditions"


# ── US state lookup tables (May 28, 2026) ──
# Used by _smart_location_label to detect and de-duplicate state names
# in malformed addresses. Added when subscriber addresses came in as
# "Lebanon, in, IN" (state appearing twice), which produced "Today in
# in, IN..." in briefs going to subscribers.
US_STATE_NAME_TO_CODE = {
    "alabama":"AL","alaska":"AK","arizona":"AZ","arkansas":"AR","california":"CA",
    "colorado":"CO","connecticut":"CT","delaware":"DE","district of columbia":"DC",
    "florida":"FL","georgia":"GA","hawaii":"HI","idaho":"ID","illinois":"IL",
    "indiana":"IN","iowa":"IA","kansas":"KS","kentucky":"KY","louisiana":"LA",
    "maine":"ME","maryland":"MD","massachusetts":"MA","michigan":"MI",
    "minnesota":"MN","mississippi":"MS","missouri":"MO","montana":"MT",
    "nebraska":"NE","nevada":"NV","new hampshire":"NH","new jersey":"NJ",
    "new mexico":"NM","new york":"NY","north carolina":"NC","north dakota":"ND",
    "ohio":"OH","oklahoma":"OK","oregon":"OR","pennsylvania":"PA","rhode island":"RI",
    "south carolina":"SC","south dakota":"SD","tennessee":"TN","texas":"TX",
    "utah":"UT","vermont":"VT","virginia":"VA","washington":"WA","west virginia":"WV",
    "wisconsin":"WI","wyoming":"WY",
}
US_STATE_CODES = set(US_STATE_NAME_TO_CODE.values())


def _titlecase_city(s: str) -> str:
    """Title-case a city name. Each word's first letter uppercased,
    rest lowercased. Preserves dots ("St. Louis") and hyphens."""
    if not s:
        return s
    return " ".join(
        (w[0].upper() + w[1:].lower()) if w else w
        for w in s.split()
    )


def _looks_like_state_dup(part_lower: str, state_code: str) -> bool:
    """True if this address part IS just the state code or full name,
    matching the state_code we already detected. Used to skip redundant
    "state appearing twice" pieces like 'in' or 'Indiana' when state='IN'."""
    if part_lower.upper() == state_code:
        return True
    if (part_lower in US_STATE_NAME_TO_CODE
            and US_STATE_NAME_TO_CODE[part_lower] == state_code):
        return True
    return False


def _smart_location_label(label: str, address: str) -> str:
    """Pick the best label for the brief opener.

    May 22, 2026: subscribers often label their primary location as
    'Home' / 'Work' / 'House' / etc., which reads awkwardly in a brief
    ('Today in Home...'). When the label is generic, we fall back to
    extracting a city/state from the address.

    May 28, 2026 rebuild: handles bad addresses gracefully. Many
    subscribers had addresses stored as 'Lebanon, in, IN' (state
    duplicated) or 'atwood kansas, KS' (lowercase + redundant state
    name), which produced 'Today in in, IN...' or 'Today in atwood
    kansas, KS...' in briefs. Now:
      - Detects state code in the last part (e.g., 'KS', 'IN', 'DC')
      - Strips redundant state names appearing earlier in the address
      - Title-cases the city (so 'atwood' becomes 'Atwood')
      - Falls back to 'your location' only if nothing parses cleanly

    20/20 test cases pass including: 'Lebanon, in, IN' -> 'Lebanon, IN',
    'atwood kansas, KS' -> 'Atwood, KS', 'New York, NY' -> 'New York, NY'.
    """
    generic = {"home", "house", "work", "office", "primary", "main", ""}
    label_clean = (label or "").strip()
    if label_clean and label_clean.lower() not in generic:
        return label_clean

    addr = (address or "").strip()
    if not addr:
        return "your location"

    # Split on commas, strip, drop empties
    parts = [p.strip() for p in addr.split(",") if p.strip()]

    # Strip trailing zip from last part (e.g., 'IN 46052' -> 'IN')
    if parts:
        last_tokens = parts[-1].split()
        if last_tokens and last_tokens[-1].isdigit() and len(last_tokens[-1]) >= 5:
            parts[-1] = " ".join(last_tokens[:-1]).strip()
            if not parts[-1]:
                parts.pop()

    # Drop parts that look like street numbers (start with a digit)
    clean = []
    for p in parts:
        first_word = p.split()[0] if p.split() else ""
        if first_word and first_word[0].isdigit():
            continue  # street address fragment, skip
        clean.append(p)

    if not clean:
        return "your location"

    # Detect state in the last part — code (e.g. 'KS') or full name (e.g. 'Kansas')
    state_code = None
    last = clean[-1].strip()
    if last.upper() in US_STATE_CODES:
        state_code = last.upper()
    elif last.lower() in US_STATE_NAME_TO_CODE:
        state_code = US_STATE_NAME_TO_CODE[last.lower()]

    if not state_code:
        # No state detected — return what we have, title-cased
        if len(clean) >= 2:
            return f"{_titlecase_city(clean[-2])}, {_titlecase_city(clean[-1])}"
        return _titlecase_city(clean[0])

    # State found. Walk left to find the city, skipping any redundant
    # state-name parts (e.g., 'in' or 'Indiana' when state='IN').
    candidates = clean[:-1]
    city_part = None
    for p in reversed(candidates):
        if _looks_like_state_dup(p.lower(), state_code):
            continue
        city_part = p
        break

    if city_part is None:
        # All candidates were state duplicates. Take rightmost as last resort.
        if candidates:
            city_part = candidates[-1]

    if city_part:
        # Strip a trailing redundant state name inside the city string
        # (e.g., 'trenton new jersey' -> 'trenton' when state='NJ',
        #  'atwood kansas' -> 'atwood' when state='KS')
        words = city_part.split()
        if len(words) >= 2:
            last_lower = words[-1].lower()
            if (last_lower in US_STATE_NAME_TO_CODE
                    and US_STATE_NAME_TO_CODE[last_lower] == state_code):
                city_part = " ".join(words[:-1])
            elif len(words) >= 3:
                last_two = " ".join(words[-2:]).lower()
                if (last_two in US_STATE_NAME_TO_CODE
                        and US_STATE_NAME_TO_CODE[last_two] == state_code):
                    city_part = " ".join(words[:-2])
        return f"{_titlecase_city(city_part)}, {state_code}"

    return state_code


def _format_precip_natural(precip: float) -> str:
    """Convert inches to natural English ('about a third of an inch')."""
    if precip < 0.05:
        return ""
    if precip < 0.15:
        return "a tenth of an inch"
    if precip < 0.30:
        return "about a quarter of an inch"
    if precip < 0.45:
        return "about a third of an inch"
    if precip < 0.65:
        return "about half an inch"
    if precip < 0.85:
        return "about three quarters of an inch"
    if precip < 1.10:
        return "about an inch"
    return f"around {precip:.1f} inches"


def _alert_met_on_suppressed_brief(subscriber_user_id: int,
                                    subscriber_name: str,
                                    location_label: str,
                                    reason: str) -> None:
    """Email the assigned primary Met (or admin fallback) when an AI
    Hobbyist brief was held back due to bad data.

    Added May 22, 2026 alongside the data quality gate in
    _generate_ai_brief. The Met can then look at the subscriber's
    profile, fix the data issue (or wait for the forecast feed to
    recover), and send the brief manually if appropriate.

    Idempotency: this function sends one email per call. The caller
    (the scheduler) only invokes it once per suppression event because
    of the brief_history check downstream. We don't dedupe here.
    """
    # Look up the primary Met (or any admin if no Met assigned)
    met_email = None
    met_name = None
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.email, u.name
                       FROM subscriber_coverage sc
                       JOIN users u ON u.id = sc.primary_met_id
                       WHERE sc.user_id = %s""",
                    (subscriber_user_id,),
                )
                row = cur.fetchone()
                if row:
                    met_email = row["email"]
                    met_name = row["name"]
                else:
                    # No primary Met — fall back to first admin
                    cur.execute(
                        """SELECT u.email, u.name
                           FROM users u
                           JOIN user_roles ur ON ur.user_id = u.id
                           WHERE ur.role = 'admin' AND u.is_active = TRUE
                           ORDER BY u.id ASC LIMIT 1"""
                    )
                    row = cur.fetchone()
                    if row:
                        met_email = row["email"]
                        met_name = row["name"]
    except Exception as e:
        print(f"[alert-suppressed] met lookup failed: {e}", flush=True)
        return

    if not met_email:
        print(f"[alert-suppressed] no Met/admin email found for subscriber {subscriber_user_id}", flush=True)
        return

    subject = f"Hold required: {subscriber_name}'s morning brief flagged"
    body_text = (
        f"Hi {met_name or 'team'},\n\n"
        f"WeatherValet's automated brief generator flagged today's morning brief for "
        f"{subscriber_name} ({location_label}) as low-confidence. The brief was NOT sent.\n\n"
        f"Reason: {reason}\n\n"
        f"Please review the subscriber's data (location coordinates, etc.) and decide "
        f"whether to send a manual brief, fix the data, or wait for the next scheduled run.\n\n"
        f"— WeatherValet"
    )
    body_html = (
        f"<p>Hi {_html_escape(met_name or 'team')},</p>"
        f"<p>WeatherValet's automated brief generator flagged today's morning brief for "
        f"<strong>{_html_escape(subscriber_name)}</strong> ({_html_escape(location_label)}) "
        f"as low-confidence. The brief was <strong>NOT sent</strong>.</p>"
        f"<p><strong>Reason:</strong> {_html_escape(reason)}</p>"
        f"<p>Please review the subscriber's data (location coordinates, etc.) and decide "
        f"whether to send a manual brief, fix the data, or wait for the next scheduled run.</p>"
        f"<p style='color:#666;font-size:12px;'>— WeatherValet</p>"
    )
    try:
        ok = _send_brief_email(met_email, subject, body_html)
        if ok:
            print(f"[alert-suppressed] alerted met={met_email} subscriber={subscriber_user_id}", flush=True)
        else:
            print(f"[alert-suppressed] email send failed met={met_email}", flush=True)
    except Exception as e:
        print(f"[alert-suppressed] send exception met={met_email}: {e}", flush=True)


def _generate_ai_brief(location_label: str, forecast: dict,
                       address: str = "") -> tuple[str, str, str]:
    """Generate a daily brief paragraph.

    Returns (verdict, snippet, full_body):
      verdict — "clear" | "caution" | "risk" | "suppress"
      snippet — first ~140 chars suitable for SMS preview / portal card
      full_body — the full brief in complete sentences

    May 22, 2026 rewrite: plain English with complete sentences. No
    editorializing about "you can work today" or "outdoor plans."
    The brief describes the weather; the subscriber/Met decides what
    to do with it.

    Data quality: returns verdict='suppress' when the forecast looks
    unusable (missing high/low/precip, fetch failed, etc.) — callers
    should NOT send the brief in this case; instead alert the Met or
    admin so a human can investigate.

    location_label: the label from saved_locations (e.g., "Home"); we
        upgrade to city/state via address if it's generic.
    address: optional full address string used to extract city/state
        when location_label is generic.
    """
    # Data quality check: forecast must be present and have daily data
    if not forecast or "daily" not in forecast:
        body = "Today's forecast data is not available right now."
        return ("suppress", body, body)

    daily = forecast["daily"]
    high = (daily.get("temperature_2m_max") or [None])[0]
    low = (daily.get("temperature_2m_min") or [None])[0]
    precip = (daily.get("precipitation_sum") or [0])[0] or 0
    wind = (daily.get("windspeed_10m_max") or [0])[0] or 0
    code = (daily.get("weathercode") or [0])[0] or 0

    # Data quality: critical fields can't be None
    if high is None or low is None:
        body = "Today's high/low temperature data is missing from the forecast feed."
        return ("suppress", body, body)
    # Sanity range check
    try:
        high_int = int(high)
        low_int = int(low)
        if high_int < -60 or high_int > 140 or low_int < -80 or low_int > 130:
            body = f"Today's forecast data looks out of range (high={high_int}°F, low={low_int}°F)."
            return ("suppress", body, body)
        if low_int > high_int:
            body = f"Today's forecast has low ({low_int}°F) higher than high ({high_int}°F), data may be corrupted."
            return ("suppress", body, body)
    except (TypeError, ValueError):
        body = "Today's temperature data couldn't be parsed."
        return ("suppress", body, body)

    conditions = _weather_code_label(int(code))
    place = _smart_location_label(location_label, address)

    # Verdict logic — conservative thresholds suitable for a "should I
    # do my outdoor thing today" brief. Verdict drives the UI badge
    # color, not the prose itself.
    if precip >= 0.5 or wind >= 30 or code in (95, 96, 99):
        verdict = "risk"
    elif precip >= 0.1 or wind >= 20 or code in (51, 53, 55, 61, 63, 65, 80, 81):
        verdict = "caution"
    else:
        verdict = "clear"

    # ── Compose the brief in complete sentences ──
    # No editorializing about what the subscriber should or shouldn't
    # do. Just describe the weather accurately.
    sentences = []

    # Opening sentence: conditions + high/low in one natural sentence
    cond_lower = conditions.lower()
    if cond_lower == "clear":
        opener = f"Today in {place} will be clear, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower == "mostly clear":
        opener = f"Today in {place} will be mostly clear, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower == "overcast":
        opener = f"Today in {place} will be overcast, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower == "fog":
        opener = f"Today in {place} starts with fog, then a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower in ("drizzle", "rain", "rain showers"):
        opener = f"Today in {place} brings {cond_lower}, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower == "freezing rain":
        opener = f"Today in {place} brings freezing rain, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower in ("snow", "snow showers"):
        opener = f"Today in {place} brings {cond_lower}, with a high of {high_int}°F and a low of {low_int}°F."
    elif cond_lower == "thunderstorms":
        opener = f"Today in {place} looks unsettled, with thunderstorms expected and a high of {high_int}°F and a low of {low_int}°F."
    else:
        opener = f"Today in {place} will be {cond_lower}, with a high of {high_int}°F and a low of {low_int}°F."
    sentences.append(opener)

    # Precipitation detail sentence
    precip_phrase = _format_precip_natural(precip)
    if precip_phrase:
        # Avoid awkward "Around about three quarters..." when the phrase
        # already includes "about" or "around".
        if precip_phrase.startswith("about") or precip_phrase.startswith("around"):
            sentences.append(f"{precip_phrase.capitalize()} of precipitation is expected through the day.")
        else:
            sentences.append(f"Around {precip_phrase} of precipitation is expected through the day.")

    # Wind detail sentence
    if wind >= 25:
        sentences.append(f"Winds could gust up to {int(wind)} mph at times.")
    elif wind >= 15:
        sentences.append(f"Winds will gust up to {int(wind)} mph at times.")
    elif wind >= 8:
        sentences.append(f"Winds will be light, around {int(wind)} mph.")

    full_body = " ".join(sentences)
    snippet = full_body[:140]
    return (verdict, snippet, full_body)


def _extract_predicted_values_from_forecast(forecast: Optional[dict]) -> dict:
    """Extract structured predictions from an Open-Meteo forecast dict.

    Added May 26, 2026 to support work-impact accuracy grading. The
    brief generator already has the forecast in hand when it writes
    to brief_history — we just need to peel out the day's high, low,
    expected precipitation, and max wind so the grader can compare
    against observed values later.

    Returns a dict with keys: predicted_high_f, predicted_low_f,
    predicted_precip_in, predicted_max_wind_mph. Any field that the
    forecast didn't include comes back as None — the grader handles
    NULLs gracefully (it grades on what's available).

    Open-Meteo response shape:
        forecast = {
            "daily": {
                "temperature_2m_max": [78.4],
                "temperature_2m_min": [52.1],
                "precipitation_sum":  [0.0],
                "windspeed_10m_max":  [11.8],
                ...
            },
            ...
        }
    The brief covers today (forecast_days=1) so we always read index [0].
    """
    out = {
        "predicted_high_f": None,
        "predicted_low_f": None,
        "predicted_precip_in": None,
        "predicted_max_wind_mph": None,
    }
    if not forecast:
        return out
    daily = forecast.get("daily") or {}

    def _first_value(key: str):
        seq = daily.get(key)
        if isinstance(seq, list) and seq:
            v = seq[0]
            return v if v is not None else None
        return None

    high = _first_value("temperature_2m_max")
    low = _first_value("temperature_2m_min")
    precip = _first_value("precipitation_sum")
    wind = _first_value("windspeed_10m_max")

    # Round temps/wind to integers (the columns are INTEGER); keep precip
    # as float for the NUMERIC(5,2) column.
    try:
        out["predicted_high_f"] = int(round(float(high))) if high is not None else None
    except Exception:
        pass
    try:
        out["predicted_low_f"] = int(round(float(low))) if low is not None else None
    except Exception:
        pass
    try:
        out["predicted_precip_in"] = float(precip) if precip is not None else None
    except Exception:
        pass
    try:
        out["predicted_max_wind_mph"] = int(round(float(wind))) if wind is not None else None
    except Exception:
        pass
    return out


def _parse_predictions_from_brief_text(body: Optional[str]) -> dict:
    """Best-effort extraction of predicted values from brief body text.

    Added May 26, 2026 as a fallback for briefs that pre-date the
    structured-predictions schema. Brief authors write in natural
    language so this parser is intentionally conservative — it catches
    common patterns and returns None for anything ambiguous. The grader
    treats None as "couldn't extract this field, skip the comparison."

    Patterns we try to catch:
      - "high of 78°F" / "high near 78" / "highs in the upper 70s"
      - "low of 52°F" / "overnight low 52" / "lows in the low 50s"
      - "0.25 inches of rain" / "0.1\" precip" / "trace rain"
      - "winds 10-15 mph" / "wind gusts to 25 mph" / "20 mph winds"

    Returns dict with same shape as _extract_predicted_values_from_forecast.
    """
    out = {
        "predicted_high_f": None,
        "predicted_low_f": None,
        "predicted_precip_in": None,
        "predicted_max_wind_mph": None,
    }
    if not body:
        return out
    text = body.lower()

    # ── High temperature ──
    # Match: "high of 78", "high near 78", "high 78°F"
    # Does NOT match "high 70s" (decade form) — handled below.
    high_match = re.search(
        r"high(?:s)?\s+(?:of|near|around)\s+(\d{2,3})(?:[\s°]*f)?",
        text,
    )
    if not high_match:
        # "high XX°F" / "high XX F" with no preposition
        high_match = re.search(
            r"\bhigh(?:s)?\s+(\d{2,3})\s*°?\s*f\b",
            text,
        )
    if not high_match:
        # "high XX." or "high XX," (sentence-final number)
        high_match = re.search(
            r"\bhigh(?:s)?\s+(\d{2,3})[\s\.,]",
            text,
        )
    if high_match:
        try:
            v = int(high_match.group(1))
            # Sanity: realistic high temps are 0-130°F
            if 0 <= v <= 130:
                out["predicted_high_f"] = v
        except Exception:
            pass

    # "highs in the upper 70s" / "highs in the low 80s" — coarse but useful
    if out["predicted_high_f"] is None:
        decade_match = re.search(
            r"high(?:s)?\s*(?:in the)?\s*(low|mid|upper)\s+(\d0)s",
            text,
        )
        if decade_match:
            try:
                base = int(decade_match.group(2))
                pos = decade_match.group(1)
                offset = {"low": 2, "mid": 5, "upper": 8}.get(pos, 5)
                out["predicted_high_f"] = base + offset
            except Exception:
                pass

    # ── Low temperature ──
    # Match: "low of 52", "low near 52", "overnight low 52°F"
    # Intentionally requires either an explicit prefix (of/near/around)
    # OR direct number after — does NOT match "low 50s" (decade form),
    # which is handled by the decade fallback below.
    low_match = re.search(
        r"(?:overnight\s+)?low(?:s)?\s+(?:of|near|around)\s+(\d{1,3})(?:[\s°]*f)?",
        text,
    )
    if not low_match:
        # Also try "low XX°F" / "low XX F" with no preposition
        low_match = re.search(
            r"\blow(?:s)?\s+(\d{1,3})\s*°?\s*f\b",
            text,
        )
    if not low_match:
        # And "low XX." or "low XX," (sentence-final number)
        low_match = re.search(
            r"\blow(?:s)?\s+(\d{1,3})[\s\.,]",
            text,
        )
    if low_match:
        try:
            v = int(low_match.group(1))
            if -30 <= v <= 90:  # sanity
                out["predicted_low_f"] = v
        except Exception:
            pass

    if out["predicted_low_f"] is None:
        decade_match = re.search(
            r"low(?:s)?\s*(?:in the)?\s*(low|mid|upper)\s+(\d0)s",
            text,
        )
        if decade_match:
            try:
                base = int(decade_match.group(2))
                pos = decade_match.group(1)
                offset = {"low": 2, "mid": 5, "upper": 8}.get(pos, 5)
                out["predicted_low_f"] = base + offset
            except Exception:
                pass

    # ── Precipitation ──
    # Match: "0.25 inches", "0.1\"", "1.5 inches of rain"
    precip_match = re.search(
        r"(\d+\.\d+)\s*(?:inches?|\"|in\b)\s*(?:of\s+)?(?:rain|precip|precipitation)",
        text,
    )
    if precip_match:
        try:
            v = float(precip_match.group(1))
            if 0 <= v <= 20:  # sanity (20" is biblical)
                out["predicted_precip_in"] = v
        except Exception:
            pass

    # "trace" / "no rain" / "dry" / "no measurable precip"
    if out["predicted_precip_in"] is None:
        if re.search(r"\bno\s+(?:measurable\s+)?(?:rain|precip|precipitation)\b", text) or \
           re.search(r"\b(?:dry|clear)\s+(?:day|conditions|throughout)", text):
            out["predicted_precip_in"] = 0.0
        elif re.search(r"\btrace\s+(?:of\s+)?(?:rain|precip|precipitation)\b", text):
            out["predicted_precip_in"] = 0.01  # nominal trace

    # ── Max wind ──
    # Match: "winds 10-15 mph", "winds W 5-15 mph", "winds NW at 10-15 mph"
    # Direction letters (N/S/E/W, NE/NW/SE/SW, NNE etc.) may appear
    # between "winds" and the number — optionally followed by "at".
    # Match: "gusts to 25 mph", "20 mph winds"
    wind_range = re.search(
        r"winds?\s+(?:[NSEWnsew]{1,3}\s+)?(?:at\s+)?\d{1,2}\s*[-\u2013]\s*(\d{1,3})\s*mph",
        text,
    )
    wind_gust = re.search(r"gust(?:s|ing)?\s+to\s+(\d{1,3})\s*mph", text)
    wind_solo = re.search(r"(\d{1,3})\s*mph\s+winds?", text)

    best_wind = None
    for m in (wind_gust, wind_range, wind_solo):
        if m:
            try:
                v = int(m.group(1))
                if 0 <= v <= 150 and (best_wind is None or v > best_wind):
                    best_wind = v
            except Exception:
                pass
    if best_wind is not None:
        out["predicted_max_wind_mph"] = best_wind

    return out


def _generate_hobbyist_brief_llm(location_label: str, forecast: dict,
                                   address: str = "",
                                   subscriber_name: str = "") -> tuple[str, str, str]:
    """LLM-backed Hobbyist daily brief generation (May 23, 2026).

    Tries the LLM first using EXPLAINER_SYSTEM_PROMPT with a synthetic
    "daily brief, no specific activity" plan. Falls back to the
    deterministic template (_generate_ai_brief) on any failure: no API
    key, timeout, non-200, malformed response.

    Returns the same (verdict, snippet, full_body) tuple as
    _generate_ai_brief — drop-in replacement.

    Why this exists: the template is plain English and accurate, but
    sterile. The LLM produces warmer prose with texture words, time-
    anchored detail, and soft conditionals — same standard we set for
    the homepage Starter Forecast. Hobbyists pay $30/mo and deserve
    the upgrade.

    Why we keep the template as fallback: a subscriber missing a brief
    because Gemini hiccuped is worse than a sterile brief. Template
    output is always available, always correct.
    """
    # Step 1: Compute the verdict + assemble the data payload using the
    # existing template generator. We use its verdict as the safety
    # floor (LLM can downgrade Caution → Clear but never upgrade), and
    # its weather extraction as the data we feed the LLM.
    template_verdict, template_snippet, template_body = _generate_ai_brief(
        location_label, forecast, address=address
    )

    # If the template suppressed (forecast data was bad), don't even
    # try the LLM — the data quality issue isn't fixable with prose.
    if template_verdict == "suppress":
        return (template_verdict, template_snippet, template_body)

    # Step 2: Build the payload for the explainer prompt. The prompt
    # expects a plan + when + where + weather. For a Hobbyist brief we
    # synthesize a generic plan so the prompt's "no specific activity"
    # fallback path engages.
    try:
        daily = forecast.get("daily") or {}
        high = (daily.get("temperature_2m_max") or [None])[0]
        low = (daily.get("temperature_2m_min") or [None])[0]
        precip = (daily.get("precipitation_sum") or [0])[0] or 0
        wind = (daily.get("windspeed_10m_max") or [0])[0] or 0
        code = (daily.get("weathercode") or [0])[0] or 0
        # Convert mm to inches (Open-Meteo returns mm by default; the
        # template handles unit conversion, but the payload to the LLM
        # should be in the user-facing units the prompt expects).
        precip_in = round(precip / 25.4, 2) if precip else 0
        # Estimate feels-like as the high (rough; full feels-like math
        # requires hourly humidity which we'd have to fetch separately).
        weather_block = {
            "temperature_f": int(high) if high is not None else None,
            "feels_like_f": int(high) if high is not None else None,
            "wind_mph": int(wind) if wind is not None else 0,
            "precip_amount_in": precip_in,
        }
        # If precip is meaningful, include a rough timing hint
        if precip_in >= 0.05:
            weather_block["rain_window"] = "during the day"

        place = _smart_location_label(location_label, address)
        first_name = (subscriber_name.split()[0] if subscriber_name else "").strip()
        # Use the date from the forecast if available; otherwise just "today"
        today_label = "this morning's brief, no specific plan named"

        payload = {
            "plan": today_label,
            "location": place,
            "when": "today",
            "verdict": template_verdict.capitalize(),
            "weather": weather_block,
        }
        user_message = _build_explainer_user_message(payload)
    except Exception as e:
        print(f"[hobbyist-llm] payload build failed: {e!r}, falling back to template", flush=True)
        return (template_verdict, template_snippet, template_body)

    # Step 3: Try the LLM. _call_gemini returns None on any failure.
    raw_response = _call_gemini(EXPLAINER_SYSTEM_PROMPT, user_message)
    if not raw_response:
        # No API key, network error, timeout, etc. Template fallback.
        return (template_verdict, template_snippet, template_body)

    # Step 4: Parse the response (paragraph + optional verdict override)
    paragraph = raw_response
    llm_verdict = template_verdict
    if "---VERDICT---" in raw_response:
        parts = raw_response.split("---VERDICT---", 1)
        paragraph = parts[0].strip()
        suggested = parts[1].strip().lower()
        if suggested in ("clear", "caution", "risk"):
            # Apply the same safety-floor rule used in forecast_explain:
            # LLM can downgrade Caution → Clear, but Risk stays Risk, and
            # we never upgrade.
            order = {"clear": 0, "caution": 1, "risk": 2}
            if order[suggested] <= order[template_verdict]:
                llm_verdict = suggested

    # Step 5: Sanity check — if the LLM returned nothing useful or a
    # very short response, fall back rather than send garbage.
    paragraph = (paragraph or "").strip()
    if len(paragraph) < 40:
        print(f"[hobbyist-llm] short response ({len(paragraph)} chars), falling back to template", flush=True)
        return (template_verdict, template_snippet, template_body)

    snippet = paragraph[:140]
    return (llm_verdict, snippet, paragraph)


def _html_escape(s):
    """Escape user-supplied strings for safe inclusion in HTML email."""
    return _html_module.escape(str(s or ""), quote=True)


def _send_welcome_email_with_temp_password(email: str, name: str,
                                            temp_password: str,
                                            role_label: str) -> bool:
    """Welcome email sent when admin creates a new Met/Crew/Admin account.
    Includes a one-time temp password and instructions to change it on
    first sign-in.

    role_label is the human-readable role (e.g. "Meteorologist", "Valet
    Crew", "Admin") — appears in the email body.

    Returns True on send success (or stub-mode print), False on send fail.
    """
    api_key = os.environ.get("RESEND_API_KEY", "").strip()
    from_addr = os.environ.get("EMAIL_FROM", "").strip()
    # Subject — avoid "Welcome" + "password" combos that trip spam filters.
    # Mention the role so the recipient knows it's expected.
    subject = f"Your WeatherValet {role_label} account is ready"

    # Stub fallback if Resend isn't configured (dev mode)
    if not api_key or not from_addr:
        print(
            f"[welcome-email-stub] To: {email}\n"
            f"Subject: {subject}\n"
            f"Temp password: {temp_password}\n"
            f"(no RESEND_API_KEY set; logging only)",
            flush=True,
        )
        return True

    first_name = (name.split()[0] if name else "there")
    safe_name = first_name[:40]
    sign_in_url = f"{FRONTEND_BASE_URL}/?signin=1"

    # Plain-text fallback for email clients without HTML rendering
    text_body = (
        f"Welcome to WeatherValet, {safe_name}!\n\n"
        f"Your {role_label} account has been created. Here's how to sign in:\n\n"
        f"Email: {email}\n"
        f"Temporary password: {temp_password}\n\n"
        f"Sign in here: {sign_in_url}\n\n"
        f"You'll be asked to set your own password on first sign-in. "
        f"This temporary password expires after first use.\n\n"
        f"If you weren't expecting this email, please contact Michael at "
        f"michael@weathervalet.ai.\n\n"
        f"- The WeatherValet team"
    )

    # HTML body inside the branded shell
    html_inner = f"""
    <h1 style="color:#0E1116;font-size:22px;margin:0 0 16px;font-weight:600;letter-spacing:-0.01em;">
      Welcome to WeatherValet, {_html_escape(safe_name)}
    </h1>
    <p style="color:#0E1116;font-size:15px;line-height:1.6;margin:0 0 18px;">
      Your <strong>{_html_escape(role_label)}</strong> account is ready. Here's how to sign in for the first time:
    </p>
    <div style="background:#F5F7FB;border:1px solid #E5E9F2;border-radius:8px;padding:18px;margin:0 0 22px;">
      <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:#8B8F96;margin-bottom:4px;">Email</div>
      <div style="font-size:14.5px;color:#0E1116;font-family:'JetBrains Mono',Menlo,monospace;margin-bottom:14px;">{_html_escape(email)}</div>
      <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:#8B8F96;margin-bottom:4px;">Temporary password</div>
      <div style="font-size:16px;color:#0E1116;font-family:'JetBrains Mono',Menlo,monospace;letter-spacing:0.5px;background:#fff;border:1px solid #E5E9F2;border-radius:6px;padding:10px 12px;">{_html_escape(temp_password)}</div>
    </div>
    <div style="margin:0 0 22px;">
      <a href="{sign_in_url}" style="display:inline-block;background:#2E4FB8;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:14.5px;font-weight:600;">Sign in to WeatherValet</a>
    </div>
    <p style="color:#5B6370;font-size:13px;line-height:1.55;margin:0 0 18px;">
      On first sign-in, you'll be asked to set your own password. This temporary password expires after first use.
    </p>
    <p style="color:#8B8F96;font-size:12px;line-height:1.5;margin:24px 0 0;padding-top:18px;border-top:1px solid #ECEEF1;">
      If you weren't expecting this email, contact Michael at
      <a href="mailto:michael@weathervalet.ai" style="color:#2E4FB8;text-decoration:none;">michael@weathervalet.ai</a>.
    </p>
    """

    html_body = _email_shell(
        html_inner,
        preheader=f"Your WeatherValet {role_label} account is ready. Sign in with the temporary password inside."
    )

    payload = json.dumps({
        "from": from_addr,
        "to": [email],
        "reply_to": "michael@weathervalet.ai",
        "subject": subject,
        "html": html_body,
        "text": text_body,
    }).encode("utf-8")

    req = urllib.request.Request(
        "https://api.resend.com/emails",
        data=payload,
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            ok = 200 <= resp.status < 300
            if ok:
                print(f"[welcome-email] sent to={email}", flush=True)
            return ok
    except Exception as e:
        print(f"[welcome-email] FAILED to={email}: {type(e).__name__}: {e}", flush=True)
        return False


def _get_subscriber_reply_to_email(subscriber_user_id: int) -> Optional[str]:
    """Look up the email address subscriber replies should route to.

    Added May 22, 2026. Pairs with the EMAIL_FROM = hello@weathervalet.ai
    sender (set May 23, 2026 — Ionos forwards hello@ to
    michael@weathervalet.com). Subscribers should reply to a real human
    on the team, ideally the Met handling them, rather than the general
    inbox.

    Resolution order:
      1. Subscriber's assigned primary Met (subscriber_coverage.primary_met_id)
      2. None if no primary Met assigned — caller should omit reply_to
         entirely. Resend will fall back to the From: address
         (hello@weathervalet.ai), which still reaches a human via the
         Ionos forwarding rule.

    Returns the Met's email from users.email — uses whatever's on file
    (work email if configured, else personal — admin's call).
    """
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.email
                       FROM subscriber_coverage sc
                       JOIN users u ON u.id = sc.primary_met_id
                       WHERE sc.user_id = %s AND u.is_active = TRUE""",
                    (subscriber_user_id,),
                )
                row = cur.fetchone()
                if row and row.get("email"):
                    return row["email"]
    except Exception as e:
        print(f"[reply-to-lookup] failed for subscriber {subscriber_user_id}: {e}", flush=True)
    return None


def _send_brief_email(email: str, subject: str, body_text: str,
                      html: bool = False, reply_to: Optional[str] = None) -> bool:
    """Send a daily brief via Resend. Mirrors _send_magic_link_email but
    for plain text brief content. Stub mode (no API key) logs to console.

    If html=True, body_text is treated as a complete HTML email body that
    should be sent as-is (rather than wrapped in the default shell). Used
    for the structured Pro Brief format which builds its own HTML.

    reply_to (added May 22, 2026): when set, the Resend payload includes
    a reply_to field so subscriber replies land in this address instead
    of going to the From: sender. Used to route replies to the assigned
    Met's inbox. If None, Resend falls back to the From: address
    (hello@weathervalet.ai), which still forwards to a human via the
    Ionos forwarding rule.
    """
    api_key = os.environ.get("RESEND_API_KEY", "").strip()
    from_addr = os.environ.get("EMAIL_FROM", "").strip()

    if not api_key or not from_addr:
        print(f"[brief-email-stub] To: {email}\nSubject: {subject}\n{body_text[:500]}\n", flush=True)
        return True

    if html:
        # Caller built complete HTML. Send as-is. Plain-text fallback is
        # a minimal stripped version for clients that don't render HTML.
        html_body = body_text
        # Naive HTML-to-text for the plain part — strip tags, collapse whitespace
        plain_text = re.sub(r'<[^>]+>', '', body_text)
        plain_text = re.sub(r'\s+', ' ', plain_text).strip()
        payload_dict = {
            "from": from_addr,
            "to": [email],
            "subject": subject,
            "html": html_body,
            "text": plain_text[:5000],
        }
        if reply_to:
            payload_dict["reply_to"] = reply_to
        payload = json.dumps(payload_dict).encode("utf-8")
    else:
        # Build a nicely-structured HTML body inside the shared email shell.
        # The brief text typically has paragraphs separated by blank lines —
        # we preserve those by converting \n\n to paragraph breaks and single
        # \n to <br>.
        body_html = ''
        paragraphs = body_text.split('\n\n')
        for i, para in enumerate(paragraphs):
            if not para.strip():
                continue
            # Single newlines within a paragraph become <br>
            para_html = para.replace('\n', '<br>')
            margin = '0 0 14px' if i < len(paragraphs) - 1 else '0'
            body_html += (
                f'<p style="color:#0E1116;font-size:15px;line-height:1.6;'
                f'margin:{margin};">{para_html}</p>'
            )

        html_body_inner = (
            f'<h1 style="color:#0E1116;font-size:20px;margin:0 0 18px;'
            f'font-weight:600;letter-spacing:-0.01em;">{subject}</h1>'
            + body_html +
            '<p style="color:#8B8F96;font-size:12px;line-height:1.5;margin:24px 0 0;'
            'padding-top:18px;border-top:1px solid #ECEEF1;">'
            'Adjust your brief preferences or threshold alerts in your '
            '<a href="https://weathervalet.ai/?portal=1" '
            'style="color:#2E4FB8;text-decoration:none;">subscriber portal</a>.</p>'
        )
        # Preheader: first ~90 chars of brief body so inbox preview is useful
        preheader_text = body_text.replace('\n', ' ').strip()[:90]
        html_body = _email_shell(html_body_inner, preheader=preheader_text)

        payload_dict = {
            "from": from_addr,
            "to": [email],
            "subject": subject,
            "html": html_body,
            "text": body_text,
        }
        if reply_to:
            payload_dict["reply_to"] = reply_to
        payload = json.dumps(payload_dict).encode("utf-8")

    req = urllib.request.Request(
        "https://api.resend.com/emails",
        data=payload,
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return 200 <= resp.status < 300
    except Exception as e:
        print(f"[brief-email] FAILED to={email}: {type(e).__name__}: {e}", flush=True)
        return False


def _channels_note() -> tuple[str, str]:
    """Self-expiring settings note (July 2026). Every subscriber was moved
    to text+email delivery on July 6; this note rides along on brief
    emails through July 14 so people know why, see that email carries the
    full brief and images, and know where to change it. Returns
    (html, text), both empty once the window closes."""
    try:
        if datetime.now(tz=timezone.utc) >= datetime(2026, 7, 15, tzinfo=timezone.utc):
            return "", ""
    except Exception:
        return "", ""
    html = ("<div style='margin-top:14px;padding:10px 12px;background:#F4F7FF;"
            "border:1px solid #D5DEF5;border-radius:8px;font-size:12.5px;"
            "color:#3B4658;'>New: your brief now arrives by text and email. "
            "Email carries the full brief and any images. Prefer it differently? "
            "Adjust your delivery anytime in your settings at "
            "<a href='https://weathervalet.ai'>weathervalet.ai</a>.</div>")
    text = ("\n\nNew: your brief now arrives by text and email. Email carries "
            "the full brief and any images. Adjust your delivery anytime in "
            "your settings at weathervalet.ai.")
    return html, text


def _render_pro_brief_email_html(
    verdict: str,
    verdict_label: str,
    bottom_line: str,
    weather_details: str,
    whats_ahead: str,
    image_url: str,
    met_name: str,
    location_label: str,
    subscriber_name: str,
    web_url: str,
) -> str:
    """Render a structured Pro Brief as a complete email-safe HTML string.

    Uses inline styles only (no <style> blocks) because email clients
    strip <style>. Uses table-based layout where alignment matters,
    plain divs where it doesn't.

    Verdict chip color matches the verdict:
        clear   -> green
        caution -> amber
        risk    -> red
    """
    v = (verdict or "").lower()
    if v == "clear":
        chip_bg = "#0e6e3a"
        chip_fg = "#ffffff"
    elif v == "risk":
        chip_bg = "#9a1d18"
        chip_fg = "#ffffff"
    else:
        chip_bg = "#92400e"
        chip_fg = "#ffffff"

    # Format date in subscriber's locale
    today_str = datetime.now(timezone.utc).strftime("%A, %B %-d, %Y") if hasattr(datetime, "strftime") else datetime.now(timezone.utc).strftime("%A, %B %d, %Y")

    def _section(label, content):
        if not content:
            return ""
        # Convert newlines to <br> for weather_details (which is bullet-style)
        body_html = content.replace("\n", "<br>")
        return (
            f'<div style="margin-top:22px;">'
            f'<div style="font-size:11px;font-weight:700;text-transform:uppercase;'
            f'letter-spacing:0.08em;color:#6b7280;margin-bottom:6px;">{label}</div>'
            f'<div style="font-size:15px;line-height:1.55;color:#0f1116;">{body_html}</div>'
            f'</div>'
        )

    image_html = ""
    if image_url:
        image_html = (
            f'<div style="margin-top:22px;">'
            f'<img src="{image_url}" alt="Forecast graphic" '
            f'style="max-width:100%;height:auto;border-radius:8px;display:block;">'
            f'</div>'
        )

    sub_display = subscriber_name or location_label

    html = f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Your WeatherValet brief</title>
</head>
<body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
<div style="max-width:600px;margin:0 auto;background:#ffffff;">

  <!-- Header bar -->
  <div style="background:linear-gradient(135deg,#C2342B 0%,#9a1d18 100%);padding:18px 24px;color:#fff;">
    <div style="font-size:20px;font-weight:700;letter-spacing:-0.01em;">⚡ WeatherValet</div>
    <div style="font-size:12px;opacity:0.85;margin-top:2px;">{sub_display} · {today_str}</div>
  </div>

  <!-- Body -->
  <div style="padding:24px;">

    <!-- Today's call -->
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:#6b7280;margin-bottom:6px;">Today's call</div>
    <div style="display:inline-block;background:{chip_bg};color:{chip_fg};padding:6px 14px;border-radius:999px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;">{verdict_label}</div>

    {_section("Bottom line", bottom_line)}
    {_section("Weather details", weather_details)}
    {_section("What's ahead", whats_ahead)}
    {image_html}

    <!-- Signature -->
    <div style="margin-top:28px;padding-top:18px;border-top:1px dashed #e5e7eb;color:#6b7280;font-size:13px;font-style:italic;">
      Signed, {met_name}, WeatherValet
    </div>

    <!-- Reply prompt -->
    <div style="margin-top:18px;padding:12px 14px;background:rgba(37,99,235,0.06);border-left:3px solid #2563eb;font-size:12.5px;color:#374151;border-radius:0 6px 6px 0;">
      💬 Reply to this email or text us to talk to {met_name} directly.
    </div>

    <!-- Web view link -->
    <div style="margin-top:18px;text-align:center;">
      <a href="{web_url}" style="display:inline-block;background:#2563eb;color:#ffffff;padding:10px 24px;border-radius:6px;font-size:13px;font-weight:600;text-decoration:none;">View brief on web</a>
    </div>

  </div>

  <!-- Footer -->
  <div style="padding:18px 24px;background:#f8f9fa;color:#9ca3af;font-size:11px;line-height:1.5;text-align:center;">
    WeatherValet: your meteorologist on call.<br>
    Adjust preferences in your <a href="https://weathervalet.ai/?portal=1" style="color:#2563eb;text-decoration:none;">subscriber portal</a>.
  </div>

</div>
</body>
</html>"""
    _note_html, _ = _channels_note()
    if _note_html:
        html = html.replace("</div>\n</div>", _note_html + "</div>\n</div>", 1) if "</div>\n</div>" in html else (html + _note_html)
    return html


def _timezone_for_latlng(lat: float, lng: float) -> str:
    """Best-effort IANA timezone for a US lat/lng.

    Uses longitude bands — accurate for the continental US except at
    a few state boundary edge cases (TN/KY, FL panhandle, parts of ID,
    AZ which doesn't observe DST). For nationwide launch we should
    upgrade to the `timezonefinder` library; this is good enough for
    Indianapolis-area testing and early nationwide subscribers.

    Returns an IANA name like "America/Indiana/Indianapolis" so it
    survives ZoneInfo lookups.
    """
    try:
        lat = float(lat)
        lng = float(lng)
    except (ValueError, TypeError):
        return "America/Indiana/Indianapolis"

    # Alaska / Hawaii / outlying — coarse handling
    if lat > 50 and lng < -130:
        return "America/Anchorage"
    if 18 < lat < 23 and -161 < lng < -154:
        return "Pacific/Honolulu"

    # Continental US — longitude bands
    if lng >= -85:
        return "America/New_York"
    if lng >= -100:
        return "America/Chicago"
    if lng >= -114:
        return "America/Denver"
    return "America/Los_Angeles"


def _local_now_for_user(user_timezone: str) -> datetime:
    """Current datetime in the user's local timezone."""
    try:
        return datetime.now(ZoneInfo(user_timezone))
    except Exception:
        return datetime.now(ZoneInfo("America/Indiana/Indianapolis"))


def _time_in_window(now_hour: int, now_min: int, start_str: str, end_str: str) -> bool:
    """Is the current HH:MM within the [start_str, end_str] window?

    Both strings are 'HH:MM'. Handles windows that cross midnight
    (e.g. quiet hours 21:00 → 05:00) by checking start <= now OR now <= end.
    """
    try:
        sh, sm = int(start_str[:2]), int(start_str[3:])
        eh, em = int(end_str[:2]), int(end_str[3:])
    except (ValueError, TypeError, IndexError):
        return False
    now_minutes = now_hour * 60 + now_min
    start_minutes = sh * 60 + sm
    end_minutes = eh * 60 + em
    if start_minutes <= end_minutes:
        return start_minutes <= now_minutes <= end_minutes
    # Window crosses midnight
    return now_minutes >= start_minutes or now_minutes <= end_minutes


def _already_sent_today(user_id: int, brief_type: str, user_timezone: str = None) -> bool:
    """Check if this user has received a brief of the given type today.

    "Today" means today in the subscriber's local timezone. Defaults to
    Indianapolis time if no timezone passed (preserves prior behavior
    for older callers).
    """
    tz = user_timezone or "America/Indiana/Indianapolis"
    try:
        local_now = _local_now_for_user(tz)
    except Exception:
        local_now = datetime.now(timezone.utc)
    today_start_local = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    today_start_ms = int(today_start_local.timestamp() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT COUNT(*) AS n FROM brief_history
                   WHERE user_id = %s AND brief_type = %s AND delivered_at >= %s""",
                (user_id, brief_type, today_start_ms),
            )
            row = cur.fetchone()
    return (row["n"] or 0) > 0 if row else False


def _record_brief_delivery(user_id: int, brief_type: str, verdict: str,
                            snippet: str, full_body: str, delivery_status: str,
                            channels_used: str, is_met_touched: bool = False,
                            met_name: Optional[str] = None,
                            predictions: Optional[dict] = None) -> None:
    """Insert a brief_history row.

    May 26, 2026: added predictions param. When supplied, the dict should
    contain keys predicted_high_f, predicted_low_f, predicted_precip_in,
    predicted_max_wind_mph (any may be None). When omitted, all
    structured predictions are stored as NULL — that's fine, the grader
    falls back to text-parsing the full_body or skips the comparison.
    """
    now_ms = int(time.time() * 1000)
    p = predictions or {}
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO brief_history
                   (user_id, brief_type, delivered_at, verdict, snippet,
                    full_body, delivery_status, channels_used,
                    is_met_touched, met_name,
                    predicted_high_f, predicted_low_f,
                    predicted_precip_in, predicted_max_wind_mph)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                           %s, %s, %s, %s)""",
                (user_id, brief_type, now_ms, verdict, snippet, full_body,
                 delivery_status, channels_used, is_met_touched, met_name,
                 p.get("predicted_high_f"), p.get("predicted_low_f"),
                 p.get("predicted_precip_in"), p.get("predicted_max_wind_mph")),
            )


def _try_acquire_scheduler_lock(lock_key: int) -> Optional[object]:
    """Try to acquire a Postgres session-level advisory lock for a scheduler tick.

    Added May 22, 2026 to fix duplicate brief delivery: when Render runs
    multiple Gunicorn workers, each worker has its own scheduler thread.
    Without coordination, two workers can simultaneously enter
    _process_pending_briefs (or _pregenerate_pro_brief_drafts) and both
    send the same brief.

    Postgres advisory locks are a cluster-wide mutex — only one worker
    in any process can hold the lock at a time. pg_try_advisory_lock
    returns true if acquired, false if another session has it.

    Returns the database connection if lock acquired (caller must call
    _release_scheduler_lock with same connection when done). Returns
    None if another worker already holds the lock — caller should
    simply skip this tick.

    Why session-level (not transaction-level) advisory locks: the
    scheduler operation spans multiple DB transactions (forecast fetch,
    multiple SQL queries, email sends). A transaction-level lock would
    release on the first COMMIT. Session-level locks persist for the
    life of the connection, which we explicitly release at the end.

    Lock keys are arbitrary BIGINTs unique per scheduler job:
      91234567 — _process_pending_briefs
      91234568 — _pregenerate_pro_brief_drafts
      91234569 — _process_severe_alerts
      91234570 — _check_missed_pro_briefs
      91234571 — _process_scheduled_messages

    Note: this opens a dedicated long-lived connection (different from
    the per-request context-managed db() pattern). The connection is
    closed in _release_scheduler_lock.
    """
    try:
        conn = psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)
        conn.autocommit = True
        with conn.cursor() as cur:
            cur.execute("SELECT pg_try_advisory_lock(%s) AS got", (lock_key,))
            got_lock = cur.fetchone()["got"]
        if not got_lock:
            conn.close()
            return None
        return conn
    except Exception as e:
        print(f"[scheduler-lock] acquire failed key={lock_key}: {e}", flush=True)
        return None


def _release_scheduler_lock(conn: object, lock_key: int) -> None:
    """Release the advisory lock acquired by _try_acquire_scheduler_lock.

    Must be called in a try/finally so the lock releases even if the
    scheduler tick raises an exception. Closes the connection.
    """
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_advisory_unlock(%s)", (lock_key,))
    except Exception as e:
        print(f"[scheduler-lock] release failed key={lock_key}: {e}", flush=True)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _process_pending_briefs() -> None:
    """Called once per scheduler tick (every 60s). Finds subscribers whose
    morning window matches the current time in THEIR local timezone,
    generates + sends their brief.

    Pro-tier briefs are flagged but NOT sent — Chunk 3B handles Met review.
    Hobbyist (and any tier not requiring review) gets the full automated
    flow.

    Phase 10 timezone foundation: each subscriber has u.timezone. We
    compute "what time is it in THEIR timezone right now" and compare
    against their morning_window_start/end (which are stored as local
    HH:MM strings). This is what makes nationwide delivery work — a
    California subscriber's 6 AM window fires at 9 AM Eastern when
    the scheduler ticks during Indianapolis morning.

    Concurrency (May 22, 2026): wrapped in a Postgres advisory lock
    so multi-worker deployments (Render with 2+ Gunicorn workers)
    don't fire the scheduler twice and double-send briefs. If another
    worker holds the lock, this tick is a no-op (the holder will do
    the work; we'll try again on the next minute).
    """
    _LOCK_KEY = 91234567
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # Another worker is processing this tick; skip silently
    try:
        _process_pending_briefs_inner()
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


def _process_pending_briefs_inner() -> None:
    """Original body of _process_pending_briefs. Extracted May 22, 2026
    so the outer function can wrap it in an advisory lock without a
    massive indent change. Do not call this directly — use
    _process_pending_briefs which handles the lock.
    """
    try:
        with db() as conn:
            with conn.cursor() as cur:
                # Find subscribers with morning brief enabled, in window,
                # and not yet sent today. JOIN user → preferences → primary location.
                cur.execute(
                    """SELECT
                          u.id AS user_id,
                          u.email,
                          u.phone,
                          u.name,
                          u.subscription_tier,
                          u.timezone,
                          bp.morning_window_start,
                          bp.morning_window_end,
                          bp.channels,
                          loc.label AS loc_label,
                          loc.address_text AS loc_address,
                          loc.lat AS loc_lat,
                          loc.lng AS loc_lng,
                          loc.county AS loc_county
                       FROM users u
                       JOIN brief_preferences bp ON bp.user_id = u.id
                       LEFT JOIN saved_locations loc
                            ON loc.user_id = u.id AND loc.is_primary = TRUE
                       WHERE u.is_active = TRUE
                         AND bp.morning_enabled = TRUE
                         AND EXISTS (
                           SELECT 1 FROM user_roles ur
                            WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                         )"""
                )
                candidates = cur.fetchall()
    except Exception as e:
        print(f"[brief-scheduler] query failed: {e}", flush=True)
        return

    for c in candidates:
        try:
            # Compute "now" in THIS subscriber's local timezone
            user_tz = c.get("timezone") or "America/Indiana/Indianapolis"
            local_now = _local_now_for_user(user_tz)
            now_hour = local_now.hour
            now_min = local_now.minute

            if not _time_in_window(now_hour, now_min,
                                   c["morning_window_start"],
                                   c["morning_window_end"]):
                continue
            if _already_sent_today(c["user_id"], "morning", user_tz):
                continue

            # Daily Brief cancellation check (May 17, 2026). If a Met
            # published a Daily Brief broadcast that included this
            # subscriber within the last 24 hours, skip the AI auto-brief.
            # Avoids double-messaging when the Met has already taken care
            # of this subscriber's county personally that morning.
            #
            # Implementation: when a Met publishes a Daily Brief broadcast,
            # _publish_daily_brief_internal writes a brief_history row per
            # recipient with brief_type='daily_brief'. We check for any
            # such row in the last 24h for this user. If found, skip.
            try:
                twenty_four_h_ago_ms = int(time.time() * 1000) - 24 * 60 * 60 * 1000
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT 1 FROM brief_history
                               WHERE user_id = %s
                                 AND brief_type = 'daily_brief'
                                 AND delivered_at >= %s
                               LIMIT 1""",
                            (c["user_id"], twenty_four_h_ago_ms),
                        )
                        if cur.fetchone():
                            print(
                                f"[brief-scheduler] skipping AI auto-brief "
                                f"user={c['user_id']}, Met already broadcast "
                                f"to them in last 24h",
                                flush=True,
                            )
                            continue
            except Exception as e:
                # Cancellation check failure shouldn't block the AI brief —
                # better to send a possible duplicate than skip a real
                # subscriber due to a query error. Log and continue.
                print(f"[brief-scheduler] cancel-check failed user={c['user_id']}: {e}", flush=True)

            if not c["loc_lat"] or not c["loc_lng"]:
                # No primary location set — skip silently. Subscriber should
                # add one in the portal; we don't pester them with an error.
                continue

            # Pro-tier path: generate the AI draft, insert a pro_brief_drafts
            # row for Met review. Don't send via channels here — that happens
            # when the Met sends via the workspace endpoint. Idempotency note:
            # _already_sent_today checks brief_history. If a draft was created
            # but not yet sent, the next tick would re-create it. To prevent
            # that, we also check pro_brief_drafts for a pending row.
            tier = c["subscription_tier"] or "hobbyist"
            if tier in ("pro_single", "pro_multi", "pro_enterprise"):
                # Has a pending draft for today's morning already? If so, skip.
                # We look back 18 hours so that an evening pre-generated draft
                # (created the night before at 8 PM) is detected when the
                # morning window fires the next day. Without this, the morning
                # tick would create a duplicate draft for the same brief day.
                # (Widened May 22, 2026 to support evening pre-generation.)
                eighteen_hours_ago_ms = int(time.time() * 1000) - 18 * 60 * 60 * 1000
                try:
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """SELECT id FROM pro_brief_drafts
                                   WHERE user_id = %s AND brief_type = 'morning'
                                     AND created_at >= %s
                                     AND status IN ('pending-review','claimed','sent')
                                   LIMIT 1""",
                                (c["user_id"], eighteen_hours_ago_ms),
                            )
                            existing = cur.fetchone()
                except Exception as e:
                    print(f"[brief-scheduler] pro draft lookup failed: {e}", flush=True)
                    continue
                if existing:
                    continue

                # Generate the AI draft using the same generator hobbyists get
                location_label = c["loc_label"] or c["loc_address"] or "your location"
                forecast = _fetch_forecast(float(c["loc_lat"]), float(c["loc_lng"]))
                ai_verdict, ai_snippet, ai_body = _generate_ai_brief(
                    location_label, forecast or {}, address=c.get("loc_address") or "")

                # Compute window_end_at — the scheduler shouldn't send a
                # "morning brief" at 2pm. Use the user's window_end as the
                # cutoff; after that, the draft is too stale.
                # (Fixed May 22, 2026 — was using undefined `now`; should
                # be `local_now` from line ~14504.)
                try:
                    eh, em = int(c["morning_window_end"][:2]), int(c["morning_window_end"][3:])
                    window_end_dt = local_now.replace(hour=eh, minute=em, second=0, microsecond=0)
                    if window_end_dt < local_now:
                        # Window ended already (shouldn't happen if we got here, but defend)
                        window_end_dt = local_now
                    window_end_ms = int(window_end_dt.timestamp() * 1000)
                except (ValueError, TypeError, IndexError):
                    # Default cutoff: 4 hours from now
                    window_end_ms = int(time.time() * 1000) + 4 * 60 * 60 * 1000

                now_ms = int(time.time() * 1000)
                draft_preds = _extract_predicted_values_from_forecast(forecast)
                try:
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """INSERT INTO pro_brief_drafts
                                   (user_id, brief_type, created_at, window_end_at, status,
                                    user_tier, location_label, location_lat, location_lng,
                                    channels, ai_verdict, ai_snippet, ai_body,
                                    met_verdict, met_snippet, met_body,
                                    predicted_high_f, predicted_low_f,
                                    predicted_precip_in, predicted_max_wind_mph)
                                   VALUES (%s, 'morning', %s, %s, 'pending-review',
                                           %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                                           %s, %s, %s, %s)
                                   RETURNING id""",
                                (c["user_id"], now_ms, window_end_ms,
                                 tier, location_label,
                                 float(c["loc_lat"]), float(c["loc_lng"]),
                                 c["channels"] or "",
                                 ai_verdict, ai_snippet, ai_body,
                                 ai_verdict, ai_snippet, ai_body,
                                 draft_preds.get("predicted_high_f"),
                                 draft_preds.get("predicted_low_f"),
                                 draft_preds.get("predicted_precip_in"),
                                 draft_preds.get("predicted_max_wind_mph")),
                            )
                            new_id = cur.fetchone()["id"]
                    print(
                        f"[brief-scheduler] pro draft created id={new_id} user_id={c['user_id']} "
                        f"tier={tier} verdict={ai_verdict}",
                        flush=True,
                    )
                except Exception as e:
                    print(f"[brief-scheduler] pro draft insert failed: {e}", flush=True)
                continue

            # ── Hobbyist auto-send path ──
            # Check for a pre-existing draft (pregen from night before or
            # an early-morning create) so the Met's edits (if any) override
            # the AI. If a draft exists with status='sent', skip — Met
            # already sent it before window-start. If 'pending-review' or
            # 'claimed', use the Met's content (falls back to AI content
            # if Met didn't edit). If no draft, generate fresh as before.
            # (May 22, 2026: added Hobbyist override flow.)
            eighteen_hours_ago_ms = int(time.time() * 1000) - 18 * 60 * 60 * 1000
            existing_draft = None
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT id, status, met_verdict, met_snippet, met_body,
                                      ai_verdict, ai_snippet, ai_body,
                                      sent_at, sent_by_name
                               FROM pro_brief_drafts
                               WHERE user_id = %s AND brief_type = 'morning'
                                 AND created_at >= %s
                               ORDER BY created_at DESC LIMIT 1""",
                            (c["user_id"], eighteen_hours_ago_ms),
                        )
                        existing_draft = cur.fetchone()
            except Exception as e:
                print(f"[brief-scheduler] hobbyist draft lookup failed: {e}", flush=True)

            if existing_draft and existing_draft["status"] == "sent":
                # Met already sent the override. Nothing to do.
                continue

            # Fetch forecast once at the top of both branches so we
            # have predicted values available for brief_history even
            # when the Met overrides the AI text (added May 26, 2026
            # for work-impact accuracy grading).
            forecast = _fetch_forecast(float(c["loc_lat"]), float(c["loc_lng"]))

            # ── Generate the brief content ──
            if existing_draft and existing_draft["status"] in ("pending-review", "claimed"):
                location_label = c["loc_label"] or c["loc_address"] or "your location"
                # At pre-gen we copy ai_* into met_* , so "met fields present"
                # does NOT mean a Met edited. The reliable signal is whether
                # met_body actually differs from ai_body.
                _met_body = (existing_draft["met_body"] or "").strip()
                _ai_body = (existing_draft["ai_body"] or "").strip()
                real_met_edit = bool(_met_body) and _met_body != _ai_body
                if real_met_edit:
                    # Met wrote their own words — send exactly those, untouched.
                    verdict = existing_draft["met_verdict"] or existing_draft["ai_verdict"] or "clear"
                    snippet = existing_draft["met_snippet"] or existing_draft["ai_snippet"] or ""
                    full_body = existing_draft["met_body"] or existing_draft["ai_body"] or ""
                    is_met_touched = True
                    met_name_for_record = existing_draft["sent_by_name"] or None
                else:
                    # Met didn't change the content — regenerate from the fresh
                    # send-time forecast (fetched above) so the auto-sent brief
                    # shows current numbers, not the night-before snapshot.
                    rv, rs, rb = _generate_ai_brief(
                        location_label, forecast or {}, address=c.get("loc_address") or "")
                    if rv != "suppress" and rb:
                        verdict, snippet, full_body = rv, rs, rb
                    else:
                        verdict = existing_draft["ai_verdict"] or "clear"
                        snippet = existing_draft["ai_snippet"] or ""
                        full_body = existing_draft["ai_body"] or ""
                    is_met_touched = False
                    met_name_for_record = None
            else:
                # No draft — generate fresh AI brief (Hobbyist auto-send flow)
                # May 23, 2026: upgraded to LLM-first generation with template
                # fallback. Subscribers get warmer, more textured prose; if
                # the LLM is unavailable for any reason the template still
                # works as before, no delivery is missed.
                location_label = c["loc_label"] or c["loc_address"] or "your location"
                verdict, snippet, full_body = _generate_hobbyist_brief_llm(
                    location_label, forecast or {},
                    address=c.get("loc_address") or "",
                    subscriber_name=c.get("name") or "")
                is_met_touched = False
                met_name_for_record = None

            # Data quality gate (May 22, 2026): if AI brief came back with
            # verdict='suppress', the forecast data was bad. Don't send to
            # subscriber; instead alert the assigned primary Met (or admin
            # if none) so a human can investigate.
            if verdict == "suppress":
                # Record the suppression in brief_history so the Met
                # workspace can surface it for recovery (May 29, 2026).
                # Idempotent: skip if a suppressed row already exists
                # today for this subscriber + brief_type.
                try:
                    sup_now_ms = int(time.time() * 1000)
                    user_tz = c.get("timezone") or "America/Indiana/Indianapolis"
                    if not _already_sent_today(c["user_id"], "morning", user_tz):
                        with db() as conn:
                            with conn.cursor() as cur:
                                cur.execute(
                                    """INSERT INTO brief_history
                                       (user_id, brief_type, delivered_at, verdict,
                                        snippet, full_body, delivery_status, channels_used,
                                        is_met_touched, met_name)
                                       VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                                    (c["user_id"], "morning", sup_now_ms, "suppress",
                                     (snippet or "")[:140],
                                     full_body, "suppressed", "",
                                     False, None),
                                )
                except Exception as hist_e:
                    print(f"[brief-scheduler] suppressed history insert failed user_id={c['user_id']}: {hist_e}", flush=True)

                try:
                    _alert_met_on_suppressed_brief(
                        subscriber_user_id=c["user_id"],
                        subscriber_name=c.get("name") or c.get("email") or "subscriber",
                        location_label=location_label,
                        reason=full_body,  # contains the suppression reason
                    )
                except Exception as alert_e:
                    print(f"[brief-scheduler] alert send failed user_id={c['user_id']}: {alert_e}", flush=True)
                print(
                    f"[brief-scheduler] SUPPRESSED user_id={c['user_id']} tier={tier} reason={full_body!r}",
                    flush=True,
                )
                continue  # Don't send to subscriber

            # ── Send via channels ──
            channels = [ch for ch in (c["channels"] or "").split(",") if ch]
            channels_used = []
            any_success = False
            for ch in channels:
                if ch == "sms" and c["phone"]:
                    ok = send_sms(c["phone"], snippet + "\n\nFull brief: " + full_body[:1200])
                    if ok:
                        channels_used.append("sms")
                        any_success = True
                elif ch == "email" and c["email"]:
                    # Phase 3 (May 22, 2026): smart subject + reply-to-Met.
                    # Subject uses city/state when label is generic ("Home" etc.).
                    # reply_to routes subscriber replies to their assigned Met.
                    smart_label = _smart_location_label(
                        c.get("loc_label") or "",
                        c.get("loc_address") or "")
                    subject = f"Your WeatherValet brief, {smart_label}"
                    reply_to = _get_subscriber_reply_to_email(c["user_id"])
                    ok = _send_brief_email(c["email"], subject, full_body + _channels_note()[1], reply_to=reply_to)
                    if ok:
                        channels_used.append("email")
                        any_success = True
                # 'push' not yet wired; skip silently
            delivery_status = "sent" if any_success else "failed"

            _record_brief_delivery(
                user_id=c["user_id"],
                brief_type="morning",
                verdict=verdict,
                snippet=snippet,
                full_body=full_body,
                delivery_status=delivery_status,
                channels_used=",".join(channels_used),
                is_met_touched=is_met_touched,
                met_name=met_name_for_record,
                predictions=_extract_predicted_values_from_forecast(forecast),
            )

            # ── Payroll attribution for Hobbyists (May 23, 2026) ──
            # Per the corrected pay rule: the assigned primary Met earns
            # 50% of the daily Hobbyist revenue EVERY day, even when AI
            # auto-sends the brief (no human Met touched it). The brief
            # is the Met's product — they're the assigned owner of that
            # subscriber relationship.
            #
            # _compute_payroll_for_month reads daily_brief_tasks for
            # Hobbyist attribution. Without a row here, the primary Met
            # gets $0 for AI-only days and the house keeps everything.
            #
            # Pro tiers are NOT attributed here — Pro pay is per
            # Met-sent morning brief in pro_brief_drafts. The scheduler
            # only AI-sends Hobbyists; Pro tier sends always go through
            # the workspace endpoint which has its own attribution.
            #
            # Upsert pattern matches the broadcast flow (line ~20708):
            # if a row already exists for today with status='sent', we
            # preserve it (first successful send wins). Otherwise we
            # write 'sent' with the primary Met from subscriber_coverage.
            if any_success and tier == "hobbyist":
                try:
                    now_ms_dbt = int(time.time() * 1000)
                    # Compute task_date in subscriber's local timezone
                    try:
                        sub_zone_dbt = ZoneInfo(c.get("timezone") or "America/Indiana/Indianapolis")
                    except Exception:
                        sub_zone_dbt = ZoneInfo("America/Indiana/Indianapolis")
                    local_dt_dbt = datetime.fromtimestamp(
                        now_ms_dbt / 1000, tz=timezone.utc
                    ).astimezone(sub_zone_dbt)
                    task_date_dbt = local_dt_dbt.strftime("%Y-%m-%d")
                    # Look up the subscriber's primary Met (may be None
                    # if admin hasn't assigned one — then no Met earns,
                    # which is the correct outcome).
                    primary_met_id_dbt = None
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """SELECT sc.primary_met_id
                                   FROM subscriber_coverage sc
                                   JOIN users u ON u.id = sc.primary_met_id
                                   WHERE sc.user_id = %s AND u.is_active = TRUE""",
                                (c["user_id"],),
                            )
                            row_dbt = cur.fetchone()
                            if row_dbt:
                                primary_met_id_dbt = row_dbt.get("primary_met_id")
                            cur.execute(
                                """INSERT INTO daily_brief_tasks
                                     (subscriber_user_id, task_date, assigned_met_id,
                                      due_at_ms, status, sent_at_ms)
                                   VALUES (%s, %s, %s, %s, 'sent', %s)
                                   ON CONFLICT (subscriber_user_id, task_date) DO UPDATE
                                   SET assigned_met_id = CASE
                                           WHEN daily_brief_tasks.status = 'sent' THEN daily_brief_tasks.assigned_met_id
                                           ELSE EXCLUDED.assigned_met_id
                                       END,
                                       status = 'sent',
                                       sent_at_ms = CASE
                                           WHEN daily_brief_tasks.status = 'sent' THEN daily_brief_tasks.sent_at_ms
                                           ELSE EXCLUDED.sent_at_ms
                                       END""",
                                (c["user_id"], task_date_dbt, primary_met_id_dbt,
                                 now_ms_dbt, now_ms_dbt),
                            )
                except Exception as e:
                    # Don't fail the send over a payroll bookkeeping issue.
                    # Backfill endpoint can recover if this fails.
                    print(f"[brief-scheduler] daily_brief_tasks upsert failed "
                          f"user={c.get('user_id')}: {e!r}", flush=True)

            # If we sourced from a draft, mark the draft as 'sent' too so
            # the queue shows it correctly and the duplicate-check skips
            # it on the next tick.
            if existing_draft and any_success:
                try:
                    now_ms = int(time.time() * 1000)
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """UPDATE pro_brief_drafts
                                   SET status = 'sent', sent_at = COALESCE(sent_at, %s),
                                       sent_by_name = COALESCE(sent_by_name, 'WeatherValet AI'),
                                       final_verdict = %s, final_body = %s
                                   WHERE id = %s""",
                                (now_ms, verdict, full_body, existing_draft["id"]),
                            )
                except Exception as e:
                    print(f"[brief-scheduler] hobbyist draft mark-sent failed: {e}", flush=True)
            print(
                f"[brief-scheduler] delivered user_id={c['user_id']} tier={tier} "
                f"channels={channels_used} verdict={verdict} met_touched={is_met_touched}",
                flush=True,
            )
        except Exception as e:
            print(f"[brief-scheduler] FAILED for user_id={c.get('user_id')}: {e!r}", flush=True)


def _pregenerate_pro_brief_drafts() -> None:
    """Pre-generate next-morning brief drafts at 8 PM the night before.

    Added May 22, 2026: Mets requested the ability to start writing
    briefs the night before. This function runs each scheduler tick
    and, for each Pro OR Hobbyist subscriber whose local time is
    20:00-20:59 (8:00-8:59 PM), pre-generates tomorrow's morning draft
    if one doesn't already exist.

    Pro draft workflow: Met claims, edits, sends. NO auto-send by AI.
    Hobbyist draft workflow: Met can claim and override BEFORE the
        morning window opens. If Met doesn't override, the morning
        scheduler auto-sends the AI version (Hobbyist commitment is
        delivery, not Met review).

    Forecast staleness: the AI snapshot is from Tuesday evening, but
    weather can shift overnight. We mark the draft so the Met UI can
    show a "refresh AI" button. (TODO: wire that button.)

    Duplicate prevention: uses the same 18-hour look-back as the morning
    scheduler. An 8 PM draft will be detected as "already exists" when
    the 7 AM morning scheduler runs the next day.

    Idempotency at the hourly level: the 8-9 PM window is one hour wide,
    so the scheduler will run this check ~60 times during that hour.
    The duplicate detection prevents re-generation; only the first tick
    in the window creates the draft.

    Concurrency (May 22, 2026): wrapped in a Postgres advisory lock
    so multi-worker deployments don't run the pregen twice.
    """
    _LOCK_KEY = 91234568
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # Another worker is processing this tick; skip silently
    try:
        _pregenerate_pro_brief_drafts_inner()
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


def _generate_widget_narratives() -> None:
    """Pre-generate widget narratives twice daily.

    Phase 2 of the radio-partner widget (May 28, 2026). Runs at 5 AM CT
    (morning narrative — covers AM drive + workday) and 12 PM CT
    (afternoon narrative — covers PM drive + evening) for each active
    widget location.

    Each generation cycle creates a new widget_narratives row with
    status='pending-review' so a Met can claim it and edit before
    publish. If no Met touches it within the freshness window, the
    public widget falls back to showing the AI version.

    Concurrency: wrapped in a Postgres advisory lock (key 91234569,
    distinct from Pro brief pregen's 91234568) so multi-worker
    deployments don't generate twice.

    Idempotency: each (location, cycle, date) tuple is generated at
    most once via a duplicate check before INSERT.
    """
    _LOCK_KEY = 91234569
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return
    try:
        _generate_widget_narratives_inner()
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


def _generate_widget_narratives_inner() -> None:
    """Body of _generate_widget_narratives. See outer function docstring.

    For each active widget_location:
      1. Check if it's currently 5 AM or 12 PM in the location's local tz
      2. If so, determine cycle ('morning' or 'afternoon')
      3. Skip if a narrative for this (location, cycle, today) already exists
      4. Fetch a 7-day forecast
      5. Generate the AI narrative
      6. INSERT with status='pending-review' and a Met-edit window

    Expires_at is set to:
      - Morning cycle: noon local time (when afternoon cycle takes over)
      - Afternoon cycle: 5 AM tomorrow local (when next morning cycle takes over)
    """
    now_ms = int(time.time() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, slug, name, lat, lng, timezone
                   FROM widget_locations
                   WHERE is_active = TRUE
                   ORDER BY sort_order, id"""
            )
            locations = cur.fetchall()

    for loc in locations:
        try:
            tz = ZoneInfo(loc.get("timezone") or "America/Chicago")
            local_now = datetime.now(tz)
            hour = local_now.hour
            today_str = local_now.strftime("%Y-%m-%d")

            # Decide cycle. Generate at 5 AM and 12 PM (noon) local.
            # We give a 1-hour window for each so the scheduler tick can
            # land any time within. Duplicate check prevents re-generation.
            if hour == 5:
                cycle = "morning"
                # Expires when afternoon cycle starts (noon today local)
                expires_local = local_now.replace(hour=12, minute=0, second=0, microsecond=0)
            elif hour == 12:
                cycle = "afternoon"
                # Expires when next morning cycle starts (5 AM tomorrow local)
                from datetime import timedelta
                expires_local = (local_now + timedelta(days=1)).replace(
                    hour=5, minute=0, second=0, microsecond=0
                )
            else:
                continue  # not a generation hour for this location

            expires_ms = int(expires_local.timestamp() * 1000)

            # Duplicate check: has a narrative for this (location, cycle,
            # today's local date) already been generated?
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT id FROM widget_narratives
                           WHERE location_id = %s
                             AND cycle = %s
                             AND created_at >= %s
                           LIMIT 1""",
                        (loc["id"], cycle, now_ms - 18 * 3600 * 1000),
                    )
                    if cur.fetchone():
                        continue  # already created in this 18-hour window

            # Fetch forecast and generate narrative
            forecast = _fetch_forecast_7day(loc["lat"], loc["lng"])
            if not forecast:
                print(f"[widget-narratives] forecast fetch failed for {loc['slug']}",
                      flush=True)
                continue
            narrative = _generate_widget_narrative(loc["name"], forecast)
            if not narrative:
                print(f"[widget-narratives] narrative empty for {loc['slug']}, skipping",
                      flush=True)
                continue

            # Insert as pending-review
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO widget_narratives
                             (location_id, cycle, status, ai_body,
                              created_at, expires_at)
                           VALUES (%s, %s, 'pending-review', %s, %s, %s)""",
                        (loc["id"], cycle, narrative, now_ms, expires_ms),
                    )
            print(f"[widget-narratives] generated {cycle} narrative for {loc['slug']}",
                  flush=True)
        except Exception as e:
            print(f"[widget-narratives] failed for loc {loc.get('slug')}: {e!r}",
                  flush=True)
            continue


def _pregenerate_pro_brief_drafts_inner() -> None:
    """Original body of _pregenerate_pro_brief_drafts. Extracted May 22,
    2026 so the outer function can wrap it in an advisory lock without
    a massive indent change. Do not call this directly — use
    _pregenerate_pro_brief_drafts which handles the lock.
    """
    try:
        with db() as conn:
            with conn.cursor() as cur:
                # Find Pro subscribers with morning brief enabled. Pre-gen
                # is Pro-only — Hobbyists don't get Met review so there's
                # nothing to pre-write.
                cur.execute(
                    """SELECT
                          u.id AS user_id,
                          u.email,
                          u.phone,
                          u.name,
                          u.subscription_tier,
                          u.timezone,
                          bp.morning_window_start,
                          bp.morning_window_end,
                          bp.channels,
                          loc.label AS loc_label,
                          loc.address_text AS loc_address,
                          loc.lat AS loc_lat,
                          loc.lng AS loc_lng
                       FROM users u
                       JOIN brief_preferences bp ON bp.user_id = u.id
                       LEFT JOIN saved_locations loc
                            ON loc.user_id = u.id AND loc.is_primary = TRUE
                       WHERE u.is_active = TRUE
                         AND bp.morning_enabled = TRUE
                         AND u.subscription_tier IN ('hobbyist', 'pro_single', 'pro_multi', 'pro_enterprise')
                         AND EXISTS (
                           SELECT 1 FROM user_roles ur
                            WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                         )"""
                )
                candidates = cur.fetchall()
    except Exception as e:
        print(f"[pregen-pro] query failed: {e}", flush=True)
        return

    for c in candidates:
        try:
            # Check if it's 8 PM in THIS subscriber's local timezone.
            # 20:00-20:59 local = pre-generation window.
            user_tz = c.get("timezone") or "America/Indiana/Indianapolis"
            local_now = _local_now_for_user(user_tz)
            if local_now.hour != 20:
                continue

            # No location → can't generate. Skip silently.
            if not c["loc_lat"] or not c["loc_lng"]:
                continue

            # Has a draft already been created in the last 18 hours?
            # If yes, skip — either today's morning draft (still pending)
            # or one we already pre-generated earlier in this 8 PM hour.
            eighteen_hours_ago_ms = int(time.time() * 1000) - 18 * 60 * 60 * 1000
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT id FROM pro_brief_drafts
                               WHERE user_id = %s AND brief_type = 'morning'
                                 AND created_at >= %s
                                 AND status IN ('pending-review','claimed','sent')
                               LIMIT 1""",
                            (c["user_id"], eighteen_hours_ago_ms),
                        )
                        if cur.fetchone():
                            continue
            except Exception as e:
                print(f"[pregen-pro] dup check failed user_id={c['user_id']}: {e}", flush=True)
                continue

            # Generate the AI draft for tomorrow morning. Fetch TOMORROW's
            # forecast (day_offset=1), not tonight's, so the high/low match the
            # day the subscriber receives the brief.
            location_label = c["loc_label"] or c["loc_address"] or "your location"
            forecast = _fetch_forecast(float(c["loc_lat"]), float(c["loc_lng"]), day_offset=1)
            ai_verdict, ai_snippet, ai_body = _generate_ai_brief(
                location_label, forecast or {}, address=c.get("loc_address") or "")

            # Compute window_end_at — tomorrow's morning_window_end in local time.
            # We use local_now + 1 day, then set the hour to the window_end.
            try:
                eh, em = int(c["morning_window_end"][:2]), int(c["morning_window_end"][3:])
                # Tomorrow in subscriber's local timezone
                tomorrow_local = local_now + timedelta(days=1)
                window_end_dt = tomorrow_local.replace(hour=eh, minute=em, second=0, microsecond=0)
                window_end_ms = int(window_end_dt.timestamp() * 1000)
            except (ValueError, TypeError, IndexError):
                # Default cutoff: 18 hours from now (covers 8 PM tonight → ~2 PM tomorrow)
                window_end_ms = int(time.time() * 1000) + 18 * 60 * 60 * 1000

            now_ms = int(time.time() * 1000)
            tier = c["subscription_tier"]
            pregen_preds = _extract_predicted_values_from_forecast(forecast)
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """INSERT INTO pro_brief_drafts
                               (user_id, brief_type, created_at, window_end_at, status,
                                user_tier, location_label, location_lat, location_lng,
                                channels, ai_verdict, ai_snippet, ai_body,
                                met_verdict, met_snippet, met_body,
                                predicted_high_f, predicted_low_f,
                                predicted_precip_in, predicted_max_wind_mph)
                               VALUES (%s, 'morning', %s, %s, 'pending-review',
                                       %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                                       %s, %s, %s, %s)
                               RETURNING id""",
                            (c["user_id"], now_ms, window_end_ms,
                             tier, location_label,
                             float(c["loc_lat"]), float(c["loc_lng"]),
                             c["channels"] or "",
                             ai_verdict, ai_snippet, ai_body,
                             ai_verdict, ai_snippet, ai_body,
                             pregen_preds.get("predicted_high_f"),
                             pregen_preds.get("predicted_low_f"),
                             pregen_preds.get("predicted_precip_in"),
                             pregen_preds.get("predicted_max_wind_mph")),
                        )
                        new_id = cur.fetchone()["id"]
                print(
                    f"[pregen-pro] draft created id={new_id} user_id={c['user_id']} "
                    f"tier={tier} verdict={ai_verdict} (for tomorrow morning)",
                    flush=True,
                )
            except Exception as e:
                print(f"[pregen-pro] insert failed user_id={c['user_id']}: {e}", flush=True)
        except Exception as e:
            print(f"[pregen-pro] FAILED for user_id={c.get('user_id')}: {e!r}", flush=True)


def _process_pending_team_invites() -> None:
    """Self-healing team members (June 2026).

    Three jobs in one, all idempotent and self-limiting:
      1. Backfill subscription_tier on members (inherit the primary's) so
         their own location gets its own daily brief and alerts.
      2. Re-send the onboarding invite to members who never got a working
         one (password not set).
      3. Re-send onboarding to members who signed up but never saved a
         location, so they are walked through setting their zip.
    Groups 2 and 3 are throttled by invite_sent_at (stamped on a
    successful send) so no member is emailed twice from here. Scoped to
    memberships invited in the last 30 days and capped per tick.

    Concurrency: advisory lock (key 91234573), distinct from other jobs.
    """
    _LOCK_KEY = 91234573
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return
    try:
        # Tier backfill: existing team members were created without a
        # subscription_tier, which left them out of the brief pipeline
        # entirely (briefs only generate for pro-tier users). Give every
        # member the primary's tier so their own location gets its own
        # daily brief and alerts. Idempotent: only fills NULL tiers, so it
        # does nothing once everyone is fixed.
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """UPDATE users mu
                           SET subscription_tier = pu.subscription_tier
                           FROM pro_multi_memberships m
                           JOIN users pu ON pu.id = m.primary_user_id
                           WHERE mu.id = m.member_user_id
                             AND m.status IN ('pending','active')
                             AND mu.subscription_tier IS NULL
                             AND pu.subscription_tier IS NOT NULL""",
                    )
                    if cur.rowcount:
                        print(f"[team-invite-heal] backfilled tier for {cur.rowcount} member(s)", flush=True)
        except Exception as e:
            print(f"[team-invite-heal] tier backfill failed: {e!r}", flush=True)

        cutoff = now_ts() - 30 * 24 * 60 * 60
        with db() as conn:
            with conn.cursor() as cur:
                # Pick up two groups, both throttled by invite_sent_at so we
                # never email the same member twice from here:
                #   (a) never received a working invite (password not set), and
                #   (b) signed up but never saved a location (so they get no
                #       briefs/alerts) — the onboarding email walks them through
                #       setting their zip.
                cur.execute(
                    """SELECT m.id
                       FROM pro_multi_memberships m
                       JOIN users mu ON mu.id = m.member_user_id
                       WHERE m.status IN ('pending','active')
                         AND m.invite_sent_at IS NULL
                         AND m.invited_at >= %s
                         AND (
                               mu.password_hash IS NULL
                               OR NOT EXISTS (
                                   SELECT 1 FROM saved_locations sl
                                   WHERE sl.user_id = mu.id AND sl.is_primary = TRUE
                               )
                             )
                       ORDER BY m.invited_at ASC
                       LIMIT 25""",
                    (cutoff,),
                )
                rows = cur.fetchall() or []
        if not rows:
            return
        for r in rows:
            mid = r["id"]
            if _send_membership_invite(mid):
                print(f"[team-invite-heal] sent recovery invite for membership={mid}", flush=True)
            else:
                print(f"[team-invite-heal] could not send for membership={mid}; will retry", flush=True)
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)

def _process_expired_trials() -> None:
    """Auto-expire Boone free trials that have passed their end date and
    have NOT converted to paid (June 2026).

    For each user with trial_status = 'active' and trial_ends_at <= now,
    we revoke their Pro access (subscriber role removed + subscription_tier
    cleared to NULL via _revoke_subscriber_role) and set trial_status =
    'expired'. The account itself is kept — only Pro access ends.

    Conversions are excluded automatically: when a trial user pays through
    Stripe, the webhook sets trial_status = 'converted', so they never
    match this query.

    Notifies the team so they have a record (no auto email to the
    subscriber — follow-up is handled by the team).

    Concurrency: Postgres advisory lock (key 91234572, distinct from the
    other scheduler locks) so multi-worker deployments don't double-run.
    """
    _LOCK_KEY = 91234572
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # Another worker holds the lock this tick; skip silently
    try:
        now = now_ts()  # seconds since epoch (codebase standard)
        # Find trials that are due to expire.
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT id, email, name, trial_business_name, trial_ends_at
                       FROM users
                       WHERE trial_status = 'active'
                         AND trial_ends_at IS NOT NULL
                         AND trial_ends_at <= %s
                       ORDER BY trial_ends_at ASC
                       LIMIT 200""",
                    (now,),
                )
                due = cur.fetchall() or []

        if not due:
            return

        for row in due:
            uid = row["id"]
            try:
                with db() as conn:
                    # Re-check status inside the txn to avoid a race where
                    # a conversion landed between the SELECT and now.
                    with conn.cursor() as cur:
                        cur.execute(
                            "SELECT trial_status FROM users WHERE id = %s FOR UPDATE",
                            (uid,),
                        )
                        cur_row = cur.fetchone() or {}
                    if cur_row.get("trial_status") != "active":
                        continue  # converted or already expired — leave alone
                    _revoke_subscriber_role(uid, conn)
                    with conn.cursor() as cur:
                        cur.execute(
                            "UPDATE users SET trial_status = 'expired' WHERE id = %s",
                            (uid,),
                        )
                print(f"[trial-expiry] expired trial for user={uid} "
                      f"({row.get('email')})", flush=True)
                # Team notification (record of the expiry).
                biz = row.get("trial_business_name") or row.get("name") or row.get("email")
                try:
                    _send_team_notification(
                        subject=f"Boone trial expired: {biz}",
                        html_body=(
                            f"<p>The free trial for <b>{biz}</b> ({row.get('email')}) "
                            f"has reached day 31 without converting, so Pro access was "
                            f"automatically removed. The account was kept.</p>"
                            f"<p style='font-size:13px;color:#555'>If they still want to "
                            f"continue, point them to checkout to start a paid Pro Single "
                            f"plan.</p>"
                        ),
                        text_body=(
                            f"Boone trial expired: {biz} ({row.get('email')}).\n\n"
                            f"The trial reached day 31 without converting, so Pro access "
                            f"was automatically removed. The account was kept. If they "
                            f"still want to continue, point them to checkout for paid "
                            f"Pro Single."
                        ),
                    )
                except Exception as e:
                    print(f"[trial-expiry] notify failed for user={uid}: {e!r}", flush=True)
            except Exception as e:
                print(f"[trial-expiry] failed to expire user={uid}: {e!r}", flush=True)
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)

def _brief_scheduler_loop() -> None:
    """Main scheduler loop — runs in a daemon thread. Ticks every 60s.

    Each tick runs three independent jobs:
      1. _process_pending_briefs — daily brief delivery
      2. _process_severe_alerts  — NWS severe alert detection + Met paging
      3. _check_missed_pro_briefs — alert admin + Met when a Pro brief
                                    was supposed to send but didn't

    Failures in one don't stop the others.
    """
    print("[brief-scheduler] started", flush=True)
    # Initial small delay so the app fully boots before our first tick.
    time.sleep(15)
    while True:
        try:
            _process_pending_briefs()
        except Exception as e:
            print(f"[brief-scheduler] tick failed: {e!r}", flush=True)
        try:
            _pregenerate_pro_brief_drafts()
        except Exception as e:
            print(f"[pregen-pro] tick failed: {e!r}", flush=True)
        # Widget narrative pregen disabled May 29 2026 — Met-edited
        # narratives removed from public widget (competed with paid
        # subs) and from Met workspace. Pregen would just write to
        # a table no one reads. Uncomment to re-enable.
        # try:
        #     _generate_widget_narratives()
        # except Exception as e:
        #     print(f"[widget-narratives] tick failed: {e!r}", flush=True)
        try:
            _process_severe_alerts()
        except Exception as e:
            print(f"[nws-scheduler] tick failed: {e!r}", flush=True)
        try:
            _process_rain_alerts()
        except Exception as e:
            print(f"[rain-alert] tick failed: {e!r}", flush=True)

        try:
            _process_threshold_alerts()
        except Exception as e:
            print(f"[scheduler] threshold alerts failed: {e}", flush=True)
        try:
            _check_missed_pro_briefs()
        except Exception as e:
            print(f"[missed-brief-check] tick failed: {e!r}", flush=True)
        try:
            _autosend_missed_pro_briefs()
        except Exception as e:
            print(f"[autosend-scheduler] tick failed: {e!r}", flush=True)
        try:
            _process_scheduled_messages()
        except Exception as e:
            print(f"[scheduled-msg-tick] tick failed: {e!r}", flush=True)
        try:
            _process_rep_trial_nudges()
        except Exception as e:
            print(f"[rep-nudge] tick failed: {e!r}", flush=True)
        try:
            _crew_daily_checkin_nudge()
        except Exception as e:
            print(f"[crew-nudge] tick failed: {e!r}", flush=True)
        # Phase 11 (May 17): Coverage scheduler jobs
        # Generate today/tomorrow tasks for Pro subscribers, then check
        # for escalations. Both run on the same 60s tick so deadlines
        # are checked at minute resolution.
        try:
            _coverage_generate_pending_tasks()
        except Exception as e:
            print(f"[coverage-tasks] generate failed: {e!r}", flush=True)
        try:
            _coverage_check_escalations()
        except Exception as e:
            print(f"[coverage-tasks] escalation check failed: {e!r}", flush=True)
        try:
            _coverage_auto_close_storm_shelters()
        except Exception as e:
            print(f"[storm-shelter] auto-close tick failed: {e!r}", flush=True)
        try:
            _rosie_fire_reminders()
        except Exception as e:
            print(f"[rosie-reminder] fire tick failed: {e!r}", flush=True)
        try:
            _rosie_proactive_check_tick()
        except Exception as e:
            print(f"[rosie-proactive] tick failed: {e!r}", flush=True)
        try:
            _maybe_run_nightly_brief_grader()
        except Exception as e:
            print(f"[brief-grader] tick failed: {e!r}", flush=True)
        try:
            _maybe_run_accuracy_emails()
        except Exception as e:
            print(f"[accuracy-email] tick failed: {e!r}", flush=True)
        try:
            _process_expired_trials()
        except Exception as e:
            print(f"[trial-expiry] tick failed: {e!r}", flush=True)
        try:
            _process_pending_team_invites()
        except Exception as e:
            print(f"[team-invite-heal] tick failed: {e!r}", flush=True)
        time.sleep(60)


# ────────────────────────────────────────────────────────────────────────────
# Coverage scheduler — Phase 2 (task generation + escalation)
# ────────────────────────────────────────────────────────────────────────────


def _coverage_generate_pending_tasks() -> None:
    """For every active Pro subscriber, ensure a daily_brief_tasks row
    exists for today and tomorrow (in their local timezone).

    Runs on the main scheduler tick. Idempotent — uses ON CONFLICT to
    avoid duplicate rows. Generates 2 days ahead so timezone edge cases
    (subscribers in HI vs NY) all get coverage even if the cron is a
    few hours late.
    """
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id AS user_id, u.name, u.email,
                          u.subscription_tier AS tier,
                          sc.primary_met_id, sc.backup_met_id,
                          sc.daily_brief_time, sc.daily_brief_timezone,
                          bp.morning_window_start
                   FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'subscriber'
                   LEFT JOIN subscriber_coverage sc ON sc.user_id = u.id
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   WHERE u.is_active = TRUE
                     AND u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')"""
            )
            subs = cur.fetchall()

            # Read recurring + overrides once for performance
            cur.execute(
                """SELECT mrs.*, u.name AS met_name
                   FROM met_recurring_shifts mrs
                   JOIN users u ON u.id = mrs.met_user_id
                   WHERE u.is_active = TRUE"""
            )
            recurring = cur.fetchall()

            today_utc = datetime.now(timezone.utc).date()
            window_start = today_utc.strftime("%Y-%m-%d")
            window_end = (today_utc + timedelta(days=2)).strftime("%Y-%m-%d")
            cur.execute(
                """SELECT mso.*, u.name AS met_name
                   FROM met_shift_overrides mso
                   LEFT JOIN users u ON u.id = mso.met_user_id
                   WHERE mso.shift_date >= %s
                     AND mso.shift_date <= %s
                   ORDER BY mso.created_at""",
                (window_start, window_end),
            )
            overrides = cur.fetchall()

    now_ms = int(time.time() * 1000)
    created_count = 0
    inserts = []  # batched (subscriber_id, date, met_id, due_at_ms) tuples

    for sub in subs:
        tz_name = sub.get("daily_brief_timezone") or "America/New_York"
        # Use the delivery time the subscriber actually set in their portal
        # (brief_preferences.morning_window_start) — the same field the brief
        # send uses. The older subscriber_coverage.daily_brief_time stays at
        # its 07:00 default unless separately changed, so relying on it made
        # Rosie flag a brief "overdue" at 7:00 AM even when the subscriber
        # chose a later time. (June 2026)
        delivery_time_str = (
            sub.get("morning_window_start")
            or sub.get("daily_brief_time")
            or "07:00"
        )

        try:
            sub_tz = ZoneInfo(tz_name)
        except Exception:
            sub_tz = ZoneInfo("America/New_York")

        # Today + tomorrow in subscriber's local timezone
        now_local = datetime.now(sub_tz)
        for offset in (0, 1):
            local_date = (now_local + timedelta(days=offset)).date()
            local_date_str = local_date.strftime("%Y-%m-%d")
            # Compute deadline = local date + delivery time, converted to UTC ms
            try:
                hh, mm = delivery_time_str.split(":")
                deadline_local = datetime(
                    local_date.year, local_date.month, local_date.day,
                    int(hh), int(mm), tzinfo=sub_tz
                )
                deadline_utc = deadline_local.astimezone(timezone.utc)
                due_at_ms = int(deadline_utc.timestamp() * 1000)
            except Exception as e:
                print(f"[coverage-tasks] bad time '{delivery_time_str}' for user {sub['user_id']}: {e}", flush=True)
                continue

            # Skip generating if deadline already past (we don't backfill old days)
            if due_at_ms < now_ms - 24 * 60 * 60 * 1000:
                continue

            # Resolve assigned Met via the same logic as the dashboard
            dow = (local_date.weekday() + 1) % 7  # 0=Sun
            assigned = _resolve_coverage_for_day(
                local_date_str, dow, sub["user_id"], sub.get("primary_met_id"),
                recurring, overrides, scope="subscriber"
            )
            assigned_met_id = assigned["met_id"] if assigned else None
            # Stash for batched insert below — one DB round-trip per
            # subscriber instead of per-(subscriber, day).
            inserts.append((sub["user_id"], local_date_str, assigned_met_id, due_at_ms))

    # Batched insert — one transaction for all rows generated this tick.
    # ON CONFLICT preserves any existing assignment: if a task row was
    # created earlier with assigned_met_id=X, we don't overwrite X even
    # if the resolver would now return Y. This protects work-in-progress
    # from getting reassigned mid-day. Admin can manually reassign by
    # updating the row directly if needed.
    if inserts:
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    for row_args in inserts:
                        cur.execute(
                            """INSERT INTO daily_brief_tasks
                               (subscriber_user_id, task_date, assigned_met_id,
                                due_at_ms, status)
                               VALUES (%s, %s, %s, %s, 'pending')
                               ON CONFLICT (subscriber_user_id, task_date) DO UPDATE
                               SET assigned_met_id = COALESCE(daily_brief_tasks.assigned_met_id,
                                                              EXCLUDED.assigned_met_id),
                                   due_at_ms = EXCLUDED.due_at_ms
                               RETURNING (xmax = 0) AS inserted""",
                            row_args,
                        )
                        r = cur.fetchone()
                        if r and r.get("inserted"):
                            created_count += 1
        except Exception as e:
            print(f"[coverage-tasks] batch insert failed: {e}", flush=True)

    if created_count:
        print(f"[coverage-tasks] generated {created_count} new task rows", flush=True)


# How long after a Pro brief's delivery time we wait before paging admins.
# Pro briefs are Meteorologist-owned and are NOT auto-sent, so a brief that
# is neither sent nor scheduled by this grace genuinely won't go out and
# needs a human. The grace keeps a Met who is a few minutes late from
# triggering a page. Tunable via env (minutes); default 30.
try:
    _PRO_BRIEF_ADMIN_GRACE_MS = int(
        float(os.environ.get("PRO_BRIEF_ADMIN_GRACE_MIN", "30")) * 60 * 1000)
except Exception:
    _PRO_BRIEF_ADMIN_GRACE_MS = 30 * 60 * 1000


def _pro_brief_is_scheduled(subscriber_user_id) -> bool:
    """True if a Met has a pending scheduled Pro brief queued for this
    subscriber. A scheduled brief keeps its draft in 'pending-review', so
    without this check it looks identical to a missed brief. We never page
    admins for a brief that is going to send itself on the Met's schedule."""
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT target_audience FROM scheduled_messages
                       WHERE type = 'pro_brief' AND status = 'pending'"""
                )
                rows = cur.fetchall()
        target = str(subscriber_user_id)
        for row in rows:
            ta = row.get("target_audience")
            if not ta:
                continue
            try:
                obj = json.loads(ta)
            except Exception:
                continue
            if str(obj.get("subscriber_user_id")) == target:
                return True
    except Exception as e:
        print(f"[coverage-escalate] scheduled-check failed: {e}", flush=True)
    return False


def _coverage_check_escalations() -> None:
    """For pending daily brief tasks approaching their deadline, fire
    SMS escalations.

    Schedule:
      - T-30 minutes (before deadline), Met not started → SMS assigned Met
      - T+grace (delivery time passed by the grace window), still not sent
        and not scheduled → SMS admin + Chief Met (Joe). Pro briefs are
        never auto-sent, so this means no brief will go out until a Met
        acts. (June 2026: was T+0, which paged before the Met realistically
        had time and before the old auto-send safety net ran. Auto-send of
        unreviewed AI drafts has since been removed at Michael's direction.)

    Each escalation level recorded in escalated_at_ms / escalated_admin_at_ms
    so we don't double-fire. If the brief is sent in between, the task
    transitions to 'sent' and escalations stop.

    Concurrency (June 2026): wrapped in a Postgres advisory lock (key
    91234574) so multi-worker deployments don't run this in two workers
    at once and page every overdue task twice. This was the cause of the
    duplicate overdue texts.
    """
    _LOCK_KEY = 91234574
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # Another worker is handling escalations this tick
    try:
        _coverage_check_escalations_inner()
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


def _coverage_check_escalations_inner() -> None:
    now_ms = int(time.time() * 1000)
    thirty_min_ms = 30 * 60 * 1000

    with db() as conn:
        with conn.cursor() as cur:
            # Find tasks whose deadline is within the next 30 min and
            # haven't been started yet (or deadline has passed and not sent).
            cur.execute(
                """SELECT dbt.id, dbt.subscriber_user_id, dbt.assigned_met_id,
                          dbt.task_date, dbt.due_at_ms, dbt.status,
                          dbt.started_at_ms, dbt.sent_at_ms,
                          dbt.escalated_at_ms, dbt.escalated_admin_at_ms,
                          su.name AS subscriber_name,
                          su.email AS subscriber_email,
                          mu.name AS met_name, mu.phone AS met_phone,
                          sc.backup_met_id, sc.daily_brief_timezone,
                          bu.name AS backup_name, bu.phone AS backup_phone
                   FROM daily_brief_tasks dbt
                   JOIN users su ON su.id = dbt.subscriber_user_id
                   LEFT JOIN users mu ON mu.id = dbt.assigned_met_id
                   LEFT JOIN subscriber_coverage sc ON sc.user_id = dbt.subscriber_user_id
                   LEFT JOIN users bu ON bu.id = sc.backup_met_id
                   WHERE dbt.status = 'pending'
                     AND dbt.sent_at_ms IS NULL
                     AND dbt.due_at_ms <= %s""",
                (now_ms + thirty_min_ms,),
            )
            rows = cur.fetchall()

    for r in rows:
        # If T-30 reached and we haven't sent Met SMS yet, send it
        time_to_deadline = r["due_at_ms"] - now_ms
        # Level 1: T-30 min, not started, not yet escalated
        if (time_to_deadline <= thirty_min_ms
            and r["started_at_ms"] is None
            and r["escalated_at_ms"] is None
            and r["assigned_met_id"]):
            _coverage_escalate_to_met(r)
        # Level 2: delivery time passed by the grace window, still not sent,
        # not yet admin-escalated, and the Met has not scheduled it. Because
        # Pro briefs are never auto-sent, this means the subscriber will get
        # nothing unless a human acts, which is the only thing worth paging
        # admins about.
        elif (time_to_deadline <= -_PRO_BRIEF_ADMIN_GRACE_MS
              and r["sent_at_ms"] is None
              and r["escalated_admin_at_ms"] is None
              and not _pro_brief_is_scheduled(r["subscriber_user_id"])):
            _coverage_escalate_to_admin(r)


def _coverage_escalate_to_met(task_row) -> None:
    """SMS the assigned (primary) Met that the brief is due in 30 minutes
    and they haven't started yet. Backup is NOT pinged at this level —
    they only get involved if the primary fails (L2 escalation). This
    keeps SMS noise low and avoids cry-wolf fatigue."""
    now_ms = int(time.time() * 1000)
    sub_name = task_row.get("subscriber_name") or "a Pro subscriber"
    msg = (
        f"WeatherValet: daily brief for {sub_name} is due in 30 minutes. "
        f"You haven't started yet. Open your workspace to begin. "
        f"Task date: {task_row['task_date']}."
    )

    targets = []
    if task_row.get("met_phone"):
        targets.append((task_row["assigned_met_id"], task_row["met_phone"], "assigned"))
    # Note: backup intentionally excluded here — see L2 escalation.

    sent_any = False
    for met_id, phone, role in targets:
        try:
            if send_sms(phone, msg):
                sent_any = True
                print(f"[coverage-escalate] L1 SMS to met={met_id} ({role}) for task={task_row['id']}", flush=True)
        except Exception as e:
            print(f"[coverage-escalate] L1 SMS failed met={met_id}: {e}", flush=True)

    # Mark escalated even if SMS failed — we don't want to keep retrying
    # endlessly. Failed sends will surface in logs for investigation.
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE daily_brief_tasks
                       SET escalated_at_ms = %s
                       WHERE id = %s""",
                    (now_ms, task_row["id"]),
                )
    except Exception as e:
        print(f"[coverage-escalate] DB update failed: {e}", flush=True)


def _coverage_escalate_to_admin(task_row) -> None:
    """SMS admins, Chief Met (Joe), AND the backup Met (if any) when a
    brief deadline has passed and the brief still hasn't been sent.
    This is the loud alert — backup is brought in here, not at L1,
    so they only get pinged when it actually matters."""
    now_ms = int(time.time() * 1000)
    sub_name = task_row.get("subscriber_name") or "a Pro subscriber"
    met_name = task_row.get("met_name") or "(unassigned)"
    msg = (
        f"WeatherValet ALERT: the Pro brief for {sub_name} has not been sent "
        f"or scheduled and its delivery time has passed. Assigned Met: {met_name}. "
        f"Date: {task_row['task_date']}. No brief will go out until a Meteorologist sends it."
    )

    # Find escalation targets: all active admins + any user with name
    # containing "Joe" or "Clauss" (Chief Met). Falls back gracefully if
    # neither exists.
    targets = []
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.phone
                   FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'admin'
                   WHERE u.is_active = TRUE
                     AND u.phone IS NOT NULL AND u.phone != ''"""
            )
            for r in cur.fetchall():
                targets.append((r["id"], r["phone"], "admin"))

            # Chief Met by email (configurable later)
            chief_email = os.environ.get("CHIEF_MET_EMAIL", "joe@weathervalet.com").strip()
            if chief_email:
                cur.execute(
                    """SELECT u.id, u.name, u.phone
                       FROM users u
                       WHERE LOWER(u.email) = LOWER(%s)
                         AND u.is_active = TRUE
                         AND u.phone IS NOT NULL AND u.phone != ''""",
                    (chief_email,),
                )
                for r in cur.fetchall():
                    # Avoid duplicates if Chief Met is also admin
                    if not any(t[0] == r["id"] for t in targets):
                        targets.append((r["id"], r["phone"], "chief"))

    # Backup Met — only paged at L2, not L1. Use a friendlier message
    # since they're being asked to actually do work, not just be aware.
    if task_row.get("backup_phone") and task_row.get("backup_met_id"):
        backup_id = task_row["backup_met_id"]
        if not any(t[0] == backup_id for t in targets):
            targets.append((backup_id, task_row["backup_phone"], "backup"))

    if not targets:
        print(f"[coverage-escalate] L2: no admin/chief/backup targets for task={task_row['id']}", flush=True)

    for uid, phone, role in targets:
        # Friendly variant for backup — they're being asked to step in
        if role == "backup":
            send_msg = (
                f"WeatherValet: {met_name} hasn't sent the daily brief for "
                f"{sub_name} yet ({task_row['task_date']}). Can you cover? "
                f"Open your workspace to claim the task."
            )
        else:
            send_msg = msg
        try:
            if send_sms(phone, send_msg):
                print(f"[coverage-escalate] L2 SMS to {role} uid={uid} for task={task_row['id']}", flush=True)
        except Exception as e:
            print(f"[coverage-escalate] L2 SMS failed uid={uid}: {e}", flush=True)

    # Mark admin-escalated + status=overdue so the dashboard reflects it
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE daily_brief_tasks
                       SET escalated_admin_at_ms = %s,
                           status = 'overdue'
                       WHERE id = %s""",
                    (now_ms, task_row["id"]),
                )
    except Exception as e:
        print(f"[coverage-escalate] L2 DB update failed: {e}", flush=True)


def _check_missed_pro_briefs() -> None:
    """Detect Pro subscribers whose morning brief window has closed
    without a brief being sent. SMS admin + the Met team so someone
    can catch up.

    Runs every 60s. Dedupes via a daily marker so we don't spam.
    A "missed" alert fires once: at 5 minutes past window end.
    """
    # We track which (user_id, local_date) combos we've already alerted
    # for, to avoid repeating. Use brief_history with a special
    # brief_type='missed_alert' marker so dedup persists across restarts.
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT
                          u.id AS user_id, u.email, u.name, u.timezone,
                          u.subscription_tier,
                          bp.morning_window_start, bp.morning_window_end
                       FROM users u
                       JOIN brief_preferences bp ON bp.user_id = u.id
                       WHERE u.is_active = TRUE
                         AND bp.morning_enabled = TRUE
                         AND u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')
                         AND EXISTS (
                           SELECT 1 FROM user_roles ur
                           WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                         )"""
                )
                pro_subs = cur.fetchall()
    except Exception as e:
        print(f"[missed-brief-check] query failed: {e}", flush=True)
        return

    for c in pro_subs:
        try:
            user_tz = c.get("timezone") or "America/Indiana/Indianapolis"
            try:
                tz = ZoneInfo(user_tz)
            except Exception:
                tz = ZoneInfo("America/Indiana/Indianapolis")
            local_now = datetime.now(tz)

            # Parse window end and add 5-minute grace
            try:
                end_h = int(c["morning_window_end"][:2])
                end_m = int(c["morning_window_end"][3:])
            except (ValueError, TypeError, IndexError):
                continue

            window_end_today = local_now.replace(
                hour=end_h, minute=end_m, second=0, microsecond=0
            )
            check_after = window_end_today + timedelta(minutes=5)

            # Only check after the grace period
            if local_now < check_after:
                continue
            # Only check if it's still the same day (don't fire stale alerts)
            if (local_now - check_after).total_seconds() > 7200:
                # Window ended >2hr ago — too late, skip
                continue

            # Already sent the brief? Skip.
            if _already_sent_today(c["user_id"], "morning", user_tz):
                continue
            # Already alerted about this miss today? Skip.
            if _already_sent_today(c["user_id"], "missed_alert", user_tz):
                continue

            # Fire alerts: admin + Met team
            sub_name = (c.get("name") or "").strip() or c["email"]
            msg = (
                f"WeatherValet: Pro brief for {sub_name} missed window today. "
                f"Subscriber is paying for daily Met-touched briefs, "
                f"please send manually or check the workspace."
            )

            # Met team SMS
            met_phone = os.environ.get("METEOROLOGIST_PHONE", "").strip()
            if met_phone:
                try:
                    send_sms(met_phone, msg)
                except Exception as e:
                    print(f"[missed-brief-check] met SMS failed: {e}", flush=True)

            # Admin SMS: lookup admin users with phones
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT u.phone FROM users u
                               WHERE u.is_active = TRUE
                                 AND u.phone IS NOT NULL AND u.phone != ''
                                 AND EXISTS (
                                   SELECT 1 FROM user_roles ur
                                   WHERE ur.user_id = u.id AND ur.role = 'admin'
                                 )
                               LIMIT 5"""
                        )
                        admin_rows = cur.fetchall()
                for a in admin_rows:
                    try:
                        send_sms(a["phone"], msg)
                    except Exception as e:
                        print(f"[missed-brief-check] admin SMS failed: {e}", flush=True)
            except Exception as e:
                print(f"[missed-brief-check] admin lookup failed: {e}", flush=True)

            # Record the alert so we don't repeat
            now_ms = int(time.time() * 1000)
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """INSERT INTO brief_history
                               (user_id, brief_type, delivered_at, channels_used,
                                delivery_status)
                               VALUES (%s, 'missed_alert', %s, 'sms', 'sent')""",
                            (c["user_id"], now_ms),
                        )
            except Exception as e:
                print(f"[missed-brief-check] dedup-write failed: {e}", flush=True)

            print(
                f"[missed-brief-check] alerted on missed brief user_id={c['user_id']} ({sub_name})",
                flush=True,
            )
        except Exception as e:
            print(f"[missed-brief-check] per-sub error user_id={c.get('user_id')}: {e!r}", flush=True)


def _autosend_missed_pro_briefs() -> None:
    """Auto-send Pro briefs when the Met failed to send by window+15min.

    Phase: safety net (May 29, 2026). Pro subscribers pay for daily
    Met-touched briefs. The existing _check_missed_pro_briefs fires
    at +5 min with an SMS to admin+Met. This function fires at +15
    min — giving the Met a 10-minute window to react to the alert
    before the system auto-sends the AI version (unless verdict=suppress,
    in which case we hold and rely on the human alert path).

    Runs every 60s. Dedupes via the auto_sent_at column on
    pro_brief_drafts (set by _autosend_pro_brief_draft on success),
    so a draft is auto-sent at most once.
    """
    _LOCK_KEY = 91234571  # distinct from other scheduler locks
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # another worker is on it
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT
                          u.id AS user_id, u.email, u.name, u.timezone,
                          u.subscription_tier,
                          bp.morning_window_start, bp.morning_window_end
                       FROM users u
                       JOIN brief_preferences bp ON bp.user_id = u.id
                       WHERE u.is_active = TRUE
                         AND bp.morning_enabled = TRUE
                         AND u.subscription_tier IN
                             ('pro_single','pro_multi','pro_enterprise')
                         AND EXISTS (
                           SELECT 1 FROM user_roles ur
                           WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                         )"""
                )
                pro_subs = cur.fetchall()

        for c in pro_subs:
            try:
                user_tz = c.get("timezone") or "America/Indiana/Indianapolis"
                try:
                    tz = ZoneInfo(user_tz)
                except Exception:
                    tz = ZoneInfo("America/Indiana/Indianapolis")
                local_now = datetime.now(tz)

                try:
                    end_h = int(c["morning_window_end"][:2])
                    end_m = int(c["morning_window_end"][3:])
                except (ValueError, TypeError, IndexError):
                    continue

                window_end_today = local_now.replace(
                    hour=end_h, minute=end_m, second=0, microsecond=0
                )
                # Auto-send threshold: 15 minutes past window end.
                # This gives the Met 10 minutes after the +5min admin
                # alert to react before the system takes over.
                check_after = window_end_today + timedelta(minutes=15)
                if local_now < check_after:
                    continue
                # Don't auto-send for windows that closed too long ago —
                # the subscriber's context has moved on; sending now
                # would be more confusing than helpful.
                if (local_now - check_after).total_seconds() > 7200:
                    continue

                # Already sent (manually or auto)?
                if _already_sent_today(c["user_id"], "morning", user_tz):
                    continue

                # Find the most recent pending draft for this subscriber today
                today_start_ms = int(local_now.replace(
                    hour=0, minute=0, second=0, microsecond=0
                ).timestamp() * 1000)
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT id FROM pro_brief_drafts
                               WHERE user_id = %s
                                 AND status IN ('pending-review', 'claimed')
                                 AND brief_type = 'morning'
                                 AND auto_sent_at IS NULL
                                 AND cancelled_at IS NULL
                                 AND created_at >= %s
                               ORDER BY created_at DESC
                               LIMIT 1""",
                            (c["user_id"], today_start_ms),
                        )
                        draft_row = cur.fetchone()

                if not draft_row:
                    # No eligible draft — could be that pregen failed last
                    # night, or the draft was cancelled. The +5min admin
                    # alert already fired for this case; nothing more
                    # we can do here.
                    continue

                # Pro briefs are Meteorologist-owned. We do NOT auto-send the
                # AI draft on the Met's behalf (Michael's direction, June
                # 2026). If the Met hasn't sent or scheduled by now, no brief
                # goes out; the coverage escalation pages admins about the
                # miss. We keep this job only to log the gap for visibility.
                sub_name = (c.get("name") or "").strip() or c["email"]
                print(
                    f"[autosend-scheduler] auto-send disabled (Met-owned); "
                    f"not sending draft={draft_row['id']} for {sub_name} "
                    f"(user_id={c['user_id']})",
                    flush=True,
                )
            except Exception as e:
                print(
                    f"[autosend-scheduler] per-sub error user_id={c.get('user_id')}: {e!r}",
                    flush=True,
                )
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


#
# Each scheduler tick:
#   1. Fetch active NWS alerts (events we care about)
#   2. For each alert, check if its polygon contains any Pro subscriber's
#      primary saved location
#   3. If yes, dedupe against nws_alert_pages (by nws_alert_id) — skip
#      if already paged
#   4. Insert a new row, page the on-duty Met via SMS with a link
#
# This runs every 60s; NWS alerts can have <20min lead time so a 1-min
# detection latency is acceptable. Tighter polling adds little value
# and risks NWS rate limits.

# Severe events we page Mets for. Other NWS event types (Special Weather
# Statement, Hydrologic Outlook, etc.) are informational and don't warrant
# waking the on-duty Met. We can expand this list over time.
_NWS_SEVERE_EVENTS = (
    "Tornado Warning",
    "Severe Thunderstorm Warning",
    "Flash Flood Warning",
    "Tornado Watch",
    "Severe Thunderstorm Watch",
    "Flood Warning",
)


def _fetch_active_nws_alerts() -> list:
    """Fetch active NWS alerts via the api.weather.gov /alerts/active endpoint.

    Returns a list of normalized alert dicts. Empty list on any error —
    we never want a transient NWS hiccup to break the scheduler.

    Note: NWS API requires a User-Agent header identifying the app.
    """
    try:
        # Filter to severe events only (server-side filtering reduces
        # response size + processing time)
        events_param = ",".join(_NWS_SEVERE_EVENTS)
        url = (
            "https://api.weather.gov/alerts/active"
            f"?event={urllib.parse.quote(events_param)}"
            "&status=actual"
        )
        req = urllib.request.Request(url, headers={
            "User-Agent": "WeatherValet/1.0 (+https://weathervalet.ai)",
            "Accept": "application/geo+json",
        })
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        print(f"[nws-fetch] failed: {e}", flush=True)
        return []

    features = data.get("features") or []
    now_ms = int(time.time() * 1000)
    out = []
    for f in features:
        props = f.get("properties") or {}
        geom = f.get("geometry")
        nws_id = props.get("id") or f.get("id")  # the urn:oid alert ID
        if not nws_id:
            continue
        has_polygon = bool(geom) and geom.get("type") in ("Polygon", "MultiPolygon")
        # Watches (and some warnings) arrive WITHOUT a polygon — they are
        # county/zone-based. We keep those and match them by county text
        # instead of point-in-polygon. SAME = FIPS county codes; areaDesc
        # is the "County, ST; County, ST" list we match against.
        geocode = props.get("geocode") or {}
        same_codes = geocode.get("SAME") or []
        match_mode = "polygon" if has_polygon else "county"
        expires_str = props.get("expires") or props.get("ends")
        expires_ms = None
        if expires_str:
            try:
                from datetime import datetime as _dt
                expires_ms = int(_dt.fromisoformat(
                    expires_str.replace("Z", "+00:00")
                ).timestamp() * 1000)
            except (ValueError, TypeError):
                pass
        # ── Filter out expired alerts (May 18, 2026) ──
        # NWS /alerts/active sometimes returns alerts whose expiration
        # has already passed but haven't been removed from the feed yet.
        if expires_ms is not None and expires_ms < now_ms:
            continue
        out.append({
            "nws_id": nws_id,
            "event": props.get("event") or "",
            "severity": props.get("severity") or "",
            "headline": props.get("headline") or "",
            "description": props.get("description") or "",
            "instruction": props.get("instruction") or "",
            "area_desc": props.get("areaDesc") or "",
            "geometry": geom if has_polygon else None,
            "match_mode": match_mode,
            "same_codes": same_codes,
            "expires_at": expires_ms,
        })
    return out


def _find_pro_subscribers_in_polygon(geom: dict) -> list:
    """Find ALL subscribers (any tier, July 2026) whose primary saved_location is inside
    the alert polygon. Returns list of dicts with user info needed for
    later notification (id, name, email, phone, location), plus the
    subscriber's assigned primary Met (id, name, phone) so the pager can
    route the alert to the right Met.
    """
    # Stringify geometry once so _point_in_polygon_geojson can parse it
    geom_str = json.dumps(geom)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.email, u.phone,
                          u.subscription_tier,
                          loc.label AS loc_label, loc.lat, loc.lng,
                          cov.primary_met_id AS met_id,
                          met.name  AS met_name,
                          met.phone AS met_phone,
                          cov.backup_met_id AS backup_met_id,
                          bm.name  AS backup_met_name,
                          bm.phone AS backup_met_phone
                   FROM users u
                   JOIN saved_locations loc
                     ON loc.user_id = u.id AND loc.is_primary = TRUE
                   LEFT JOIN subscriber_coverage cov
                     ON cov.user_id = u.id
                   LEFT JOIN users met
                     ON met.id = cov.primary_met_id
                   LEFT JOIN users bm
                     ON bm.id = cov.backup_met_id
                   WHERE u.is_active = TRUE
                     -- July 2026: severe weather does not check tiers.
                     -- Every subscriber in the warning area gets the alert,
                     -- Pro and Hobbyist alike (Michael + Met decision).
                     AND EXISTS (
                       SELECT 1 FROM user_roles ur
                        WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                     )"""
            )
            rows = cur.fetchall()

    matching = []
    for r in rows:
        if r["lat"] is None or r["lng"] is None:
            continue
        if _point_in_polygon_geojson(float(r["lat"]), float(r["lng"]), geom_str):
            matching.append({
                "user_id": r["id"],
                "name": r.get("name") or "",
                "email": r["email"],
                "phone": r.get("phone") or "",
                "tier": r["subscription_tier"],
                "loc_label": r["loc_label"],
                "met_id": r.get("met_id"),
                "met_name": r.get("met_name") or "",
                "met_phone": r.get("met_phone") or "",
                "backup_met_id": r.get("backup_met_id"),
                "backup_met_name": r.get("backup_met_name") or "",
                "backup_met_phone": r.get("backup_met_phone") or "",
            })
    return matching


def _find_pro_subscribers_by_county(alert: dict) -> list:
    """Find ALL subscribers (any tier, July 2026) whose saved location falls in a county-based
    (geometry-less) alert, e.g. a Severe Thunderstorm Watch. Watches identify
    their area by county, not a polygon, so we match the alert's areaDesc
    ("County, ST; County, ST") against each subscriber's county + state.

    Matching is done on the "<county>, <ST>" pair to avoid cross-state false
    matches (same logic that fixed the overlay warning scroll). The
    subscriber's state is parsed from address_text (e.g. "Lebanon, IN"); the
    county comes from the saved_locations.county field.
    """
    area_l = (alert.get("area_desc") or "").lower()
    if not area_l:
        return []

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.email, u.phone,
                          u.subscription_tier,
                          loc.label AS loc_label, loc.county, loc.address_text,
                          cov.primary_met_id AS met_id,
                          met.name  AS met_name,
                          met.phone AS met_phone,
                          cov.backup_met_id AS backup_met_id,
                          bm.name  AS backup_met_name,
                          bm.phone AS backup_met_phone
                   FROM users u
                   JOIN saved_locations loc
                     ON loc.user_id = u.id AND loc.is_primary = TRUE
                   LEFT JOIN subscriber_coverage cov
                     ON cov.user_id = u.id
                   LEFT JOIN users met
                     ON met.id = cov.primary_met_id
                   LEFT JOIN users bm
                     ON bm.id = cov.backup_met_id
                   WHERE u.is_active = TRUE
                     -- July 2026: severe weather does not check tiers.
                     -- Every subscriber in the warning area gets the alert,
                     -- Pro and Hobbyist alike (Michael + Met decision).
                     AND EXISTS (
                       SELECT 1 FROM user_roles ur
                        WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                     )"""
            )
            rows = cur.fetchall()

    import re as _re
    matching = []
    for r in rows:
        # County name without the trailing " county" word, lowercased.
        county = (r.get("county") or "").lower().replace(" county", "").strip()
        if not county:
            continue
        # State = the 2-letter code at the end of address_text ("Lebanon, IN").
        addr = (r.get("address_text") or "").strip()
        m = _re.search(r",\s*([A-Za-z]{2})\b\s*$", addr)
        st = m.group(1).lower() if m else ""
        if not st:
            # Without a reliable state we can't safely pair-match; skip to
            # avoid cross-state false positives.
            continue
        if (county + ", " + st) in area_l:
            matching.append({
                "user_id": r["id"],
                "name": r.get("name") or "",
                "email": r["email"],
                "phone": r.get("phone") or "",
                "tier": r["subscription_tier"],
                "loc_label": r["loc_label"],
                "met_id": r.get("met_id"),
                "met_name": r.get("met_name") or "",
                "met_phone": r.get("met_phone") or "",
                "backup_met_id": r.get("backup_met_id"),
                "backup_met_name": r.get("backup_met_name") or "",
                "backup_met_phone": r.get("backup_met_phone") or "",
            })
    return matching


def _page_met_for_alert(alert: dict, affected: list, page_token: str,
                        *, met_phone: str = "", met_name: str = "") -> bool:
    """SMS a specific Met about a new severe alert affecting THEIR Pro
    subscribers. Returns True on successful send (or stub mode), False on
    Twilio failure or when no phone is available.

    `affected` is the subset of Pro subscribers assigned to this Met that
    fall inside the alert polygon. `met_phone` is the Met's own number; if
    it is empty we cannot page (we do NOT fall back to a global number, per
    the per-Met routing design).
    """
    target = (met_phone or "").strip()
    if not target:
        print(f"[nws-page] no phone for Met {met_name!r}; cannot page", flush=True)
        return False

    base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
    page_url = f"{base}/?nws-page={page_token}"

    body = (
        f"WV NWS PAGE: {alert['event']}\n"
        f"Area: {(alert.get('area_desc') or '')[:80]}\n"
        f"Your affected Pro subs: {len(affected)}\n"
        f"Review: {page_url}\n"
        f"Reply STOP to opt out."
    )
    try:
        return send_sms(target, body)
    except Exception as e:
        print(f"[nws-page] SMS failed for Met {met_name!r}: {e}", flush=True)
        return False


def _notify_crew_in_severe_alert(alert: dict) -> None:
    """Notify opted-in Crew whose home base falls inside a severe alert
    polygon.

    Safe to call every scheduler tick: each (alert, Crew member) pair is
    notified at most once, enforced by crew_severe_alert_notifications.

    Deliberately independent of the Met-paging path below. Crew are
    notified whether or not a Pro subscriber is in the polygon, and
    whether or not the Met was already paged for this alert. The per-member
    severe-alert preference is enforced inside _notify_crew_member (it
    defaults to ON), so we pull every located Crew member here.
    """
    geom = alert.get("geometry")
    nws_id = alert.get("nws_id")
    if not geom or not nws_id:
        return
    geom_str = json.dumps(geom)
    event = alert.get("event") or "Severe weather alert"

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.id, u.crew_home_lat AS lat, u.crew_home_lng AS lng
                       FROM users u
                       WHERE u.is_active = TRUE
                         AND u.crew_home_lat IS NOT NULL
                         AND u.crew_home_lng IS NOT NULL
                         AND EXISTS (
                           SELECT 1 FROM user_roles ur
                            WHERE ur.user_id = u.id AND ur.role = 'crew'
                         )"""
                )
                rows = cur.fetchall()
    except Exception as e:
        print(f"[crew-severe] candidate lookup failed: {e}", flush=True)
        return

    now_ms = int(time.time() * 1000)
    for r in rows:
        if r["lat"] is None or r["lng"] is None:
            continue
        try:
            inside = _point_in_polygon_geojson(
                float(r["lat"]), float(r["lng"]), geom_str
            )
        except Exception:
            inside = False
        if not inside:
            continue

        # Dedupe per (alert, Crew member). ON CONFLICT DO NOTHING means a
        # repeat tick inserts nothing, so rowcount is 0 and we skip.
        notified_now = False
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO crew_severe_alert_notifications
                           (nws_alert_id, crew_user_id, notified_at, alert_expires_at,
                            event, instruction)
                           VALUES (%s, %s, %s, %s, %s, %s)
                           ON CONFLICT (nws_alert_id, crew_user_id) DO NOTHING""",
                        (nws_id, r["id"], now_ms, alert.get("expires_at"),
                         alert.get("event") or "", alert.get("instruction") or ""),
                    )
                    notified_now = (cur.rowcount == 1)
        except Exception as e:
            print(f"[crew-severe] dedupe insert failed: {e}", flush=True)
            continue
        if not notified_now:
            continue

        subject = f"{event} in your area"
        body = (
            f"The National Weather Service has issued a {event} for your area. "
            f"Please take it seriously, get to a safe place, and follow "
            f"official guidance."
        )
        try:
            _notify_crew_member(r["id"], "notify_on_severe_alert", subject, body)
        except Exception as e:
            print(f"[crew-severe] notify failed for user {r['id']}: {e}", flush=True)


# ─── Crew daily check-in nudge (#C9) ────────────────────────────────
# Opt-in morning message that rotates through a pool so a member does not
# see the same words every day, and skips anyone who already checked in.
# Sent from the toll-free number, so a reply lands in the inbound webhook
# (rosie_sms_inbound) and checks them in.
_CREW_DAILY_NUDGE_MESSAGES = [
    "Good morning! What does it look like outside right now? Reply clear, cloudy, rain, or storm, or send a photo of your sky.",
    "Check-in time! A quick word (clear, cloudy, rain, storm) or a photo puts you on the Crew map today.",
    "Our Meteorologists need your eyes. What does it look like at your location? Photos welcome!",
    "Take a look outside. Is it clear, cloudy, raining, or storming? Snap a photo if the sky is doing something interesting.",
    "Daily update: what does it look like outside at your location? A photo says it best.",
    "Weather check! What are conditions like right now? Reply with a word or a picture.",
    "Help us monitor conditions in your area. What does the weather look like outside?",
    "Take a quick glance outside and let us know what you see: clear, cloudy, rain, or storm.",
    "We'd love an update from your location. What are current conditions outside? Photos land straight on the Crew map.",
    "Ground truth matters. What does the sky look like where you are right now?",
    "Can you help us out with a quick observation? Reply clear, cloudy, rain, or storm, or just send a photo.",
    "What's happening outside your window? A word or a photo checks you in for today.",
    "Conditions can change quickly. What does the weather look like at your location right now?",
    "Weather observation request: is it clear, cloudy, raining, or storming where you are?",
    "Today's check-in: what are you seeing outside? Bonus points for a great sky photo.",
    "Help improve our weather picture. What does it look like outside right now?",
    "Quick check: are conditions clear, cloudy, rainy, or stormy in your area?",
    "Your observation helps everyone in your region. What are conditions like outside?",
    "What does the sky have in store today? Reply clear, cloudy, rain, or storm, or show us with a photo.",
    "We're checking conditions across the region. What does it look like where you are?",
    "Step outside or look out a window. What are you seeing right now? Photos welcome.",
    "A quick update from you goes a long way. What's the weather doing at your location?",
    "Current conditions check: clear, cloudy, rain, or storm? A photo works too.",
    "Take 5 seconds to help us out. What does the weather look like where you are?",
    "Valet Crew, we need your eyes on the sky. What's it looking like at your location? Send a photo if it's a good one.",
    "Crew check-in: what are current conditions where you are?",
    "Help us build a real-time weather picture. A word or a photo does it.",
    "Your local observation helps everyone. What conditions are you seeing at your location?",
    "Be our weather spotter for the day. Is it clear, cloudy, raining, or storming where you are?",
]

_CREW_CONDITION_WORDS = {
    "clear": "clear", "sunny": "clear", "sun": "clear",
    "cloud": "cloudy", "cloudy": "cloudy", "clouds": "cloudy", "overcast": "cloudy",
    "rain": "rain", "raining": "rain", "rainy": "rain", "wet": "rain", "drizzle": "rain",
    "storm": "storm", "storming": "storm", "stormy": "storm", "thunder": "storm",
    "snow": "snow", "snowing": "snow", "snowy": "snow",
    "fog": "fog", "foggy": "fog",
    "wind": "wind", "windy": "wind",
    "hail": "hail",
}


def _parse_crew_condition(body):
    """Map the first recognizable word of an inbound reply to a condition,
    or None if nothing matches. Forgiving: scans the whole message, not
    just the first word, so 'it is raining' still resolves to rain."""
    for raw in (body or "").lower().replace(",", " ").split():
        w = raw.strip(".!?;:'\"")
        if w in _CREW_CONDITION_WORDS:
            return _CREW_CONDITION_WORDS[w]
    return None


# Maps a parsed condition to a crew_reports.report_type so a texted-in
# reply can be placed on the Crew map. 'clear'/'cloudy' have no dedicated
# map type, so they land as 'other' (still a valid ground-truth pin).
_CREW_CONDITION_TO_REPORT = {
    "clear": "other", "cloudy": "other", "rain": "rain",
    "storm": "storm", "snow": "snow", "fog": "fog",
    "wind": "wind", "hail": "hail",
}


# Optional precise timezone lookup. If the `timezonefinder` package is
# installed, we resolve a member's IANA timezone from their exact home
# coordinates, which handles zone boundaries and split states (Indiana,
# Tennessee, and so on) correctly. If it is not installed, everything still
# works through the longitude-band fallback below, so the app never depends
# on the package being present. To enable the precise path in production,
# add `timezonefinder` to requirements.
try:
    from timezonefinder import TimezoneFinder as _TimezoneFinder
    _TF = _TimezoneFinder()
except Exception:
    _TF = None


def _approx_us_tz_from_lng(lng):
    """Rough US timezone from longitude, used only as a fallback when a
    Crew member has no explicit timezone on file. Approximate band edges;
    the point is simply to keep the morning nudge in the morning and never
    send a pre-dawn text (a West Coast member must not be pinged at 5 AM)."""
    try:
        x = float(lng)
    except (TypeError, ValueError):
        return "America/Indiana/Indianapolis"
    if x >= -87.5:
        return "America/New_York"
    if x >= -101.0:
        return "America/Chicago"
    if x >= -114.5:
        return "America/Denver"
    return "America/Los_Angeles"


def _tz_from_latlng(lat, lng):
    """Best available IANA timezone for a coordinate. Uses timezonefinder
    when it is installed (precise polygons), otherwise the longitude band.
    Always returns a valid IANA name, never None or empty."""
    if _TF is not None:
        try:
            name = _TF.timezone_at(lat=float(lat), lng=float(lng))
            if name:
                return name
        except Exception:
            pass
    return _approx_us_tz_from_lng(lng)


def _crew_daily_checkin_nudge() -> None:
    """Each tick, text opted-in Crew for whom it is now the 8 AM hour in
    THEIR local timezone and who have not checked in yet.

    Per-member local time is the whole point here: an 8 AM Eastern blast
    would hit a West Coast member at 5 AM. We use the member's stored
    timezone when present, otherwise derive one from their home longitude.
    Strictly opt-in (notify_on_daily_checkin). Deduped once per day via
    crew_daily_nudges, and the message rotates by day and member id so the
    same person does not see the same words two mornings running.
    """
    today_key = _local_date_key()
    now_ms = int(time.time() * 1000)
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.id, u.phone, u.timezone, u.crew_home_lat, u.crew_home_lng
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'crew'
                       JOIN crew_notification_prefs p ON p.user_id = u.id
                            AND p.notify_on_daily_checkin = TRUE
                       WHERE u.is_active = TRUE
                         AND u.phone IS NOT NULL AND u.phone != ''
                         AND NOT EXISTS (
                           SELECT 1 FROM crew_checkins c
                            WHERE c.user_id = u.id AND c.date_key = %s
                         )
                         AND NOT EXISTS (
                           SELECT 1 FROM crew_daily_nudges n
                            WHERE n.user_id = u.id AND n.date_key = %s
                         )
                       LIMIT 2000""",
                    (today_key, today_key),
                )
                rows = cur.fetchall()
    except Exception as e:
        print(f"[crew-nudge] lookup failed: {e!r}", flush=True)
        return

    if not rows:
        return
    pool = _CREW_DAILY_NUDGE_MESSAGES
    if not pool:
        return
    day_number = now_ms // (24 * 60 * 60 * 1000)
    for r in rows:
        # Only send during the 8 AM hour in this member's own timezone.
        # A Crew member's home coordinates are the truth of where they wake
        # up, so we resolve from those first. The stored `timezone` column
        # carries a default for everyone, so trusting it blindly would treat
        # a West Coast member as Eastern and ping them pre-dawn. Coordinates
        # avoid that; the stored value and the longitude band are fallbacks.
        lat = r.get("crew_home_lat")
        lng = r.get("crew_home_lng")
        if lat is not None and lng is not None:
            tz = _tz_from_latlng(lat, lng)
        else:
            tz = (r.get("timezone") or "").strip() or _approx_us_tz_from_lng(lng)
        local_now = _local_now_for_user(tz)
        if local_now.hour != 8:
            continue

        # Claim the per-day slot first so a re-run cannot double-send.
        claimed = False
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO crew_daily_nudges (user_id, date_key, sent_at)
                           VALUES (%s, %s, %s)
                           ON CONFLICT (user_id, date_key) DO NOTHING""",
                        (r["id"], today_key, now_ms),
                    )
                    claimed = (cur.rowcount == 1)
        except Exception as e:
            print(f"[crew-nudge] claim failed: {e!r}", flush=True)
            continue
        if not claimed:
            continue
        msg = pool[(day_number + r["id"]) % len(pool)]
        try:
            if TWILIO_CREW_NUMBER:
                send_sms_from(r["phone"], msg, TWILIO_CREW_NUMBER)
            else:
                send_sms(r["phone"], msg)
        except Exception as e:
            print(f"[crew-nudge] send failed for user {r['id']}: {e!r}", flush=True)


def _send_crew_all_clears() -> None:
    """Relief half of severe weather (#C14): when an alert we notified Crew
    about has passed its effective time, tell those same members the storm
    has cleared.

    Runs every tick, independent of whether anything is currently active
    (an alert clearing is exactly when nothing is active). Each notification
    row gets at most one all-clear, claimed atomically via all_clear_sent_at
    so concurrent ticks cannot double-send.
    """
    now_ms = int(time.time() * 1000)
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT nws_alert_id, crew_user_id
                       FROM crew_severe_alert_notifications
                       WHERE all_clear_sent_at IS NULL
                         AND alert_expires_at IS NOT NULL
                         AND alert_expires_at <= %s
                       LIMIT 500""",
                    (now_ms,),
                )
                rows = cur.fetchall()
    except Exception as e:
        print(f"[crew-allclear] lookup failed: {e!r}", flush=True)
        return

    for r in (rows or []):
        # Claim the row first so a concurrent worker won't also send.
        claimed = False
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """UPDATE crew_severe_alert_notifications
                           SET all_clear_sent_at = %s
                           WHERE nws_alert_id = %s AND crew_user_id = %s
                             AND all_clear_sent_at IS NULL""",
                        (now_ms, r["nws_alert_id"], r["crew_user_id"]),
                    )
                    claimed = (cur.rowcount == 1)
        except Exception as e:
            print(f"[crew-allclear] claim failed: {e!r}", flush=True)
            continue
        if not claimed:
            continue
        try:
            _notify_crew_member(
                r["crew_user_id"],
                "notify_on_severe_alert",
                "All clear in your area",
                "The severe weather alert for your area has passed. The "
                "National Weather Service is no longer showing it active. "
                "Take care as conditions settle.",
            )
        except Exception as e:
            print(f"[crew-allclear] notify failed for user {r['crew_user_id']}: {e!r}", flush=True)


# ──────────────────────────────────────────────────────────────────────
# Per-client threshold alerts (June 2026)
#
# Subscribers (via account settings or the onboarding profile) define
# thresholds like "wind gusts above 35 mph" or "heat index above 100F".
# This engine checks each enabled threshold against the subscriber's
# primary location on BOTH the current conditions (it's happening) and the
# next 12 hours of forecast (heads-up), and pages the subscriber's lead Met
# so the Met can send a personalized message. It does NOT text the
# subscriber directly.
#
# Safety, built deliberately conservative after the June duplicate-alert
# incident: advisory lock (key 91234575) so it never runs in two workers at
# once; a quiet window per threshold so a Met is paged once per event and
# not every minute; pages the Met only (bounded blast radius); a kill
# switch via the THRESHOLD_ALERTS_ENABLED env var (set to 0 to silence).
# ──────────────────────────────────────────────────────────────────────

_THRESHOLD_CURRENT_FIELDS = [
    "temperature_2m", "apparent_temperature", "relative_humidity_2m",
    "wind_speed_10m", "wind_gusts_10m",
    "precipitation", "snowfall",
]
# Hourly adds precipitation_probability, which is a forecast-only variable
# (there is no "current" probability), so it only ever trips on the forecast.
_THRESHOLD_HOURLY_FIELDS = _THRESHOLD_CURRENT_FIELDS + ["precipitation_probability"]


def _threshold_metric_fields(metric):
    """Map a subscriber's metric label to Open-Meteo field name(s).
    Returns the field(s) to check (trip if ANY crosses), or [] if the
    metric isn't one we can read from the forecast yet (e.g. lightning,
    which needs a separate feed)."""
    m = (metric or "").strip().lower().replace(" ", "_")
    mapping = {
        "wind": ["wind_gusts_10m", "wind_speed_10m"],
        "wind_speed": ["wind_speed_10m"],
        "windspeed": ["wind_speed_10m"],
        "wind_gust": ["wind_gusts_10m"],
        "wind_gusts": ["wind_gusts_10m"],
        "gust": ["wind_gusts_10m"],
        "gusts": ["wind_gusts_10m"],
        "temperature": ["temperature_2m"],
        "temp": ["temperature_2m"],
        "temp_high": ["temperature_2m"],
        "temp_low": ["temperature_2m"],
        "high_temp": ["temperature_2m"],
        "low_temp": ["temperature_2m"],
        "cold": ["temperature_2m"],
        "heat": ["apparent_temperature"],
        "heat_index": ["apparent_temperature"],
        "feels_like": ["apparent_temperature"],
        "wind_chill": ["apparent_temperature"],
        "humidity": ["relative_humidity_2m"],
        "precip_chance": ["precipitation_probability"],
        "precipitation": ["precipitation"],
        "precip": ["precipitation"],
        "rain": ["precipitation"],
        "rain_amount": ["precipitation"],
        "rainfall": ["precipitation"],
        "snow": ["snowfall"],
        "snow_amount": ["snowfall"],
        "snowfall": ["snowfall"],
    }
    return mapping.get(m, [])


def _threshold_metric_label(metric):
    m = (metric or "").strip().lower().replace(" ", "_")
    labels = {
        "wind": "Wind gusts", "wind_gust": "Wind gusts", "wind_gusts": "Wind gusts",
        "gust": "Wind gusts", "gusts": "Wind gusts",
        "wind_speed": "Wind", "windspeed": "Wind",
        "temperature": "Temperature", "temp": "Temperature",
        "temp_high": "Temperature", "temp_low": "Temperature",
        "high_temp": "Temperature", "low_temp": "Temperature", "cold": "Temperature",
        "heat": "Heat index", "heat_index": "Heat index", "feels_like": "Heat index",
        "wind_chill": "Wind chill",
        "humidity": "Humidity",
        "precip_chance": "Rain chance",
        "precipitation": "Rain", "precip": "Rain", "rain": "Rain",
        "rain_amount": "Rainfall", "rainfall": "Rainfall",
        "snow": "Snow", "snow_amount": "Snowfall", "snowfall": "Snowfall",
    }
    return labels.get(m, (metric or "Conditions").strip().title())


def _threshold_cmp(value, comparator, threshold):
    c = (comparator or "").strip().lower()
    if c in (">", "gt", "above", "over", "greater"):
        return value > threshold
    if c in (">=", "gte", "at_least"):
        return value >= threshold
    if c in ("<", "lt", "below", "under", "less"):
        return value < threshold
    if c in ("<=", "lte", "at_most"):
        return value <= threshold
    if c in ("==", "=", "eq", "equals"):
        return abs(value - threshold) < 1e-9
    return value >= threshold


def _threshold_cmp_label(comparator):
    c = (comparator or "").strip().lower()
    if c in (">", "gt", "above", "over", "greater"):
        return "above"
    if c in (">=", "gte", "at_least"):
        return "at or above"
    if c in ("<", "lt", "below", "under", "less"):
        return "below"
    if c in ("<=", "lte", "at_most"):
        return "at or below"
    return "at"


def _fetch_threshold_forecast(lat, lng):
    """Open-Meteo current + next-12h hourly for the threshold metrics, in
    imperial units (mph, F, inch). UTC unixtime."""
    try:
        cur_fields = ",".join(_THRESHOLD_CURRENT_FIELDS)
        hr_fields = ",".join(_THRESHOLD_HOURLY_FIELDS)
        url = (
            "https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat}&longitude={lng}"
            f"&current={cur_fields}&hourly={hr_fields}"
            "&wind_speed_unit=mph&temperature_unit=fahrenheit"
            "&precipitation_unit=inch&timeformat=unixtime&timezone=GMT"
            "&forecast_hours=12"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "weathervalet/1.0"})
        with urllib.request.urlopen(req, timeout=6) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        print(f"[threshold-alert] forecast fetch failed ({lat},{lng}): {e}", flush=True)
        return None


def _evaluate_threshold(metric, comparator, threshold_value, fc):
    """Return {"kind","value","at_ms"} if the threshold is met now (observed)
    or within the next 12h (forecast), else None. Observed wins over
    forecast so a Met is told it's happening, not just expected."""
    fields = _threshold_metric_fields(metric)
    if not fields or fc is None:
        return None
    try:
        tv = float(threshold_value)
    except (TypeError, ValueError):
        return None
    now_s = int(time.time())

    # Observed: the current block.
    cur = fc.get("current") or {}
    for f in fields:
        v = cur.get(f)
        if v is not None and _threshold_cmp(v, comparator, tv):
            return {"kind": "observed", "value": v, "at_ms": now_s * 1000}

    # Forecast: any hour in the next 12h.
    hourly = fc.get("hourly") or {}
    times = hourly.get("time") or []
    horizon_s = now_s + 12 * 3600
    for i, ts in enumerate(times):
        if ts <= now_s or ts > horizon_s:
            continue
        for f in fields:
            series = hourly.get(f) or []
            v = series[i] if i < len(series) else None
            if v is not None and _threshold_cmp(v, comparator, tv):
                return {"kind": "forecast", "value": v, "at_ms": ts * 1000}
    return None


def _ensure_threshold_alert_state_table():
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """CREATE TABLE IF NOT EXISTS threshold_alert_state (
                           threshold_id   INTEGER PRIMARY KEY
                                          REFERENCES threshold_alerts(id) ON DELETE CASCADE,
                           last_paged_ms  BIGINT NOT NULL,
                           last_kind      TEXT,
                           last_value     DOUBLE PRECISION
                       )"""
                )
    except Exception as e:
        print(f"[threshold-alert] state table ensure failed: {e}", flush=True)


def _threshold_alert_message(sub_name, place, metric, comparator, value, units, hit):
    label = _threshold_metric_label(metric)
    cmp_l = _threshold_cmp_label(comparator)
    u = (units or "").strip()
    try:
        val_txt = f"{float(value):g}"
    except (TypeError, ValueError):
        val_txt = str(value)
    _unit_disp = {"mph": " mph", "F": "\u00b0F", "C": "\u00b0C", "pct": "%", "in": " in"}
    val_txt = val_txt + _unit_disp.get(u, ((" " + u) if u else ""))
    if hit["kind"] == "observed":
        timing = "right now"
    else:
        try:
            tz = ZoneInfo("America/Indiana/Indianapolis")
            when = datetime.fromtimestamp(hit["at_ms"] / 1000, tz).strftime("%I:%M %p").lstrip("0")
            timing = f"expected around {when}"
        except Exception:
            timing = "expected soon"
    first = (sub_name or "this subscriber").split()[0] if sub_name else "them"
    return (f"WeatherValet threshold alert: {sub_name or 'a subscriber'} at "
            f"{place or 'their location'}. {label} {cmp_l} {val_txt} {timing}. "
            f"Send {first} a personalized update.")


def _process_threshold_alerts():
    """Scheduler job: page Mets when a subscriber's threshold is met.
    Advisory-locked (key 91234575) and gated by THRESHOLD_ALERTS_ENABLED."""
    if (os.environ.get("THRESHOLD_ALERTS_ENABLED", "1") or "1").strip() != "1":
        return
    _LOCK_KEY = 91234575
    _lock_conn = _try_acquire_scheduler_lock(_LOCK_KEY)
    if _lock_conn is None:
        return  # Another worker is handling thresholds this tick
    try:
        _process_threshold_alerts_inner()
    finally:
        _release_scheduler_lock(_lock_conn, _LOCK_KEY)


def _process_threshold_alerts_inner():
    _ensure_threshold_alert_state_table()
    now_ms = int(time.time() * 1000)
    quiet_ms = 3 * 60 * 60 * 1000  # once per event, then quiet ~3 hours

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT ta.id AS threshold_id, ta.user_id, ta.metric,
                          ta.comparator, ta.threshold_value, ta.units,
                          u.name AS sub_name,
                          sc.primary_met_id,
                          mu.name AS met_name, mu.phone AS met_phone,
                          loc.lat AS lat, loc.lng AS lng,
                          loc.address_text AS place,
                          st.last_paged_ms AS last_paged_ms
                   FROM threshold_alerts ta
                   JOIN users u ON u.id = ta.user_id
                   LEFT JOIN subscriber_coverage sc ON sc.user_id = ta.user_id
                   LEFT JOIN users mu ON mu.id = sc.primary_met_id
                   LEFT JOIN saved_locations loc
                          ON loc.user_id = ta.user_id AND loc.is_primary = TRUE
                   LEFT JOIN threshold_alert_state st ON st.threshold_id = ta.id
                   WHERE ta.enabled = TRUE AND u.is_active = TRUE"""
            )
            rows = cur.fetchall()

    if not rows:
        return

    # Group by location so each forecast is fetched once per tick.
    by_loc = {}
    for r in rows:
        if r["lat"] is None or r["lng"] is None:
            continue
        key = (round(float(r["lat"]), 3), round(float(r["lng"]), 3))
        by_loc.setdefault(key, []).append(r)

    for (lat, lng), group in by_loc.items():
        fc = _fetch_threshold_forecast(lat, lng)
        if fc is None:
            continue
        for r in group:
            try:
                # Quiet window: if we paged this threshold within the last
                # few hours, stay silent (one page per event).
                lp = r.get("last_paged_ms") or 0
                if now_ms - lp < quiet_ms:
                    continue
                hit = _evaluate_threshold(
                    r["metric"], r["comparator"], r["threshold_value"], fc
                )
                if not hit:
                    continue
                met_phone = (r.get("met_phone") or "").strip()
                if not met_phone:
                    print(f"[threshold-alert] threshold {r['threshold_id']} tripped "
                          f"for user {r['user_id']} but no lead Met phone; skipped",
                          flush=True)
                    continue
                msg = _threshold_alert_message(
                    r.get("sub_name"), r.get("place"), r["metric"],
                    r["comparator"], r["threshold_value"], r.get("units"), hit,
                )
                if send_sms(met_phone, msg):
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """INSERT INTO threshold_alert_state
                                       (threshold_id, last_paged_ms, last_kind, last_value)
                                   VALUES (%s, %s, %s, %s)
                                   ON CONFLICT (threshold_id) DO UPDATE
                                       SET last_paged_ms = EXCLUDED.last_paged_ms,
                                           last_kind = EXCLUDED.last_kind,
                                           last_value = EXCLUDED.last_value""",
                                (r["threshold_id"], now_ms, hit["kind"], float(hit["value"])),
                            )
                    print(f"[threshold-alert] paged Met {met_phone} for threshold "
                          f"{r['threshold_id']} ({hit['kind']})", flush=True)
            except Exception as e:
                print(f"[threshold-alert] threshold {r.get('threshold_id')} failed: {e}",
                      flush=True)


# ──────────────────────────────────────────────────────────────────────
# Outreach (Jun 30, 2026)
# A Met can email their own Pro subscribers; an admin can email all Pro
# subscribers. Each goes out as an individual, personalized email with the
# reply-to set to whoever sent it, so replies land in the sender's inbox.
# Reuses the Resend email path.
# ──────────────────────────────────────────────────────────────────────

def _ensure_outreach_table():
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """CREATE TABLE IF NOT EXISTS outreach_sends (
                           id                SERIAL PRIMARY KEY,
                           batch_id          TEXT NOT NULL,
                           sender_user_id    INTEGER NOT NULL,
                           sender_email      TEXT,
                           subject           TEXT,
                           recipient_user_id INTEGER,
                           recipient_email   TEXT,
                           status            TEXT NOT NULL,
                           created_at        BIGINT NOT NULL
                       )"""
                )
    except Exception as e:
        print(f"[outreach] table ensure failed: {e}", flush=True)


def _send_outreach_email(to_email, subject, text_body, reply_to, from_name):
    """Individual outreach email via Resend. The From display name is the
    sender (so the subscriber sees their Met by name) over the verified
    hello@ address; reply_to routes replies straight back to the sender."""
    api_key = os.environ.get("RESEND_API_KEY", "").strip()
    base_from = os.environ.get("EMAIL_FROM", "").strip() or "WeatherValet <hello@weathervalet.ai>"
    m = re.search(r"<([^>]+)>", base_from)
    addr = m.group(1) if m else base_from
    from_field = (from_name + " <" + addr + ">") if from_name else base_from
    if not api_key:
        print(f"[outreach-stub] To {to_email} from {from_field} reply-to {reply_to}: {subject}", flush=True)
        return True
    try:
        html_body = _email_shell("<p>" + text_body.replace("\n", "<br>") + "</p>")
    except Exception:
        html_body = "<p>" + text_body + "</p>"
    payload = {"from": from_field, "to": [to_email], "subject": subject,
               "html": html_body, "text": text_body}
    if reply_to:
        payload["reply_to"] = reply_to
    req = urllib.request.Request(
        "https://api.resend.com/emails",
        data=json.dumps(payload).encode("utf-8"), method="POST",
        headers={"Authorization": "Bearer " + api_key,
                 "Content-Type": "application/json",
                 "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)"})
    try:
        with urllib.request.urlopen(req, timeout=12) as resp:
            return 200 <= resp.status < 300
    except Exception as e:
        print(f"[outreach] send failed to {to_email}: {e}", flush=True)
        return False


def _outreach_recipients_for(user):
    """Pro subscribers this user may email: a Met's own, or all (admin)."""
    roles = user.get("roles") or []
    is_admin = "admin" in roles
    rows = []
    try:
        with db() as conn:
            with conn.cursor() as cur:
                if is_admin:
                    cur.execute(
                        """SELECT u.id, u.name, u.email
                           FROM users u
                           WHERE u.subscription_tier LIKE %s
                             AND u.is_active = TRUE
                             AND COALESCE(u.email,'') <> ''
                           ORDER BY u.name""", ("pro%",))
                else:
                    cur.execute(
                        """SELECT u.id, u.name, u.email
                           FROM users u
                           JOIN subscriber_coverage sc ON sc.user_id = u.id
                           WHERE sc.primary_met_id = %s
                             AND u.subscription_tier LIKE %s
                             AND u.is_active = TRUE
                             AND COALESCE(u.email,'') <> ''
                           ORDER BY u.name""", (user["id"], "pro%"))
                rows = cur.fetchall()
    except Exception as e:
        print(f"[outreach] recipient lookup failed: {e}", flush=True)
    out = []
    for r in rows:
        nm = (r.get("name") or "").strip()
        first = nm.split()[0] if nm else "there"
        out.append({"user_id": r["id"], "name": nm or r.get("email"),
                    "email": r.get("email"), "first_name": first})
    return out


@app.route("/api/v1/outreach/recipients", methods=["OPTIONS"])
def outreach_recipients_preflight():
    return ("", 204)


@app.get("/api/v1/outreach/recipients")
def outreach_recipients():
    user = _get_current_user()
    if not user:
        return jsonify({"ok": False, "error": "auth"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    return jsonify({"ok": True, "recipients": _outreach_recipients_for(user),
                    "is_admin": "admin" in roles})


@app.route("/api/v1/outreach/send", methods=["OPTIONS"])
def outreach_send_preflight():
    return ("", 204)


@app.post("/api/v1/outreach/send")
def outreach_send():
    user = _get_current_user()
    if not user:
        return jsonify({"ok": False, "error": "auth"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    data = request.get_json(silent=True) or {}
    subject = (data.get("subject") or "").strip()
    body = (data.get("body") or "").strip()
    ids = data.get("recipient_ids") or []
    if not subject or not body:
        return jsonify({"ok": False, "message": "Subject and message are both required."}), 400
    try:
        ids = set(int(i) for i in ids)
    except Exception:
        return jsonify({"ok": False, "message": "Bad recipient list."}), 400
    if not ids:
        return jsonify({"ok": False, "message": "Pick at least one recipient."}), 400
    # Only allow recipients within the sender's own permitted set.
    allowed = {r["user_id"]: r for r in _outreach_recipients_for(user)}
    targets = [allowed[i] for i in ids if i in allowed]
    if not targets:
        return jsonify({"ok": False, "message": "None of those recipients are available to you."}), 400
    _ensure_outreach_table()
    sender_email = (user.get("email") or "").strip()
    sender_name = (user.get("name") or "Your Meteorologist").strip()
    batch_id = new_secure_token()
    now_ms = int(time.time() * 1000)
    sent = failed = 0
    for t in targets:
        personalized = body.replace("{name}", t["first_name"]).replace("{first}", t["first_name"])
        ok = _send_outreach_email(t["email"], subject, personalized,
                                  reply_to=(sender_email or None), from_name=sender_name)
        status = "sent" if ok else "failed"
        if ok:
            sent += 1
        else:
            failed += 1
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO outreach_sends
                               (batch_id, sender_user_id, sender_email, subject,
                                recipient_user_id, recipient_email, status, created_at)
                           VALUES (%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (batch_id, user["id"], sender_email, subject,
                         t["user_id"], t["email"], status, now_ms))
        except Exception as e:
            print(f"[outreach] log failed: {e}", flush=True)
    return jsonify({"ok": True, "sent": sent, "failed": failed, "reply_to": sender_email})


def _severe_fallback_pages() -> list:
    """On-call fallback for affected subscribers who have no reachable primary
    OR backup Met. Returns (phone, name) for every active Met with a phone, so
    a no-Met subscriber's tornado page still reaches a human who can confirm it.
    Falls back to METEOROLOGIST_PHONE if the roster somehow has no phones.
    """
    out = []
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT DISTINCT u.name, u.phone
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'met'
                       WHERE u.is_active = TRUE AND COALESCE(u.phone, '') <> ''"""
                )
                for r in cur.fetchall():
                    ph = (r.get("phone") or "").strip()
                    if ph:
                        out.append((ph, r.get("name") or "On-call Meteorologist"))
    except Exception as e:
        print(f"[nws-process] fallback roster lookup failed: {e}", flush=True)
    if not out and METEOROLOGIST_PHONE:
        out.append((METEOROLOGIST_PHONE, "On-call Meteorologist"))
    return out


def _process_severe_alerts() -> None:
    """One scheduler tick: fetch alerts, match against subscribers, page Met."""
    # Relief half (#C14): send all-clears for alerts that have passed their
    # effective time. Runs first, so it fires even when nothing is active.
    try:
        _send_crew_all_clears()
    except Exception as e:
        print(f"[nws-process] all-clear pass failed: {e}", flush=True)

    alerts = _fetch_active_nws_alerts()
    if not alerts:
        return

    for alert in alerts:
        nws_id = alert["nws_id"]

        # Notify opted-in Crew in this alert's area. Runs independently of
        # the Met-paging logic below (which dedupes and may skip), so Crew
        # coverage does not depend on a Pro subscriber being in the polygon.
        try:
            _notify_crew_in_severe_alert(alert)
        except Exception as e:
            print(f"[nws-process] crew notify pass failed: {e}", flush=True)

        # Dedupe — have we already paged for this alert?
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT id FROM nws_alert_pages WHERE nws_alert_id = %s",
                        (nws_id,),
                    )
                    if cur.fetchone():
                        continue  # already paged
        except Exception as e:
            print(f"[nws-process] dedupe check failed: {e}", flush=True)
            continue

        # Find affected Pro subscribers, by polygon (warnings) or by county
        # (geometry-less alerts like watches).
        if alert.get("match_mode") == "county" or not alert.get("geometry"):
            affected = _find_pro_subscribers_by_county(alert)
        else:
            affected = _find_pro_subscribers_in_polygon(alert["geometry"])
        if not affected:
            # No Pro subscribers in this alert's area; don't page, don't
            # record. (We could record for analytics but it'd pile up
            # quickly — every NWS alert nationally would create a row.)
            continue

        # Route affected subscribers to the humans who can confirm the alert
        # (primary Met, backup Met, on-call fallback). See routing below.
        # Route affected subscribers to page targets so a human reliably gets
        # paged for EVERY affected subscriber (June 2026 reliability fix):
        #   - primary Met (as before)
        #   - backup Met too, so one unresponsive Met can't leave subs uncovered
        #   - on-call fallback for subs with no reachable Met, instead of
        #     silently skipping them
        # Keyed by phone, so a Met covering many affected subs is paged once.
        targets = {}          # phone -> {"name": str, "subs": [], "_ids": set()}

        def _route(phone, name, sub):
            phone = (phone or "").strip()
            if not phone:
                return False
            t = targets.get(phone)
            if t is None:
                t = {"name": name or "", "subs": [], "_ids": set()}
                targets[phone] = t
            if sub["user_id"] not in t["_ids"]:
                t["_ids"].add(sub["user_id"])
                t["subs"].append(sub)
            return True

        uncovered = []
        for sub in affected:
            covered = False
            if sub.get("met_id") and _route(sub.get("met_phone"), sub.get("met_name"), sub):
                covered = True
            if sub.get("backup_met_id") and _route(sub.get("backup_met_phone"), sub.get("backup_met_name"), sub):
                covered = True
            if not covered:
                uncovered.append(sub)

        # Fallback: subscribers with no reachable primary/backup Met go to the
        # on-call roster so they are still covered by a human who can confirm.
        fallback_subs = len(uncovered)
        if uncovered:
            for ph, nm in _severe_fallback_pages():
                for sub in uncovered:
                    _route(ph, nm, sub)

        if not targets:
            # No reachable human anywhere (no Met phones and no fallback).
            print(
                f"[nws-process] alert={alert['event']!r} hit {len(affected)} "
                f"Pro sub(s) but no reachable Met or fallback phone; skipped",
                flush=True,
            )
            continue

        # Insert ONE page row for the alert (dedupe key is the alert id), then
        # page each affected Met. We record the full affected set and the list
        # of Met phones we paged.
        page_token = new_secure_token()
        now_ms = int(time.time() * 1000)
        affected_ids_csv = ",".join(str(a["user_id"]) for a in affected)
        paged_phones_csv = ",".join(targets.keys())

        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO nws_alert_pages
                           (created_at, nws_alert_id, event, severity, headline,
                            description, instruction, area_desc, polygon_geojson,
                            expires_at, response_token, status, affected_user_ids,
                            met_paged_phone)
                           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                                   'paged', %s, %s)
                           RETURNING id""",
                        (now_ms, nws_id, alert["event"], alert["severity"],
                         alert["headline"], alert["description"],
                         alert["instruction"], alert["area_desc"],
                         json.dumps(alert["geometry"]),
                         alert["expires_at"], page_token,
                         affected_ids_csv, paged_phones_csv),
                    )
                    new_row = cur.fetchone()
        except Exception as e:
            # Unique constraint violation = race with another worker.
            # Anything else = unexpected; log loud.
            print(f"[nws-process] insert failed for {nws_id}: {e}", flush=True)
            continue

        # Page every routed target: primary Mets, backup Mets, and any
        # on-call fallback. Each target gets only the subs they cover.
        paged_mets = 0
        for phone, t in targets.items():
            ok = _page_met_for_alert(alert, t["subs"], page_token,
                                     met_phone=phone, met_name=t["name"])
            if ok:
                paged_mets += 1

        print(
            f"[nws-process] alert={alert['event']!r} id={new_row['id']} "
            f"affected={len(affected)} pages_sent={paged_mets} "
            f"fallback_subs={fallback_subs}",
            flush=True,
        )


def _ensure_brief_scheduler_started() -> None:
    """Start the scheduler thread exactly once per process lifetime.

    Called from before_request so it kicks off after the app is serving
    requests (avoids race with init_db on cold boot). Idempotent + thread-safe.
    """
    global _BRIEF_SCHEDULER_STARTED
    if _BRIEF_SCHEDULER_STARTED:
        return
    with _BRIEF_SCHEDULER_LOCK:
        if _BRIEF_SCHEDULER_STARTED:
            return
        # Only start if not in test/debug short-circuit modes
        if os.environ.get("WV_DISABLE_SCHEDULER") == "1":
            print("[brief-scheduler] disabled via env var", flush=True)
            _BRIEF_SCHEDULER_STARTED = True
            return
        t = threading.Thread(target=_brief_scheduler_loop, daemon=True, name="brief-scheduler")
        t.start()
        _BRIEF_SCHEDULER_STARTED = True
        # Worker diagnostic (May 22, 2026): print one line per process when
        # the scheduler starts. If Render runs 2+ Gunicorn workers, you'll
        # see this line printed 2+ times (different PIDs). This is how we
        # confirm worker count without dashboard access. Look for
        # "[worker-startup]" in Render logs after deploy.
        try:
            import socket
            host = socket.gethostname()
        except Exception:
            host = "unknown"
        print(
            f"[worker-startup] pid={os.getpid()} host={host} "
            f"scheduler=started time={int(time.time())}",
            flush=True,
        )


# Admin / debug endpoint — manually trigger one tick. Useful for the
# launch-day smoke test ("does the scheduler actually do anything?").
# Requires admin role to prevent abuse (someone hammering this could
# DOS the Open-Meteo / Twilio / Resend rate limits).
@app.route("/api/v1/admin/brief/run-now", methods=["OPTIONS"])
def _brief_run_now_preflight():
    return ("", 204)


@app.post("/api/v1/admin/brief/run-now")
def admin_brief_run_now():
    """Manually fire one scheduler tick. Admin-only."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        _process_pending_briefs()
        return jsonify({"ok": True, "message": "tick fired, check Render logs for delivery results"})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


# Hook the scheduler start into Flask's request lifecycle. Flask 3.x
# removed before_first_request, so we use a flag + before_request.
@app.before_request
def _scheduler_kickstart():
    _ensure_brief_scheduler_started()


# ════════════════════════════════════════════════════════════════════
# Mission deployments (Item #4)
# ════════════════════════════════════════════════════════════════════
#
# CRUD for missions fired by Mets. The frontend's Mission tab calls
# these to persist deployments and read them back. Real Crew SMS
# (Item #5) and Crew location matching (Item #6) build on top.

# ─── Polygon match helpers (Item #6) ──────────────────────────────
# Standard ray-casting point-in-polygon. Pure Python, no dependencies.

def _point_in_ring(lat: float, lng: float, ring: list) -> bool:
    """Ray-casting point-in-polygon. ring is a list of [lng, lat] pairs.

    Returns True if the point is inside. Boundary cases are imprecise
    (the algorithm is good enough for "is this Crew member roughly in
    this county-sized polygon" — not for legal property boundaries).
    """
    inside = False
    n = len(ring)
    if n < 3:
        return False
    j = n - 1
    for i in range(n):
        xi, yi = ring[i][0], ring[i][1]  # lng, lat
        xj, yj = ring[j][0], ring[j][1]
        # Standard ray cast: does horizontal ray from (lng, lat) cross
        # edge from (xi, yi) to (xj, yj)?
        intersect = ((yi > lat) != (yj > lat)) and \
                    (lng < (xj - xi) * (lat - yi) / ((yj - yi) or 1e-12) + xi)
        if intersect:
            inside = not inside
        j = i
    return inside


def _point_in_polygon_geojson(lat: float, lng: float, geojson_str: str) -> bool:
    """Test whether (lat, lng) is inside the polygon encoded in geojson_str.

    Accepts:
      - A Feature with geometry.type 'Polygon' or 'MultiPolygon'
      - A bare geometry object
      - A FeatureCollection (uses the first polygon feature)

    Returns False on parse errors — safer to skip than crash a Crew
    dispatch loop.
    """
    if not geojson_str:
        return False
    try:
        obj = json.loads(geojson_str) if isinstance(geojson_str, str) else geojson_str
    except (ValueError, TypeError):
        return False
    if not isinstance(obj, dict):
        return False

    # Extract a geometry from whatever shape we got
    geometry = None
    if obj.get("type") == "FeatureCollection":
        features = obj.get("features") or []
        for f in features:
            g = (f or {}).get("geometry")
            if g and g.get("type") in ("Polygon", "MultiPolygon"):
                geometry = g
                break
    elif obj.get("type") == "Feature":
        geometry = obj.get("geometry")
    elif obj.get("type") in ("Polygon", "MultiPolygon"):
        geometry = obj
    if not geometry:
        return False

    gtype = geometry.get("type")
    coords = geometry.get("coordinates") or []

    if gtype == "Polygon":
        # coords[0] is the outer ring; coords[1:] are holes. We treat any
        # point in the outer ring as inside (ignoring holes — close enough
        # for Crew targeting, which doesn't deal with donut-shaped areas).
        if not coords:
            return False
        return _point_in_ring(lat, lng, coords[0])
    if gtype == "MultiPolygon":
        for poly in coords:
            if poly and _point_in_ring(lat, lng, poly[0]):
                return True
        return False
    return False


def _find_crew_for_mission(polygon_geojson: Optional[str]) -> list:
    """Return all active Crew members matching the mission's target area.

    If polygon_geojson is empty/None, returns ALL active Crew (mission
    targets "all Crew in coverage area"). If a polygon is provided,
    returns only Crew whose crew_home location is inside it.

    Each row includes id, name, phone, crew_home_lat/lng so the SMS
    dispatcher has everything it needs without further DB hits.
    """
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.email, u.phone,
                          u.crew_home_lat, u.crew_home_lng, u.crew_home_label
                   FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id
                   WHERE ur.role = 'crew'
                     AND u.is_active = TRUE
                     AND u.crew_active = TRUE
                     AND u.phone IS NOT NULL AND u.phone <> ''"""
            )
            all_crew = cur.fetchall()

    if not polygon_geojson:
        # No polygon = broadcast to all Crew
        return list(all_crew)

    matching = []
    for c in all_crew:
        if c["crew_home_lat"] is None or c["crew_home_lng"] is None:
            continue  # Crew member hasn't set location, can't target them
        if _point_in_polygon_geojson(c["crew_home_lat"], c["crew_home_lng"], polygon_geojson):
            matching.append(c)
    return matching


def _dispatch_mission_sms(mission_id: int, prompt: str, polygon_geojson: Optional[str],
                          template_name: str) -> tuple[int, int]:
    """Find matching Crew + send SMS to each. Returns (total_matched, sent_count).

    Creates a mission_notifications row per Crew member so we have an
    audit trail of who got pinged. Failures are logged but don't stop
    the dispatch loop — one bad number shouldn't block the rest.
    """
    crew_list = _find_crew_for_mission(polygon_geojson)
    if not crew_list:
        print(f"[mission-sms] no matching Crew for mission_id={mission_id}", flush=True)
        return (0, 0)

    base_url = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
    sent = 0
    now_ms = int(time.time() * 1000)

    for c in crew_list:
        # Generate a per-notification response token. Lets us identify
        # which Crew member responded without sticking their user_id in
        # a URL (privacy + idempotence).
        resp_token = new_secure_token()
        response_url = f"{base_url}/?mission={resp_token}"

        # Compose the SMS. The prompt cap matches the compose field's
        # 600-char limit so the full mission message the Met wrote goes
        # out (a 300 cap was silently cutting longer prompts). Messages
        # over 160 chars send as multiple SMS segments, which is fine;
        # the 600 ceiling keeps a runaway prompt from ballooning cost or
        # carrier-filtering risk.
        _PROMPT_SMS_CAP = 600
        sms_body = (
            f"WeatherValet mission ({template_name}):\n"
            f"{prompt[:_PROMPT_SMS_CAP]}{'…' if len(prompt) > _PROMPT_SMS_CAP else ''}\n\n"
            f"Respond: {response_url}\n"
            f"Reply STOP to opt out."
        )

        delivery_status = "stubbed"
        twilio_sid = None
        try:
            ok = send_sms(c["phone"], sms_body)
            delivery_status = "sent" if ok else "failed"
        except Exception as e:
            print(f"[mission-sms] send failed crew_id={c['id']}: {e}", flush=True)
            delivery_status = "failed"

        # Record the notification regardless of send outcome — we want
        # the audit trail even for failures.
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO mission_notifications
                           (mission_id, crew_user_id, sent_at, delivery_status,
                            twilio_sid, response_token)
                           VALUES (%s, %s, %s, %s, %s, %s)""",
                        (mission_id, c["id"], now_ms, delivery_status,
                         twilio_sid, resp_token),
                    )
        except Exception as e:
            print(f"[mission-sms] notification record failed crew_id={c['id']}: {e}", flush=True)

        if delivery_status in ("sent", "stubbed"):
            sent += 1

    print(
        f"[mission-sms] mission_id={mission_id} dispatched: "
        f"matched={len(crew_list)} sent={sent}",
        flush=True,
    )
    return (len(crew_list), sent)


@app.route("/api/v1/missions/deployments", methods=["OPTIONS"])
def _missions_deployments_preflight():
    return ("", 204)


@app.get("/api/v1/missions/deployments")
def missions_list():
    """List recent mission deployments fired by the current Met.

    Returns the 20 most recent deployments. Admin role sees everyone's;
    Met role sees only their own.

    Returns:
        200 {"ok": true, "deployments": [...]}
        401 not authenticated
        403 not a Met or admin
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    is_admin = "admin" in roles

    with db() as conn:
        with conn.cursor() as cur:
            if is_admin:
                cur.execute(
                    """SELECT * FROM mission_deployments
                       ORDER BY fired_at DESC LIMIT 20"""
                )
            else:
                # Mets see (a) all their own missions, plus (b) any
                # pending-approval missions from other Mets so they can
                # provide the second-set-of-eyes approval. This is the
                # F-X1 launch fix: no single-admin bottleneck.
                cur.execute(
                    """SELECT * FROM mission_deployments
                       WHERE fired_by_user_id = %s
                          OR status = 'pending-approval'
                       ORDER BY fired_at DESC LIMIT 20""",
                    (user["id"],),
                )
            rows = cur.fetchall()

    deployments = [
        {
            "id": r["id"],
            "fired_at": r["fired_at"],
            "fired_by_name": r["fired_by_name"],
            "template_id": r["template_id"],
            "template_name": r["template_name"],
            "prompt": r["prompt"],
            "polygon_geojson": r["polygon_geojson"],
            "polygon_label": r["polygon_label"],
            "is_severe": r["is_severe"],
            "status": r["status"],
            "audience_estimate": r["audience_estimate"],
            "crew_responded": r["crew_responded"],
            "crew_cited": r["crew_cited"],
            "completed_at": r["completed_at"],
        }
        for r in rows
    ]
    return jsonify({"ok": True, "deployments": deployments})


@app.post("/api/v1/missions/deployments")
def missions_create():
    """Fire a new mission. Met or admin role required.

    Body:
        {
          "template_id": "flag-check",
          "template_name": "Flag check (wind)",
          "prompt": "Look at the flag at Lebanon HS...",
          "polygon_geojson": "..." (optional, JSON-stringified GeoJSON),
          "polygon_label": "Boone County, IN" (optional),
          "is_severe": false,
          "audience_estimate": 4
        }

    Severe missions land in status 'pending-approval' awaiting admin
    sign-off. Normal missions go straight to 'fired'.

    Returns:
        200 {"ok": true, "deployment": {...}}
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}

    template_id = (data.get("template_id") or "").strip()
    template_name = (data.get("template_name") or "").strip()
    prompt = (data.get("prompt") or "").strip()

    if not template_id:
        return jsonify({"ok": False, "error": "missing-template-id"}), 400
    if not template_name:
        return jsonify({"ok": False, "error": "missing-template-name"}), 400
    if not prompt:
        return jsonify({"ok": False, "error": "missing-prompt"}), 400
    if len(prompt) > 4000:
        return jsonify({"ok": False, "error": "prompt-too-long"}), 400

    polygon_geojson = data.get("polygon_geojson") or None
    polygon_label = (data.get("polygon_label") or "").strip() or None
    is_severe = bool(data.get("is_severe", False))
    try:
        audience_estimate = int(data.get("audience_estimate") or 0)
    except (ValueError, TypeError):
        audience_estimate = 0

    # Severe missions are queued for approval; normal fire immediately.
    status = "pending-approval" if is_severe else "fired"
    now_ms = int(time.time() * 1000)

    fired_by_name = user.get("name") or (user.get("email") or "").split("@")[0]

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO mission_deployments
                   (fired_at, fired_by_user_id, fired_by_name, template_id,
                    template_name, prompt, polygon_geojson, polygon_label,
                    is_severe, status, audience_estimate)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                   RETURNING *""",
                (now_ms, user["id"], fired_by_name, template_id, template_name,
                 prompt, polygon_geojson, polygon_label, is_severe, status,
                 audience_estimate),
            )
            r = cur.fetchone()

    # ── Item #5: Dispatch Crew SMS for non-severe missions ──
    # Only fire SMS when status is 'fired' — severe missions wait in
    # 'pending-approval' until an admin approves them (which is when
    # the PATCH endpoint should call this same dispatcher).
    #
    # We update audience_estimate with the REAL matched count returned
    # by _dispatch_mission_sms, overriding the modal's estimate. This
    # is the truth — the modal estimate is a UI hint; the matched count
    # is what actually got pinged.
    real_matched = 0
    real_sent = 0
    if status == "fired":
        try:
            real_matched, real_sent = _dispatch_mission_sms(
                r["id"], prompt, polygon_geojson, template_name
            )
            # Update audience_estimate to reflect reality. If the modal
            # said "4 Crew" but only 2 matched the polygon, the row should
            # show 2 — that's what got pinged.
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE mission_deployments SET audience_estimate = %s WHERE id = %s",
                        (real_matched, r["id"]),
                    )
            audience_estimate = real_matched
        except Exception as e:
            # Don't fail the mission create if SMS dispatch hits a snag —
            # the mission row is persisted, dispatch can be retried by
            # an admin later. Log loudly so we notice.
            print(
                f"[mission-sms] dispatch failed for mission_id={r['id']}: {e!r}",
                flush=True,
            )

    # F-X1: For severe (pending-approval) missions, SMS the other Mets
    # so a second pair of eyes shows up fast. Time-critical workflow.
    if status == "pending-approval":
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT u.id, u.phone FROM users u
                           WHERE u.is_active = TRUE
                             AND u.phone IS NOT NULL AND u.phone != ''
                             AND u.id != %s
                             AND (
                               EXISTS (SELECT 1 FROM user_roles ur
                                       WHERE ur.user_id = u.id AND ur.role = 'met')
                               OR
                               EXISTS (SELECT 1 FROM user_roles ur
                                       WHERE ur.user_id = u.id AND ur.role = 'admin')
                             )
                           LIMIT 10""",
                        (user["id"],),
                    )
                    notify_rows = cur.fetchall()
            sev_msg = (
                f"WeatherValet: SEVERE mission pending approval from "
                f"{fired_by_name}. Polygon: {polygon_label or '-'}. "
                f"Prompt: \"{prompt[:80]}\". Open the workspace Missions tab to review."
            )
            for n in notify_rows:
                try:
                    send_sms(n["phone"], sev_msg)
                except Exception as e:
                    print(f"[mission-sms] approval-notify failed for uid={n['id']}: {e}", flush=True)
        except Exception as e:
            print(f"[mission-sms] approval-notify lookup failed: {e}", flush=True)

    print(
        f"[mission] fired id={r['id']} template={template_id} "
        f"by user_id={user['id']} status={status} "
        f"matched={real_matched} sent={real_sent}",
        flush=True,
    )

    return jsonify({
        "ok": True,
        "deployment": {
            "id": r["id"],
            "fired_at": r["fired_at"],
            "fired_by_name": r["fired_by_name"],
            "template_id": r["template_id"],
            "template_name": r["template_name"],
            "prompt": r["prompt"],
            "polygon_geojson": r["polygon_geojson"],
            "polygon_label": r["polygon_label"],
            "is_severe": r["is_severe"],
            "status": r["status"],
            "audience_estimate": audience_estimate,
            "crew_responded": r["crew_responded"],
            "crew_cited": r["crew_cited"],
            "completed_at": r["completed_at"],
            "matched_crew_count": real_matched,
            "sms_sent_count": real_sent,
        },
    })


@app.route("/api/v1/missions/deployments/<int:dep_id>", methods=["OPTIONS"])
def _missions_deployment_id_preflight(dep_id):
    return ("", 204)


@app.get("/api/v1/missions/deployments/<int:dep_id>")
def missions_get_one(dep_id):
    """Return a single deployment. Only the firing Met or an admin can read.

    Returns:
        200 {"ok": true, "deployment": {...}}
        403 not your deployment
        404 not found
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM mission_deployments WHERE id = %s",
                (dep_id,),
            )
            r = cur.fetchone()

    if not r:
        return jsonify({"ok": False, "error": "not-found"}), 404

    roles = user.get("roles") or []
    is_owner = r["fired_by_user_id"] == user["id"]
    is_admin = "admin" in roles
    if not (is_owner or is_admin):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    return jsonify({
        "ok": True,
        "deployment": {
            "id": r["id"],
            "fired_at": r["fired_at"],
            "fired_by_name": r["fired_by_name"],
            "template_id": r["template_id"],
            "template_name": r["template_name"],
            "prompt": r["prompt"],
            "polygon_geojson": r["polygon_geojson"],
            "polygon_label": r["polygon_label"],
            "is_severe": r["is_severe"],
            "status": r["status"],
            "audience_estimate": r["audience_estimate"],
            "crew_responded": r["crew_responded"],
            "crew_cited": r["crew_cited"],
            "completed_at": r["completed_at"],
        },
    })


@app.patch("/api/v1/missions/deployments/<int:dep_id>")
def missions_update(dep_id):
    """Update a deployment's status (admin approval, cancellation, completion).

    Body:
        {"status": "fired" | "cancelled" | "completed",
         "crew_responded": 3, "crew_cited": 2}

    Approval flow: severe mission lands in 'pending-approval'. Admin
    PATCHes status='fired' which records approved_by_user_id + approved_at.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    data = request.get_json(silent=True) or {}
    roles = user.get("roles") or []

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM mission_deployments WHERE id = %s",
                (dep_id,),
            )
            r = cur.fetchone()
    if not r:
        return jsonify({"ok": False, "error": "not-found"}), 404

    is_owner = r["fired_by_user_id"] == user["id"]
    is_admin = "admin" in roles

    set_clauses = []
    params = []
    now_ms = int(time.time() * 1000)

    if "status" in data:
        new_status = (data["status"] or "").strip()
        if new_status not in ("fired", "cancelled", "completed", "pending-approval"):
            return jsonify({"ok": False, "error": "invalid-status"}), 400

        # Approval: pending-approval → fired requires a SECOND Met or admin
        # (not the same person who fired the mission). This prevents single-
        # Met severe deployments AND avoids the single-admin bottleneck.
        # Rationale: Mets are trained meteorologists. A second pair of eyes
        # from another Met is the right guardrail, not non-meteorologist admin.
        if r["status"] == "pending-approval" and new_status == "fired":
            is_other_met = ("met" in roles) and (r["fired_by_user_id"] != user["id"])
            if not (is_admin or is_other_met):
                # Same-Met self-approval, or non-Met non-admin trying to approve
                if r["fired_by_user_id"] == user["id"]:
                    return jsonify({
                        "ok": False, "error": "second-met-required",
                        "message": "Severe missions need approval from a different Met (or admin)."
                    }), 403
                return jsonify({"ok": False, "error": "met-or-admin-required"}), 403
            set_clauses.append("approved_by_user_id = %s")
            params.append(user["id"])
            set_clauses.append("approved_at = %s")
            params.append(now_ms)
            # Flag that we should dispatch SMS after the UPDATE commits.
            # We can't dispatch here because the update hasn't happened
            # yet — and if it fails, we don't want to have already SMSed.
            is_approval_transition = True
        elif not (is_owner or is_admin):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        else:
            is_approval_transition = False

        set_clauses.append("status = %s")
        params.append(new_status)
        if new_status == "completed":
            set_clauses.append("completed_at = %s")
            params.append(now_ms)
    else:
        is_approval_transition = False

    if "crew_responded" in data and (is_owner or is_admin):
        try:
            set_clauses.append("crew_responded = %s")
            params.append(int(data["crew_responded"]))
        except (ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-crew-responded"}), 400

    if "crew_cited" in data and (is_owner or is_admin):
        try:
            set_clauses.append("crew_cited = %s")
            params.append(int(data["crew_cited"]))
        except (ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid-crew-cited"}), 400

    if not set_clauses:
        return jsonify({"ok": False, "error": "no-fields-to-update"}), 400

    params.append(dep_id)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE mission_deployments SET {', '.join(set_clauses)} "
                f"WHERE id = %s",
                tuple(params),
            )
            cur.execute(
                "SELECT * FROM mission_deployments WHERE id = %s",
                (dep_id,),
            )
            r2 = cur.fetchone()

    # ── Item #5: dispatch SMS now that admin has approved a severe mission.
    # Same flow as initial fire for non-severe missions: find Crew in
    # polygon, send SMS, update real audience count.
    if is_approval_transition:
        try:
            real_matched, real_sent = _dispatch_mission_sms(
                r2["id"], r2["prompt"], r2["polygon_geojson"], r2["template_name"]
            )
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE mission_deployments SET audience_estimate = %s WHERE id = %s",
                        (real_matched, r2["id"]),
                    )
            r2 = dict(r2)
            r2["audience_estimate"] = real_matched
            print(
                f"[mission-approval] mission_id={r2['id']} approved by user_id={user['id']} "
                f"- matched={real_matched} sent={real_sent}",
                flush=True,
            )
        except Exception as e:
            print(
                f"[mission-approval] dispatch failed for mission_id={r2['id']}: {e!r}",
                flush=True,
            )

    return jsonify({
        "ok": True,
        "deployment": {
            "id": r2["id"],
            "fired_at": r2["fired_at"],
            "fired_by_name": r2["fired_by_name"],
            "template_id": r2["template_id"],
            "template_name": r2["template_name"],
            "prompt": r2["prompt"],
            "polygon_geojson": r2["polygon_geojson"],
            "polygon_label": r2["polygon_label"],
            "is_severe": r2["is_severe"],
            "status": r2["status"],
            "audience_estimate": r2["audience_estimate"],
            "crew_responded": r2["crew_responded"],
            "crew_cited": r2["crew_cited"],
            "completed_at": r2["completed_at"],
        },
    })


@app.delete("/api/v1/missions/deployments/<int:dep_id>")
def missions_delete(dep_id):
    """Delete a deployment. Owner or admin only."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT fired_by_user_id FROM mission_deployments WHERE id = %s",
                (dep_id,),
            )
            r = cur.fetchone()
    if not r:
        return jsonify({"ok": False, "error": "not-found"}), 404

    roles = user.get("roles") or []
    is_owner = r["fired_by_user_id"] == user["id"]
    is_admin = "admin" in roles
    if not (is_owner or is_admin):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "DELETE FROM mission_deployments WHERE id = %s",
                (dep_id,),
            )

    return jsonify({"ok": True})


# ════════════════════════════════════════════════════════════════════
# Mission response — Crew tap SMS link to submit their observation
# (Phase 10 Item #5)
# ════════════════════════════════════════════════════════════════════
#
# When _dispatch_mission_sms sends an SMS to a Crew member, the link
# in that SMS points at /?mission=<token>. The frontend shows a response
# page; the Crew member types their observation + submits → POST to
# this endpoint with the token. We record the response, increment
# mission counters.
#
# Authentication: the response_token IS the authentication. It's
# generated per-Crew, per-mission, unguessable, and stored once in
# mission_notifications. No login required — the Crew member identifies
# themselves by possessing the token (sent only to their phone).

@app.route("/api/v1/missions/respond/<response_token>", methods=["OPTIONS"])
def _missions_respond_preflight(response_token):
    return ("", 204)


@app.get("/api/v1/missions/respond/<response_token>")
def missions_respond_get(response_token: str):
    """Return mission context for the response page.

    The frontend calls this when the Crew member opens the SMS link.
    Returns the mission prompt + template name so the page can render
    "Mission: Flag check — Look at the flag at Lebanon HS, how is it
    behaving?" with a textarea + submit.
    """
    if not response_token or len(response_token) < 10:
        return jsonify({"ok": False, "error": "invalid-token"}), 400
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT mn.id AS notification_id, mn.responded_at, mn.response_text,
                          md.id AS mission_id, md.template_name, md.prompt,
                          md.fired_by_name, md.status
                   FROM mission_notifications mn
                   JOIN mission_deployments md ON md.id = mn.mission_id
                   WHERE mn.response_token = %s""",
                (response_token,),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    return jsonify({
        "ok": True,
        "mission": {
            "template_name": row["template_name"],
            "prompt": row["prompt"],
            "fired_by_name": row["fired_by_name"],
            "status": row["status"],
            "already_responded": bool(row["responded_at"]),
            "previous_response": row["response_text"] or "",
        }
    })


@app.post("/api/v1/missions/respond/<response_token>")
def missions_respond_submit(response_token: str):
    """Submit a Crew response to a mission.

    Body: {"response_text": "Flag flapping pretty hard, NW direction..."}

    Idempotency: if already responded, returns the existing response
    (doesn't accept a re-submission). Crew can call submit-again with
    overwrite=true to update.
    """
    if not response_token or len(response_token) < 10:
        return jsonify({"ok": False, "error": "invalid-token"}), 400

    data = request.get_json(silent=True) or {}
    response_text = (data.get("response_text") or "").strip()
    overwrite = bool(data.get("overwrite", False))

    if not response_text:
        return jsonify({"ok": False, "error": "empty-response"}), 400
    if len(response_text) > 4000:
        return jsonify({"ok": False, "error": "response-too-long"}), 400

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, mission_id, responded_at
                   FROM mission_notifications
                   WHERE response_token = %s""",
                (response_token,),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404

    is_first_response = (row["responded_at"] is None)
    if not is_first_response and not overwrite:
        return jsonify({
            "ok": False,
            "error": "already-responded",
            "message": "You've already responded. Send ?overwrite=true to update.",
        }), 409

    now_ms = int(time.time() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE mission_notifications
                   SET response_text = %s, responded_at = %s
                   WHERE id = %s""",
                (response_text, now_ms, row["id"]),
            )
            # On first response, bump the mission's crew_responded counter.
            # On overwrite, don't double-count.
            if is_first_response:
                cur.execute(
                    """UPDATE mission_deployments
                       SET crew_responded = crew_responded + 1
                       WHERE id = %s""",
                    (row["mission_id"],),
                )

    print(
        f"[mission-respond] notification_id={row['id']} mission_id={row['mission_id']} "
        f"first_response={is_first_response}",
        flush=True,
    )

    return jsonify({"ok": True, "first_response": is_first_response})


# ════════════════════════════════════════════════════════════════════
# Crew applications — public submit + admin review (Phase 10 Admin Tools)
# ════════════════════════════════════════════════════════════════════
#
# Public-facing endpoint for the Crew register form (no auth required).
# Anyone can apply; admin approval gates whether they actually become Crew.

@app.route("/api/v1/crew/apply", methods=["OPTIONS"])
def _crew_apply_preflight():
    return ("", 204)


@app.post("/api/v1/crew/apply")
def crew_apply_submit():
    """Submit a Crew application. Public — no auth required.

    Body:
      {
        "name": "Sarah Indianapolis",
        "handle": "@sarah_indy",
        "email": "sarah@example.com",
        "phone": "317-555-0123",
        "county": "Marion County",
        "state": "Indiana",
        "mission_interests": ["storms","hail","wind"],
        "hours": "all",
        "notify": "sms"
      }

    Returns:
        200 {"ok": true, "application_id": N}
        400 invalid input (missing required, bad email, etc.)
        409 email already has a pending or approved application
    """
    data = request.get_json(silent=True) or {}

    name = (data.get("name") or "").strip()
    email = (data.get("email") or "").strip().lower()
    if not name:
        return jsonify({"ok": False, "error": "name-required"}), 400
    if not email or not is_valid_email(email):
        return jsonify({"ok": False, "error": "valid-email-required"}), 400

    handle = (data.get("handle") or "").strip() or None
    phone_raw = (data.get("phone") or "").strip()
    phone = normalize_phone(phone_raw) if phone_raw else None
    county = (data.get("county") or "").strip() or None
    state = (data.get("state") or "").strip() or None
    zip_code = (data.get("zip") or "").strip() or None
    # Keep only a clean 5-digit US zip; ignore anything else.
    if zip_code:
        import re as _re_zip
        m = _re_zip.match(r"^(\d{5})", zip_code)
        zip_code = m.group(1) if m else None

    interests_list = data.get("mission_interests") or []
    if isinstance(interests_list, str):
        # Accept comma-separated string too
        interests_list = [x.strip() for x in interests_list.split(",") if x.strip()]
    valid_interests = {"storms", "hail", "wind", "rain", "winter", "general"}
    mission_interests = ",".join(
        x for x in interests_list if x in valid_interests
    ) or None

    hours = (data.get("hours") or "all").strip()
    if hours not in ("all", "weekdays-day", "weekdays-evening", "weekends", "custom"):
        hours = "all"

    notify = (data.get("notify") or "sms").strip()
    if notify not in ("sms", "email", "both"):
        notify = "sms"

    now_ms = int(time.time() * 1000)

    def _crew_send_verify_and_notify(application_id_inner):
        """Inner helper: mint a fresh magic-link token, send the verify
        email to the applicant, and send admin notification. Called from
        BOTH the pending-update path and the new-application path so
        applicants get a fresh link each time they submit, even if a
        prior application already existed.

        Wrapped in its own try/except. Failures here don't block the
        API response — the application row already exists.
        """
        # Verification email setup
        try:
            print(f"[crew-apply] starting verify setup for {email} (app_id={application_id_inner})", flush=True)
            with db() as conn:
                applicant_user_id = _get_or_create_user(email, conn)
                print(f"[crew-apply] user_id={applicant_user_id} for {email}", flush=True)
                with conn.cursor() as cur:
                    if name:
                        cur.execute(
                            """UPDATE users SET name = %s
                               WHERE id = %s AND (name IS NULL OR name = '')""",
                            (name, applicant_user_id),
                        )
                    if phone:
                        cur.execute(
                            """UPDATE users SET phone = %s
                               WHERE id = %s AND (phone IS NULL OR phone = '')""",
                            (phone, applicant_user_id),
                        )
                # Geocode the applicant so they become targetable on the
                # mission deploy map immediately. We prefer the zip code,
                # which geocodes to a tight, accurate point; if there is no
                # usable zip we fall back to county + state. Non-blocking:
                # if geocoding fails we still create the applicant and send
                # the welcome link; they can set a precise location later
                # via /api/v1/me/crew-location.
                if zip_code or county:
                    try:
                        # Build the geocode query, zip first (most precise).
                        # State is appended for the county fallback so the
                        # geocoder cannot drift to a same-named place in
                        # another state. The confidence gate below then
                        # checks the result against this query.
                        if zip_code:
                            geo_query = zip_code + ", USA"
                        else:
                            geo_query = county
                            if state and state.lower() not in county.lower():
                                geo_query = county + ", " + state
                        geo = _geocode_address(geo_query)
                        if geo and geo.get("lat") is not None and geo.get("lng") is not None:
                            conf_ok, conf_reason = _geocode_looks_confident(geo_query, geo)
                            if not conf_ok:
                                print(
                                    f"[crew-apply] LOW-CONFIDENCE geocode for county={county!r} "
                                    f"-> name={geo.get('name')!r} state={geo.get('admin1')!r} "
                                    f"(reason={conf_reason}); skipping auto-write so user_id="
                                    f"{applicant_user_id} is not placed in the wrong spot. An admin "
                                    f"can set it via /api/v1/admin/crew/<id>/geocode-home.",
                                    flush=True,
                                )
                            else:
                                geo_label = geo.get("name") or county
                                if geo.get("admin1") and ", " not in geo_label:
                                    geo_label += ", " + geo["admin1"]
                                tz_val = _tz_from_latlng(geo["lat"], geo["lng"])
                                with conn.cursor() as cur:
                                    cur.execute(
                                        """UPDATE users
                                           SET crew_home_lat = %s,
                                               crew_home_lng = %s,
                                               timezone = %s,
                                               crew_home_label = COALESCE(NULLIF(crew_home_label, ''), %s)
                                           WHERE id = %s
                                             AND (crew_home_lat IS NULL OR crew_home_lng IS NULL)""",
                                        (float(geo["lat"]), float(geo["lng"]),
                                         tz_val, geo_label, applicant_user_id),
                                    )
                                    print(
                                        f"[crew-apply] geocoded county={county!r} → "
                                        f"({geo['lat']}, {geo['lng']}) for user_id={applicant_user_id}",
                                        flush=True,
                                    )
                        else:
                            print(
                                f"[crew-apply] geocode returned nothing for county={county!r} "
                                f"(user_id={applicant_user_id}) — crew won't be on map until they set location",
                                flush=True,
                            )
                    except Exception as geo_e:
                        print(f"[crew-apply] geocode error: {geo_e!r}", flush=True)
                # Auto-approval (June 2026): no admin step. Grant the crew
                # role immediately and stamp the application approved, then
                # send a welcome email with a sign-in link and the Crew
                # to-do list. The applicant is a full Crew member right away.
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO user_roles (user_id, role, granted_at)
                           VALUES (%s, 'crew', %s)
                           ON CONFLICT (user_id, role) DO NOTHING""",
                        (applicant_user_id, int(time.time() * 1000)),
                    )
                    cur.execute(
                        """UPDATE crew_applications
                           SET status='approved', reviewed_at=%s,
                               created_user_id=%s, updated_at=%s
                           WHERE id=%s""",
                        (int(time.time() * 1000), applicant_user_id,
                         int(time.time() * 1000), application_id_inner),
                    )
                raw_token = new_secure_token()
                token_hash = hash_token(raw_token)
                now_seconds = int(time.time())
                seven_days = 7 * 24 * 60 * 60
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO magic_link_tokens
                             (token_hash, user_id, created_at, expires_at, ip_requested)
                           VALUES (%s, %s, %s, %s, %s)""",
                        (token_hash, applicant_user_id, now_seconds,
                         now_seconds + seven_days, "crew-welcome"),
                    )
                print(f"[crew-apply] crew role granted + approved for user_id={applicant_user_id}", flush=True)
            base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai")
            magic_link_url = f"{base}/?auth=verify&token={raw_token}&intent=new-account"
            print(f"[crew-apply] calling _send_crew_welcome_email for {email}", flush=True)
            try:
                send_result = _send_crew_welcome_email(email, magic_link_url,
                                                       member_name=name)
                print(f"[crew-apply] _send_crew_welcome_email returned {send_result} for {email}", flush=True)
            except Exception as e:
                print(f"[crew-apply] welcome email send failed: {e!r}", flush=True)
        except Exception as e:
            print(f"[crew-apply] verification setup failed: {e!r}", flush=True)

        # Admin notification
        try:
            admin_email = os.environ.get("ADMIN_NOTIFY_EMAIL", "").strip()
            if not admin_email:
                admin_email = "hello@weathervalet.ai"
            admin_subject = f"New Valet Crew application: {name}"
            admin_html = (
                '<!DOCTYPE html><html><body style="font-family:-apple-system,'
                'BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;color:#0E1116;'
                'max-width:560px;margin:24px auto;padding:0 16px;">'
                f'<h2 style="font-size:18px;margin:0 0 14px;">New Valet Crew application</h2>'
                '<table style="border-collapse:collapse;font-size:14px;'
                'line-height:1.55;color:#0E1116;">'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Name</td><td>{_html_escape(name)}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Email</td><td><a href="mailto:{_html_escape(email)}">{_html_escape(email)}</a></td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Handle</td><td>{_html_escape(handle or "(none)")}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Phone</td><td>{_html_escape(phone or "(none)")}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">County</td><td>{_html_escape(county or "(none)")}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Interests</td><td>{_html_escape(mission_interests or "(none)")}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Hours</td><td>{_html_escape(hours)}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">Notify</td><td>{_html_escape(notify)}</td></tr>'
                f'<tr><td style="padding:4px 12px 4px 0;color:#6E7682;">App ID</td><td>{application_id_inner}</td></tr>'
                '</table>'
                '<p style="font-size:13px;color:#6E7682;margin:18px 0 0;line-height:1.55;">'
                'They&rsquo;ve been added to the Crew automatically and emailed a '
                'welcome link with their next steps. No approval needed.</p>'
                '</body></html>'
            )
            _send_brief_email(admin_email, admin_subject, admin_html, html=True)
        except Exception as e:
            print(f"[crew-apply] admin notify failed: {e!r}", flush=True)

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # Check for existing application
                cur.execute(
                    "SELECT id, status FROM crew_applications WHERE email = %s",
                    (email,),
                )
                existing = cur.fetchone()
                if existing:
                    if existing["status"] == "approved":
                        # Already a Crew member. Update their details and
                        # re-send a fresh welcome/sign-in link so they can
                        # get back in. No blocking error.
                        cur.execute(
                            """UPDATE crew_applications
                               SET name = %s, handle = %s, phone = %s, county = %s,
                                   mission_interests = %s, hours = %s, notify = %s,
                                   updated_at = %s
                               WHERE id = %s""",
                            (name, handle, phone, county, mission_interests, hours,
                             notify, now_ms, existing["id"]),
                        )
                    if existing["status"] == "pending":
                        # Update the existing pending row rather than create a duplicate
                        cur.execute(
                            """UPDATE crew_applications
                               SET name = %s, handle = %s, phone = %s, county = %s,
                                   mission_interests = %s, hours = %s, notify = %s,
                                   updated_at = %s
                               WHERE id = %s""",
                            (name, handle, phone, county, mission_interests, hours,
                             notify, now_ms, existing["id"]),
                        )
        # Existing member (approved or pending): re-send a fresh welcome
        # + sign-in link so they can finish or get back in.
        if existing and existing["status"] in ("approved", "pending"):
            _crew_send_verify_and_notify(existing["id"])
            return jsonify({
                "ok": True,
                "application_id": existing["id"],
                "updated": True,
            })

        with db() as conn:
            with conn.cursor() as cur:
                if existing and existing["status"] == "rejected":
                    # 'rejected' — allow them to re-join by clearing rejection
                    cur.execute(
                        """UPDATE crew_applications
                           SET status='pending', name=%s, handle=%s, phone=%s, county=%s,
                               mission_interests=%s, hours=%s, notify=%s,
                               updated_at=%s, rejection_reason=NULL,
                               reviewed_at=NULL, reviewed_by_user_id=NULL
                           WHERE id=%s""",
                        (name, handle, phone, county, mission_interests, hours,
                         notify, now_ms, existing["id"]),
                    )
                    reapply_id = existing["id"]
                else:
                    # New application — created as 'pending', then the
                    # helper below grants the crew role and flips it to
                    # 'approved' (auto-approval, June 2026).
                    cur.execute(
                        """INSERT INTO crew_applications
                           (created_at, updated_at, status, name, handle, email, phone,
                            county, mission_interests, hours, notify)
                           VALUES (%s, %s, 'pending', %s, %s, %s, %s, %s, %s, %s, %s)
                           RETURNING id""",
                        (now_ms, now_ms, name, handle, email, phone, county,
                         mission_interests, hours, notify),
                    )
                    row = cur.fetchone()
                    reapply_id = row["id"]

        # Grant crew role + send welcome for new joins and rejected-rejoins.
        _crew_send_verify_and_notify(reapply_id)

        print(f"[crew-apply] application id={reapply_id} email={email}", flush=True)
        return jsonify({"ok": True, "application_id": reapply_id})
    except Exception as e:
        print(f"[crew-apply] insert failed for {email}: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "internal-error"}), 500


def _send_crew_welcome_email(email: str, magic_link_url: str,
                             member_name: str = "") -> bool:
    """Send the Valet Crew welcome email with a sign-in link and the Crew
    to-do list (June 2026). Sent the moment someone joins the Crew, since
    joining is now instant with no approval step.

    Uses urllib + Resend, matching the rest of our outbound mail. Returns
    True if Resend accepted the request.
    """
    if not RESEND_API_KEY:
        print("[crew-welcome-email] RESEND_API_KEY not set, skipping", flush=True)
        return False
    greeting_name = member_name.strip() if member_name and member_name.strip() else "there"
    steps = [
        ("Set your password.",
         "Tap the button above to set your password and sign in. That is step one."),
        ("Confirm your location.",
         "On your Crew page, set your location so we know which part of the "
         "community you are reporting for. This is how your reports help your "
         "neighbors and our Meteorologists."),
        ("Reply to your daily check-in.",
         "Each day we will message you to ask what the weather looks like where "
         "you are. Just reply with what you see (clear, cloudy, rain, storm, and "
         "so on). Every reply keeps your streak going and puts you on the Crew map. "
         "Standout photos may be featured, with your first-name credit, on our "
         "channels, social media, and live streams."),
        ("Report it when weather hits.",
         "When you see something worth flagging (storms, hail, high wind, "
         "flooding), send a quick report. Your eyes on the ground help our "
         "Meteorologists keep everyone safe."),
    ]
    rows_html = ""
    for i, (t, b) in enumerate(steps):
        last = (i == len(steps) - 1)
        pad = "0" if last else "0 0 14px"
        numpad = "0 10px 0 0" if last else "0 10px 14px 0"
        rows_html += (
            f'<tr><td style="vertical-align:top;padding:{numpad};color:#2E4FB8;'
            f'font-size:14px;font-weight:700;">{i + 1}.</td>'
            f'<td style="padding:{pad};color:#3D4148;font-size:13.5px;line-height:1.6;">'
            f'<b style="color:#0E1116;">{t}</b> {b}</td></tr>'
        )
    rows_text = "".join(f"{i + 1}. {t} {b}\n" for i, (t, b) in enumerate(steps))
    try:
        subject = "Welcome to the Valet Crew! Let's get you started"
        html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#F8F9FB;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#0E1116;">
  <div style="max-width:560px;margin:32px auto;padding:32px 28px;background:#fff;border-radius:12px;box-shadow:0 1px 3px rgba(15,17,22,0.06);">
    <h1 style="font-size:22px;font-weight:700;margin:0 0 14px;">Welcome to the Valet Crew, {greeting_name}!</h1>
    <p style="font-size:15px;line-height:1.55;color:rgba(15,17,22,0.75);margin:0 0 22px;">
      You are officially on the Crew. You will help your community and our Meteorologists by sharing what the weather is really doing where you are. Here is how to get started. It only takes a few minutes.
    </p>
    <div style="text-align:center;margin:24px 0;">
      <a href="{magic_link_url}" style="display:inline-block;background:#2E4FB8;color:#fff;text-decoration:none;padding:13px 28px;border-radius:8px;font-weight:600;font-size:15px;">Set your password</a>
    </div>
    <div style="background:#F4F6FB;border:1px solid #DCE3F5;border-radius:10px;padding:18px 20px;margin:0 0 22px;">
      <p style="color:#0E1116;font-size:15px;font-weight:700;margin:0 0 12px;">Your quick start list</p>
      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;">{rows_html}</table>
      <p style="color:#6B7280;font-size:12.5px;line-height:1.5;margin:14px 0 0;">
        Thank you for joining. Your reports make a real difference.
      </p>
    </div>
    <p style="font-size:12.5px;line-height:1.55;color:rgba(15,17,22,0.55);margin:0;">
      This sign-in link is valid for 7 days. Questions? Just reply to this email and a human will read it.
    </p>
  </div>
</body></html>"""
        text = (f"Welcome to the Valet Crew, {greeting_name}!\n\n"
                "You are officially on the Crew. You will help your community and "
                "our Meteorologists by sharing what the weather is really doing "
                "where you are. Here is how to get started.\n\n"
                f"Set your password: {magic_link_url}\n\n"
                "YOUR QUICK START LIST\n"
                f"{rows_text}\n"
                "Thank you for joining. Your reports make a real difference. "
                "This sign-in link is valid for 7 days. Questions? Just reply to "
                "this email and a human will read it.")
        from_addr = os.environ.get("EMAIL_FROM", "").strip() or "WeatherValet <hello@weathervalet.ai>"
        payload = json.dumps({
            "from": from_addr,
            "to": [email],
            "subject": subject,
            "html": html,
            "text": text,
        }).encode("utf-8")
        req = urllib.request.Request(
            "https://api.resend.com/emails",
            data=payload,
            method="POST",
            headers={
                "Authorization": f"Bearer {RESEND_API_KEY}",
                "Content-Type": "application/json",
                "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)",
            },
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                return True
            print(f"[crew-welcome-email] Resend returned status {resp.status}", flush=True)
            return False
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            pass
        print(f"[crew-welcome-email] Resend HTTPError {e.code}: {body}", flush=True)
        return False
    except Exception as e:
        print(f"[crew-welcome-email] failed: {e!r}", flush=True)
        return False

def _send_crew_verify_email(email: str, magic_link_url: str,
                            applicant_name: str = "") -> bool:
    """Send a Valet Crew application verification email. Returns True
    if Resend accepted the request.

    Added May 24, 2026 as part of the self-service Crew flow. The user
    applies, lands on a "check your email" success state, then clicks
    this email's link. On click, the magic-link verify endpoint grants
    them the 'crew' role and signs them in.

    Token TTL is 7 days. If they wait too long, they can re-submit the
    application form to get a fresh link.

    Diagnostic logging: prints entry, API key presence, and the Resend
    response status/body to Render logs. Helps debug why an email
    didn't arrive (rejected sender, throttled, etc.).
    """
    print(f"[crew-verify-email] ENTER email={email} link_len={len(magic_link_url)}", flush=True)
    RESEND_API_KEY = os.environ.get("RESEND_API_KEY", "").strip()
    if not RESEND_API_KEY:
        print(f"[crew-verify-email] RESEND_API_KEY not set. Link for {email}: {magic_link_url}", flush=True)
        return False
    print(f"[crew-verify-email] API key present (len={len(RESEND_API_KEY)})", flush=True)
    try:
        greeting = f"Hi {applicant_name.split()[0]}," if applicant_name else "Hi,"
        subject = "Verify your Valet Crew application"
        html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#F8F9FB;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#0E1116;">
  <div style="max-width:560px;margin:32px auto;padding:32px 28px;background:#fff;border-radius:12px;box-shadow:0 1px 3px rgba(15,17,22,0.06);">
    <h1 style="font-size:22px;font-weight:600;margin:0 0 16px;">{greeting}</h1>
    <p style="font-size:15px;line-height:1.55;color:rgba(15,17,22,0.75);margin:0 0 14px;">
      Thanks for applying to the Valet Crew. We&rsquo;re a community of weather watchers helping our meteorologists keep an eye on the ground.
    </p>
    <p style="font-size:15px;line-height:1.55;color:rgba(15,17,22,0.75);margin:0 0 22px;">
      Tap the button below to verify your email and finish joining. You&rsquo;ll be signed in and able to start submitting reports right away.
    </p>
    <div style="text-align:center;margin:28px 0;">
      <a href="{magic_link_url}" style="display:inline-block;background:#2E4FB8;color:#fff;text-decoration:none;padding:13px 28px;border-radius:8px;font-weight:600;font-size:15px;">Verify and join the Crew</a>
    </div>
    <p style="font-size:13px;line-height:1.55;color:rgba(15,17,22,0.55);margin:22px 0 0;">
      This link is valid for 7 days. If it expires, just submit the application again at <a href="https://weathervalet.ai/crew" style="color:#2E4FB8;">weathervalet.ai/crew</a> for a fresh link.
    </p>
    <p style="font-size:13px;line-height:1.55;color:rgba(15,17,22,0.55);margin:14px 0 0;">
      Questions? Just reply to this email and a human will read it.
    </p>
  </div>
</body></html>"""
        text = (f"{greeting}\n\n"
                "Thanks for applying to the Valet Crew. We're a community of "
                "weather watchers helping our meteorologists keep an eye "
                "on the ground.\n\n"
                "Tap the link below to verify your email and finish joining. "
                "You'll be signed in and able to start submitting reports "
                f"right away.\n\n{magic_link_url}\n\n"
                "This link is valid for 7 days. If it expires, just submit "
                "the application again at https://weathervalet.ai/crew for "
                "a fresh link.\n\n"
                "Questions? Just reply to this email and a human will read it.")
        resend_headers = {
            "Authorization": f"Bearer {RESEND_API_KEY}",
            "Content-Type": "application/json",
            "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)",
        }
        resend_body = {
            "from": "WeatherValet <hello@weathervalet.ai>",
            "to": [email],
            "subject": subject,
            "html": html,
            "text": text,
        }
        payload = json.dumps(resend_body).encode("utf-8")
        print(f"[crew-verify-email] POSTing to Resend for {email}", flush=True)
        req = urllib.request.Request(
            "https://api.resend.com/emails",
            data=payload,
            method="POST",
            headers=resend_headers,
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                ok = 200 <= resp.status < 300
                if ok:
                    print(f"[crew-verify-email] Resend OK status={resp.status} for {email}", flush=True)
                else:
                    body_preview = resp.read(500).decode("utf-8", errors="replace")
                    print(f"[crew-verify-email] Resend REJECTED status={resp.status} for {email}: {body_preview}", flush=True)
                return ok
        except urllib.error.HTTPError as e:
            body_preview = ""
            try:
                body_preview = e.read(500).decode("utf-8", errors="replace")
            except Exception:
                pass
            print(f"[crew-verify-email] Resend HTTPError status={e.code} for {email}: {body_preview}", flush=True)
            return False
        except Exception as e:
            print(f"[crew-verify-email] urlopen failed for {email}: {type(e).__name__}: {e}", flush=True)
            return False
    except Exception as e:
        print(f"[crew-verify-email] EXCEPTION for {email}: {e!r}", flush=True)
        return False


