@app.get("/api/v1/met/map-default-center")
def met_map_default_center():
    """Return the best default center+zoom for this Met's map view.

    Added May 29, 2026 to fix the Indianapolis-defaults-for-everyone bug.

    Priority order:
      1. Centroid of subscribers this Met is primary_met for. Most accurate
         since it reflects who the Met actually serves.
      2. Met's own primary saved location, if set. Useful for new Mets
         who don't yet have assigned subscribers.
      3. Continental US fallback (geographic center of the lower 48,
         ~39.5, -98.4). Last resort — better than hardcoded Indianapolis.

    Returns {ok, lat, lng, zoom, source}. source = subscribers|self|fallback.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    met_id = user["id"]

    with db() as conn:
        with conn.cursor() as cur:
            # Try 1: subscriber centroid
            cur.execute(
                """SELECT AVG(loc.lat) AS clat, AVG(loc.lng) AS clng,
                          COUNT(*) AS n
                   FROM subscriber_coverage sc
                   JOIN saved_locations loc ON loc.user_id = sc.user_id
                   WHERE sc.primary_met_id = %s
                     AND loc.is_primary = TRUE
                     AND loc.lat IS NOT NULL AND loc.lng IS NOT NULL""",
                (met_id,),
            )
            row = cur.fetchone()
            if row and row.get("n") and row["n"] > 0:
                return jsonify({
                    "ok": True,
                    "lat": float(row["clat"]),
                    "lng": float(row["clng"]),
                    "zoom": 7,
                    "source": "subscribers",
                    "subscriber_count": row["n"],
                })

            # Try 2: Met's own primary saved location
            cur.execute(
                """SELECT lat, lng FROM saved_locations
                   WHERE user_id = %s AND is_primary = TRUE
                     AND lat IS NOT NULL AND lng IS NOT NULL
                   LIMIT 1""",
                (met_id,),
            )
            row = cur.fetchone()
            if row:
                return jsonify({
                    "ok": True,
                    "lat": float(row["lat"]),
                    "lng": float(row["lng"]),
                    "zoom": 7,
                    "source": "self",
                })

    # Try 3: continental US fallback (geographic center of the lower 48)
    return jsonify({
        "ok": True,
        "lat": 39.5,
        "lng": -98.4,
        "zoom": 4,
        "source": "fallback",
    })


@app.get("/api/v1/met/suppressed-briefs")
def met_list_suppressed_briefs():
    """List today's suppressed Hobbyist briefs for the Met workspace.

    Added May 29, 2026 as the Suppressed-Hobbyist recovery surface.

    Scope: Pro covering Mets see ONLY their assigned subscribers'
    suppressions; admins see all. "Today" = subscriber's local day.

    Returns rows with enough context for the Met to act:
      - history_id (for retry/manual-send endpoints)
      - subscriber name/email/phone/location
      - the original suppression reason (the AI's full_body output)
      - timestamp when suppression occurred
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    is_admin = "admin" in roles
    met_id = user["id"]

    # Window: last 24 hours, captures today + any late-night suppressions
    cutoff_ms = int(time.time() * 1000) - (24 * 3600 * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            if is_admin:
                cur.execute(
                    """SELECT bh.id AS history_id, bh.user_id, bh.delivered_at AS suppressed_at,
                              bh.snippet, bh.full_body AS reason,
                              u.name AS subscriber_name, u.email AS subscriber_email,
                              u.phone AS subscriber_phone,
                              loc.label AS location_label, loc.address_text AS location_address
                       FROM brief_history bh
                       JOIN users u ON u.id = bh.user_id
                       LEFT JOIN saved_locations loc
                            ON loc.user_id = u.id AND loc.is_primary = TRUE
                       WHERE bh.delivery_status = 'suppressed'
                         AND bh.delivered_at >= %s
                       ORDER BY bh.delivered_at DESC""",
                    (cutoff_ms,),
                )
            else:
                # Met sees only assigned subscribers (primary_met or backup_met).
                # Hobbyists don't have subscriber_coverage rows, so we also
                # surface unassigned suppressions (any Met can recover them).
                cur.execute(
                    """SELECT bh.id AS history_id, bh.user_id, bh.delivered_at AS suppressed_at,
                              bh.snippet, bh.full_body AS reason,
                              u.name AS subscriber_name, u.email AS subscriber_email,
                              u.phone AS subscriber_phone,
                              loc.label AS location_label, loc.address_text AS location_address
                       FROM brief_history bh
                       JOIN users u ON u.id = bh.user_id
                       LEFT JOIN saved_locations loc
                            ON loc.user_id = u.id AND loc.is_primary = TRUE
                       LEFT JOIN subscriber_coverage sc ON sc.user_id = u.id
                       WHERE bh.delivery_status = 'suppressed'
                         AND bh.delivered_at >= %s
                         AND (sc.primary_met_id = %s
                              OR sc.backup_met_id = %s
                              OR sc.user_id IS NULL)
                       ORDER BY bh.delivered_at DESC""",
                    (cutoff_ms, met_id, met_id),
                )
            rows = cur.fetchall()

    out = []
    for r in rows:
        out.append({
            "history_id": r["history_id"],
            "user_id": r["user_id"],
            "suppressed_at": r["suppressed_at"],
            "subscriber_name": r.get("subscriber_name") or "",
            "subscriber_email": r["subscriber_email"],
            "subscriber_phone": r.get("subscriber_phone") or "",
            "location_label": r.get("location_label") or "",
            "location_address": r.get("location_address") or "",
            "snippet": r.get("snippet") or "",
            "reason": r.get("reason") or "",
        })
    return jsonify({"ok": True, "count": len(out), "rows": out})


@app.post("/api/v1/met/suppressed-briefs/<int:history_id>/retry")
def met_retry_suppressed_brief(history_id):
    """Regenerate the AI brief for a previously-suppressed subscriber.

    If the new generation returns verdict != 'suppress', the brief is
    sent to the subscriber and a new brief_history row is written
    (delivery_status='sent', is_met_touched=FALSE, met_name=NULL —
    because the Met didn't write content, just clicked Retry).

    If the new generation ALSO returns verdict='suppress', we return
    an error and DO NOT send. Met can then fall back to manual-send.

    The original suppressed history row is left in place for audit.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    # Look up the original suppression row + subscriber context
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT bh.id, bh.user_id, bh.delivery_status,
                          u.name, u.email, u.phone, u.timezone,
                          bp.channels,
                          loc.label AS loc_label, loc.address_text AS loc_address,
                          loc.lat AS loc_lat, loc.lng AS loc_lng,
                          loc.county AS loc_county
                   FROM brief_history bh
                   JOIN users u ON u.id = bh.user_id
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   LEFT JOIN saved_locations loc
                        ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE bh.id = %s""",
                (history_id,),
            )
            row = cur.fetchone()

    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if row["delivery_status"] != "suppressed":
        return jsonify({"ok": False, "error": "not-suppressed",
                        "current_status": row["delivery_status"]}), 409

    if not row.get("loc_lat") or not row.get("loc_lng"):
        return jsonify({"ok": False, "error": "no-location",
                        "message": "Subscriber has no primary location set"}), 422

    # Regenerate forecast + brief
    try:
        forecast = _fetch_forecast(row["loc_lat"], row["loc_lng"])
    except Exception as e:
        print(f"[suppressed-retry] forecast fetch failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "forecast-failed",
                        "message": "Could not fetch forecast data"}), 502

    location_label = _smart_location_label(
        row.get("loc_label") or "",
        row.get("loc_address") or "")
    try:
        verdict, snippet, full_body = _generate_hobbyist_brief_llm(
            location_label, forecast,
            county=row.get("loc_county") or "",
        )
    except Exception as e:
        print(f"[suppressed-retry] brief gen failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "generation-failed",
                        "message": "AI brief generation failed"}), 500

    if verdict == "suppress":
        # Still bad data. Don't send. Met should use manual-send instead.
        return jsonify({
            "ok": False,
            "error": "still-suppressed",
            "message": "AI re-generation still returned suppress verdict. Data may still be bad. Use Manual-send to write a brief manually.",
            "reason": full_body,
        }), 409

    # Good brief — send via subscriber's preferred channels
    channels = [ch for ch in (row.get("channels") or "").split(",") if ch]
    channels_used = []
    any_success = False
    smart_subject = f"Your WeatherValet brief, {location_label}"
    reply_to = _get_subscriber_reply_to_email(row["user_id"])

    for ch in channels:
        if ch == "sms" and row.get("phone"):
            ok = send_sms(row["phone"], snippet + "\n\nFull brief: " + full_body[:1200])
            if ok:
                channels_used.append("sms")
                any_success = True
        elif ch == "email" and row.get("email"):
            try:
                _send_brief_email(row["email"], smart_subject, full_body, reply_to=reply_to)
                channels_used.append("email")
                any_success = True
            except Exception as e:
                print(f"[suppressed-retry] email send failed: {e}", flush=True)

    if not any_success:
        return jsonify({"ok": False, "error": "no-channels-succeeded",
                        "message": "No delivery channel succeeded. Check subscriber phone/email."}), 502

    # Record new brief_history row marking the successful recovery delivery
    try:
        now_ms = int(time.time() * 1000)
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO brief_history
                       (user_id, brief_type, delivered_at, verdict,
                        snippet, full_body, delivery_status, channels_used,
                        is_met_touched, met_name)
                       VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                    (row["user_id"], "morning", now_ms, verdict,
                     (snippet or "")[:140], full_body,
                     "sent", ",".join(channels_used),
                     False, None),
                )
    except Exception as e:
        print(f"[suppressed-retry] history insert failed: {e}", flush=True)
        # Don't fail the request — brief WAS sent, just recording failed

    return jsonify({
        "ok": True,
        "verdict": verdict,
        "channels_used": channels_used,
        "snippet": snippet,
    })


@app.post("/api/v1/met/suppressed-briefs/<int:history_id>/manual-send")
def met_manual_send_suppressed_brief(history_id):
    """Send a Met-authored brief to a previously-suppressed subscriber.

    Body: {"snippet": "...", "full_body": "...", "verdict": "clear|caution|risk"}

    snippet is what goes in the SMS preview (140 chars max).
    full_body is the full brief shown in email and the long-form SMS append.
    verdict is the Met's call after looking at the data. Defaults to 'clear'
    if not provided.

    Writes a new brief_history row marking is_met_touched=TRUE so payroll/
    audit can credit the Met. Original suppressed row stays for audit.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}
    snippet = (data.get("snippet") or "").strip()
    full_body = (data.get("full_body") or "").strip()
    verdict = (data.get("verdict") or "clear").strip().lower()

    if not snippet:
        return jsonify({"ok": False, "error": "missing-snippet",
                        "message": "snippet field is required"}), 422
    if not full_body:
        return jsonify({"ok": False, "error": "missing-body",
                        "message": "full_body field is required"}), 422
    if verdict not in ("clear", "caution", "risk"):
        return jsonify({"ok": False, "error": "invalid-verdict",
                        "message": "verdict must be clear, caution, or risk"}), 422

    # Look up subscriber + channels
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT bh.id, bh.user_id, bh.delivery_status,
                          u.name, u.email, u.phone,
                          bp.channels,
                          loc.label AS loc_label, loc.address_text AS loc_address
                   FROM brief_history bh
                   JOIN users u ON u.id = bh.user_id
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   LEFT JOIN saved_locations loc
                        ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE bh.id = %s""",
                (history_id,),
            )
            row = cur.fetchone()

    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if row["delivery_status"] != "suppressed":
        return jsonify({"ok": False, "error": "not-suppressed",
                        "current_status": row["delivery_status"]}), 409

    location_label = _smart_location_label(
        row.get("loc_label") or "",
        row.get("loc_address") or "")

    # Send via channels
    channels = [ch for ch in (row.get("channels") or "").split(",") if ch]
    channels_used = []
    any_success = False
    met_name = user.get("name") or user.get("email") or "Met"
    smart_subject = f"Your WeatherValet brief, {location_label}"
    reply_to = _get_subscriber_reply_to_email(row["user_id"])

    for ch in channels:
        if ch == "sms" and row.get("phone"):
            ok = send_sms(row["phone"], snippet + "\n\nFull brief: " + full_body[:1200])
            if ok:
                channels_used.append("sms")
                any_success = True
        elif ch == "email" and row.get("email"):
            try:
                _send_brief_email(row["email"], smart_subject, full_body, reply_to=reply_to)
                channels_used.append("email")
                any_success = True
            except Exception as e:
                print(f"[suppressed-manual-send] email failed: {e}", flush=True)

    if not any_success:
        return jsonify({"ok": False, "error": "no-channels-succeeded",
                        "message": "No delivery channel succeeded. Check subscriber phone/email."}), 502

    # Record new history row, attributed to the Met
    try:
        now_ms = int(time.time() * 1000)
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO brief_history
                       (user_id, brief_type, delivered_at, verdict,
                        snippet, full_body, delivery_status, channels_used,
                        is_met_touched, met_name)
                       VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                    (row["user_id"], "morning", now_ms, verdict,
                     snippet[:140], full_body,
                     "sent", ",".join(channels_used),
                     True, met_name),
                )
    except Exception as e:
        print(f"[suppressed-manual-send] history insert failed: {e}", flush=True)

    return jsonify({
        "ok": True,
        "channels_used": channels_used,
        "met_name": met_name,
    })


@app.post("/api/v1/met/pro-briefs/<int:draft_id>/send")
def met_pro_brief_send(draft_id):
    """Send the Met's edited brief to the subscriber. Marks status='sent',
    records brief_history row (is_met_touched=TRUE), dispatches via SMS+email.

    May 17, 2026 rebuild: structured Pro Brief format.
    - SMS = short (verdict + bottom line + link to web view)
    - Email = full structured brief with all four sections
    - Web view = same as email, gated by login

    If the draft has structured fields (bottom_line, weather_details,
    whats_ahead) populated, we use those. Otherwise we fall back to the
    legacy single-body field for backward compat with older drafts.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    # Visibility-gated (May 22, 2026): covering Met must have access to send
    if not _can_met_see_pro_brief(user["id"], draft_id, "admin" in roles):
        return jsonify({"ok": False, "error": "not-found"}), 404

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT d.*, u.email AS sub_email, u.phone AS sub_phone,
                          u.name AS sub_name,
                          loc.address_text AS location_address
                   FROM pro_brief_drafts d
                   JOIN users u ON u.id = d.user_id
                   LEFT JOIN saved_locations loc
                        ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE d.id = %s""",
                (draft_id,),
            )
            row = cur.fetchone()

    if not row:
        return jsonify({"ok": False, "error": "not-found"}), 404
    # Auto-send safety net guard (May 29, 2026): if the system already
    # auto-sent this brief to protect the subscriber from a missed
    # window, the Met cannot send it again. Block with 409 + the
    # auto_sent_at timestamp so the UI can show "Auto-sent at X:XX AM".
    if row.get("auto_sent_at"):
        return jsonify({
            "ok": False,
            "error": "already-auto-sent",
            "auto_sent_at": row["auto_sent_at"],
        }), 409
    if row["status"] not in ("pending-review", "claimed"):
        return jsonify({"ok": False, "error": "already-sent-or-expired", "status": row["status"]}), 409

    # Resolve final content with backward compat
    final_verdict = (row["met_verdict"] or row["ai_verdict"] or "caution").strip()
    final_snippet = (row["met_snippet"] or row["ai_snippet"] or "").strip()
    legacy_body = (row["met_body"] or row["ai_body"] or "").strip()

    # New structured sections — fall back to legacy body for older drafts
    bottom_line = (row.get("bottom_line") or "").strip()
    weather_details = (row.get("weather_details") or "").strip()
    whats_ahead = (row.get("whats_ahead") or "").strip()
    image_url = (row.get("image_url") or "").strip()

    is_structured = bool(bottom_line or weather_details or whats_ahead)

    # If no structured content AND no legacy body — can't send empty
    if not is_structured and not legacy_body:
        return jsonify({"ok": False, "error": "empty-brief"}), 400

    met_name = user.get("name") or "Your meteorologist"
    location_label = row["location_label"] or "your location"
    now_ms = int(time.time() * 1000)

    # Accuracy refresh (June 2026): if the Met is sending the AI draft
    # untouched (no structured edits and the legacy body is still the AI
    # body), re-pull the forecast now so the brief reflects current numbers
    # rather than the night-before snapshot. If the Met wrote ANY of their
    # own content, we never touch it. We also persist the fresh AI content
    # and predictions onto the draft so the brief_history snapshot used for
    # accuracy grading matches what actually went out.
    _ai_body_txt = (row.get("ai_body") or "").strip()
    _met_body_txt = (row.get("met_body") or "").strip()
    _is_untouched_ai = (not is_structured) and (not _met_body_txt or _met_body_txt == _ai_body_txt)
    if (_is_untouched_ai and row.get("location_lat") is not None
            and row.get("location_lng") is not None):
        try:
            _fresh = _fetch_forecast(float(row["location_lat"]), float(row["location_lng"]))
            if _fresh:
                _rv, _rs, _rb = _generate_ai_brief(
                    location_label, _fresh, address=row.get("location_address") or "")
                if _rv != "suppress" and _rb:
                    final_verdict = (_rv or final_verdict).strip()
                    final_snippet = (_rs or final_snippet).strip()
                    legacy_body = (_rb or legacy_body).strip()
                    _p = _extract_predicted_values_from_forecast(_fresh)
                    with db() as conn:
                        with conn.cursor() as cur:
                            cur.execute(
                                """UPDATE pro_brief_drafts
                                   SET ai_verdict = %s, ai_snippet = %s, ai_body = %s,
                                       met_verdict = %s, met_snippet = %s, met_body = %s,
                                       predicted_high_f = %s, predicted_low_f = %s,
                                       predicted_precip_in = %s, predicted_max_wind_mph = %s
                                   WHERE id = %s""",
                                (_rv, _rs, _rb, _rv, _rs, _rb,
                                 _p.get("predicted_high_f"), _p.get("predicted_low_f"),
                                 _p.get("predicted_precip_in"), _p.get("predicted_max_wind_mph"),
                                 draft_id),
                            )
                    # Keep the in-memory row consistent for the rest of this send
                    row["predicted_high_f"] = _p.get("predicted_high_f")
                    row["predicted_low_f"] = _p.get("predicted_low_f")
                    row["predicted_precip_in"] = _p.get("predicted_precip_in")
                    row["predicted_max_wind_mph"] = _p.get("predicted_max_wind_mph")
        except Exception as e:
            print(f"[pro-brief-send] send-time refresh skipped for draft={draft_id}: {e}", flush=True)

    # Verdict label for display
    verdict_label = {
        "clear": "✓ CLEAR",
        "caution": "⚠ CAUTION",
        "risk": "⚠ RISK",
    }.get(final_verdict.lower(), final_verdict.upper())

    # Build the rich content. We do this BEFORE creating the access token
    # because we want to insert brief_history first to get its id.

    # Concatenated full body for brief_history / legacy compatibility
    # (so admin views, audit logs, search etc. all show useful content)
    if is_structured:
        full_body_parts = [
            f"TODAY'S CALL: {verdict_label}",
        ]
        if bottom_line:
            full_body_parts.append(f"\nBOTTOM LINE\n{bottom_line}")
        if weather_details:
            full_body_parts.append(f"\nWEATHER DETAILS\n{weather_details}")
        if whats_ahead:
            full_body_parts.append(f"\nWHAT'S AHEAD\n{whats_ahead}")
        full_body_parts.append(f"\n- {met_name}, WeatherValet")
        full_body = "\n".join(full_body_parts)
    else:
        full_body = legacy_body + f"\n\n- {met_name}, WeatherValet"

    # Write brief_history row first so we can attach the access token
    # Capture forecast predictions for accuracy grading.
    #
    # Phase 3 (May 26, 2026): Prefer the draft-time forecast snapshot
    # (stored in pro_brief_drafts) over a fresh send-time fetch. The
    # draft snapshot reflects what the Met actually saw when they
    # edited the brief — that's what should be graded against.
    #
    # If the draft predictions are NULL (older drafts pre-dating this
    # schema), fall back to send-time fetch (Phase 2 behavior).
    pro_preds = {
        "predicted_high_f": row.get("predicted_high_f"),
        "predicted_low_f": row.get("predicted_low_f"),
        "predicted_precip_in": (
            float(row["predicted_precip_in"])
            if row.get("predicted_precip_in") is not None else None
        ),
        "predicted_max_wind_mph": row.get("predicted_max_wind_mph"),
    }
    have_draft_preds = any(v is not None for v in pro_preds.values())
    if not have_draft_preds:
        # Fallback for older drafts: fetch forecast now.
        try:
            if row.get("location_lat") is not None and row.get("location_lng") is not None:
                pro_forecast = _fetch_forecast(
                    float(row["location_lat"]), float(row["location_lng"])
                )
                pro_preds = _extract_predicted_values_from_forecast(pro_forecast)
        except Exception as e:
            print(f"[pro-brief-send] fallback forecast fetch failed (non-fatal): {e}", flush=True)

    history_id = None
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO brief_history
                       (user_id, brief_type, delivered_at, verdict, snippet,
                        full_body, delivery_status, channels_used,
                        is_met_touched, met_name,
                        predicted_high_f, predicted_low_f,
                        predicted_precip_in, predicted_max_wind_mph)
                       VALUES (%s, %s, %s, %s, %s, %s, %s, %s, TRUE, %s,
                               %s, %s, %s, %s)
                       RETURNING id""",
                    (row["user_id"], row["brief_type"], now_ms, final_verdict,
                     bottom_line[:200] if bottom_line else (final_snippet or legacy_body[:140]),
                     full_body, "pending", "", met_name,
                     pro_preds.get("predicted_high_f"),
                     pro_preds.get("predicted_low_f"),
                     pro_preds.get("predicted_precip_in"),
                     pro_preds.get("predicted_max_wind_mph")),
                )
                history_id = cur.fetchone()["id"]
    except Exception as e:
        print(f"[pro-brief-send] history insert failed: {e}", flush=True)
        return jsonify({"ok": False, "error": "history-insert-failed"}), 500

    # Create a brief access token for the web view
    access_token = secrets.token_urlsafe(24)
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO brief_access_tokens
                       (token, history_id, subscriber_user_id, created_at_ms)
                       VALUES (%s, %s, %s, %s)""",
                    (access_token, history_id, row["user_id"], now_ms),
                )
    except Exception as e:
        print(f"[pro-brief-send] token insert failed: {e}", flush=True)
        # Continue anyway — SMS/email still ships, just no web view link

    frontend_base = os.environ.get("FRONTEND_BASE_URL") or os.environ.get("PUBLIC_BASE_URL") or "https://weathervalet.ai"
    if frontend_base.endswith("/"):
        frontend_base = frontend_base[:-1]
    web_url = f"{frontend_base}/brief/{access_token}"

    # Dispatch through the channels the subscriber configured (snapshot)
    channels = [ch for ch in (row["channels"] or "").split(",") if ch]
    channels_used = []
    any_success = False

    for ch in channels:
        if ch == "sms" and row["sub_phone"]:
            # SMS = short. Verdict + truncated bottom line + link to web view.
            # Goal: keeps under 2 SMS segments (320 chars) typically.
            if is_structured and bottom_line:
                sms_intro = bottom_line[:140].rstrip()
                if len(bottom_line) > 140:
                    sms_intro = sms_intro.rsplit(" ", 1)[0] + "…"
                sms_text = (
                    f"{verdict_label} · WeatherValet\n\n"
                    f"{sms_intro}\n\n"
                    f"Full brief: {web_url}\n- {met_name}"
                )
            else:
                # Legacy fallback
                sms_text = (final_snippet or legacy_body[:140]) + f"\n\nFull: {web_url}\n- {met_name}"
            try:
                _media = [image_url] if image_url.startswith("http") else None
                if send_sms(row["sub_phone"], sms_text, media_url=_media):
                    channels_used.append("sms")
                    any_success = True
            except Exception as e:
                print(f"[pro-brief-send] SMS failed user={row['user_id']}: {e}", flush=True)
        elif ch == "email" and row["sub_email"]:
            # Phase 3 (May 22, 2026): smart subject + reply-to-Met.
            smart_label = _smart_location_label(
                row.get("location_label") or "",
                row.get("location_address") or "")
            subject = f"Your WeatherValet brief, {smart_label}"
            reply_to = _get_subscriber_reply_to_email(row["user_id"])
            try:
                # Build rich HTML email for structured briefs
                if is_structured:
                    html_body = _render_pro_brief_email_html(
                        verdict=final_verdict,
                        verdict_label=verdict_label,
                        bottom_line=bottom_line,
                        weather_details=weather_details,
                        whats_ahead=whats_ahead,
                        image_url=image_url,
                        met_name=met_name,
                        location_label=smart_label,
                        subscriber_name=row.get("sub_name") or "",
                        web_url=web_url,
                    )
                    if _send_brief_email(row["sub_email"], subject, html_body, html=True, reply_to=reply_to):
                        channels_used.append("email")
                        any_success = True
                else:
                    # Legacy plain-text email
                    if _send_brief_email(row["sub_email"], subject, full_body, reply_to=reply_to):
                        channels_used.append("email")
                        any_success = True
            except Exception as e:
                print(f"[pro-brief-send] email failed user={row['user_id']}: {e}", flush=True)

    delivery_status = "sent" if any_success else "failed"

    # Update brief_history delivery_status + channels_used
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE brief_history
                       SET delivery_status = %s, channels_used = %s
                       WHERE id = %s""",
                    (delivery_status, ",".join(channels_used), history_id),
                )
    except Exception as e:
        print(f"[pro-brief-send] history update failed: {e}", flush=True)

    # Update the draft
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE pro_brief_drafts
                   SET status = 'sent', sent_at = %s, sent_by_user_id = %s,
                       sent_by_name = %s, final_verdict = %s, final_body = %s,
                       history_id = %s
                   WHERE id = %s""",
                (now_ms, user["id"], met_name, final_verdict, full_body,
                 history_id, draft_id),
            )

    print(
        f"[pro-brief-send] draft={draft_id} sent by met={user['id']} "
        f"channels={channels_used} status={delivery_status} "
        f"structured={is_structured} token={access_token[:8]}…",
        flush=True,
    )

    # Phase 11 Phase 2 (May 17): Mark today's daily_brief_task as sent
    # for this subscriber. Best effort — task tracking is separate
    # from the actual send.
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT user_id FROM pro_brief_drafts WHERE id = %s""",
                    (draft_id,),
                )
                drow = cur.fetchone()
                if drow and drow.get("user_id"):
                    subscriber_id = drow["user_id"]
                    # Get subscriber's local date
                    cur.execute(
                        """SELECT daily_brief_timezone
                           FROM subscriber_coverage WHERE user_id = %s""",
                        (subscriber_id,),
                    )
                    cov_row = cur.fetchone()
                    tz_name = (cov_row or {}).get("daily_brief_timezone") or "America/New_York"
                    try:
                        sub_tz = ZoneInfo(tz_name)
                    except Exception:
                        sub_tz = ZoneInfo("America/New_York")
                    local_date_str = datetime.now(sub_tz).strftime("%Y-%m-%d")
                    cur.execute(
                        """UPDATE daily_brief_tasks
                           SET sent_at_ms = %s, status = 'sent'
                           WHERE subscriber_user_id = %s
                             AND task_date = %s
                             AND status != 'sent'""",
                        (now_ms, subscriber_id, local_date_str),
                    )
    except Exception as e:
        print(f"[pro-brief-send] task mark-sent failed (non-fatal): {e}", flush=True)

    # ───────────────────────────────────────────────────────────────
    # Multi-send (May 17, 2026): if the Met selected additional
    # subscribers in the editor sidebar, send the same brief content
    # to each of them now.
    #
    # Trust model: per Chris's feedback (May 17), we trust Mets to use
    # this responsibly. Rosie will monitor multi-send patterns over time
    # and flag suspicious bulk-sends (Phase 2 post-launch).
    #
    # Each additional recipient gets:
    #   - Their own brief_history row (with their primary Met's name)
    #   - Their own access token + web view URL
    #   - SMS + email via THEIR channel preferences (not the original sub's)
    # ───────────────────────────────────────────────────────────────
    additional_user_ids = []
    try:
        body_data = request.get_json(silent=True) or {}
        raw = body_data.get("additional_recipients") or []
        if isinstance(raw, list):
            # Sanitize: must be ints, must not include the original draft user
            seen = set([row["user_id"]])
            for uid in raw:
                try:
                    uid_int = int(uid)
                    if uid_int not in seen:
                        additional_user_ids.append(uid_int)
                        seen.add(uid_int)
                except (TypeError, ValueError):
                    continue
        # Hard cap to prevent abuse: max 50 additional recipients per send
        if len(additional_user_ids) > 50:
            additional_user_ids = additional_user_ids[:50]
    except Exception as e:
        print(f"[pro-brief-send] multi-send parse failed: {e}", flush=True)

    # ── Pro Multi team member auto-include (May 20, 2026) ─────────────
    # If the primary subscriber is on Pro Multi tier, automatically fan
    # out the brief to all ACTIVE team members. Met doesn't have to
    # remember to check team membership — system does it.
    #
    # We use the same 'seen' set so we don't duplicate if the Met also
    # manually selected a team member via the multisend list.
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT pmm.member_user_id
                       FROM pro_multi_memberships pmm
                       JOIN users primary_u ON primary_u.id = pmm.primary_user_id
                       WHERE pmm.primary_user_id = %s
                         AND pmm.status = 'active'
                         AND primary_u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')""",
                    (row["user_id"],),
                )
                team_rows = cur.fetchall()
                seen_set = set([row["user_id"]] + additional_user_ids)
                for t in team_rows:
                    if t["member_user_id"] not in seen_set:
                        additional_user_ids.append(t["member_user_id"])
                        seen_set.add(t["member_user_id"])
                if team_rows:
                    print(
                        f"[pro-brief-send] auto-included {len(team_rows)} "
                        f"team members for primary user={row['user_id']}",
                        flush=True,
                    )
    except Exception as e:
        print(f"[pro-brief-send] team auto-include failed: {e!r}", flush=True)

    multi_results = []
    for extra_user_id in additional_user_ids:
        try:
            # Verify the extra recipient is a Pro-tier subscriber for whom
            # the calling Met is the assigned primary (or admin override).
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT u.id, u.email, u.phone, u.name,
                                  u.subscription_tier,
                                  bp.channels,
                                  sc.primary_met_id,
                                  loc.label AS loc_label,
                                  loc.address_text AS loc_address,
                                  loc.lat AS loc_lat,
                                  loc.lng AS loc_lng
                           FROM users u
                           LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                           LEFT JOIN subscriber_coverage sc ON sc.user_id = u.id
                           LEFT JOIN saved_locations loc
                                ON loc.user_id = u.id AND loc.is_primary = TRUE
                           WHERE u.id = %s AND u.is_active = TRUE""",
                        (extra_user_id,),
                    )
                    sub = cur.fetchone()

            if not sub:
                multi_results.append({"user_id": extra_user_id, "ok": False, "error": "not-found"})
                continue

            # Check if this extra_user_id is a team member of the primary
            # (row["user_id"] is the primary subscriber for this brief).
            # Team members inherit Pro Multi eligibility + Met assignment
            # from the primary, so they pass tier + auth checks via the
            # membership row.
            is_team_member = False
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT 1 FROM pro_multi_memberships
                               WHERE primary_user_id = %s
                                 AND member_user_id = %s
                                 AND status = 'active'
                               LIMIT 1""",
                            (row["user_id"], extra_user_id),
                        )
                        is_team_member = cur.fetchone() is not None
            except Exception as e:
                print(f"[pro-brief-send] team check failed: {e!r}", flush=True)

            # Only Pro-tier eligible (team members bypass this check —
            # they inherit eligibility from the primary)
            if not is_team_member:
                if (sub.get("subscription_tier") or "") not in ("pro_single", "pro_multi", "pro_enterprise"):
                    multi_results.append({"user_id": extra_user_id, "ok": False, "error": "not-pro-tier"})
                    continue
            # Authorization: calling Met must be the primary for this sub,
            # OR be an admin, OR this is a team member of the primary.
            # Team members inherit Met assignment from the primary.
            is_admin = "admin" in (user.get("roles") or [])
            if not is_admin and not is_team_member and sub.get("primary_met_id") != user["id"]:
                multi_results.append({"user_id": extra_user_id, "ok": False, "error": "not-your-subscriber"})
                continue

            # Insert brief_history for this recipient
            sub_loc_label = sub.get("loc_label") or "your location"

            # Capture forecast predictions for this extra subscriber's
            # location (each has their own — same brief body but
            # different observation points). Best-effort, non-fatal.
            extra_forecast = None
            try:
                if sub.get("loc_lat") is not None and sub.get("loc_lng") is not None:
                    extra_forecast = _fetch_forecast(
                        float(sub["loc_lat"]), float(sub["loc_lng"])
                    )
            except Exception as e:
                print(f"[pro-brief-send] extra forecast fetch failed user={extra_user_id}: {e}", flush=True)
            extra_preds = _extract_predicted_values_from_forecast(extra_forecast)

            extra_hist_id = None
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO brief_history
                           (user_id, brief_type, delivered_at, verdict, snippet,
                            full_body, delivery_status, channels_used,
                            is_met_touched, met_name,
                            predicted_high_f, predicted_low_f,
                            predicted_precip_in, predicted_max_wind_mph)
                           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, TRUE, %s,
                                   %s, %s, %s, %s)
                           RETURNING id""",
                        (extra_user_id, row["brief_type"], int(time.time() * 1000),
                         final_verdict,
                         bottom_line[:200] if bottom_line else (final_snippet or legacy_body[:140]),
                         full_body, "pending", "", met_name,
                         extra_preds.get("predicted_high_f"),
                         extra_preds.get("predicted_low_f"),
                         extra_preds.get("predicted_precip_in"),
                         extra_preds.get("predicted_max_wind_mph")),
                    )
                    extra_hist_id = cur.fetchone()["id"]

            # Create access token
            extra_token = secrets.token_urlsafe(24)
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """INSERT INTO brief_access_tokens
                               (token, history_id, subscriber_user_id, created_at_ms)
                               VALUES (%s, %s, %s, %s)""",
                            (extra_token, extra_hist_id, extra_user_id, int(time.time() * 1000)),
                        )
            except Exception as e:
                print(f"[pro-brief-send] multi token insert failed user={extra_user_id}: {e}", flush=True)

            extra_web_url = f"{frontend_base}/brief/{extra_token}"

            # Dispatch via this subscriber's preferred channels
            extra_channels = [ch for ch in (sub.get("channels") or "sms,email").split(",") if ch]
            extra_channels_used = []
            extra_any_success = False

            for ch in extra_channels:
                if ch == "sms" and sub.get("phone"):
                    if is_structured and bottom_line:
                        sms_intro = bottom_line[:140].rstrip()
                        if len(bottom_line) > 140:
                            sms_intro = sms_intro.rsplit(" ", 1)[0] + "…"
                        extra_sms = (
                            f"{verdict_label} · WeatherValet\n\n"
                            f"{sms_intro}\n\n"
                            f"Full brief: {extra_web_url}\n- {met_name}"
                        )
                    else:
                        extra_sms = (final_snippet or legacy_body[:140]) + f"\n\nFull: {extra_web_url}\n- {met_name}"
                    try:
                        if send_sms(sub["phone"], extra_sms):
                            extra_channels_used.append("sms")
                            extra_any_success = True
                    except Exception as e:
                        print(f"[pro-brief-send] multi SMS failed user={extra_user_id}: {e}", flush=True)
                elif ch == "email" and sub.get("email"):
                    # Phase 3 (May 22, 2026): smart subject + reply-to-Met.
                    sub_smart_label = _smart_location_label(
                        sub.get("loc_label") or "",
                        sub.get("loc_address") or "")
                    extra_subject = f"Your WeatherValet brief, {sub_smart_label}"
                    extra_reply_to = _get_subscriber_reply_to_email(extra_user_id)
                    try:
                        if is_structured:
                            extra_html = _render_pro_brief_email_html(
                                verdict=final_verdict,
                                verdict_label=verdict_label,
                                bottom_line=bottom_line,
                                weather_details=weather_details,
                                whats_ahead=whats_ahead,
                                image_url=image_url,
                                met_name=met_name,
                                location_label=sub_smart_label,
                                subscriber_name=sub.get("name") or "",
                                web_url=extra_web_url,
                            )
                            if _send_brief_email(sub["email"], extra_subject, extra_html, html=True, reply_to=extra_reply_to):
                                extra_channels_used.append("email")
                                extra_any_success = True
                        else:
                            if _send_brief_email(sub["email"], extra_subject, full_body, reply_to=extra_reply_to):
                                extra_channels_used.append("email")
                                extra_any_success = True
                    except Exception as e:
                        print(f"[pro-brief-send] multi email failed user={extra_user_id}: {e}", flush=True)

            extra_delivery_status = "sent" if extra_any_success else "failed"

            # Update brief_history with delivery result
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """UPDATE brief_history
                               SET delivery_status = %s, channels_used = %s
                               WHERE id = %s""",
                            (extra_delivery_status, ",".join(extra_channels_used), extra_hist_id),
                        )
            except Exception as e:
                print(f"[pro-brief-send] multi hist update failed: {e}", flush=True)

            # Also try to mark the daily_brief_task as sent if one exists
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT daily_brief_timezone FROM subscriber_coverage
                               WHERE user_id = %s""",
                            (extra_user_id,),
                        )
                        tzr = cur.fetchone()
                        extra_tz_name = (tzr or {}).get("daily_brief_timezone") or "America/New_York"
                        try:
                            etz = ZoneInfo(extra_tz_name)
                        except Exception:
                            etz = ZoneInfo("America/New_York")
                        extra_date_str = datetime.now(etz).strftime("%Y-%m-%d")
                        cur.execute(
                            """UPDATE daily_brief_tasks
                               SET sent_at_ms = %s, status = 'sent'
                               WHERE subscriber_user_id = %s
                                 AND task_date = %s
                                 AND status != 'sent'""",
                            (int(time.time() * 1000), extra_user_id, extra_date_str),
                        )
            except Exception as e:
                print(f"[pro-brief-send] multi task mark failed: {e}", flush=True)

            multi_results.append({
                "user_id": extra_user_id,
                "ok": extra_any_success,
                "channels_used": extra_channels_used,
                "history_id": extra_hist_id,
            })
            print(
                f"[pro-brief-send] multi-send draft={draft_id} -> user={extra_user_id} "
                f"channels={extra_channels_used} status={extra_delivery_status}",
                flush=True,
            )

            # Phase 3 (May 22, 2026): rate-limit pacing for Resend.
            # Pause briefly between sends if email actually went out, to
            # stay under Resend's 10/sec limit on large multi-sends.
            if "email" in extra_channels_used:
                time.sleep(0.11)

        except Exception as e:
            print(f"[pro-brief-send] multi-send failed user={extra_user_id}: {e}", flush=True)
            multi_results.append({"user_id": extra_user_id, "ok": False, "error": "exception"})

    return jsonify({
        "ok": True,
        "channels_used": channels_used,
        "delivery_status": delivery_status,
        "history_id": history_id,
        "multi_results": multi_results,
        "multi_count": len([r for r in multi_results if r.get("ok")]),
    })


# ════════════════════════════════════════════════════════════════════
# Ad-hoc Weather Update — Met composes & sends anytime (May 22, 2026)
# ════════════════════════════════════════════════════════════════════
#
# Mets can compose and send a weather update to any subscriber they
# have visibility for (primary or covering today), 24/7. Used when
# weather changes mid-day and the subscriber needs a heads-up.
#
# Does NOT count toward payroll — only morning briefs earn the daily
# commission. This is a value-add capability for the team.
#
# Creates a row in pro_brief_drafts with brief_type='update', sends
# immediately via SMS+email, marks status='sent'. The subscriber sees
# subject "Weather Update — [location]" so they know it's not the
# daily morning brief.

@app.route("/api/v1/met/pro-briefs/compose-update", methods=["OPTIONS"])
def _met_pro_brief_compose_update_preflight():
    return ("", 204)


@app.post("/api/v1/met/pro-briefs/compose-update")
def met_pro_brief_compose_update():
    """Compose and immediately send an ad-hoc weather update.

    Body:
      user_id (int)         — subscriber to send to
      verdict (str)         — 'clear' | 'caution' | 'risk'
      snippet (str)         — short headline (also SMS body)
      body (str)            — full update text (email body)
      channels (list[str])  — optional override; default uses subscriber's prefs

    Visibility: caller must be the subscriber's primary Met OR a covering
    Met for today OR an admin. Returns 404 if not visible (to avoid
    leaking existence).
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    is_admin = "admin" in roles
    me_id = user["id"]

    data = request.get_json(silent=True) or {}
    target_user_id = data.get("user_id")
    try:
        target_user_id = int(target_user_id)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "invalid-user-id"}), 400

    verdict = (data.get("verdict") or "caution").strip().lower()
    if verdict not in ("clear", "caution", "risk"):
        return jsonify({"ok": False, "error": "invalid-verdict"}), 400
    snippet = (data.get("snippet") or "").strip()
    body_text = (data.get("body") or "").strip()
    image_url = (data.get("image_url") or "").strip()
    if image_url.startswith("http"):
        image_url = _mirror_external_image(image_url, user["id"]) or image_url
    if not snippet and not body_text:
        return jsonify({"ok": False, "error": "empty-update",
                        "message": "Provide a snippet or body."}), 400

    # Visibility check: same logic as Pro Brief queue. We reuse the
    # _can_met_see_pro_brief pattern but for an arbitrary user_id (no
    # draft yet). Inline the SQL since the helper expects a draft_id.
    ET = ZoneInfo("America/New_York")
    today_et = datetime.now(ET).date().isoformat()
    if not is_admin:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT 1
                       FROM subscriber_coverage sc
                       LEFT JOIN met_territories t ON t.met_user_id = sc.primary_met_id
                       LEFT JOIN shift_assignments sa
                            ON sa.territory_id = t.id
                           AND sa.met_user_id = %s
                           AND sa.is_drop = FALSE
                           AND sa.shift_date = ANY(%s)
                       WHERE sc.user_id = %s
                         AND (sc.primary_met_id = %s OR sa.id IS NOT NULL)
                       LIMIT 1""",
                    (me_id, _met_coverage_shift_dates(), target_user_id, me_id),
                )
                visible = cur.fetchone() is not None
        if not visible:
            return jsonify({"ok": False, "error": "not-found"}), 404

    # Pull subscriber details for sending
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.email, u.name, u.phone, u.subscription_tier,
                          bp.channels,
                          loc.label AS loc_label, loc.address_text AS loc_address,
                          loc.lat, loc.lng
                   FROM users u
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   LEFT JOIN saved_locations loc
                        ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE u.id = %s AND u.is_active = TRUE""",
                (target_user_id,),
            )
            sub = cur.fetchone()
    if not sub:
        return jsonify({"ok": False, "error": "subscriber-not-found"}), 404

    location_label = sub["loc_label"] or sub["loc_address"] or "your location"
    channels_override = data.get("channels")
    if channels_override and isinstance(channels_override, list):
        channels = [c for c in channels_override if c in ("sms", "email")]
    else:
        channels = [c for c in (sub["channels"] or "sms,email").split(",") if c]

    # Send via channels. Subject: "Weather Update — [location]"
    # Phase 3 (May 22, 2026): smart subject + reply-to-Met.
    smart_label = _smart_location_label(
        sub.get("loc_label") or "",
        sub.get("loc_address") or "")
    channels_used = []
    any_success = False
    update_subject = f"Weather Update — {smart_label}"
    update_reply_to = _get_subscriber_reply_to_email(target_user_id)
    for ch in channels:
        if ch == "sms" and sub["phone"]:
            sms_text = "WeatherValet Update: " + (snippet or body_text[:140])
            if body_text and len(snippet) + len(body_text) < 1200:
                sms_text = sms_text + "\n\n" + body_text[:1200]
            _media = [image_url] if image_url.startswith("http") else None
            ok = send_sms(sub["phone"], sms_text, media_url=_media)
            if ok:
                channels_used.append("sms")
                any_success = True
        elif ch == "email" and sub["email"]:
            email_body_html = (body_text or snippet).replace("\n", "<br>")
            _img_html = (f"<p><img src='{image_url}' alt='' style='max-width:100%;border-radius:8px;'></p>"
                         if image_url.startswith("http") else "")
            email_body_full = (
                f"<p><strong>{snippet}</strong></p>"
                f"<p>{email_body_html}</p>"
                f"{_img_html}"
                f"<p style='color:#666;font-size:12px;'>Sent by your meteorologist via WeatherValet.</p>"
            )
            ok = _send_brief_email(sub["email"], update_subject, email_body_full, reply_to=update_reply_to)
            if ok:
                channels_used.append("email")
                any_success = True

    if not any_success:
        return jsonify({"ok": False, "error": "send-failed",
                        "message": "Could not deliver via any channel."}), 502

    # Record the update as a draft row with brief_type='update'. Status='sent'.
    # This makes it visible in the Met queue's "recently sent" view and in
    # the subscriber's brief history. It is NOT counted in payroll because
    # _compute_payroll_for_month filters on brief_type='sent' AND looks at
    # daily_brief_tasks (Hobbyist) or pro_brief_drafts where brief_type='morning'.
    now_ms = int(time.time() * 1000)
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO pro_brief_drafts
                         (user_id, brief_type, created_at, window_end_at, status,
                          user_tier, location_label, location_lat, location_lng,
                          channels, ai_verdict, ai_snippet, ai_body,
                          met_verdict, met_snippet, met_body,
                          sent_at, sent_by_user_id, sent_by_name, final_verdict, final_body)
                       VALUES (%s, 'update', %s, %s, 'sent',
                               %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                               %s, %s, %s, %s, %s)
                       RETURNING id""",
                    (target_user_id, now_ms, now_ms,
                     sub["subscription_tier"] or "hobbyist",
                     location_label,
                     float(sub["lat"]) if sub["lat"] else 0.0,
                     float(sub["lng"]) if sub["lng"] else 0.0,
                     ",".join(channels_used),
                     verdict, snippet, body_text,
                     verdict, snippet, body_text,
                     now_ms, me_id, user.get("name") or user.get("email") or "Met",
                     verdict, body_text),
                )
                draft_id = cur.fetchone()["id"]
    except Exception as e:
        print(f"[compose-update] draft insert failed: {e}", flush=True)
        # Don't return error to user — the update was successfully sent.
        # Just log the bookkeeping miss.
        draft_id = None

    print(
        f"[compose-update] met_user_id={me_id} target_user_id={target_user_id} "
        f"channels={channels_used} verdict={verdict} draft_id={draft_id}",
        flush=True,
    )
    return jsonify({
        "ok": True,
        "channels_used": channels_used,
        "draft_id": draft_id,
    })


# ════════════════════════════════════════════════════════════════════
# NWS severe alert page review (Phase 10 Item #7)
# ════════════════════════════════════════════════════════════════════
#
# Met taps the SMS link, lands on /?nws-page=<token>. Frontend calls
# GET to load context. Met decides:
#   - Confirm → POST /confirm with custom subscriber message →
#     subscribers get SMS + email
#   - Dismiss → POST /dismiss (false alarm / not actionable)
#
# Auth model is the same as the Crew mission response page: the token
# IS the authentication. It was sent only to the Met's phone via SMS.

@app.route("/api/v1/nws/page/<response_token>", methods=["OPTIONS"])
def _nws_page_preflight(response_token):
    return ("", 204)


@app.get("/api/v1/met/nws/pending")
def met_nws_pending():
    """Backstop for the SMS page: list the severe-alert pages still awaiting
    THIS Met's review, so they can see and send even if the SMS never
    arrived. A page is "theirs" if any affected subscriber is assigned to
    them (subscriber_coverage.primary_met_id). Only status='paged' (not yet
    confirmed/dismissed) and not expired are returned.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    met_id = user["id"]
    is_admin = "admin" in roles
    now_ms = int(time.time() * 1000)

    with db() as conn:
        with conn.cursor() as cur:
            # Recent, still-open pages. Cap the window so this stays cheap.
            cur.execute(
                """SELECT id, nws_alert_id, event, severity, area_desc,
                          response_token, affected_user_ids, created_at, expires_at
                   FROM nws_alert_pages
                   WHERE status = 'paged'
                     AND (expires_at IS NULL OR expires_at > %s)
                   ORDER BY created_at DESC
                   LIMIT 50""",
                (now_ms,),
            )
            pages = cur.fetchall()

            out = []
            for p in pages:
                ids = []
                if p["affected_user_ids"]:
                    try:
                        ids = [int(x) for x in p["affected_user_ids"].split(",") if x.strip()]
                    except ValueError:
                        ids = []
                if not ids:
                    continue
                # Surface this page to any Met who could act on it, regardless
                # of where they're logged in (June 2026 fix): the primary OR
                # backup Met for an affected subscriber, ANY Met when affected
                # subscribers have no assigned Met (orphans page the whole
                # roster), and admins (who see everything).
                placeholders = ",".join(["%s"] * len(ids))
                cur.execute(
                    f"""SELECT
                          COUNT(*) FILTER (
                            WHERE cov.primary_met_id = %s OR cov.backup_met_id = %s
                          ) AS mine,
                          COUNT(*) FILTER (WHERE cov.primary_met_id IS NOT NULL) AS has_primary
                        FROM subscriber_coverage cov
                        WHERE cov.user_id IN ({placeholders})""",
                    tuple([met_id, met_id] + ids),
                )
                row = cur.fetchone()
                mine = (row["mine"] if row else 0) or 0
                has_primary = (row["has_primary"] if row else 0) or 0
                orphan = len(ids) - has_primary
                if not (is_admin or mine > 0 or orphan > 0):
                    continue
                shown = len(ids) if is_admin else (mine + orphan)
                out.append({
                    "token": p["response_token"],
                    "event": p["event"] or "",
                    "severity": p["severity"] or "",
                    "area_desc": p["area_desc"] or "",
                    "my_affected": shown,
                    "created_at": p["created_at"],
                    "expires_at": p["expires_at"],
                })

    return jsonify({"ok": True, "pending": out})


@app.get("/api/v1/nws/page/<response_token>")
def nws_page_get(response_token: str):
    """Return the alert details + list of affected subscribers for the
    Met to review. No auth required — the token is the auth.
    """
    if not response_token or len(response_token) < 10:
        return jsonify({"ok": False, "error": "invalid-token"}), 400

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT * FROM nws_alert_pages WHERE response_token = %s""",
                (response_token,),
            )
            page = cur.fetchone()
    if not page:
        return jsonify({"ok": False, "error": "not-found"}), 404

    # Resolve affected user info from the CSV
    affected_user_ids = []
    if page["affected_user_ids"]:
        try:
            affected_user_ids = [
                int(x) for x in page["affected_user_ids"].split(",") if x.strip()
            ]
        except ValueError:
            affected_user_ids = []

    subscribers = []
    if affected_user_ids:
        placeholders = ",".join(["%s"] * len(affected_user_ids))
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""SELECT u.id, u.name, u.email, u.phone,
                              u.subscription_tier,
                              loc.label AS loc_label
                       FROM users u
                       LEFT JOIN saved_locations loc
                         ON loc.user_id = u.id AND loc.is_primary = TRUE
                       WHERE u.id IN ({placeholders})""",
                    tuple(affected_user_ids),
                )
                rows = cur.fetchall()
        for r in rows:
            subscribers.append({
                "id": r["id"],
                "name": r.get("name") or "",
                "email": r["email"],
                "phone": r.get("phone") or "",
                "tier": r["subscription_tier"],
                "location": r.get("loc_label") or "",
            })

    return jsonify({
        "ok": True,
        "page": {
            "id": page["id"],
            "created_at": page["created_at"],
            "event": page["event"],
            "severity": page["severity"],
            "headline": page["headline"],
            "description": page["description"],
            "instruction": page["instruction"],
            "area_desc": page["area_desc"],
            "expires_at": page["expires_at"],
            "status": page["status"],
            "reviewed_at": page["reviewed_at"],
            "reviewed_by_name": page["reviewed_by_name"],
            "subscriber_message": page["subscriber_message"],
            "subscribers_notified": page["subscribers_notified"],
        },
        "subscribers": subscribers,
    })


@app.post("/api/v1/nws/page/<response_token>/confirm")
def nws_page_confirm(response_token: str):
    """Met confirms the alert and sends a custom message to all affected
    Pro subscribers via SMS + email.

    Body:
      {
        "message": "Tornado Warning active for Lebanon area until 4:30pm. Get to interior shelter NOW.",
        "met_name": "Michael Reynolds"  (optional override; defaults to "On-duty Met")
      }

    Auth: requires the response_token in URL. The Met doesn't need to be
    logged in (they tapped the SMS link from their phone), but we use
    their logged-in name if available.
    """
    if not response_token or len(response_token) < 10:
        return jsonify({"ok": False, "error": "invalid-token"}), 400

    data = request.get_json(silent=True) or {}
    message = (data.get("message") or "").strip()
    if not message:
        return jsonify({"ok": False, "error": "message-required"}), 400
    if len(message) > 1000:
        return jsonify({"ok": False, "error": "message-too-long"}), 400

    # If signed in, use their real name + user_id for audit
    actor = _get_current_user()
    met_name = (
        (data.get("met_name") or "").strip()
        or (actor.get("name") if actor else None)
        or "On-duty meteorologist"
    )
    met_user_id = actor["id"] if actor else None

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM nws_alert_pages WHERE response_token = %s",
                (response_token,),
            )
            page = cur.fetchone()
    if not page:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if page["status"] not in ("paged",):
        return jsonify({
            "ok": False,
            "error": "already-handled",
            "status": page["status"],
        }), 409

    # Resolve affected subscribers
    affected_user_ids = []
    if page["affected_user_ids"]:
        try:
            affected_user_ids = [
                int(x) for x in page["affected_user_ids"].split(",") if x.strip()
            ]
        except ValueError:
            pass

    if not affected_user_ids:
        # Nothing to send — mark confirmed but with 0 sent
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE nws_alert_pages
                       SET status = 'confirmed', reviewed_at = %s,
                           reviewed_by_user_id = %s, reviewed_by_name = %s,
                           subscriber_message = %s, subscribers_notified = 0
                       WHERE id = %s""",
                    (int(time.time() * 1000), met_user_id, met_name, message, page["id"]),
                )
        return jsonify({"ok": True, "subscribers_notified": 0})

    # Fetch contact info for each affected user
    placeholders = ",".join(["%s"] * len(affected_user_ids))
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""SELECT u.id, u.name, u.email, u.phone
                   FROM users u
                   WHERE u.id IN ({placeholders}) AND u.is_active = TRUE""",
                tuple(affected_user_ids),
            )
            subs = cur.fetchall()

    # Compose the SMS body (160-char-friendly) and the email body
    sms_body = (
        f"WeatherValet ALERT ({page['event']}): {message}\n"
        f"- {met_name}\n"
        f"Reply STOP to opt out."
    )
    email_subject = f"WeatherValet alert: {page['event']}"
    email_body = (
        f"{page['event']}\n\n"
        f"{message}\n\n"
        f"- {met_name}\n"
        f"WeatherValet on-duty meteorologist\n\n"
        f"Affected area: {page['area_desc']}\n"
        f"NWS headline: {page['headline']}\n"
    )

    sent_count = 0
    for s in subs:
        any_channel = False
        if s.get("phone"):
            try:
                if send_sms(s["phone"], sms_body):
                    any_channel = True
            except Exception as e:
                print(f"[nws-confirm] SMS failed user={s['id']}: {e}", flush=True)
        if s.get("email"):
            try:
                # Phase 3 (May 22, 2026): reply-to goes to the Met who
                # sent this NWS confirmation. Falls back gracefully if
                # the Met isn't signed in (no actor) → uses the From:
                # default (hello@weathervalet.ai) which forwards to a human.
                nws_reply_to = actor.get("email") if actor else None
                if _send_brief_email(s["email"], email_subject, email_body, reply_to=nws_reply_to):
                    any_channel = True
            except Exception as e:
                print(f"[nws-confirm] email failed user={s['id']}: {e}", flush=True)
        if any_channel:
            sent_count += 1

    # Mark page as confirmed
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE nws_alert_pages
                   SET status = 'confirmed', reviewed_at = %s,
                       reviewed_by_user_id = %s, reviewed_by_name = %s,
                       subscriber_message = %s, subscribers_notified = %s
                   WHERE id = %s""",
                (int(time.time() * 1000), met_user_id, met_name,
                 message, sent_count, page["id"]),
            )

    # Audit log if we have a logged-in actor
    if actor:
        try:
            _audit_log(
                actor_user_id=met_user_id, actor_name=met_name,
                action="nws.confirm", target_type="nws_alert_page",
                target_id=page["id"],
                details={
                    "event": page["event"],
                    "subscribers_notified": sent_count,
                    "affected_total": len(affected_user_ids),
                },
            )
        except Exception:
            pass

    print(
        f"[nws-confirm] page_id={page['id']} confirmed by met={met_name} "
        f"sent={sent_count}/{len(affected_user_ids)}",
        flush=True,
    )
    return jsonify({"ok": True, "subscribers_notified": sent_count})


@app.post("/api/v1/nws/page/<response_token>/dismiss")
def nws_page_dismiss(response_token: str):
    """Met dismisses the alert (false alarm, already-known, out-of-scope).
    No subscriber notification.

    Body:
      {"reason": "Already escalated by NWS via Wireless Emergency Alerts"}
    """
    if not response_token or len(response_token) < 10:
        return jsonify({"ok": False, "error": "invalid-token"}), 400

    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip() or None

    actor = _get_current_user()
    met_name = (
        (actor.get("name") if actor else None)
        or "On-duty meteorologist"
    )
    met_user_id = actor["id"] if actor else None

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, status FROM nws_alert_pages WHERE response_token = %s",
                (response_token,),
            )
            page = cur.fetchone()
    if not page:
        return jsonify({"ok": False, "error": "not-found"}), 404
    if page["status"] not in ("paged",):
        return jsonify({
            "ok": False,
            "error": "already-handled",
            "status": page["status"],
        }), 409

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE nws_alert_pages
                   SET status = 'dismissed', reviewed_at = %s,
                       reviewed_by_user_id = %s, reviewed_by_name = %s,
                       subscriber_message = %s
                   WHERE id = %s""",
                (int(time.time() * 1000), met_user_id, met_name,
                 reason, page["id"]),
            )

    if actor:
        try:
            _audit_log(
                actor_user_id=met_user_id, actor_name=met_name,
                action="nws.dismiss", target_type="nws_alert_page",
                target_id=page["id"],
                details={"reason": reason},
            )
        except Exception:
            pass

    print(f"[nws-dismiss] page_id={page['id']} dismissed by met={met_name}", flush=True)
    return jsonify({"ok": True})


# ════════════════════════════════════════════════════════════════════
# Pro Threads — Met<>Subscriber DMs (Phase 10)
# ════════════════════════════════════════════════════════════════════
#
# Subscriber endpoints (require subscriber role + Pro tier):
#   GET  /api/v1/me/thread                    — get my thread + recent messages
#   POST /api/v1/me/thread/messages           — send a message
#   POST /api/v1/me/thread/mark-read          — reset my unread counter
#
# Met endpoints (require met or admin role):
#   GET  /api/v1/met/threads                  — list all threads (queue)
#   GET  /api/v1/met/threads/<id>             — get one thread + messages
#   POST /api/v1/met/threads/<id>/messages    — send a message
#   POST /api/v1/met/threads/<id>/mark-read   — reset Met's unread counter

# ─── Subscriber side ────────────────────────────────────────────────

def _get_or_create_thread_for_subscriber(user_id: int):
    """Find or create the single thread for a subscriber. Returns the
    thread row. Idempotent — same subscriber always gets same thread."""
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM pro_threads WHERE subscriber_user_id = %s",
                (user_id,),
            )
            row = cur.fetchone()
            if row:
                return row
            cur.execute(
                """INSERT INTO pro_threads (subscriber_user_id, created_at)
                   VALUES (%s, %s) RETURNING *""",
                (user_id, int(time.time() * 1000)),
            )
            return cur.fetchone()


def _post_to_pro_thread(
    subscriber_user_id: int,
    body: str,
    sender_role: str,
    sender_user_id: int | None = None,
    sender_name: str | None = None,
    notify_met: bool = True,
) -> dict | None:
    """Append a message to a subscriber's Pro Thread. Idempotent thread
    creation. Returns the message dict, or None on failure.

    Used by:
      - Portal "send message" endpoint (sender_role='subscriber')
      - Met workspace reply endpoint (sender_role='met')
      - Brief reply webhooks (sender_role='subscriber', auto-routed inbound)

    notify_met: if True, sends an SMS heads-up to METEOROLOGIST_PHONE.
                Skip for high-volume contexts (bulk imports) to avoid
                paging Met about every message.
    """
    if not body or not body.strip():
        return None
    body = body.strip()[:5000]  # cap at 5KB

    thread = _get_or_create_thread_for_subscriber(subscriber_user_id)
    if not thread:
        return None

    now_ms = int(time.time() * 1000)
    preview = body[:120]
    msg_id = None

    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO pro_thread_messages
                       (thread_id, created_at, sender_role, sender_user_id,
                        sender_name, body)
                       VALUES (%s, %s, %s, %s, %s, %s)
                       RETURNING id""",
                    (thread["id"], now_ms, sender_role,
                     sender_user_id, sender_name or "", body),
                )
                msg_id = cur.fetchone()["id"]

                # Update thread metadata based on who sent
                if sender_role == "subscriber":
                    cur.execute(
                        """UPDATE pro_threads
                           SET last_message_at = %s,
                               last_message_preview = %s,
                               last_message_from = 'subscriber',
                               unread_for_met = unread_for_met + 1
                           WHERE id = %s""",
                        (now_ms, preview, thread["id"]),
                    )
                else:  # met
                    cur.execute(
                        """UPDATE pro_threads
                           SET last_message_at = %s,
                               last_message_preview = %s,
                               last_message_from = 'met',
                               unread_for_subscriber = unread_for_subscriber + 1
                           WHERE id = %s""",
                        (now_ms, preview, thread["id"]),
                    )
    except Exception as e:
        print(f"[pro-thread-post] insert failed sub={subscriber_user_id}: {e}", flush=True)
        return None

    # Page on-duty Met if requested (only for subscriber-originated messages)
    if notify_met and sender_role == "subscriber":
        try:
            met_phone = os.environ.get("METEOROLOGIST_PHONE", "").strip()
            if met_phone:
                base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
                sms_body = (
                    f"WV Pro Thread from {sender_name or 'subscriber'}:\n"
                    f"{preview}\n\n"
                    f"Reply in workspace: {base}/?screen=met"
                )
                send_sms(met_phone, sms_body)
        except Exception as e:
            print(f"[pro-thread-post] Met SMS notify failed: {e}", flush=True)

    return {
        "id": msg_id,
        "thread_id": thread["id"],
        "subscriber_user_id": subscriber_user_id,
        "sender_role": sender_role,
        "body": body,
        "created_at": now_ms,
    }


def _is_pro_subscriber(user: dict) -> bool:
    """True if the user is a Pro-tier subscriber OR a team member of a
    Pro Multi primary. Pro Threads is a Pro feature; Hobbyists can't
    access it.

    Updated May 20, 2026: team members inherit Pro access from their
    primary subscriber's Pro Multi plan."""
    if not user:
        return False
    if "subscriber" not in (user.get("roles") or []):
        return False
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT subscription_tier FROM users WHERE id = %s",
                (user["id"],),
            )
            row = cur.fetchone()
            tier = (row or {}).get("subscription_tier") or ""
            if tier in ("pro_single", "pro_multi", "pro_enterprise"):
                return True
            # Check if this user is an active team member of any Pro
            # primary (Pro Single, Pro Multi, or Pro Enterprise).
            # Updated May 23, 2026 — was Pro Multi/Enterprise only, but
            # Pro Single now invites team members too. Their members
            # need the same access to Pro features as the primary.
            cur.execute(
                """SELECT 1 FROM pro_multi_memberships pmm
                   JOIN users primary_u ON primary_u.id = pmm.primary_user_id
                   WHERE pmm.member_user_id = %s
                     AND pmm.status = 'active'
                     AND primary_u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')
                   LIMIT 1""",
                (user["id"],),
            )
            return cur.fetchone() is not None


@app.route("/api/v1/me/thread", methods=["OPTIONS"])
def _me_thread_preflight():
    return ("", 204)


@app.get("/api/v1/me/thread")
def me_thread_get():
    """Return the subscriber's thread + last 50 messages."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if not _is_pro_subscriber(user):
        return jsonify({
            "ok": False,
            "error": "pro-tier-required",
            "message": "Pro Threads is available on Pro Single, Pro Multi, and Pro Enterprise plans.",
        }), 403

    thread = _get_or_create_thread_for_subscriber(user["id"])

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, created_at, sender_role, sender_name, body
                   FROM pro_thread_messages
                   WHERE thread_id = %s
                   ORDER BY created_at DESC LIMIT 50""",
                (thread["id"],),
            )
            recent = cur.fetchall()

    # Reverse so frontend gets oldest-first (chronological reading order)
    messages = [
        {
            "id": m["id"],
            "created_at": m["created_at"],
            "sender_role": m["sender_role"],
            "sender_name": m["sender_name"],
            "body": m["body"],
        }
        for m in reversed(recent)
    ]

    return jsonify({
        "ok": True,
        "thread": {
            "id": thread["id"],
            "created_at": thread["created_at"],
            "last_message_at": thread["last_message_at"],
            "unread_for_subscriber": thread["unread_for_subscriber"],
        },
        "messages": messages,
    })


@app.post("/api/v1/me/thread/messages")
def me_thread_send():
    """Subscriber sends a message. Pages the Met via SMS so they know."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if not _is_pro_subscriber(user):
        return jsonify({"ok": False, "error": "pro-tier-required"}), 403

    data = request.get_json(silent=True) or {}
    body = (data.get("body") or "").strip()
    if not body:
        return jsonify({"ok": False, "error": "empty-message"}), 400
    if len(body) > 4000:
        return jsonify({"ok": False, "error": "message-too-long"}), 400

    thread = _get_or_create_thread_for_subscriber(user["id"])
    sender_name = user.get("name") or (user.get("email") or "").split("@")[0]
    now_ms = int(time.time() * 1000)
    preview = body[:120]

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO pro_thread_messages
                   (thread_id, created_at, sender_role, sender_user_id,
                    sender_name, body)
                   VALUES (%s, %s, 'subscriber', %s, %s, %s)
                   RETURNING id""",
                (thread["id"], now_ms, user["id"], sender_name, body),
            )
            msg_id = cur.fetchone()["id"]
            cur.execute(
                """UPDATE pro_threads
                   SET last_message_at = %s,
                       last_message_preview = %s,
                       last_message_from = 'subscriber',
                       unread_for_met = unread_for_met + 1
                   WHERE id = %s""",
                (now_ms, preview, thread["id"]),
            )

    # Page the on-duty Met by SMS (fire-and-forget)
    try:
        if METEOROLOGIST_PHONE:
            base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
            sms_body = (
                f"WV Pro Thread from {sender_name}:\n"
                f"{preview}\n\n"
                f"Reply in workspace: {base}/?screen=met"
            )
            send_sms(METEOROLOGIST_PHONE, sms_body)
    except Exception as e:
        print(f"[pro-thread] Met SMS notify failed: {e}", flush=True)

    return jsonify({
        "ok": True,
        "message_id": msg_id,
        "created_at": now_ms,
    })


@app.post("/api/v1/me/thread/mark-read")
def me_thread_mark_read():
    """Subscriber acknowledges they've read the Met's messages.
    Resets their unread counter to 0."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if not _is_pro_subscriber(user):
        return jsonify({"ok": False, "error": "pro-tier-required"}), 403

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE pro_threads
                   SET unread_for_subscriber = 0
                   WHERE subscriber_user_id = %s""",
                (user["id"],),
            )

    return jsonify({"ok": True})


# ─── Met side ───────────────────────────────────────────────────────

@app.route("/api/v1/met/threads", methods=["OPTIONS"])
def _met_threads_preflight():
    return ("", 204)


@app.get("/api/v1/met/threads")
def met_threads_list():
    """List all Pro Threads, sorted by most recent activity. Met workspace
    surface — Met sees the queue of conversations.

    Unread threads (unread_for_met > 0) sort to the top regardless of
    last message time. Within each group, most recent first.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    if "met" not in (user.get("roles") or []) and "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT t.*, u.email AS subscriber_email, u.name AS subscriber_name,
                          u.subscription_tier AS subscriber_tier,
                          pmm.role_label AS team_role_label,
                          primary_u.name AS team_primary_name,
                          primary_u.id AS team_primary_user_id
                   FROM pro_threads t
                   JOIN users u ON u.id = t.subscriber_user_id
                   LEFT JOIN pro_multi_memberships pmm
                          ON pmm.member_user_id = u.id
                         AND pmm.status = 'active'
                   LEFT JOIN users primary_u
                          ON primary_u.id = pmm.primary_user_id
                   WHERE u.is_active = TRUE
                     AND (
                       u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')
                       OR (pmm.id IS NOT NULL
                           AND primary_u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise'))
                     )
                   ORDER BY
                     CASE WHEN t.unread_for_met > 0 THEN 0 ELSE 1 END,
                     COALESCE(t.last_message_at, t.created_at) DESC
                   LIMIT 100"""
            )
            rows = cur.fetchall()

    threads = [
        {
            "id": r["id"],
            "subscriber_user_id": r["subscriber_user_id"],
            "subscriber_email": r["subscriber_email"],
            "subscriber_name": r.get("subscriber_name") or "",
            "subscriber_tier": r.get("subscriber_tier"),
            "created_at": r["created_at"],
            "last_message_at": r["last_message_at"],
            "last_message_preview": r["last_message_preview"],
            "last_message_from": r["last_message_from"],
            "unread_for_met": r["unread_for_met"],
            # Team membership context (May 20, 2026): when this thread
            # belongs to a Pro Multi team member, give Met the context
            # of who the primary subscriber is and what role this member
            # plays on the team.
            "team_role_label": r.get("team_role_label"),
            "team_primary_name": r.get("team_primary_name"),
            "team_primary_user_id": r.get("team_primary_user_id"),
        }
        for r in rows
    ]
    return jsonify({"ok": True, "threads": threads})


