# ──────────────────────────────────────────────────────────────────
# Storm Shelter activations — Met opens, manages, and closes a
# regional Storm Shelter event when NWS issues a severe warning.
# Met earns $25 per activation. Auto-close when the triggering NWS
# warning expires (cron-based, every 60s).
# ──────────────────────────────────────────────────────────────────

@app.route("/api/v1/met/storm-shelter/open", methods=["OPTIONS"])
def _met_ss_open_preflight():
    return ("", 204)


@app.post("/api/v1/met/storm-shelter/open")
def met_storm_shelter_open():
    """Met opens a Storm Shelter activation.
    Body: { region_label: "...", nws_event?: "...", affected_count?: N }
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}
    region = (data.get("region_label") or "").strip()
    if not region:
        return jsonify({"ok": False, "error": "region-required"}), 400
    if len(region) > 200:
        region = region[:200]
    nws_event = (data.get("nws_event") or "").strip()[:200] or None
    affected = data.get("affected_count")
    try:
        affected = int(affected) if affected is not None else None
    except (TypeError, ValueError):
        affected = None

    now_ms = int(time.time() * 1000)
    # Prevent duplicate open activations for same Met + region
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id FROM storm_shelter_activations
                   WHERE met_user_id = %s
                     AND region_label = %s
                     AND closed_at_ms IS NULL""",
                (user["id"], region),
            )
            existing = cur.fetchone()
            if existing:
                return jsonify({
                    "ok": False, "error": "already-open",
                    "activation_id": existing["id"],
                }), 409
            cur.execute(
                """INSERT INTO storm_shelter_activations
                   (met_user_id, region_label, nws_event, affected_count,
                    opened_at_ms, payout_cents)
                   VALUES (%s, %s, %s, %s, %s, %s)
                   RETURNING id""",
                (user["id"], region, nws_event, affected, now_ms,
                 STORM_SHELTER_PAYOUT_CENTS),
            )
            row = cur.fetchone()
    print(f"[storm-shelter] OPEN met={user['id']} region={region!r} event={nws_event!r}", flush=True)
    return jsonify({"ok": True, "activation_id": row["id"]})


@app.route("/api/v1/met/storm-shelter/open-list", methods=["OPTIONS"])
def _met_ss_open_list_preflight():
    return ("", 204)


@app.get("/api/v1/met/storm-shelter/open-list")
def met_storm_shelter_open_list():
    """List the currently-open Storm Shelters, for the LIVE tab's overlay
    setup (Chunk 2b-2). When a Meteorologist is going live during a storm,
    they pick the open shelter they are covering, and its region_label
    becomes the overlay's region. Met/admin only.
    """
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    shelters = []
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT s.id, s.region_label, s.nws_event, s.opened_at_ms,
                              u.name AS met_name
                       FROM storm_shelter_activations s
                       LEFT JOIN users u ON u.id = s.met_user_id
                       WHERE s.closed_at_ms IS NULL
                       ORDER BY s.opened_at_ms DESC"""
                )
                for r in cur.fetchall():
                    shelters.append({
                        "id": r["id"],
                        "region_label": r["region_label"],
                        "nws_event": r["nws_event"],
                        "met_name": r["met_name"],
                        "opened_at_ms": r["opened_at_ms"],
                    })
    except Exception as e:
        print(f"[storm-shelter] open-list failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500
    return jsonify({"ok": True, "shelters": shelters})


# ── Live broadcasts: a Met going LIVE in the app (Phase 3, Chunk 3a) ──
def _parse_youtube_id(url: str) -> Optional[str]:
    """Pull the 11-char YouTube video id from common URL shapes. Returns
    None if we can't find one. Accepts watch?v=, youtu.be/, live/, embed/,
    and a bare id."""
    if not url:
        return None
    url = url.strip()
    # Bare 11-char id
    if re.fullmatch(r"[A-Za-z0-9_-]{11}", url):
        return url
    patterns = [
        r"[?&]v=([A-Za-z0-9_-]{11})",
        r"youtu\.be/([A-Za-z0-9_-]{11})",
        r"youtube\.com/live/([A-Za-z0-9_-]{11})",
        r"youtube\.com/embed/([A-Za-z0-9_-]{11})",
    ]
    for pat in patterns:
        m = re.search(pat, url)
        if m:
            return m.group(1)
    return None


@app.route("/api/v1/met/live/start", methods=["OPTIONS"])
def _met_live_start_preflight():
    return ("", 204)


@app.post("/api/v1/met/live/start")
def met_live_start():
    """Met goes live in the app. Records a live_broadcasts row. Met/admin
    only. Body: youtube_url, visibility ('public'|'subscribers'), region_label,
    region_state, region_counties, title (optional), shelter_activation_id
    (optional), scheduled_for_ms (optional)."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    body = request.get_json(silent=True) or {}
    youtube_url = (body.get("youtube_url") or "").strip()
    yid = _parse_youtube_id(youtube_url)
    if not yid:
        return jsonify({"ok": False, "error": "bad-youtube-url"}), 400
    visibility = (body.get("visibility") or "subscribers").strip()
    if visibility not in ("public", "subscribers"):
        visibility = "subscribers"
    title = (body.get("title") or "").strip() or None
    region_label = (body.get("region_label") or "").strip() or None
    region_state = (body.get("region_state") or "").strip().upper() or None
    region_counties = (body.get("region_counties") or "").strip() or None
    shelter_id = body.get("shelter_activation_id")
    try:
        shelter_id = int(shelter_id) if shelter_id else None
    except (ValueError, TypeError):
        shelter_id = None
    scheduled_for_ms = body.get("scheduled_for_ms")
    try:
        scheduled_for_ms = int(scheduled_for_ms) if scheduled_for_ms else None
    except (ValueError, TypeError):
        scheduled_for_ms = None
    now_ms = int(time.time() * 1000)

    try:
        with db() as conn:
            with conn.cursor() as cur:
                # End any of this Met's still-open broadcasts first, so a Met
                # is only live in one place at a time.
                cur.execute(
                    """UPDATE live_broadcasts SET ended_at_ms = %s
                       WHERE met_user_id = %s AND ended_at_ms IS NULL""",
                    (now_ms, user["id"]),
                )
                cur.execute(
                    """INSERT INTO live_broadcasts
                       (met_user_id, youtube_id, youtube_url, title, visibility,
                        region_label, region_state, region_counties,
                        shelter_activation_id, started_at_ms, scheduled_for_ms)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                       RETURNING id""",
                    (user["id"], yid, youtube_url, title, visibility,
                     region_label, region_state, region_counties,
                     shelter_id, now_ms, scheduled_for_ms),
                )
                row = cur.fetchone()
    except Exception as e:
        print(f"[live] start failed: {e!r}", flush=True)
        return jsonify({"ok": False, "error": "db-error"}), 500
    print(f"[live] START met={user['id']} yid={yid} vis={visibility} region={region_label!r}", flush=True)
    return jsonify({"ok": True, "broadcast_id": row["id"], "youtube_id": yid})


