@app.route("/api/v1/rosie/chat", methods=["OPTIONS"])
def _rosie_chat_preflight():
    return ("", 204)


@app.post("/api/v1/rosie/chat")
def rosie_chat():
    """Send a message to Rosie. Returns her reply.
    Body: { "message": "..." }
    Channel inferred as 'web' for now (SMS endpoint is separate)."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    data = request.get_json(silent=True) or {}
    msg = (data.get("message") or "").strip()
    if not msg:
        return jsonify({"ok": False, "error": "empty-message"}), 400
    if len(msg) > 4000:
        return jsonify({"ok": False, "error": "message-too-long"}), 400

    conv_id = _rosie_get_or_create_conversation(user["id"], "web")
    reply = _rosie_run_turn(user["id"], conv_id, msg, channel="web")
    return jsonify({"ok": True, "reply": reply})


@app.route("/api/v1/rosie/history", methods=["OPTIONS"])
def _rosie_history_preflight():
    return ("", 204)


@app.get("/api/v1/rosie/history")
def rosie_history():
    """Get the calling Met's web-channel conversation history with Rosie."""
    user = _get_current_user()
    if user is None:
        return jsonify({"ok": False, "error": "not-authenticated"}), 401
    roles = user.get("roles") or []
    if "met" not in roles and "admin" not in roles:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id FROM rosie_conversations
                   WHERE met_user_id = %s AND channel = 'web'""",
                (user["id"],),
            )
            row = cur.fetchone()
    if not row:
        return jsonify({"ok": True, "messages": []})
    msgs = _rosie_load_recent_messages(row["id"], limit=50)
    out = []
    for m in msgs:
        if m["role"] in ("user", "assistant"):
            out.append({"role": m["role"], "content": m["content"]})
    return jsonify({"ok": True, "messages": out})


# ─────────────────────────────────────────────────────────────
# SMS inbound router (May 17, 2026)
# Single endpoint that Twilio's "A message comes in" webhook
# points at. Routes based on who's texting:
#   - Met or admin (phone matches a user with met/admin role) → Rosie
#   - Subscriber (phone matches a user with subscriber role)   → reply capture
#   - Unknown number                                           → polite reply
#
# Rationale: we have one toll-free number, two use cases. Rather
# than buy a second number, route at the application layer.
# ─────────────────────────────────────────────────────────────

_CREW_ALERTS_PER_HOUR = 3


def _region_label_for_coords(lat, lng) -> str:
    """Coarse coordinates-to-territory mapping (July 2026). Two regions
    exist today, split cleanly by longitude; replace with real county/NWS
    zone lookup when that standardization lands."""
    try:
        return "Kansas Region" if float(lng) < -90.0 else "Indiana Region"
    except (TypeError, ValueError):
        return "Indiana Region"


def _alert_mets_for_crew_report(report_type: str, lat, lng,
                                reporter_name: str, notes: str,
                                has_photo: bool) -> None:
    """Text the territory Met(s) about a fresh crew report, throttled to
    _CREW_ALERTS_PER_HOUR per Met per rolling hour (Michael, July 2026:
    "I don't want 45 texts to the Met in 3 mins"). Suppressed reports
    still pin the map; the text is just the tap on the shoulder. Sends
    from the MAIN number so a Met's reply flows to the normal inbound
    path instead of logging a bogus crew check-in."""
    region = _region_label_for_coords(lat, lng)
    now_ms = int(time.time() * 1000)
    hour_ago = now_ms - 3600 * 1000
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT DISTINCT u.id, u.name, u.phone
                       FROM met_territories t
                       JOIN users u ON u.id = t.met_user_id
                       WHERE t.region_label = %s
                         AND u.is_active = TRUE
                         AND COALESCE(u.phone, '') <> ''""",
                    (region,),
                )
                mets = cur.fetchall()
    except Exception as e:
        print(f"[crew-alert] met lookup failed: {e!r}", flush=True)
        return
    if not mets:
        print(f"[crew-alert] no Mets for {region}, report unalerted", flush=True)
        return
    photo_bit = " (with photo)" if has_photo else ""
    note_bit = f' "{(notes or "").strip()[:80]}"' if (notes or "").strip() else ""
    msg = (f"Valet Crew: {reporter_name or 'a Crew member'} reports "
           f"{report_type}{photo_bit} in your region.{note_bit} "
           f"See the Crew map for the pin.")
    for m in mets:
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT COUNT(*) AS n FROM crew_alert_log
                           WHERE met_user_id = %s AND sent_at > %s""",
                        (m["id"], hour_ago),
                    )
                    n = int(cur.fetchone()["n"])
            if n >= _CREW_ALERTS_PER_HOUR:
                print(f"[crew-alert] throttled for met={m['id']} "
                      f"({n} in last hour)", flush=True)
                continue
            if send_sms(m["phone"], msg):
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """INSERT INTO crew_alert_log (met_user_id, sent_at)
                               VALUES (%s, %s)""",
                            (m["id"], now_ms),
                        )
                print(f"[crew-alert] sent to met={m['id']} for {report_type}",
                      flush=True)
        except Exception as e:
            print(f"[crew-alert] send failed for met={m['id']}: {e!r}", flush=True)


def _ingest_inbound_mms_image(uploaded_by) -> str | None:
    """Pull the first attached image off an inbound Twilio message and
    store it on our own /media/ host (July 2026). Returns the hosted URL
    or None. Twilio's MediaUrl0 is fetchable without auth by default."""
    try:
        num = int(request.form.get("NumMedia") or 0)
    except (TypeError, ValueError):
        num = 0
    if num < 1:
        return None
    murl = (request.form.get("MediaUrl0") or "").strip()
    ctype = (request.form.get("MediaContentType0") or "").lower()
    if not murl or not ctype.startswith("image/"):
        return None
    try:
        import urllib.request, base64
        headers = {"User-Agent": "WeatherValet crew line"}
        # Twilio enforces HTTP basic auth on media URLs for newer accounts
        # (July 2026): without credentials the fetch 401s silently and
        # every texted photo vanishes. Auth with the same creds we send with.
        if TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN:
            tok = base64.b64encode(
                f"{TWILIO_ACCOUNT_SID}:{TWILIO_AUTH_TOKEN}".encode()).decode()
            headers["Authorization"] = "Basic " + tok
        req = urllib.request.Request(murl, headers=headers)
        with urllib.request.urlopen(req, timeout=12) as resp:
            raw = resp.read(8 * 1024 * 1024 + 1)
        if len(raw) > 8 * 1024 * 1024:
            print("[crew-line] MMS image too large, skipping", flush=True)
            return None
        ok, result = _store_media_bytes(raw, "crew-mms", uploaded_by)
        if not ok:
            print(f"[crew-line] MMS store failed: {result}", flush=True)
            return None
        print(f"[crew-line] MMS photo hosted -> {result}", flush=True)
        return result
    except Exception as e:
        print(f"[crew-line] MMS fetch failed: {e!r}", flush=True)
        return None


def _crew_line_inbound(from_phone: str, body: str):
    """Inbound SMS/MMS on the dedicated Valet Crew number. The destination
    number IS the context: this is a conditions report, full stop, and on
    THIS line everyone we know counts, Crew, subscribers, Mets, admins
    (July 2026: Michael's "ALL can use it" rule). Photos become map pins.
    Always acks, so the sender knows their report landed."""
    matched_user_id = _match_any_active_user_by_phone(from_phone)

    def _twiml(msg):
        return (f"<?xml version='1.0' encoding='UTF-8'?><Response>"
                f"<Message>{escape_xml(msg)}</Message></Response>",
                200, {"Content-Type": "text/xml"})

    if matched_user_id is None:
        return _twiml("Thanks for texting the WeatherValet Crew line. We didn't "
                      "recognize this number. Please text from the phone on your "
                      "WeatherValet profile, or email hello@weathervalet.ai.")
    image_url = _ingest_inbound_mms_image(matched_user_id)
    try:
        _record_crew_checkin_from_sms(matched_user_id, body,
                                      force=True, image_url=image_url)
        recorded = True
    except Exception as e:
        print(f"[crew-line] record failed: {e!r}", flush=True)
        recorded = False
    if not recorded:
        return _twiml("Something hiccuped on our end saving that. Please try "
                      "again in a minute, your report matters to us.")
    if image_url:
        return _twiml("Got it, photo and all! Your conditions report is on the "
                      "map. Thanks for being our eyes on the ground!")
    return _twiml("Got it, your conditions report is logged. Thanks for "
                  "being our eyes on the ground!")


@app.route("/api/v1/sms-inbound-router", methods=["OPTIONS"])
def _sms_inbound_router_preflight():
    return ("", 204)


@app.post("/api/v1/sms-inbound-router")
def sms_inbound_router():
    """Front door for ALL inbound SMS. Decides which handler to invoke
    based on the sender's role.

    Twilio sends form-encoded data. We look up the sender's phone in
    the users table once, then dispatch to the appropriate logic:

        Met or admin role     → Rosie chat (returns TwiML reply)
        Subscriber role       → brief reply capture (returns empty TwiML)
        No match              → polite "wrong number" reply

    All paths return TwiML so Twilio doesn't retry.
    """
    from_phone = (request.form.get("From") or "").strip()
    body = (request.form.get("Body") or "").strip()

    # Empty body, just ack
    if not body:
        return ("<?xml version='1.0' encoding='UTF-8'?><Response/>",
                200, {"Content-Type": "text/xml"})

    # Dedicated Valet Crew line (July 2026): if this text was sent TO the
    # Crew number, it's a conditions check-in regardless of the sender's
    # roles. The destination number is the context; that's the whole point
    # of having a second number.
    to_phone = (request.form.get("To") or "").strip()
    if TWILIO_CREW_NUMBER and _phone_last10(to_phone) == _phone_last10(TWILIO_CREW_NUMBER):
        print(f"[sms-router] crew line from={from_phone} body_len={len(body)}", flush=True)
        return _crew_line_inbound(from_phone, body)

    # Look up the sender's role(s). One query, returns highest-privilege role.
    # Met/admin take priority over subscriber if the same person has both
    # (e.g. a Met testing the system using their own subscriber account).
    sender_role = None
    if from_phone:
        try:
            normalized = _normalize_phone(from_phone)
            _digits = "".join(c for c in normalized if c.isdigit())
            _last10 = _digits[-10:] if len(_digits) >= 10 else None
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT ur.role
                           FROM users u
                           JOIN user_roles ur ON ur.user_id = u.id
                           WHERE RIGHT(regexp_replace(COALESCE(u.phone, ''),
                                                      '\\D', '', 'g'), 10) = %s
                             AND u.is_active = TRUE
                             AND ur.role IN ('admin', 'met', 'subscriber', 'crew')
                           ORDER BY CASE ur.role
                             WHEN 'admin'      THEN 1
                             WHEN 'met'        THEN 2
                             WHEN 'subscriber' THEN 3
                             WHEN 'crew'       THEN 4
                             ELSE 5
                           END
                           LIMIT 1""",
                        (_last10 or "##nomatch##",),
                    )
                    row = cur.fetchone()
                    if row:
                        sender_role = row["role"]
        except Exception as e:
            print(f"[sms-router] lookup failed: {e}", flush=True)

    print(
        f"[sms-router] from={from_phone} role={sender_role} body_len={len(body)}",
        flush=True,
    )

    if sender_role in ("met", "admin"):
        # Hand off to Rosie. We invoke the existing function directly —
        # it reads request.form so the call works as-is.
        return rosie_sms_inbound()
    elif sender_role in ("subscriber", "crew"):
        # Hand off to reply capture. Same trick — reads request.form.
        # Crew members route here too (July 2026): the reply handler
        # already detects the crew role and records their check-in and
        # map report, so a text back to the daily conditions nudge counts.
        return replies_sms_inbound()
    else:
        # Unknown number. Be polite, don't be silent.
        reply = ("Thanks for texting WeatherValet. We didn't recognize this "
                 "number. If you're a subscriber, please text from the phone "
                 "we have on file, or email hello@weathervalet.ai.")
        twiml = f"<?xml version='1.0' encoding='UTF-8'?><Response><Message>{escape_xml(reply)}</Message></Response>"
        return (twiml, 200, {"Content-Type": "text/xml"})


# ─────────────────────────────────────────────────────────────
# Rosie SMS — inbound webhook from Twilio
# When a Met texts Rosie's number, Twilio POSTs here. We look up
# the Met by phone, run a Rosie turn, and reply with TwiML so the
# response comes back as an SMS.
# ─────────────────────────────────────────────────────────────

@app.post("/api/v1/rosie/sms")
def rosie_sms_inbound():
    """Twilio webhook for inbound SMS to Rosie's number.

    Twilio POSTs form-encoded data (NOT JSON). Fields we use:
      From   — sender's phone number (E.164)
      Body   — message text
      To     — Rosie's number (we ignore; could verify)

    Returns TwiML XML so Twilio sends Rosie's response as an SMS reply.
    """
    from_phone = (request.form.get("From") or "").strip()
    body = (request.form.get("Body") or "").strip()

    # Empty body, just acknowledge
    if not body:
        return ("<?xml version='1.0' encoding='UTF-8'?><Response/>",
                200, {"Content-Type": "text/xml"})

    # Look up Met by phone. Phone match is exact on E.164.
    met = None
    if from_phone:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT u.id, u.name, u.phone
                       FROM users u
                       JOIN user_roles ur ON ur.user_id = u.id
                       WHERE u.phone = %s
                         AND ur.role IN ('met','admin')
                         AND u.is_active = TRUE
                       LIMIT 1""",
                    (from_phone,),
                )
                met = cur.fetchone()

    if not met:
        # Not a Meteorologist. Is this a Crew member replying to a daily
        # nudge? If so, treat the reply as a check-in (#C9).
        crew = None
        if from_phone:
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT u.id, u.name FROM users u
                               JOIN user_roles ur ON ur.user_id = u.id
                               WHERE u.phone = %s AND ur.role = 'crew'
                                 AND u.is_active = TRUE LIMIT 1""",
                            (from_phone,),
                        )
                        crew = cur.fetchone()
            except Exception as e:
                print(f"[crew-sms] lookup failed: {e}", flush=True)

        if crew:
            # Carrier opt-out / help keywords are handled by Twilio for
            # toll-free numbers; if one still reaches us, do not check in.
            if body.strip().upper() in ("STOP", "STOPALL", "UNSUBSCRIBE",
                                        "CANCEL", "END", "QUIT", "HELP", "START"):
                return ("<?xml version='1.0' encoding='UTF-8'?><Response/>",
                        200, {"Content-Type": "text/xml"})
            condition = _parse_crew_condition(body)
            now_ms = int(time.time() * 1000)
            today_key = _local_date_key()
            try:
                with db() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            """INSERT INTO crew_checkins
                                 (user_id, date_key, conditions, notes, checked_in_at)
                               VALUES (%s, %s, %s, %s, %s)
                               ON CONFLICT (user_id, date_key) DO UPDATE
                                 SET conditions = EXCLUDED.conditions,
                                     notes = EXCLUDED.notes,
                                     checked_in_at = EXCLUDED.checked_in_at""",
                            (crew["id"], today_key, condition or "",
                             body[:500], now_ms),
                        )
            except Exception as e:
                print(f"[crew-sms] checkin failed: {e}", flush=True)
                reply = ("Sorry, something went wrong logging that. Please "
                         "try again in a moment.")
                twiml = f"<?xml version='1.0' encoding='UTF-8'?><Response><Message>{escape_xml(reply)}</Message></Response>"
                return (twiml, 200, {"Content-Type": "text/xml"})

            try:
                streak = _compute_streak(crew["id"])
            except Exception:
                streak = 0
            day_word = "day" if streak == 1 else "days"
            if condition:
                reply = (f"Got it, you are checked in. Logged: {condition}. "
                         f"Streak: {streak} {day_word}. Thank you for the "
                         f"eyes on the sky.")
            else:
                reply = (f"Got it, you are checked in. Streak: {streak} "
                         f"{day_word}. Tip: reply clear, cloudy, rain, or "
                         f"storm to log conditions.")
            twiml = f"<?xml version='1.0' encoding='UTF-8'?><Response><Message>{escape_xml(reply)}</Message></Response>"
            return (twiml, 200, {"Content-Type": "text/xml"})

        # Truly unknown number. Reply politely so a misdirected text doesn't
        # get lost in silence, but don't process the message.
        reply = ("This number is for the WeatherValet meteorologist team. "
                 "If you're a customer, please reply to your usual WV number "
                 "or email hello@weathervalet.ai.")
        twiml = f"<?xml version='1.0' encoding='UTF-8'?><Response><Message>{escape_xml(reply)}</Message></Response>"
        return (twiml, 200, {"Content-Type": "text/xml"})

    # Run a Rosie turn on the SMS conversation
    try:
        conv_id = _rosie_get_or_create_conversation(met["id"], "sms")
        reply = _rosie_run_turn(met["id"], conv_id, body, channel="sms")
    except Exception as e:
        print(f"[rosie-sms] turn failed: {e}", flush=True)
        reply = "Something went wrong on my end. Try again in a sec.\n- Rosie"

    # SMS-trim: keep replies under 320 chars (2 SMS segments) where possible.
    # Long answers get truncated with a hint to use web chat.
    if len(reply) > 320:
        reply = reply[:280].rstrip() + "...\n\n(More in your workspace chat with me.)\n- Rosie"

    twiml = f"<?xml version='1.0' encoding='UTF-8'?><Response><Message>{escape_xml(reply)}</Message></Response>"
    return (twiml, 200, {"Content-Type": "text/xml"})


def escape_xml(s: str) -> str:
    """Minimal XML escape for TwiML message bodies."""
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace('"', "&quot;").replace("'", "&apos;"))


# ─────────────────────────────────────────────────────────────
# Rosie proactive triggers — Rosie reaches out on her own
# Each function below runs on its own schedule via the main loop.
# Designed to be lightweight: query, decide, send if needed, log.
# Cooldowns prevent spamming Mets with repeat messages.
# ─────────────────────────────────────────────────────────────

def _rosie_proactive_morning_briefing():
    """At 6 AM ET, send each Met their day's brief tasks.

    Cooldown: once per Met per calendar day (uses ET).
    Skips Mets with no tasks today (don't ping just to ping).
    Skips Mets who logged in within the last 30 minutes (they're already
    looking at their workspace).
    """
    now_et = datetime.now(ZoneInfo("America/New_York"))
    # Only run between 5:55 AM and 6:05 AM ET — narrow window so we don't
    # accidentally fire twice when the cron is busy
    if not (now_et.hour == 6 and now_et.minute < 6):
        return

    today_str = now_et.strftime("%Y-%m-%d")
    now_ms = int(time.time() * 1000)
    thirty_min_ago = now_ms - 30 * 60 * 1000

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.phone, mh.last_seen_at
                   FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'met'
                   LEFT JOIN met_heartbeat mh ON mh.met_user_id = u.id
                   WHERE u.is_active = TRUE AND u.phone IS NOT NULL""",
            )
            mets = cur.fetchall()

    for m in mets:
        # Skip if Met was active in the last 30 min
        if m.get("last_seen_at") and m["last_seen_at"] > thirty_min_ago:
            continue
        # Check cooldown (one briefing per day per Met)
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT COUNT(*) AS n FROM rosie_audit_log
                       WHERE met_user_id = %s
                         AND action = 'proactive_morning_briefing'
                         AND created_at_ms >= %s""",
                    (m["id"], int(datetime.combine(now_et.date(), datetime.min.time(),
                                                    tzinfo=ZoneInfo("America/New_York")).timestamp() * 1000)),
                )
                if cur.fetchone()["n"] > 0:
                    continue

        # Count today's tasks for this Met
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT COUNT(*) AS n, MIN(due_at_ms) AS first_due
                       FROM daily_brief_tasks
                       WHERE assigned_met_id = %s
                         AND task_date = %s
                         AND sent_at_ms IS NULL""",
                    (m["id"], today_str),
                )
                row = cur.fetchone()

        task_count = (row or {}).get("n") or 0
        if task_count == 0:
            continue  # nothing to brief about

        first_due_ms = row.get("first_due") or 0
        first_due_str = ""
        if first_due_ms:
            fd = datetime.fromtimestamp(first_due_ms / 1000, tz=ZoneInfo("America/New_York"))
            first_due_str = fd.strftime("%I:%M %p ET").lstrip("0")

        first_name = (m.get("name") or "").split()[0] or "there"
        msg = (
            f"Good morning, {first_name}. You have {task_count} brief "
            f"{'task' if task_count == 1 else 'tasks'} today"
            f"{', earliest by ' + first_due_str if first_due_str else ''}. "
            f"Open your workspace when ready.\n- Rosie"
        )
        try:
            sent = send_sms_from(m["phone"], msg, ROSIE_TWILIO_NUMBER)
        except Exception as e:
            print(f"[rosie-morning] send failed met={m['id']}: {e}", flush=True)
            sent = False
        _rosie_audit(m["id"], "sms", "proactive_morning_briefing",
                     f"{task_count} tasks today", tier=1, success=sent)


def _rosie_proactive_inactivity_nudge():
    """If a Met hasn't logged in for 7+ days, send a friendly check-in.

    Cooldown: once per Met per 7-day rolling window. Won't repeat-nudge.
    Only fires once a day (runs at 4 PM ET).
    """
    now_et = datetime.now(ZoneInfo("America/New_York"))
    if not (now_et.hour == 16 and now_et.minute < 6):
        return  # narrow window

    now_ms = int(time.time() * 1000)
    seven_days_ago = now_ms - 7 * 24 * 60 * 60 * 1000

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.phone, mh.last_seen_at
                   FROM users u
                   JOIN user_roles ur ON ur.user_id = u.id AND ur.role = 'met'
                   LEFT JOIN met_heartbeat mh ON mh.met_user_id = u.id
                   WHERE u.is_active = TRUE AND u.phone IS NOT NULL
                     AND (mh.last_seen_at IS NULL OR mh.last_seen_at < %s)""",
                (seven_days_ago,),
            )
            inactive = cur.fetchall()

    for m in inactive:
        # Cooldown check: don't nudge if we nudged this Met in last 7 days
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT COUNT(*) AS n FROM rosie_audit_log
                       WHERE met_user_id = %s
                         AND action = 'proactive_inactivity_nudge'
                         AND created_at_ms >= %s""",
                    (m["id"], seven_days_ago),
                )
                if cur.fetchone()["n"] > 0:
                    continue

        first_name = (m.get("name") or "").split()[0] or "there"
        msg = (
            f"Hey {first_name}, haven't seen you log in for a bit. "
            f"Everything OK? If you need to drop shifts or change your "
            f"schedule, just text me back.\n- Rosie"
        )
        try:
            sent = send_sms_from(m["phone"], msg, ROSIE_TWILIO_NUMBER)
        except Exception as e:
            print(f"[rosie-inactivity] send failed met={m['id']}: {e}", flush=True)
            sent = False
        _rosie_audit(m["id"], "sms", "proactive_inactivity_nudge",
                     "7-day inactivity check-in", tier=1, success=sent)


def _rosie_proactive_severe_weather_heads_up():
    """When a tornado/severe-T-storm warning fires affecting a Met's
    primary subscribers, send a one-time heads-up.

    Cooldown: per (Met, NWS event id) — same warning won't re-page.
    Only sends to the PRIMARY met for affected subscribers.
    """
    try:
        alerts = _get_cached_nws_alerts() or []
    except Exception:
        return

    # Find current severe alerts
    severe = []
    for a in alerts:
        props = (a or {}).get("properties") or {}
        ev = (props.get("event") or "").lower()
        if any(k in ev for k in ("tornado warning", "severe thunderstorm warning",
                                  "flash flood warning")):
            severe.append({
                "id": props.get("id") or str(hash(json.dumps(props, sort_keys=True)))[:32],
                "event": props.get("event"),
                "area": props.get("areaDesc", "")[:120],
                "same_codes": props.get("geocode", {}).get("SAME") or [],
            })

    if not severe:
        return

    # For each severe alert, find affected Pro subscribers and their primary Mets.
    # Match strategy: NWS alerts include affectedZones URLs and areaDesc that
    # mentions counties. For v1 we do a loose substring match: subscriber's
    # saved-location county appears in the alert's areaDesc text. Imperfect
    # but works for the launch team's coverage areas.
    for alert in severe:
        area_desc = (alert.get("area") or "").lower()
        if not area_desc:
            continue

        with db() as conn:
            with conn.cursor() as cur:
                # Find Pro subscribers whose county name appears in the alert area.
                # The county column on saved_locations stores e.g. "Boone County".
                cur.execute(
                    """SELECT DISTINCT sc.primary_met_id, loc.county
                       FROM subscriber_coverage sc
                       JOIN users u ON u.id = sc.user_id
                       JOIN saved_locations loc ON loc.user_id = sc.user_id AND loc.is_primary = TRUE
                       WHERE u.is_active = TRUE
                         AND u.subscription_tier IN ('pro_single','pro_multi','pro_enterprise')
                         AND sc.primary_met_id IS NOT NULL
                         AND loc.county IS NOT NULL""",
                )
                rows = cur.fetchall()
        met_ids = set()
        for r in rows:
            county = (r.get("county") or "").lower().replace(" county", "").strip()
            if county and county in area_desc:
                met_ids.add(r["primary_met_id"])

        for met_id in met_ids:
            # Cooldown: have we already paged this Met for this event id?
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT COUNT(*) AS n FROM rosie_audit_log
                           WHERE met_user_id = %s
                             AND action = 'proactive_severe_heads_up'
                             AND detail LIKE %s""",
                        (met_id, f"%{alert['id'][:32]}%"),
                    )
                    if cur.fetchone()["n"] > 0:
                        continue
                    cur.execute("SELECT phone, name FROM users WHERE id = %s", (met_id,))
                    u = cur.fetchone()

            if not (u and u.get("phone")):
                continue
            first_name = (u.get("name") or "").split()[0] or "there"
            msg = (
                f"Heads up, {first_name}: {alert['event']} affecting your "
                f"subscribers, {alert['area'][:90]}. NWS feed is live. "
                f"You're primary.\n- Rosie"
            )
            try:
                sent = send_sms_from(u["phone"], msg, ROSIE_TWILIO_NUMBER)
            except Exception as e:
                print(f"[rosie-severe] send failed met={met_id}: {e}", flush=True)
                sent = False
            _rosie_audit(met_id, "sms", "proactive_severe_heads_up",
                         f"Event id {alert['id'][:32]}: {alert['event']}",
                         tier=1, success=sent)


# ─────────────────────────────────────────────────────────────
# Rosie Discord — outbound webhook posting (Phase 3a)
# Rosie posts to team Discord channels for things the whole team
# should see: severe weather heads-ups, morning team status,
# shift handoff prompts. We use Discord webhooks (not a bot), so
# no WebSocket / no separate worker needed.
# ─────────────────────────────────────────────────────────────

def _discord_post(webhook_url: str, content: str, username: str = "Rosie") -> bool:
    """POST a message to a Discord webhook URL. Returns True on success.

    Discord webhooks accept JSON with 'content' (the message), optional
    'username' (override the webhook's default name), and optional
    'avatar_url'. We let Rosie override the display name so all her
    posts show "Rosie" regardless of the webhook's underlying owner.

    Discord rate-limits webhooks to 30 messages per minute per webhook.
    We don't hit that organically, so no special backoff.

    Failures are logged and swallowed — Discord posts are best-effort,
    we don't want to block other proactive work if Discord is down.
    """
    if not webhook_url:
        return False
    # Truncate to 2000 chars (Discord's per-message limit)
    if len(content) > 1990:
        content = content[:1985] + "…"
    try:
        payload = {
            "content": content,
            "username": username,
            "allowed_mentions": {"parse": []},  # don't ping @everyone accidentally
        }
        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.status in (200, 204)
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = e.read().decode("utf-8", errors="replace")[:200]
        except Exception:
            pass
        print(f"[discord] post failed HTTP {e.code}: {body}", flush=True)
        return False
    except Exception as e:
        print(f"[discord] post failed: {type(e).__name__}: {e}", flush=True)
        return False


def _rosie_discord_severe_weather():
    """When a tornado/severe T-storm/flash flood warning fires nationally,
    post a summary to #severe weather. Cooldown per (channel, alert id)
    so the same alert never double-posts.

    Different from the SMS heads-up (which goes to the specific primary
    Met for affected subscribers). This channel post is informational
    for the whole team — "this is happening, everyone be aware."
    """
    if not DISCORD_WEBHOOK_SEVERE_WEATHER:
        return
    try:
        alerts = _get_cached_nws_alerts() or []
    except Exception:
        return

    severe = []
    for a in alerts:
        props = (a or {}).get("properties") or {}
        ev = (props.get("event") or "").lower()
        if any(k in ev for k in ("tornado warning", "severe thunderstorm warning",
                                  "flash flood warning")):
            alert_id = props.get("id") or str(hash(json.dumps(props, sort_keys=True)))[:32]
            severe.append({
                "id": alert_id,
                "event": props.get("event"),
                "area": props.get("areaDesc", "")[:200],
                "headline": props.get("headline", "")[:200],
                "expires": props.get("expires", ""),
            })

    if not severe:
        return

    for alert in severe:
        # Cooldown: did we already post this alert to Discord?
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT COUNT(*) AS n FROM rosie_audit_log
                       WHERE action = 'discord_severe_post'
                         AND detail LIKE %s""",
                    (f"%{alert['id'][:32]}%",),
                )
                if cur.fetchone()["n"] > 0:
                    continue

        # Pick an emoji based on event type
        ev_lower = (alert["event"] or "").lower()
        if "tornado" in ev_lower:
            emoji = "🌪️"
        elif "flash flood" in ev_lower:
            emoji = "🌊"
        else:
            emoji = "⛈️"

        msg = (
            f"{emoji} **{alert['event']}**\n"
            f"📍 {alert['area']}\n"
            f"⏰ Until {alert['expires']}\n\n"
            f"_Posted automatically, primary Mets for affected subscribers "
            f"have been SMS'd separately._"
        )
        ok = _discord_post(DISCORD_WEBHOOK_SEVERE_WEATHER, msg)
        _rosie_audit(None, "discord", "discord_severe_post",
                     f"Event id {alert['id'][:32]}: {alert['event']}",
                     tier=1, success=ok)


def _rosie_discord_morning_team_status():
    """At 6:30 AM ET, post a brief team-wide status to #announcements:
    how many tasks today across the team, who's on call, weather risk
    outlook.

    Cooldown: once per calendar day (ET). Sends to #announcements.
    """
    if not DISCORD_WEBHOOK_ANNOUNCEMENTS:
        return
    now_et = datetime.now(ZoneInfo("America/New_York"))
    if not (now_et.hour == 6 and 30 <= now_et.minute < 36):
        return

    # Cooldown: already posted today?
    midnight_ms = int(datetime.combine(now_et.date(), datetime.min.time(),
                                        tzinfo=ZoneInfo("America/New_York")).timestamp() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT COUNT(*) AS n FROM rosie_audit_log
                   WHERE action = 'discord_morning_team_status'
                     AND created_at_ms >= %s""",
                (midnight_ms,),
            )
            if cur.fetchone()["n"] > 0:
                return
            # Count today's tasks across the team
            today_str = now_et.strftime("%Y-%m-%d")
            cur.execute(
                """SELECT COUNT(*) AS total_tasks,
                          COUNT(DISTINCT assigned_met_id) AS mets_assigned
                   FROM daily_brief_tasks
                   WHERE task_date = %s
                     AND sent_at_ms IS NULL""",
                (today_str,),
            )
            task_row = cur.fetchone() or {}
            # Active severe alerts count
            cur.execute(
                """SELECT COUNT(*) AS n FROM storm_shelter_activations
                   WHERE closed_at_ms IS NULL""",
            )
            shelter_row = cur.fetchone() or {}

    total = task_row.get("total_tasks") or 0
    mets_n = task_row.get("mets_assigned") or 0
    shelters = shelter_row.get("n") or 0

    day_name = now_et.strftime("%A, %B %d")
    parts = [f"☀️ **Good morning, team, {day_name}**", ""]
    if total > 0:
        parts.append(f"📋 **{total} brief task{'s' if total != 1 else ''}** today "
                     f"across **{mets_n} Met{'s' if mets_n != 1 else ''}**.")
    else:
        parts.append("📋 No Pro brief tasks scheduled for today.")
    if shelters > 0:
        parts.append(f"⚡ **{shelters} Storm Shelter activation{'s' if shelters != 1 else ''}** "
                     f"still open from overnight.")
    parts.append("")
    parts.append("_Check your workspace for your tasks. Reach out if you need coverage._")

    msg = "\n".join(parts)
    ok = _discord_post(DISCORD_WEBHOOK_ANNOUNCEMENTS, msg)
    _rosie_audit(None, "discord", "discord_morning_team_status",
                 f"Day {today_str}: {total} tasks / {shelters} shelters",
                 tier=1, success=ok)


def _rosie_discord_shift_handoff_reminder():
    """At end of each Met's shift (rough heuristic: 9 PM ET), post a
    prompt to #shift handoff asking departing Mets to leave a note for
    the next shift.

    Cooldown: once per day. We don't try to detect individual shift
    ends — just one team-wide prompt at end of business day.
    """
    if not DISCORD_WEBHOOK_SHIFT_HANDOFF:
        return
    now_et = datetime.now(ZoneInfo("America/New_York"))
    if not (now_et.hour == 21 and now_et.minute < 6):
        return

    midnight_ms = int(datetime.combine(now_et.date(), datetime.min.time(),
                                        tzinfo=ZoneInfo("America/New_York")).timestamp() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT COUNT(*) AS n FROM rosie_audit_log
                   WHERE action = 'discord_shift_handoff'
                     AND created_at_ms >= %s""",
                (midnight_ms,),
            )
            if cur.fetchone()["n"] > 0:
                return

    msg = (
        "🔄 **End of day, shift handoff window**\n\n"
        "If you're wrapping up, drop a quick note for whoever's on tomorrow:\n"
        "• What's the weather outlook overnight?\n"
        "• Any subscribers needing extra attention?\n"
        "• Anything in progress that needs follow-up?\n\n"
        "_Doesn't need to be formal, a few lines helps the team stay aligned._"
    )
    ok = _discord_post(DISCORD_WEBHOOK_SHIFT_HANDOFF, msg)
    _rosie_audit(None, "discord", "discord_shift_handoff",
                 "Posted end-of-day handoff prompt", tier=1, success=ok)


def _rosie_proactive_check_tick():
    """Top-level cron entry: dispatches each proactive trigger.
    Each individual trigger checks its own time window + cooldown, so this
    is just a fan-out point. Runs every 60s alongside other cron jobs."""
    if os.environ.get("WV_ROSIE_DISABLED") == "1":
        return
    for fn in (_rosie_proactive_morning_briefing,
               _rosie_proactive_inactivity_nudge,
               _rosie_proactive_severe_weather_heads_up,
               _rosie_discord_severe_weather,
               _rosie_discord_morning_team_status,
               _rosie_discord_shift_handoff_reminder):
        try:
            fn()
        except Exception as e:
            print(f"[rosie-proactive] {fn.__name__} failed: {e}", flush=True)


# Reminder firing (cron). Plugged into the main scheduler loop below.
def _rosie_fire_reminders():
    """Check for due reminders and send SMS to the recipient Met."""
    now_ms = int(time.time() * 1000)
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT r.id, r.met_user_id, r.message, u.phone
                   FROM rosie_reminders r
                   JOIN users u ON u.id = r.met_user_id
                   WHERE r.remind_at_ms <= %s
                     AND r.fired_at_ms IS NULL
                     AND r.cancelled_at_ms IS NULL
                   LIMIT 20""",
                (now_ms,),
            )
            due = cur.fetchall()
    for r in due:
        sent_ok = False
        try:
            if r.get("phone"):
                # Use Rosie's dedicated number so replies route to her SMS webhook
                sent_ok = bool(send_sms_from(r["phone"], f"{r['message']}\n- Rosie", ROSIE_TWILIO_NUMBER))
        except Exception as e:
            print(f"[rosie-reminder] send failed: {e}", flush=True)
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE rosie_reminders SET fired_at_ms = %s WHERE id = %s",
                        (now_ms, r["id"]),
                    )
        except Exception as e:
            print(f"[rosie-reminder] mark fired failed: {e}", flush=True)
        _rosie_audit(r["met_user_id"], "sms", "fired_reminder",
                     f"Reminder: {r['message'][:80]}", tier=1, success=sent_ok)


