@app.route("/api/v1/admin/inspect-scheduled-messages", methods=["OPTIONS"])
def _admin_inspect_scheduled_preflight():
    return ("", 204)


@app.get("/api/v1/admin/inspect-scheduled-messages")
def admin_inspect_scheduled_messages():
    """Return recent scheduled_messages rows so we can debug stuck schedules.

    Added May 28, 2026 from Chris & Timmy report: Schedule button leaves
    briefs sitting in queue forever. Lets us see exact state — status,
    scheduled_for_ms (vs now), fire_error, fired_at — without guessing.

    Query params:
      ?hours=48                  — how far back to look (default 48, max 168)
      ?status=pending|sent|failed — filter by status (optional)
      ?type=pro_brief            — filter by type (optional)
    """
    actor, err = _require_admin()
    if err:
        return err
    try:
        hours = min(168, max(1, int(request.args.get("hours") or 48)))
    except Exception:
        hours = 48
    status_filter = (request.args.get("status") or "").strip()
    type_filter = (request.args.get("type") or "").strip()

    now_ms = int(time.time() * 1000)
    cutoff_ms = now_ms - (hours * 3600 * 1000)

    where_parts = ["created_at >= %s"]
    params = [cutoff_ms]
    if status_filter:
        where_parts.append("status = %s")
        params.append(status_filter)
    if type_filter:
        where_parts.append("type = %s")
        params.append(type_filter)
    where_sql = " AND ".join(where_parts)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""SELECT id, type, status, scheduled_for_ms, scheduled_tz,
                           scheduled_by_user_id, scheduled_by_name,
                           created_at, fired_at, fire_error,
                           content_payload, target_audience
                    FROM scheduled_messages
                    WHERE {where_sql}
                    ORDER BY created_at DESC
                    LIMIT 100""",
                params,
            )
            rows = cur.fetchall()

    ET = ZoneInfo("America/New_York")
    out = []
    for r in rows:
        scheduled_dt = datetime.fromtimestamp(
            r["scheduled_for_ms"] / 1000, tz=timezone.utc
        ).astimezone(ET)
        created_dt = datetime.fromtimestamp(
            r["created_at"] / 1000, tz=timezone.utc
        ).astimezone(ET)
        fired_dt = None
        if r.get("fired_at"):
            fired_dt = datetime.fromtimestamp(
                r["fired_at"] / 1000, tz=timezone.utc
            ).astimezone(ET).strftime("%a %b %-d %-I:%M:%S %p ET")

        # Quick parse of draft_id from content_payload for pro_brief
        draft_id = None
        if r.get("type") == "pro_brief" and r.get("content_payload"):
            try:
                cp = _json_sched.loads(r["content_payload"])
                draft_id = cp.get("draft_id")
            except Exception:
                pass

        is_overdue = (r["status"] == "pending"
                      and r["scheduled_for_ms"] < now_ms - 60_000)

        out.append({
            "id": r["id"],
            "type": r["type"],
            "status": r["status"],
            "scheduled_for_et": scheduled_dt.strftime("%a %b %-d %-I:%M:%S %p ET"),
            "scheduled_for_ms": r["scheduled_for_ms"],
            "scheduled_tz": r.get("scheduled_tz"),
            "created_et": created_dt.strftime("%a %b %-d %-I:%M:%S %p ET"),
            "scheduled_by": r.get("scheduled_by_name") or f"#{r['scheduled_by_user_id']}",
            "fired_et": fired_dt,
            "fire_error": r.get("fire_error"),
            "draft_id": draft_id,
            "is_overdue_pending": is_overdue,
            "minutes_overdue": (
                int((now_ms - r["scheduled_for_ms"]) / 60_000)
                if is_overdue else None
            ),
        })

    summary = {
        "total": len(out),
        "pending": sum(1 for r in out if r["status"] == "pending"),
        "sent": sum(1 for r in out if r["status"] == "sent"),
        "failed": sum(1 for r in out if r["status"] == "failed"),
        "overdue_pending": sum(1 for r in out if r["is_overdue_pending"]),
    }
    return jsonify({
        "ok": True,
        "now_ms": now_ms,
        "now_et": datetime.fromtimestamp(now_ms/1000, tz=timezone.utc).astimezone(ET).strftime("%a %b %-d %-I:%M:%S %p ET"),
        "hours_window": hours,
        "summary": summary,
        "rows": out,
    })


@app.route("/api/v1/admin/inspect-drafts", methods=["OPTIONS"])
def _admin_inspect_drafts_preflight():
    return ("", 204)


@app.get("/api/v1/admin/inspect-drafts")
def admin_inspect_drafts():
    """Inspect pro_brief_drafts rows directly to diagnose stuck drafts.

    Added May 28, 2026 to investigate why some Hobbyist drafts sit in
    the Met's Pro Briefs queue past their window without auto-sending.
    Distinct from inspect-briefs (which shows brief_history = sent) and
    inspect-scheduled-messages (which shows the scheduled_messages
    queue). This shows pro_brief_drafts which is the work-in-progress
    table — pending review, claimed by Met, sent, or cancelled.

    Query params:
      ?hours=48           — how far back (default 48, max 168)
      ?status=pending-review|claimed|sent|cancelled  — filter
      ?user_id=N          — filter to one subscriber
    """
    actor, err = _require_admin()
    if err:
        return err
    try:
        hours = min(168, max(1, int(request.args.get("hours") or 48)))
    except Exception:
        hours = 48
    status_filter = (request.args.get("status") or "").strip()
    try:
        user_filter = int(request.args.get("user_id") or 0) or None
    except Exception:
        user_filter = None

    now_ms = int(time.time() * 1000)
    cutoff_ms = now_ms - (hours * 3600 * 1000)

    where = ["d.created_at >= %s"]
    params = [cutoff_ms]
    if status_filter:
        where.append("d.status = %s")
        params.append(status_filter)
    if user_filter:
        where.append("d.user_id = %s")
        params.append(user_filter)
    where_sql = " AND ".join(where)

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""SELECT d.id, d.user_id, d.brief_type, d.status,
                           d.user_tier, d.location_label,
                           d.created_at, d.window_end_at, d.sent_at,
                           d.sent_by_name, d.cancelled_at,
                           d.ai_verdict, d.met_verdict,
                           d.ai_snippet, d.met_snippet,
                           u.name AS subscriber_name, u.email AS subscriber_email,
                           u.subscription_tier AS current_tier
                    FROM pro_brief_drafts d
                    JOIN users u ON u.id = d.user_id
                    WHERE {where_sql}
                    ORDER BY d.created_at DESC
                    LIMIT 200""",
                params,
            )
            rows = cur.fetchall()

    ET = ZoneInfo("America/New_York")
    def _fmt(ms):
        if not ms:
            return None
        return datetime.fromtimestamp(
            ms / 1000, tz=timezone.utc
        ).astimezone(ET).strftime("%a %b %-d %-I:%M %p ET")

    out = []
    for r in rows:
        is_past_window = (r["status"] in ("pending-review", "claimed")
                          and r.get("window_end_at")
                          and r["window_end_at"] < now_ms)
        out.append({
            "id": r["id"],
            "user_id": r["user_id"],
            "subscriber": r.get("subscriber_name") or r.get("subscriber_email"),
            "current_tier": r.get("current_tier"),
            "draft_tier": r.get("user_tier"),
            "status": r["status"],
            "verdict": r.get("met_verdict") or r.get("ai_verdict"),
            "is_met_touched": bool(r.get("met_verdict") or r.get("met_snippet")),
            "brief_type": r.get("brief_type"),
            "location_label": r.get("location_label"),
            "snippet_preview": (r.get("met_snippet") or r.get("ai_snippet") or "")[:120],
            "created_et": _fmt(r["created_at"]),
            "window_end_et": _fmt(r.get("window_end_at")),
            "sent_et": _fmt(r.get("sent_at")),
            "cancelled_et": _fmt(r.get("cancelled_at")),
            "sent_by": r.get("sent_by_name"),
            "is_past_window_pending": bool(is_past_window),
        })

    summary = {
        "total": len(out),
        "by_status": {},
        "by_tier": {},
        "past_window_pending": sum(1 for r in out if r["is_past_window_pending"]),
        "suppress_verdict": sum(1 for r in out if r["verdict"] == "suppress"),
    }
    for r in out:
        s = r["status"]
        summary["by_status"][s] = summary["by_status"].get(s, 0) + 1
        t = r.get("current_tier") or "unknown"
        summary["by_tier"][t] = summary["by_tier"].get(t, 0) + 1

    return jsonify({
        "ok": True,
        "now_et": datetime.fromtimestamp(now_ms/1000, tz=timezone.utc).astimezone(ET).strftime("%a %b %-d %-I:%M %p ET"),
        "hours_window": hours,
        "summary": summary,
        "rows": out,
    })


@app.get("/api/v1/admin/audit-subscriber-timezones")
def admin_audit_subscriber_timezones():
    """Audit subscriber timezone settings to spot inconsistencies.

    Added May 29, 2026 as part of the timezone correctness sweep.

    Three timezone fields could disagree for the same subscriber:
      1. users.timezone — used by the brief scheduler and missed-brief
         alerts (where briefs actually fire from)
      2. subscriber_coverage.daily_brief_timezone — Pro-tier only,
         used by the coverage task generator that creates
         daily_brief_tasks rows for payroll. Hobbyists have no row
         here so pref_tz will be empty for them.
      3. The 'correct' timezone for their saved address (inferred from
         state code in address_text — best-effort, not authoritative)

    Returns per-subscriber rows showing all three plus a 'flags' array
    listing any divergence. Empty flags = clean. Read-only.
    """
    actor, err = _require_admin()
    if err:
        return err

    # Rough state-to-default-tz mapping. NOT comprehensive (Indiana has
    # tz splits, Kentucky too, etc.) but catches obvious mismatches.
    STATE_DEFAULT_TZ = {
        "AL": "America/Chicago", "AK": "America/Anchorage", "AZ": "America/Phoenix",
        "AR": "America/Chicago", "CA": "America/Los_Angeles", "CO": "America/Denver",
        "CT": "America/New_York", "DE": "America/New_York", "FL": "America/New_York",
        "GA": "America/New_York", "HI": "Pacific/Honolulu", "ID": "America/Boise",
        "IL": "America/Chicago", "IN": "America/Indiana/Indianapolis",
        "IA": "America/Chicago", "KS": "America/Chicago", "KY": "America/New_York",
        "LA": "America/Chicago", "ME": "America/New_York", "MD": "America/New_York",
        "MA": "America/New_York", "MI": "America/Detroit", "MN": "America/Chicago",
        "MS": "America/Chicago", "MO": "America/Chicago", "MT": "America/Denver",
        "NE": "America/Chicago", "NV": "America/Los_Angeles", "NH": "America/New_York",
        "NJ": "America/New_York", "NM": "America/Denver", "NY": "America/New_York",
        "NC": "America/New_York", "ND": "America/Chicago", "OH": "America/New_York",
        "OK": "America/Chicago", "OR": "America/Los_Angeles", "PA": "America/New_York",
        "RI": "America/New_York", "SC": "America/New_York", "SD": "America/Chicago",
        "TN": "America/Chicago", "TX": "America/Chicago", "UT": "America/Denver",
        "VT": "America/New_York", "VA": "America/New_York", "WA": "America/Los_Angeles",
        "WV": "America/New_York", "WI": "America/Chicago", "WY": "America/Denver",
        "DC": "America/New_York",
    }

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.email, u.timezone AS user_tz,
                          u.subscription_tier,
                          bp.morning_window_start, bp.morning_window_end,
                          sc.daily_brief_time, sc.daily_brief_timezone,
                          loc.address_text AS loc_address
                   FROM users u
                   LEFT JOIN brief_preferences bp ON bp.user_id = u.id
                   LEFT JOIN subscriber_coverage sc ON sc.user_id = u.id
                   LEFT JOIN saved_locations loc
                          ON loc.user_id = u.id AND loc.is_primary = TRUE
                   WHERE u.is_active = TRUE
                     AND EXISTS (
                       SELECT 1 FROM user_roles ur
                       WHERE ur.user_id = u.id AND ur.role = 'subscriber'
                     )
                   ORDER BY u.id"""
            )
            rows = cur.fetchall()

    out = []
    for r in rows:
        user_tz = r.get("user_tz") or ""
        pref_tz = r.get("daily_brief_timezone") or ""
        addr = r.get("loc_address") or ""
        tier = r.get("subscription_tier") or ""
        is_pro = tier.startswith("pro_")

        # Extract state code from address — last token like ", IN 46052"
        state_code = ""
        m = re.search(r',\s*([A-Z]{2})\s+\d{5}', addr or "")
        if m:
            state_code = m.group(1)
        implied_tz = STATE_DEFAULT_TZ.get(state_code, "")

        flags = []
        # Flag 1: u.timezone missing
        if not user_tz:
            flags.append("user_tz_empty")
        # Flag 2: pref tz set AND differs from user_tz (Pro only — Hobbyists
        # don't have a subscriber_coverage row by design)
        if is_pro and pref_tz and user_tz and pref_tz != user_tz:
            flags.append("user_tz_vs_pref_tz_mismatch")
        # Flag 3: Pro subscriber with NO pref_tz at all — coverage row
        # might be missing entirely
        if is_pro and not pref_tz:
            flags.append("pro_missing_coverage_row")
        # Flag 4: implied tz from address differs from user_tz
        if implied_tz and user_tz and implied_tz != user_tz:
            # Indiana has tz splits, Kentucky too — flag for review,
            # admin decides whether the address actually implies a
            # different tz for this person.
            flags.append("user_tz_vs_address_mismatch")
        # Flag 5: tz string fails to parse (invalid IANA name)
        for label, tz_val in (("user_tz", user_tz), ("pref_tz", pref_tz)):
            if tz_val:
                try:
                    ZoneInfo(tz_val)
                except Exception:
                    flags.append(f"{label}_invalid")

        out.append({
            "user_id": r["id"],
            "name": r.get("name") or "",
            "email": r["email"],
            "tier": tier,
            "user_tz": user_tz,
            "pref_tz": pref_tz,
            "address": addr,
            "state_code": state_code,
            "implied_tz_from_state": implied_tz,
            "morning_window_start": r.get("morning_window_start") or "",
            "morning_window_end": r.get("morning_window_end") or "",
            "daily_brief_time": r.get("daily_brief_time") or "",
            "flags": flags,
        })

    flagged = [s for s in out if s["flags"]]
    return jsonify({
        "ok": True,
        "total_subscribers": len(out),
        "flagged_count": len(flagged),
        "rows": out,
    })


@app.route("/api/v1/admin/widget-narrative/generate/<slug>", methods=["OPTIONS"])
def _admin_widget_narr_generate_preflight(slug):
    return ("", 204)


@app.post("/api/v1/admin/widget-narrative/generate/<slug>")
def admin_generate_widget_narrative(slug: str):
    """Admin: manually generate a widget narrative for a location, NOW.

    Bypasses the 5 AM / noon CT scheduler gate so we can test the
    full Phase 2 workflow end-to-end without waiting for the cron.
    Creates a pending-review row using the current cycle (morning if
    before noon local; afternoon if noon or later).

    Idempotent at the cycle level — uses the same 18-hour duplicate
    check as the scheduler, so calling twice in the same cycle is a
    no-op (returns existing).
    """
    actor, err = _require_admin()
    if err:
        return err

    slug = (slug or "").strip().lower()
    if not slug:
        return jsonify({"ok": False, "error": "slug-required"}), 400

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, slug, name, lat, lng, timezone
                   FROM widget_locations
                   WHERE slug = %s AND is_active = TRUE""",
                (slug,),
            )
            loc = cur.fetchone()
    if not loc:
        return jsonify({"ok": False, "error": "location-not-found"}), 404

    tz = ZoneInfo(loc.get("timezone") or "America/Chicago")
    local_now = datetime.now(tz)
    # Choose cycle based on time-of-day in the location's timezone
    cycle = "morning" if local_now.hour < 12 else "afternoon"
    # Expires when the OTHER cycle takes over
    from datetime import timedelta
    if cycle == "morning":
        expires_local = local_now.replace(hour=12, minute=0, second=0, microsecond=0)
        if expires_local <= local_now:
            expires_local = expires_local + timedelta(days=1)
    else:
        next_day = local_now + timedelta(days=1)
        expires_local = next_day.replace(hour=5, minute=0, second=0, microsecond=0)
    expires_ms = int(expires_local.timestamp() * 1000)
    now_ms = int(time.time() * 1000)

    # Duplicate check
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, status FROM widget_narratives
                   WHERE location_id = %s
                     AND cycle = %s
                     AND created_at >= %s
                   ORDER BY created_at DESC
                   LIMIT 1""",
                (loc["id"], cycle, now_ms - 18 * 3600 * 1000),
            )
            existing = cur.fetchone()
    if existing:
        return jsonify({
            "ok": True,
            "narrative_id": existing["id"],
            "status": existing["status"],
            "note": "Existing narrative for this cycle returned (idempotent).",
        })

    forecast = _fetch_forecast_7day(loc["lat"], loc["lng"])
    if not forecast:
        return jsonify({"ok": False, "error": "forecast-fetch-failed"}), 503
    narrative = _generate_widget_narrative(loc["name"], forecast)
    if not narrative:
        return jsonify({"ok": False, "error": "narrative-generation-failed"}), 500

    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO widget_narratives
                     (location_id, cycle, status, ai_body, created_at, expires_at)
                   VALUES (%s, %s, 'pending-review', %s, %s, %s)
                   RETURNING id""",
                (loc["id"], cycle, narrative, now_ms, expires_ms),
            )
            row = cur.fetchone()
    print(f"[widget-narratives] admin={actor['id']} force-generated for {slug}",
          flush=True)
    return jsonify({
        "ok": True,
        "narrative_id": row["id"],
        "cycle": cycle,
        "ai_body_preview": narrative[:200],
    })


