def _sales_pipeline_preflight():
    return ("", 204)


@app.get("/api/v1/sales/pipeline")
def sales_pipeline():
    """Every signup attributed to the signed-in rep, newest first, with a
    computed status so the portal can show 'Day 12 of 30' at a glance."""
    user, rep = _current_sales_rep()
    if user is None:
        return jsonify({"ok": False, "error": "not-signed-in"}), 401
    if rep is None:
        return jsonify({"ok": False, "error": "not-a-rep"}), 403
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT a.signed_up_at, a.starter_used,
                          u.id AS user_id, u.name, u.email,
                          u.trial_business_name, u.trial_status,
                          u.trial_started_at, u.trial_ends_at,
                          u.subscription_tier, u.is_active
                   FROM sales_attributions a
                   JOIN users u ON u.id = a.user_id
                   WHERE a.rep_slug = %s
                   ORDER BY a.signed_up_at DESC""",
                (rep["slug"],),
            )
            rows = cur.fetchall()
    now_ms = int(time.time() * 1000)
    out = []
    for r in rows:
        status, day, days_total = "paying", None, None
        if not r["is_active"]:
            status = "deactivated"
        elif r.get("trial_status") == "active":
            ends = r.get("trial_ends_at") or 0
            started = r.get("trial_started_at") or r["signed_up_at"]
            if ends and now_ms >= ends:
                status = "trial_ended"
            else:
                status = "trial"
                day = max(1, int((now_ms - started) // 86400000) + 1)
                if ends and started:
                    days_total = max(day, int(round((ends - started) / 86400000)))
        elif (r.get("subscription_tier") or "").startswith("pro"):
            status = "paying"
        else:
            status = "ended"
        out.append({
            "user_id": r["user_id"],
            "display_name": r.get("trial_business_name") or r.get("name") or r.get("email"),
            "contact_name": r.get("name") or "",
            "signed_up_at": r["signed_up_at"],
            "starter_used": bool(r.get("starter_used")),
            "status": status,
            "trial_day": day,
            "trial_days_total": days_total,
        })
    return jsonify({"ok": True, "pipeline": out})


@app.route("/api/v1/sales/commissions", methods=["OPTIONS"])
def _sales_commissions_preflight():
    return ("", 204)


@app.get("/api/v1/sales/commissions")
def sales_commissions():
    """The signed-in rep's money: this month's statement plus lifetime
    total, computed with the exact same engine the admin report uses so
    the numbers can never disagree."""
    user, rep = _current_sales_rep()
    if user is None:
        return jsonify({"ok": False, "error": "not-signed-in"}), 401
    if rep is None:
        return jsonify({"ok": False, "error": "not-a-rep"}), 403
    ET = ZoneInfo("America/New_York")
    now_dt = datetime.now(tz=ET)

    def _mine(result):
        for rrow in result.get("reps", []):
            if rrow.get("slug") == rep["slug"]:
                return rrow
        return {"customer_count": 0, "commission_cents": 0, "customers": []}

    this_month = _compute_commissions_for_month(now_dt.year, now_dt.month)
    mine_now = _mine(this_month)

    # Lifetime: walk back from the current month to the rep's earliest
    # attribution (capped at 24 months, the system is young).
    lifetime_cents = mine_now["commission_cents"]
    earliest_ms = None
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT MIN(signed_up_at) AS m FROM sales_attributions WHERE rep_slug = %s",
                (rep["slug"],),
            )
            r = cur.fetchone()
            earliest_ms = r["m"] if r else None
    if earliest_ms:
        earliest_dt = datetime.fromtimestamp(earliest_ms / 1000, tz=ET)
        y, m = now_dt.year, now_dt.month
        steps = 0
        while steps < 24:
            m -= 1
            if m == 0:
                y, m = y - 1, 12
            if (y, m) < (earliest_dt.year, earliest_dt.month):
                break
            lifetime_cents += _mine(_compute_commissions_for_month(y, m))["commission_cents"]
            steps += 1

    return jsonify({
        "ok": True,
        "month_label": this_month.get("month"),
        "month_cents": mine_now["commission_cents"],
        "lifetime_cents": lifetime_cents,
        "customers": mine_now["customers"],
    })


# ════════════════════════════════════════════════════════════════════
# Trial satisfaction survey (July 2026)
# ════════════════════════════════════════════════════════════════════
# Four questions, two minutes, one job: set up the conversion conversation.
# The "have you messaged your Meteorologist" question is the diagnostic:
# a "no" plus a wishlist means the gap is onboarding, not the Met's
# forecasting, and a "no" answer triggers an automatic follow-up teaching
# them to message their Met.

def _send_user_email(to_email: str, subject: str, body_html: str, body_text: str) -> None:
    """Minimal Resend send, best-effort."""
    api_key = os.environ.get("RESEND_API_KEY", "").strip()
    if not (to_email and api_key):
        print(f"[survey-email] skipped for {to_email!r} (no key or address)", flush=True)
        return
    try:
        from_addr = os.environ.get("RESEND_FROM_EMAIL", "WeatherValet <hello@weathervalet.ai>")
        payload = json.dumps({
            "from": from_addr, "to": [to_email], "subject": subject,
            "html": body_html, "text": body_text,
        }).encode("utf-8")
        req = urllib.request.Request(
            "https://api.resend.com/emails", data=payload, method="POST",
            headers={"Authorization": f"Bearer {api_key}",
                     "Content-Type": "application/json",
                     "User-Agent": "WeatherValet-Backend/1.0 (+https://weathervalet.ai)"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            resp.read()
    except Exception as e:
        print(f"[survey-email] send failed for {to_email!r}: {e!r}", flush=True)


def _met_first_name_for_user(user_id: int) -> str:
    try:
        with db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT m.name FROM subscriber_coverage sc
                       JOIN users m ON m.id = sc.primary_met_id
                       WHERE sc.user_id = %s""",
                    (user_id,),
                )
                r = cur.fetchone()
        nm = ((r or {}).get("name") or "").split(" ")[0]
        return nm or "your Meteorologist"
    except Exception:
        return "your Meteorologist"


@app.route("/api/v1/admin/trial-survey/send", methods=["OPTIONS"])
def _trial_survey_send_preflight():
    return ("", 204)


@app.post("/api/v1/admin/trial-survey/send")
def admin_trial_survey_send():
    """Send the survey to every active trial subscriber who hasn't been
    invited in the last 14 days. Safe to click repeatedly: repeats only
    reach subscribers who joined since the last send. Admin only."""
    user = _get_current_user()
    if user is None or "admin" not in (user.get("roles") or []):
        return jsonify({"ok": False, "error": "forbidden"}), 403
    now_ms = int(time.time() * 1000)
    fresh_cutoff = now_ms - 14 * 86400000
    with db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT u.id, u.name, u.email, u.phone, u.trial_business_name
                   FROM users u
                   WHERE u.is_active = TRUE
                     AND u.trial_status = 'active'
                     AND NOT EXISTS (
                       SELECT 1 FROM trial_surveys t
                       WHERE t.user_id = u.id AND t.created_at > %s
                     )""",
                (fresh_cutoff,),
            )
            targets = cur.fetchall()
    base = os.environ.get("FRONTEND_BASE_URL", "https://weathervalet.ai").rstrip("/")
    sent = 0
    for t in targets:
        token = new_secure_token()
        try:
            with db() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO trial_surveys (token, user_id, created_at)
                           VALUES (%s, %s, %s)""",
                        (token, t["id"], now_ms),
                    )
        except Exception as e:
            print(f"[survey-send] token insert failed for user {t['id']}: {e!r}", flush=True)
            continue
        link = f"{base}/survey?t={token}"
        first = (t.get("name") or "").split(" ")[0] or "there"
        met_first = _met_first_name_for_user(t["id"])
        sms = (f"Hi {first}, it's {met_first} with WeatherValet. I want to make your "
               f"briefs perfect for you. Two minutes and brutal honesty, please: {link}")
        phone = (t.get("phone") or "").strip()
        if phone:
            send_sms(phone, sms)
        subject = "Two minutes and brutal honesty, please"
        body_html = (
            "<div style='font-family:Arial,sans-serif;max-width:520px;'>"
            f"<p style='font-size:15px;'>Hi {_html_escape(first)},</p>"
            f"<p style='font-size:15px;'>It's {_html_escape(met_first)} with WeatherValet. "
            "I want to make your briefs perfect for you, and the only way I can is if you "
            "tell me the truth. Four quick questions, about two minutes:</p>"
            f"<p style='margin:18px 0;'><a href='{link}' style='background:#4169E1;color:#fff;"
            "padding:11px 22px;border-radius:7px;text-decoration:none;font-weight:700;'>"
            "Take the survey</a></p>"
            "<p style='color:#6B7280;font-size:13px;'>WeatherValet</p></div>"
        )
        body_text = (f"Hi {first}, it's {met_first} with WeatherValet. I want to make your "
                     f"briefs perfect for you. Two minutes and brutal honesty, please: {link}")
        _send_user_email((t.get("email") or "").strip(), subject, body_html, body_text)
        sent += 1
    return jsonify({"ok": True, "sent": sent,
                    "message": (f"Survey sent to {sent} active trial "
                                f"{'subscriber' if sent == 1 else 'subscribers'}."
                                if sent else
                                "No one to send to. Everyone active on trial was already "
                                "invited in the last 14 days.")})


